// ==========================================
// GOOGLE APPS SCRIPT CODE
// ==========================================
// 1. Go to your Google Sheet -> Extensions -> Apps Script
// 2. Paste this code into Code.gs
// 3. Deploy as Web App -> Access: Anyone -> Copy URL

const SHEET_PO = "PO_Database";
const SHEET_INVENTORY = "Master_SKU_Mapping";
const SHEET_CHANNEL_CONFIG = "Channel_Config";
const SHEET_EASYECOM_QUEUE = "EasyEcom_Queue"; // New Sheet for the queue

// Handle GET requests (Fetching Data)
function doGet(e) {
  const action = e.parameter.action;

  if (action === 'getPurchaseOrders') {
    return getPurchaseOrders();
  } else if (action === 'getInventory') {
    return getInventory();
  } else if (action === 'getChannelConfigs') {
    return getChannelConfigs();
  } else if (action === 'getCostPrices') {
    return getCostPrices();
  }

  return responseJSON({status: 'error', message: 'Invalid action'});
}

// Handle POST requests (Creating/Updating Data)
function doPost(e) {
  try {
    const data = JSON.parse(e.postData.contents);
    const action = data.action;

    if (action === 'createItem') {
      return createInventoryItem(data);
    } else if (action === 'updatePrice') {
      return updateInventoryPrice(data);
    } else if (action === 'saveChannelConfig') {
      return saveChannelConfig(data);
    } else if (action === 'pushToEasyEcom') {
      return pushToEasyEcom(data);
    }

    return responseJSON({status: 'error', message: 'Invalid action'});
  } catch (error) {
    return responseJSON({status: 'error', message: error.toString()});
  }
}

// --- Data Fetching Functions ---

function getPurchaseOrders() {
  const sheet = SpreadsheetApp.getActiveSpreadsheet().getSheetByName(SHEET_PO);
  if (!sheet) return responseJSON({status: 'error', message: 'Sheet "' + SHEET_PO + '" not found.'});

  // Get all data including headers
  const data = getDataAsJSON(sheet);
  return responseJSON({status: 'success', data: data});
}

function getInventory() {
  const sheet = SpreadsheetApp.getActiveSpreadsheet().getSheetByName(SHEET_INVENTORY);
  if (!sheet) return responseJSON({status: 'error', message: 'Sheet "' + SHEET_INVENTORY + '" not found. Check tab name.'});

  const data = getDataAsJSON(sheet);
  return responseJSON({status: 'success', data: data});
}

function getChannelConfigs() {
  const sheet = SpreadsheetApp.getActiveSpreadsheet().getSheetByName(SHEET_CHANNEL_CONFIG);
  if (!sheet) return responseJSON({status: 'error', message: 'Sheet "' + SHEET_CHANNEL_CONFIG + '" not found.'});

  const data = getDataAsJSON(sheet);
  return responseJSON({status: 'success', data: data});
}

function getCostPrices() {
  // External Spreadsheet ID and Sheet GID provided by user
  const SPREADSHEET_ID = '1YM0dKPWySifYFDyNqCenJ4L85xIBSTrBGNPDcoo6Kfg';
  const SHEET_GID = 1695352288;

  try {
    const ss = SpreadsheetApp.openById(SPREADSHEET_ID);
    const sheets = ss.getSheets();
    let sheet = null;

    // Find sheet by GID
    for (var i = 0; i < sheets.length; i++) {
      if (sheets[i].getSheetId() === SHEET_GID) {
        sheet = sheets[i];
        break;
      }
    }

    if (!sheet) return responseJSON({status: 'error', message: 'Cost Price Sheet not found'});

    const data = sheet.getDataRange().getValues();
    const result = [];

    // Assuming Row 1 is header, Data: A=Channel, C=SKU, D=Cost Price
    // A=0, B=1, C=2, D=3
    for (var i = 1; i < data.length; i++) {
      const row = data[i];
      if (row[0] && row[2]) { // Ensure Channel and SKU exist
        result.push({
          channel: String(row[0]),
          sku: String(row[2]),
          costPrice: Number(row[3] || 0)
        });
      }
    }

    return responseJSON({status: 'success', data: result});
  } catch (e) {
    return responseJSON({status: 'error', message: 'Failed to fetch external cost sheet: ' + e.toString()});
  }
}

// --- Data Modification Functions ---

function createInventoryItem(data) {
  const sheet = SpreadsheetApp.getActiveSpreadsheet().getSheetByName(SHEET_INVENTORY);
  if (!sheet) return responseJSON({status: 'error', message: 'Sheet "' + SHEET_INVENTORY + '" not found.'});

  // Header definition based on user requirement:
  // Channel, Channel Item Code, Master SKU, Selling Price, Inventory, EAN, Itemname, MRP

  sheet.appendRow([
    data.channel,
    data.articleCode, // Maps to Channel Item Code
    data.sku,         // Maps to Master SKU
    data.spIncTax || 0, // Maps to Selling Price
    data.stock || 0,    // Maps to Inventory
    data.ean || '',
    data.itemName || '', // Maps to Itemname
    data.mrp || 0
  ]);

  return responseJSON({status: 'success', message: 'Item created'});
}

function updateInventoryPrice(data) {
  const sheet = SpreadsheetApp.getActiveSpreadsheet().getSheetByName(SHEET_INVENTORY);
  if (!sheet) return responseJSON({status: 'error', message: 'Sheet "' + SHEET_INVENTORY + '" not found.'});

  const rows = sheet.getDataRange().getValues();
  if (rows.length < 1) return responseJSON({status: 'error', message: 'Sheet is empty'});

  const headers = rows[0].map(h => String(h).toLowerCase().trim());

  // Find column indexes based on specific headers provided
  const colChannel = headers.indexOf('channel');

  // Try exact match first, then fallback to partial
  let colArticle = headers.indexOf('channel item code');
  if (colArticle === -1) colArticle = headers.findIndex(h => h.includes('item code') || h.includes('article'));

  let colPrice = headers.indexOf('selling price');
  if (colPrice === -1) colPrice = headers.findIndex(h => h.includes('selling') || h.includes('sp'));

  if (colChannel === -1 || colArticle === -1 || colPrice === -1) {
    return responseJSON({
      status: 'error', 
      message: `Required columns not found. Found: ${headers.join(', ')}. Need: Channel, Channel Item Code, Selling Price`
    });
  }

  // Find row to update
  for (let i = 1; i < rows.length; i++) {
    const rowChannel = String(rows[i][colChannel]).trim();
    const rowArticle = String(rows[i][colArticle]).trim();

    // Loose comparison for strings/numbers
    if (rowChannel.toLowerCase() === data.channel.toLowerCase() && rowArticle === String(data.articleCode)) {
      // Update the cell (i + 1 because rows are 0-indexed but Sheets API is 1-indexed)
      sheet.getRange(i + 1, colPrice + 1).setValue(data.newPrice);
      return responseJSON({status: 'success', message: 'Price updated'});
    }
  }

  return responseJSON({status: 'error', message: 'Item not found in Inventory sheet'});
}

function saveChannelConfig(data) {
  const sheet = SpreadsheetApp.getActiveSpreadsheet().getSheetByName(SHEET_CHANNEL_CONFIG);
  if (!sheet) return responseJSON({status: 'error', message: `Sheet "${SHEET_CHANNEL_CONFIG}" not found.`});

  const rows = sheet.getDataRange().getValues();
  if (rows.length === 0) return responseJSON({status: 'error', message: 'Sheet is empty, add headers first.'});

  const headers = rows[0].map(h => String(h).toLowerCase().trim());

  const nameIdx = headers.indexOf('channel name');
  if (nameIdx === -1) return responseJSON({status: 'error', message: 'Header "Channel Name" not found.'});

  let rowIndex = -1;
  // Try to find existing
  for (let i = 1; i < rows.length; i++) {
    if (String(rows[i][nameIdx]).toLowerCase() === data.channelName.toLowerCase()) {
      rowIndex = i + 1; // 1-based
      break;
    }
  }

  // Helper to find col index safely
  const getCol = (name) => {
    const idx = headers.findIndex(h => h === name.toLowerCase());
    return idx === -1 ? -1 : idx + 1;
  };

  const colStatus = getCol('Status');
  const colEmail = getCol('Source Email');
  const colKeyword = getCol('Search Keyword');
  const colThreshold = getCol('Min Order Threshold');
  const colPocName = getCol('POC Name');
  const colPocEmail = getCol('POC Email');
  const colPocPhone = getCol('POC Phone');

  if (rowIndex > 0) {
    // Update
    if (colStatus > 0) sheet.getRange(rowIndex, colStatus).setValue(data.status);
    if (colEmail > 0) sheet.getRange(rowIndex, colEmail).setValue(data.sourceEmail);
    if (colKeyword > 0) sheet.getRange(rowIndex, colKeyword).setValue(data.searchKeyword);
    if (colThreshold > 0) sheet.getRange(rowIndex, colThreshold).setValue(data.minOrderThreshold);
    if (colPocName > 0) sheet.getRange(rowIndex, colPocName).setValue(data.pocName);
    if (colPocEmail > 0) sheet.getRange(rowIndex, colPocEmail).setValue(data.pocEmail);
    if (colPocPhone > 0) sheet.getRange(rowIndex, colPocPhone).setValue(data.pocPhone);
    return responseJSON({status: 'success', message: 'Channel updated'});
  } else {
    // Create (Append)
    const newRow = new Array(headers.length).fill('');
    if (nameIdx > -1) newRow[nameIdx] = data.channelName;
    if (colStatus > -1) newRow[colStatus-1] = data.status;
    if (colEmail > -1) newRow[colEmail-1] = data.sourceEmail;
    if (colKeyword > -1) newRow[colKeyword-1] = data.searchKeyword;
    if (colThreshold > -1) newRow[colThreshold-1] = data.minOrderThreshold;
    if (colPocName > -1) newRow[colPocName-1] = data.pocName;
    if (colPocEmail > -1) newRow[colPocEmail-1] = data.pocEmail;
    if (colPocPhone > -1) newRow[colPocPhone-1] = data.pocPhone;

    sheet.appendRow(newRow);
    return responseJSON({status: 'success', message: 'Channel created'});
  }
}

function pushToEasyEcom(data) {
  // Check if queue sheet exists, create if not
  let sheet = SpreadsheetApp.getActiveSpreadsheet().getSheetByName(SHEET_EASYECOM_QUEUE);
  if (!sheet) {
    sheet = SpreadsheetApp.getActiveSpreadsheet().insertSheet(SHEET_EASYECOM_QUEUE);
    sheet.appendRow(['Timestamp', 'PO Number', 'Channel', 'Store Code', 'Selected SKUs (JSON)', 'Status']);
  }

  const timestamp = new Date();
  const selectedItemsJson = JSON.stringify(data.items);

  sheet.appendRow([
    timestamp,
    data.poNumber,
    data.channel,
    data.storeCode,
    selectedItemsJson,
    'Pending Process'
  ]);

  return responseJSON({
    status: 'success', 
    message: `PO ${data.poNumber} queued with ${data.items.length} items for EasyEcom`
  });
}

// --- Helpers ---

function getDataAsJSON(sheet) {
  const rawData = sheet.getDataRange().getValues();
  if (rawData.length === 0) return [];

  const headers = rawData[0];
  const data = [];

  for (let i = 1; i < rawData.length; i++) {
    const row = rawData[i];
    // Skip empty rows (check first 2 columns)
    if (row[0] === "" && row[1] === "") continue;

    const obj = {};
    for (let j = 0; j < headers.length; j++) {
      // Use header as key
      obj[headers[j]] = row[j];
    }
    data.push(obj);
  }

  return data;
}

function responseJSON(data) {
  return ContentService.createTextOutput(JSON.stringify(data))
    .setMimeType(ContentService.MimeType.JSON);
}

import { InventoryItem, PurchaseOrder, POStatus, POItem, ChannelConfig } from '../types';

// Use the public script.google.com URL (removing /a/cubelelo.com/) to ensure access works via API for "Anyone" access level
const API_URL = 'https://script.google.com/macros/s/AKfycbwBDSNnN_xKlZc4cTwwKthd7-Nq8IE83csNdNHODP55EnVEz-gfWzcvzYdxGeNbJSPzZQ/exec'; 

export const fetchInventoryFromSheet = async (): Promise<InventoryItem[]> => {
    try {
        const response = await fetch(`${API_URL}?action=getInventory`, {
            method: 'GET',
            redirect: 'follow',
            mode: 'cors',
            credentials: 'omit' // Critical for GAS web apps to avoid auth conflicts
        });

        if (!response.ok) {
            throw new Error(`HTTP Error: ${response.status}`);
        }

        const json = await response.json();
        if (json.status === 'success') {
            return transformSheetDataToInventory(json.data);
        } else {
            console.error("API Error (Inventory):", json.message);
            // Return empty array instead of throwing to prevent app crash if sheet is missing
            return [];
        }
    } catch (error) {
        console.error("Failed to fetch inventory:", error);
        return [];
    }
};

export const fetchPurchaseOrders = async (): Promise<PurchaseOrder[]> => {
    try {
        const response = await fetch(`${API_URL}?action=getPurchaseOrders`, {
            method: 'GET',
            redirect: 'follow',
            mode: 'cors',
            credentials: 'omit'
        });

        if (!response.ok) {
            throw new Error(`HTTP Error: ${response.status}`);
        }

        const json = await response.json();

        if (json.status === 'success' && Array.isArray(json.data)) {
            return transformSheetDataToPOs(json.data);
        } else {
            console.warn("API returned success=false or invalid data for POs:", json);
            return [];
        }
    } catch (error) {
        console.error("Failed to fetch purchase orders:", error);
        return [];
    }
};

export const fetchChannelConfigs = async (): Promise<ChannelConfig[]> => {
    try {
        const response = await fetch(`${API_URL}?action=getChannelConfigs`, {
            method: 'GET',
            redirect: 'follow',
            mode: 'cors',
            credentials: 'omit'
        });

        if (!response.ok) {
            throw new Error(`HTTP Error: ${response.status}`);
        }

        const json = await response.json();

        if (json.status === 'success' && Array.isArray(json.data)) {
            return transformSheetDataToChannelConfigs(json.data);
        } else {
            console.warn("API Error (Channels):", json.message);
            return [];
        }
    } catch (error) {
        console.error("Failed to fetch channel configs:", error);
        return [];
    }
};

const transformSheetDataToInventory = (rows: any[]): InventoryItem[] => {
    return rows.map((row, index) => {
        // Headers provided: Channel, Channel Item Code, Master SKU, Selling Price, Inventory, EAN, Itemname, MRP
        return {
            id: `inv-${index}-${Date.now()}`,
            channel: row['Channel'] || 'Unknown',
            articleCode: String(row['Channel Item Code'] || row['articleCode'] || ''),
            sku: String(row['Master SKU'] || row['sku'] || ''),
            ean: String(row['EAN'] || ''),
            itemName: row['Itemname'] || row['ItemName'] || row['Item Name'] || '', 
            mrp: Number(row['MRP'] || 0),
            basicPrice: 0, 
            spIncTax: Number(row['Selling Price'] || 0),
            stock: Number(row['Inventory'] || 0)
        };
    });
};

// Helper to format date consistently
const formatSheetDate = (dateVal: any): string => {
    if (!dateVal) return new Date().toLocaleDateString('en-GB', { day: 'numeric', month: 'short', year: 'numeric' });

    // Check if it's already a clean string like "12 Oct 2025" or "12/10/2025"
    if (typeof dateVal === 'string' && dateVal.length < 15 && !dateVal.includes('T')) {
        return dateVal;
    }

    const d = new Date(dateVal);
    if (isNaN(d.getTime())) return String(dateVal);

    return d.toLocaleDateString('en-GB', { day: 'numeric', month: 'short', year: 'numeric' });
};

const transformSheetDataToPOs = (rows: any[]): PurchaseOrder[] => {
    const poMap = new Map<string, PurchaseOrder>();

    rows.forEach((row) => {
        // Map keys based on likely Google Sheet Headers (handling variations)
        const poNumber = row['PO Number'] || row['PO_Number'] || row['poNumber'];
        if (!poNumber) return;

        const rawStatus = row['Status'] || 'New';
        let status = POStatus.NewPO;

        // Map Sheet Status to Enum
        if (rawStatus === 'Below Threshold') status = POStatus.BelowThreshold;
        else if (rawStatus === 'New') status = POStatus.NewPO;
        else if (Object.values(POStatus).includes(rawStatus as POStatus)) status = rawStatus as POStatus;

        // Robust parsing for Quantity and new Fulfillable Qty
        const qty = Number(row['Qty'] || row['qty'] || row['Quantity'] || 0);
        const fulfillableQty = Number(row['Fulfillable qty'] || row['fulfillable qty'] || 0);

        const unitCost = Number(row['Unit Cost (Tax Exclusive)'] || row['Unit Cost'] || 0);
        const mrp = Number(row['MRP'] || 0);
        const itemAmount = qty * unitCost;

        // Try multiple keys for Article Code / SKU to ensure mapping works
        const articleCode = String(row['Item Code'] || row['Article Code'] || row['Vendor SKU'] || row['SKU'] || '').trim();

        // Extract Price Check status from the sheet
        const priceCheckStatus = String(row['Price Check'] || row['Price Status'] || row['Cost Status'] || '').trim();

        const item: POItem = {
            articleCode: articleCode,
            masterSku: String(row['Master SKU'] || ''),
            itemName: row['Item Name'] || '',
            qty: qty,
            fulfillableQty: fulfillableQty,
            unitCost: unitCost,
            mrp: mrp,
            priceCheckStatus: priceCheckStatus // Mapped from sheet
        };

        if (poMap.has(poNumber)) {
            const po = poMap.get(poNumber)!;
            po.items?.push(item);
            po.qty += qty;
            po.amount += itemAmount;
        } else {
            const newPO: PurchaseOrder = {
                id: poNumber,
                poNumber: poNumber,
                status: status,
                channel: row['Channel Name'] || 'Unknown',
                storeCode: row['Store Code'] || '',
                qty: qty,
                amount: itemAmount,
                orderDate: formatSheetDate(row['PO Date']),
                poEdd: row['PO EDD'] ? formatSheetDate(row['PO EDD']) : undefined,
                poExpiryDate: row['PO Expiry Date'] ? formatSheetDate(row['PO Expiry Date']) : undefined,
                source: 'API',
                items: [item],
                poPdfUrl: row['PO PDF'] || undefined,
                contactVerified: false,
                actionToBeTaken: status === POStatus.NewPO ? 'Upload PO PDF' : 'Review',
                amountReceived: 0,
            };

            // Smart Actions based on data presence
            if (newPO.poPdfUrl && newPO.status === POStatus.NewPO) {
                // If PDF is already linked in sheet, maybe move to next step or mark as ready
                 newPO.actionToBeTaken = 'Verify POC';
            }
            if (newPO.status === POStatus.BelowThreshold) {
                newPO.actionToBeTaken = 'Review Threshold';
            }

            poMap.set(poNumber, newPO);
        }
    });

    return Array.from(poMap.values());
};

const transformSheetDataToChannelConfigs = (rows: any[]): ChannelConfig[] => {
    return rows.map((row) => ({
        id: row['Channel Name'] || 'unknown',
        channelName: row['Channel Name'] || '',
        status: row['Status'] === 'Active' ? 'Active' : 'Inactive',
        sourceEmail: row['Source Email'] || '',
        searchKeyword: row['Search Keyword'] || '',
        minOrderThreshold: Number(row['Min Order Threshold'] || 0),
        pocName: row['POC Name'] || '',
        pocEmail: row['POC Email'] || '',
        pocPhone: row['POC Phone'] || '',
    }));
};

