function saveSystemConfig(data) {
  let sheet = SpreadsheetApp.getActiveSpreadsheet().getSheetByName(SHEET_SYSTEM_CONFIG);
  if (!sheet) {
    sheet = SpreadsheetApp.getActiveSpreadsheet().insertSheet(SHEET_SYSTEM_CONFIG);
    sheet.appendRow(['Key', 'Value']);
  }

  const configs = {
    'easyecom_url': data.easyecom_url,
    'easyecom_token': data.easyecom_token,
    'easyecom_email': data.easyecom_email
  };

  const existingData = sheet.getDataRange().getValues();

  Object.keys(configs).forEach(key => {
    let found = false;
    for (let i = 1; i < existingData.length; i++) {
      if (existingData[i][0] === key) {
        sheet.getRange(i + 1, 2).setValue(configs[key]);
        found = true;
        break;
      }
    }
    if (!found) {
      sheet.appendRow([key, configs[key]]);
    }
  });

  return responseJSON({status: 'success', message: 'System configuration saved'});
}

function pushToEasyEcom(data) {
  // 1. Get Credentials
  let configSheet = SpreadsheetApp.getActiveSpreadsheet().getSheetByName(SHEET_SYSTEM_CONFIG);
  let config = {};
  if (configSheet) {
    let rows = configSheet.getDataRange().getValues();
    for (let i = 1; i < rows.length; i++) {
      config[rows[i][0]] = rows[i][1];
    }
  }

  // 2. Fetch Customer Details from EE_Customers
  const customerSheet = SpreadsheetApp.getActiveSpreadsheet().getSheetByName(SHEET_EE_CUSTOMERS);
  if (!customerSheet) {
      logToQueue(data, "Error", "Sheet '" + SHEET_EE_CUSTOMERS + "' not found.");
      return responseJSON({status: 'error', message: 'Sheet "' + SHEET_EE_CUSTOMERS + '" not found.'});
  }

  const customerData = getDataAsJSON(customerSheet);
  // Find customer by Store Code (Case-insensitive trim match)
  const customer = customerData.find(c => 
    String(c['Store Code'] || '').trim().toLowerCase() === String(data.storeCode || '').trim().toLowerCase()
  );

  if (!customer) {
      const msg = `Customer details not found for Store Code: ${data.storeCode}`;
      logToQueue(data, {}, "Error", msg);
      return responseJSON({status: 'error', message: msg});
  }

  // 3. Construct Payload
  // Mapping headers from EE_Customers to API fields.
  // Assumes headers: Customer Name, Contact Person, Email, Phone, Address Line 1, Address Line 2, City, State, Pincode, GST Number
  const payload = {
    reference_code: data.poNumber,
    order_type: "B2B", 
    order_date: new Date().toISOString().split('T')[0], 
    customer_name: customer['Customer Name'] || data.channel,
    customer_email: customer['Email'] || "",
    customer_contact: customer['Phone'] || "",
    shipping_address: {
        type: "shipping",
        name: customer['Contact Person'] || customer['Customer Name'],
        line_1: customer['Address Line 1'] || "",
        line_2: customer['Address Line 2'] || "",
        city: customer['City'] || "",
        state: customer['State'] || "",
        country: "India",
        pincode: String(customer['Pincode'] || ""),
        phone: String(customer['Phone'] || "")
    },
    billing_address: {
        type: "billing",
        name: customer['Contact Person'] || customer['Customer Name'],
        line_1: customer['Address Line 1'] || "",
        line_2: customer['Address Line 2'] || "",
        city: customer['City'] || "",
        state: customer['State'] || "",
        country: "India",
        pincode: String(customer['Pincode'] || ""),
        phone: String(customer['Phone'] || ""),
        gstin: customer['GST Number'] || ""
    },
    // Map selected PO items
    order_items: data.items.map(item => ({
      sku: item.masterSku || item.articleCode, // Prefer Master SKU, fallback to Article
      quantity: Number(item.qty),
      selling_price: Number(item.unitCost || 0),
      tax_inclusive: false 
    }))
  };

  // 4. Send to EasyEcom
  if (config['easyecom_token'] && config['easyecom_url']) {
    try {
      const options = {
        'method': 'post',
        'contentType': 'application/json',
        'headers': {
          'Authorization': 'Bearer ' + config['easyecom_token'] 
        },
        'payload': JSON.stringify(payload),
        'muteHttpExceptions': true
      };

      const response = UrlFetchApp.fetch(config['easyecom_url'], options);
      const resCode = response.getResponseCode();
      const resBody = response.getContentText();

      logToQueue(data, payload, (resCode >= 200 && resCode < 300) ? "Success" : "API Error " + resCode, resBody);

      if (resCode >= 200 && resCode < 300) {
        return responseJSON({status: 'success', message: `Order ${data.poNumber} created in EasyEcom.`});
      } else {
        return responseJSON({status: 'error', message: `EasyEcom API Error: ${resCode}`});
      }
    } catch (e) {
      logToQueue(data, payload, "Exception", e.toString());
      return responseJSON({status: 'error', message: `Script Error: ${e.toString()}`});
    }
  } else {
      logToQueue(data, payload, "Skipped", "Missing Credentials in System_Config");
      return responseJSON({status: 'error', message: "EasyEcom credentials missing in System_Config sheet."});
  }
}

function logToQueue(data, payload, status, response) {
  let sheet = SpreadsheetApp.getActiveSpreadsheet().getSheetByName(SHEET_EASYECOM_QUEUE);
  if (!sheet) {
    sheet = SpreadsheetApp.getActiveSpreadsheet().insertSheet(SHEET_EASYECOM_QUEUE);
    sheet.appendRow(['Timestamp', 'PO Number', 'Store', 'Payload', 'Status', 'Response']);
  }
  const timestamp = new Date();
  sheet.appendRow([timestamp, data.poNumber, data.storeCode, JSON.stringify(payload), status, response]);
}

