const SHEET_EASYECOM_QUEUE = "EasyEcom_Queue"; // Logging
const SHEET_EE_CUSTOMERS = "EE_Customers"; // Customer Database

// --- API CONFIG ---
const EASYECOM_API_URL = "https://api.easyecom.io/orders/create"; 

// Handle GET requests (Fetching Data)
function doGet(e) {
  const action = e.parameter.action;

  if (action === 'getPurchaseOrders') {
    return getPurchaseOrders();
  } else if (action === 'getInventory') {
    return getInventory();
  } else if (action === 'getChannelConfigs') {
    return getChannelConfigs();
  } else if (action === 'getCostPrices') {
    return getCostPrices();
  }

  return responseJSON({status: 'error', message: 'Invalid action'});
}

// Handle POST requests (Creating/Updating Data)
function doPost(e) {
  try {
    const data = JSON.parse(e.postData.contents);
    const action = data.action;

    if (action === 'createItem') {
      return createInventoryItem(data);
    } else if (action === 'updatePrice') {
      return updateInventoryPrice(data);
    } else if (action === 'saveChannelConfig') {
      return saveChannelConfig(data);
    } else if (action === 'pushToEasyEcom') {
      return pushToEasyEcom(data);
    }

    return responseJSON({status: 'error', message: 'Invalid action'});
  } catch (error) {
    return responseJSON({status: 'error', message: error.toString()});
  }
}

