                                                        {/* Header Section for Dates and Customer */}
                                                        <div className="grid grid-cols-1 md:grid-cols-4 gap-6 mb-6 pb-6 border-b border-gray-100">
                                                            <div>
                                                                <span className="text-xs font-semibold text-gray-500 uppercase tracking-wider block mb-1">PO EDD</span>
                                                                <span className="text-sm font-medium text-gray-900">{po.poEdd || '-'}</span>
                                                            </div>
                                                            <div>
                                                                <span className="text-xs font-semibold text-gray-500 uppercase tracking-wider block mb-1">PO Expiry Date</span>
                                                                <span className="text-sm font-medium text-gray-900">{po.poExpiryDate || '-'}</span>
