const SHEET_PO = "PO_Database";
const SHEET_INVENTORY = "Master_SKU_Mapping";
const SHEET_CHANNEL_CONFIG = "Channel_Config";
const SHEET_SHIPMENT_LOG = "EE Shipment Log"; // Logging
const SHEET_EE_CUSTOMERS = "EE_Customers"; // Customer Database

// --- API CONFIG ---
const EASYECOM_API_URL = "https://api.easyecom.io/orders/create"; 

// Handle GET requests (Fetching Data)
function doGet(e) {
  const action = e.parameter.action;

  if (action === 'getPurchaseOrders') {
    return getPurchaseOrders();
  } else if (action === 'getInventory') {
    return getInventory();
  } else if (action === 'getChannelConfigs') {
    return getChannelConfigs();
  } else if (action === 'getCostPrices') {
    return getCostPrices();
  }

  return responseJSON({status: 'error', message: 'Invalid action'});
}

// Handle POST requests (Creating/Updating Data)
function doPost(e) {
  try {
    const data = JSON.parse(e.postData.contents);
    const action = data.action;

    if (action === 'createItem') {
      return createInventoryItem(data);
    } else if (action === 'updatePrice') {
      return updateInventoryPrice(data);
    } else if (action === 'saveChannelConfig') {
      return saveChannelConfig(data);
    } else if (action === 'pushToEasyEcom') {
      return pushToEasyEcom(data);
    }

    return responseJSON({status: 'error', message: 'Invalid action'});
  } catch (error) {
    return responseJSON({status: 'error', message: error.toString()});
  }
}

// --- Data Fetching Functions ---

function getPurchaseOrders() {
  const sheet = SpreadsheetApp.getActiveSpreadsheet().getSheetByName(SHEET_PO);
  if (!sheet) return responseJSON({status: 'error', message: 'Sheet "' + SHEET_PO + '" not found.'});
  const data = getDataAsJSON(sheet);
  return responseJSON({status: 'success', data: data});
}

function getInventory() {
  const sheet = SpreadsheetApp.getActiveSpreadsheet().getSheetByName(SHEET_INVENTORY);
  if (!sheet) return responseJSON({status: 'error', message: 'Sheet "' + SHEET_INVENTORY + '" not found.'});
  const data = getDataAsJSON(sheet);
  return responseJSON({status: 'success', data: data});
}

function getChannelConfigs() {
  const sheet = SpreadsheetApp.getActiveSpreadsheet().getSheetByName(SHEET_CHANNEL_CONFIG);
  if (!sheet) return responseJSON({status: 'error', message: 'Sheet "' + SHEET_CHANNEL_CONFIG + '" not found.'});
  const data = getDataAsJSON(sheet);
  return responseJSON({status: 'success', data: data});
}

function getCostPrices() {
  // Placeholder for external sheet logic
  return responseJSON({status: 'success', data: []});
}

// --- Data Modification Functions ---

function createInventoryItem(data) {
  const sheet = SpreadsheetApp.getActiveSpreadsheet().getSheetByName(SHEET_INVENTORY);
  if (!sheet) return responseJSON({status: 'error', message: 'Sheet "' + SHEET_INVENTORY + '" not found.'});
  sheet.appendRow([
    data.channel, data.articleCode, data.sku, data.spIncTax || 0, data.stock || 0, data.ean || '', data.itemName || '', data.mrp || 0
  ]);
  return responseJSON({status: 'success', message: 'Item created'});
}

function updateInventoryPrice(data) {
  const sheet = SpreadsheetApp.getActiveSpreadsheet().getSheetByName(SHEET_INVENTORY);
  if (!sheet) return responseJSON({status: 'error', message: 'Sheet "' + SHEET_INVENTORY + '" not found.'});
  const rows = sheet.getDataRange().getValues();
  if (rows.length < 1) return responseJSON({status: 'error', message: 'Sheet is empty'});
  const headers = rows[0].map(h => String(h).toLowerCase().trim());

  const colChannel = headers.indexOf('channel');
  let colArticle = headers.indexOf('channel item code');
  if (colArticle === -1) colArticle = headers.findIndex(h => h.includes('item code') || h.includes('article'));
  let colPrice = headers.indexOf('selling price');
  if (colPrice === -1) colPrice = headers.findIndex(h => h.includes('selling') || h.includes('sp'));

  if (colChannel === -1 || colArticle === -1 || colPrice === -1) return responseJSON({status: 'error', message: 'Columns not found'});

  for (let i = 1; i < rows.length; i++) {
    const rowChannel = String(rows[i][colChannel]).trim();
    const rowArticle = String(rows[i][colArticle]).trim();
    if (rowChannel.toLowerCase() === data.channel.toLowerCase() && rowArticle === String(data.articleCode)) {
      sheet.getRange(i + 1, colPrice + 1).setValue(data.newPrice);
      return responseJSON({status: 'success', message: 'Price updated'});
    }
  }
  return responseJSON({status: 'error', message: 'Item not found'});
}

function saveChannelConfig(data) {
  const sheet = SpreadsheetApp.getActiveSpreadsheet().getSheetByName(SHEET_CHANNEL_CONFIG);
  if (!sheet) return responseJSON({status: 'error', message: `Sheet "${SHEET_CHANNEL_CONFIG}" not found.`});

  const rows = sheet.getDataRange().getValues();
  if (rows.length === 0) return responseJSON({status: 'error', message: 'Sheet is empty'});

  const headers = rows[0].map(h => String(h).toLowerCase().trim());
  const nameIdx = headers.indexOf('channel name');
  if (nameIdx === -1) return responseJSON({status: 'error', message: 'Header "Channel Name" not found.'});

  let rowIndex = -1;
  for (let i = 1; i < rows.length; i++) {
    if (String(rows[i][nameIdx]).toLowerCase() === data.channelName.toLowerCase()) {
      rowIndex = i + 1;
      break;
    }
  }

  const getCol = (name) => {
    const idx = headers.findIndex(h => h === name.toLowerCase());
    return idx === -1 ? -1 : idx + 1;
  };

  const colStatus = getCol('Status');
  const colEmail = getCol('Source Email');
  const colKeyword = getCol('Search Keyword');
  const colThreshold = getCol('Min Order Threshold');
  const colPocName = getCol('POC Name');
  const colPocEmail = getCol('POC Email');
  const colPocPhone = getCol('POC Phone');

  if (rowIndex > 0) {
    if (colStatus > 0) sheet.getRange(rowIndex, colStatus).setValue(data.status);
    if (colEmail > 0) sheet.getRange(rowIndex, colEmail).setValue(data.sourceEmail);
    if (colKeyword > 0) sheet.getRange(rowIndex, colKeyword).setValue(data.searchKeyword);
    if (colThreshold > 0) sheet.getRange(rowIndex, colThreshold).setValue(data.minOrderThreshold);
    if (colPocName > 0) sheet.getRange(rowIndex, colPocName).setValue(data.pocName);
    if (colPocEmail > 0) sheet.getRange(rowIndex, colPocEmail).setValue(data.pocEmail);
    if (colPocPhone > 0) sheet.getRange(rowIndex, colPocPhone).setValue(data.pocPhone);
    return responseJSON({status: 'success', message: 'Channel updated'});
  } else {
    const newRow = new Array(headers.length).fill('');
    if (nameIdx > -1) newRow[nameIdx] = data.channelName;
    if (colStatus > -1) newRow[colStatus-1] = data.status;
    if (colEmail > -1) newRow[colEmail-1] = data.sourceEmail;
    if (colKeyword > -1) newRow[colKeyword-1] = data.searchKeyword;
    if (colThreshold > -1) newRow[colThreshold-1] = data.minOrderThreshold;
    if (colPocName > -1) newRow[colPocName-1] = data.pocName;
    if (colPocEmail > -1) newRow[colPocEmail-1] = data.pocEmail;
    if (colPocPhone > -1) newRow[colPocPhone-1] = data.pocPhone;
    sheet.appendRow(newRow);
    return responseJSON({status: 'success', message: 'Channel created'});
  }
}

function pushToEasyEcom(data) {
  // 1. Credentials (from Script Properties)
  const props = PropertiesService.getScriptProperties();
  const rawToken = props.getProperty('EASY_ECOM_API_KEY');
  const rawLocationKey = props.getProperty('EASY_ECOM_LOCATION_KEY');

  const token = rawToken ? rawToken.trim() : null;
  const locationKey = rawLocationKey ? rawLocationKey.trim() : null;

  const url = EASYECOM_API_URL;

  // 2. Validate Customer ID from PO Data
  if (!data.eeCustomerId) {
      logToQueue(data, {}, "Error", "EE Customer ID is missing on PO.");
      return responseJSON({status: 'error', message: 'EE Customer ID is missing for this PO.'});
  }

  // 3. Fetch Customer Details from EE_Customers Sheet
  const customerSheet = SpreadsheetApp.getActiveSpreadsheet().getSheetByName(SHEET_EE_CUSTOMERS);
  if (!customerSheet) {
      logToQueue(data, {}, "Error", "Sheet '" + SHEET_EE_CUSTOMERS + "' not found.");
      return responseJSON({status: 'error', message: 'Sheet "' + SHEET_EE_CUSTOMERS + '" not found.'});
  }

  const customerData = getDataAsJSON(customerSheet);
  // Find customer by EE B2B Customer ID (mapped from PO Card)
  const customer = customerData.find(c => 
    String(c['Customer ID'] || '').trim() === String(data.eeCustomerId || '').trim()
  );

  if (!customer) {
      const msg = `Customer details not found for ID: ${data.eeCustomerId}`;
      logToQueue(data, {}, "Error", msg);
      return responseJSON({status: 'error', message: msg});
  }

  // 4. Construct Payload
  // Use orderDate from PO (which comes from PO_Database), or default to today
  const orderDateObj = new Date(data.orderDate);
  const orderDateStr = isNaN(orderDateObj.getTime()) ? new Date().toISOString().split('T')[0] : orderDateObj.toISOString().split('T')[0];

  const payload = {
    reference_code: data.poNumber,
    order_type: "B2B", 
    location_key: locationKey || "", 
    order_date: orderDateStr, 

    // Mapped Customer Fields
    customer_name: customer['Company Name'] || data.channel,
    customer_email: customer['Support email'] || "",
    customer_contact: String(customer['Support contact'] || ""),

    shipping_address: {
        type: "shipping",
        name: customer['Company Name'],
        line_1: customer['Billing Street'] || "",
        line_2: "",
        city: customer['Billing City'] || "",
        state: customer['Billing State'] || "",
        country: customer['Billing Country'] || "India", // Mapped from "EE PO Status" requirement
        pincode: String(customer['Billing Zip'] || ""),
        phone: String(customer['Support contact'] || "")
    },
    billing_address: {
        type: "billing",
        name: customer['Company Name'],
        line_1: customer['Billing Street'] || "",
        line_2: "",
        city: customer['Billing City'] || "",
        state: customer['Billing State'] || "",
        country: customer['Billing Country'] || "India",
        pincode: String(customer['Billing Zip'] || ""),
        phone: String(customer['Support contact'] || ""),
        gstin: customer['GST Number'] || "" 
    },

    // Map selected PO items
    order_items: data.items.map(item => ({
      sku: item.masterSku || item.articleCode, // "EE SKU - Master SKU - PODB"
      quantity: Number(item.qty), // "Qty - Qty - PODB"
      selling_price: Number(item.unitCost || 0), // "Rate - Unit Cost (Tax Exclusive) - PODB"
      tax_inclusive: false 
    }))
  };

  // 5. Send to EasyEcom
  if (token) {
    try {
      const options = {
        'method': 'post',
        'contentType': 'application/json',
        'headers': {
          'Authorization': 'Bearer ' + token 
        },
        'payload': JSON.stringify(payload),
        'muteHttpExceptions': true
      };

      const response = UrlFetchApp.fetch(url, options);
      const resCode = response.getResponseCode();
      const resBody = response.getContentText();

      const statusStr = (resCode >= 200 && resCode < 300) ? "Success" : "API Error " + resCode;
      logToQueue(data, payload, statusStr, resBody);

      if (resCode >= 200 && resCode < 300) {
        return responseJSON({status: 'success', message: `Order ${data.poNumber} created in EasyEcom.`});
      } else {
        return responseJSON({status: 'error', message: `EasyEcom API Error: ${resCode}`});
      }
    } catch (e) {
      logToQueue(data, payload, "Exception", e.toString());
      return responseJSON({status: 'error', message: `Script Error: ${e.toString()}`});
    }
  } else {
      logToQueue(data, payload, "Skipped", "Missing Credentials");
      return responseJSON({status: 'error', message: "EASY_ECOM_API_KEY is missing in Script Properties. Run _storeAllCredentials() first."});
  }
}

function logToQueue(data, payload, status, response) {
  let sheet = SpreadsheetApp.getActiveSpreadsheet().getSheetByName(SHEET_SHIPMENT_LOG);
  if (!sheet) {
    sheet = SpreadsheetApp.getActiveSpreadsheet().insertSheet(SHEET_SHIPMENT_LOG);
    sheet.appendRow(['Timestamp', 'PO Number', 'Store', 'Customer ID', 'Payload', 'Status', 'Response']);
  }
  const timestamp = new Date();
  sheet.appendRow([timestamp, data.poNumber, data.storeCode, data.eeCustomerId || 'N/A', JSON.stringify(payload), status, response]);
}

// --- Helpers ---

function getDataAsJSON(sheet) {
  const rawData = sheet.getDataRange().getValues();
  if (rawData.length === 0) return [];

  const headers = rawData[0];
  const data = [];

  for (let i = 1; i < rawData.length; i++) {
    const row = rawData[i];
    if (row[0] === "" && row[1] === "") continue;
    const obj = {};
    for (let j = 0; j < headers.length; j++) {
      obj[headers[j]] = row[j];
    }
    data.push(obj);
  }
  return data;
}

function responseJSON(data) {
  return ContentService.createTextOutput(JSON.stringify(data)).setMimeType(ContentService.MimeType.JSON);
}

