// --- Main EasyEcom Push Logic ---

function pushToEasyEcom(data) {
  // 1. Calculate PO Reference (Handle Suffix for Partials)
  let poRef = data.poNumber;
  if (data.isPartial) {
    poRef = getNextPoVariant(data.poNumber);
  }

  // 2. Format Items as requested: { Sku, Quantity, Price }
  const formattedItems = data.items.map(item => ({
    "Sku": item.masterSku || item.articleCode,
    "Quantity": Number(item.qty),
    "Price": Number(item.unitCost || 0)
  }));

  // 3. Call the order creation function
  // Passing 'data' as context for extra fields like orderDate, channel
  return createEasyEcomB2BOrder(poRef, data.eeCustomerId, formattedItems, data);
}

function getNextPoVariant(basePoNumber) {
  const sheet = SpreadsheetApp.getActiveSpreadsheet().getSheetByName(SHEET_SHIPMENT_LOG);
  if (!sheet) return basePoNumber + "-1"; // First partial if sheet doesn't exist

  const lastRow = sheet.getLastRow();
  if (lastRow < 2) return basePoNumber + "-1"; // No data

  // Get PO Number column (Column 2)
  const poNumbers = sheet.getRange(2, 2, lastRow - 1, 1).getValues().flat();

  let maxSuffix = 0;
  // Escape basePoNumber for regex safety
  const escapedBase = basePoNumber.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'); 
  const regex = new RegExp(`^${escapedBase}-(\\d+)$`, 'i');

  poNumbers.forEach(po => {
    const strPo = String(po);
    const match = strPo.match(regex);
    if (match) {
      const suffix = parseInt(match[1], 10);
      if (suffix > maxSuffix) maxSuffix = suffix;
    }
  });

  return basePoNumber + "-" + (maxSuffix + 1);
}

function createEasyEcomB2BOrder(poRef, customerId, items, contextData) {
  // 1. Credentials
  const props = PropertiesService.getScriptProperties();
  const token = props.getProperty('EASY_ECOM_API_KEY');
  const locationKey = props.getProperty('EASY_ECOM_LOCATION_KEY');

  if (!token) return responseJSON({status: 'error', message: "Missing EASY_ECOM_API_KEY"});

  // 2. Lookup Customer
  if (!customerId) return responseJSON({status: 'error', message: "Missing EE Customer ID"});

  const customerSheet = SpreadsheetApp.getActiveSpreadsheet().getSheetByName(SHEET_EE_CUSTOMERS);
  if (!customerSheet) return responseJSON({status: 'error', message: "Sheet " + SHEET_EE_CUSTOMERS + " not found"});

  const customerData = getDataAsJSON(customerSheet);
  const customer = customerData.find(c => String(c['Customer ID']).trim() === String(customerId).trim());

  if (!customer) return responseJSON({status: 'error', message: "Customer not found for ID: " + customerId});

  // 3. Construct Payload
  // Parse order date from context or default to today
  const orderDateObj = new Date(contextData.orderDate);
  const orderDateStr = isNaN(orderDateObj.getTime()) ? new Date().toISOString().split('T')[0] : orderDateObj.toISOString().split('T')[0];

  const payload = {
    reference_code: poRef,
    order_type: "B2B",
    location_key: locationKey || "",
    order_date: orderDateStr,

    customer_name: customer['Company Name'] || contextData.channel,
    customer_email: customer['Support email'] || "",
    customer_contact: String(customer['Support contact'] || ""),

    shipping_address: {
        type: "shipping",
        name: customer['Company Name'],
        line_1: customer['Billing Street'] || "",
        line_2: "",
        city: customer['Billing City'] || "",
        state: customer['Billing State'] || "",
        country: customer['Billing Country'] || "India",
        pincode: String(customer['Billing Zip'] || ""),
        phone: String(customer['Support contact'] || "")
    },
    billing_address: {
        type: "billing",
        name: customer['Company Name'],
        line_1: customer['Billing Street'] || "",
        line_2: "",
        city: customer['Billing City'] || "",
        state: customer['Billing State'] || "",
        country: customer['Billing Country'] || "India",
        pincode: String(customer['Billing Zip'] || ""),
        phone: String(customer['Support contact'] || ""),
        gstin: customer['GST Number'] || "" 
    },

    // Items provided in {Sku, Quantity, Price} format
    order_items: items.map(item => ({
      sku: item.Sku,
      quantity: item.Quantity,
      selling_price: item.Price,
      tax_inclusive: false 
    }))
  };

  // 4. API Call
  try {
      const options = {
        'method': 'post',
        'contentType': 'application/json',
        'headers': { 'Authorization': 'Bearer ' + token },
        'payload': JSON.stringify(payload),
        'muteHttpExceptions': true
      };

      const response = UrlFetchApp.fetch(EASYECOM_API_URL, options);
      const resCode = response.getResponseCode();
      const resBody = response.getContentText();

      // Log using the calculated poRef
      logToQueue({...contextData, poNumber: poRef}, payload, (resCode >= 200 && resCode < 300) ? "Success" : "API Error " + resCode, resBody);

      if (resCode >= 200 && resCode < 300) {
        return responseJSON({status: 'success', message: `Order ${poRef} created in EasyEcom.`});
      } else {
        return responseJSON({status: 'error', message: `EasyEcom API Error: ${resCode}`});
      }
  } catch (e) {
      logToQueue({...contextData, poNumber: poRef}, payload, "Exception", e.toString());
      return responseJSON({status: 'error', message: `Script Error: ${e.toString()}`});
  }
}

function logToQueue(data, payload, status, response) {
  let sheet = SpreadsheetApp.getActiveSpreadsheet().getSheetByName(SHEET_SHIPMENT_LOG);
  if (!sheet) {
    sheet = SpreadsheetApp.getActiveSpreadsheet().insertSheet(SHEET_SHIPMENT_LOG);
    sheet.appendRow(['Timestamp', 'PO Number', 'Store', 'Customer ID', 'Payload', 'Status', 'Response']);
  }
