interface FileUploadModalProps {
    po: PurchaseOrder;
    uploadType: 'PO' | 'POD';
    onClose: () => void;
    onUploadSuccess: (updatedPo: PurchaseOrder) => void;
    addLog: (action: string, details: string) => void;
}

const FileUploadModal: React.FC<FileUploadModalProps> = ({ po, uploadType, onClose, onUploadSuccess, addLog }) => {
    const [file, setFile] = useState<File | null>(null);
    const [error, setError] = useState<string | null>(null);
    const [isUploading, setIsUploading] = useState(false);

    const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        if (e.target.files && e.target.files[0]) {
            setFile(e.target.files[0]);
            setError(null);
        }
    };

    const handleUpload = () => {
        if (!file) {
            setError('Please select a file to upload.');
            return;
        }
        setIsUploading(true);
        setTimeout(() => {
            const updatedPo = {
                ...po,
                ...(uploadType === 'PO' && { poPdfUrl: `path/to/${file?.name}`, actionToBeTaken: 'Verify POC', status: POStatus.POCPending }),
                ...(uploadType === 'POD' && { podImageUrl: `path/to/${file?.name}`, actionToBeTaken: undefined, status: POStatus.Closed }),
            };
            onUploadSuccess(updatedPo);
            addLog('Upload', `Uploaded ${uploadType} document for PO ${po.poNumber}`);
            setIsUploading(false);
            onClose();
        }, 1500);
    };

    return (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
            <div className="bg-white rounded-lg shadow-xl w-full max-w-md">
                <div className="p-6 border-b">
                    <h3 className="text-lg font-semibold text-gray-800">Upload {uploadType} Document</h3>
                    <p className="text-sm text-gray-500 mt-1">For PO: <span className="font-bold text-partners-green">{po.poNumber}</span></p>
                </div>
                <div className="p-6">
                    <div className="border-2 border-dashed border-gray-300 rounded-lg p-8 text-center bg-gray-50">
                        <UploadIcon className="mx-auto h-12 w-12 text-gray-400" />
                        <label className="mt-4 block text-sm font-semibold text-partners-green cursor-pointer">
                            {file ? file.name : 'Select a file'}
                            <input type="file" className="sr-only" onChange={handleFileChange} />
                        </label>
                    </div>
                    {error && <div className="mt-3 text-sm text-red-600">{error}</div>}
                </div>
                <div className="px-6 py-4 bg-gray-50 flex justify-end gap-3 rounded-b-lg">
                    <button onClick={onClose} className="px-4 py-2 text-sm font-medium text-gray-700 bg-white border rounded-md">Cancel</button>
                    <button onClick={handleUpload} disabled={isUploading || !file} className="px-4 py-2 text-sm font-medium text-white bg-partners-green rounded-md">
                        {isUploading ? 'Uploading...' : 'Upload File'}
                    </button>
                </div>
            </div>
        </div>
    );
};

