const SalesOrderTable: React.FC<SalesOrderTableProps> = ({ activeFilter, setActiveFilter, purchaseOrders, setPurchaseOrders, tabCounts, addLog, addNotification, onSync, isSyncing }) => {
    const [filteredOrders, setFilteredOrders] = useState<PurchaseOrder[]>([]);
    const [expandedRowId, setExpandedRowId] = useState<string | null>(null);
    const [selectedPoItems, setSelectedPoItems] = useState<{ [key: string]: string[] }>({});
    const [pushingToEasyEcom, setPushingToEasyEcom] = useState<{ [key: string]: boolean }>({});

    const tabs = [
        { name: 'All POs' }, { name: 'In-Transit' }, { name: 'GRN Pending' }, { name: 'GRN Updated' }, { name: 'RTO' }, { name: 'Closed' },
    ];

    useEffect(() => {
        let orders = [...purchaseOrders];
        if (activeFilter !== 'All POs') {
            const filterMapping: { [key: string]: POStatus } = {
                'In-Transit': POStatus.InTransit, 'GRN Pending': POStatus.GRNPending, 'GRN Updated': POStatus.GRNUpdated,
                'RTO': POStatus.RTO, 'Closed': POStatus.Closed,
            };
            const statusToFilter = filterMapping[activeFilter];
            if (statusToFilter) orders = orders.filter(po => po.status === statusToFilter);
        }
        setFilteredOrders(orders);
    }, [activeFilter, purchaseOrders]);

    const toggleRowExpansion = (poId: string) => setExpandedRowId(expandedRowId === poId ? null : poId);

    const handleItemSelect = (poId: string, articleCode: string) => {
        setSelectedPoItems(prev => {
            const currentSelected = prev[poId] || [];
            const isSelected = currentSelected.includes(articleCode);
            return { ...prev, [poId]: isSelected ? currentSelected.filter(code => code !== articleCode) : [...currentSelected, articleCode] };
        });
    };

    const handleSelectAllItems = (po: PurchaseOrder) => {
        const selectableArticleCodes = (po.items || []).filter(i => !i.eeOrderRefId).map(item => item.articleCode);
        const currentSelected = selectedPoItems[po.id] || [];
        const allSelected = selectableArticleCodes.length > 0 && currentSelected.length === selectableArticleCodes.length;
        setSelectedPoItems(prev => ({ ...prev, [po.id]: allSelected ? [] : selectableArticleCodes }));
    };

    const handlePushToEasyEcom = async (po: PurchaseOrder) => {
        const selected = selectedPoItems[po.id] || [];
        if (selected.length === 0) return;
        setPushingToEasyEcom(prev => ({ ...prev, [po.id]: true }));
        try {
            const res = await pushToEasyEcom(po, selected);
            if (res.status === 'success') {
                addNotification(res.message, 'success');
                addLog('EasyEcom Sync', `Pushed ${selected.length} items from ${po.poNumber} to EasyEcom.`);
                setSelectedPoItems(prev => ({ ...prev, [po.id]: [] }));
                onSync();
            } else {
                addNotification('Failed: ' + res.message, 'error');
            }
        } catch (e) {
            addNotification('Network error pushing to EasyEcom', 'error');
        } finally {
            setPushingToEasyEcom(prev => ({ ...prev, [po.id]: false }));
        }
    };

    return (
        <div className="bg-white p-6 rounded-xl shadow-sm">
            <div className="flex flex-col md:flex-row justify-between items-center gap-4 mb-6">
                <div className="flex flex-wrap items-center gap-2">
                    {tabs.map(tab => (
                        <button key={tab.name} onClick={() => setActiveFilter(tab.name)}
                            className={`px-3 py-1.5 text-sm font-semibold rounded-full border transition-colors ${
                                activeFilter === tab.name ? 'bg-partners-green text-white border-partners-green' : 'bg-white text-gray-600 border-partners-border hover:bg-gray-50'
                            }`}
                        >
                            {tab.name} {tabCounts[tab.name] > 0 && <span className="ml-1 text-xs opacity-80">({tabCounts[tab.name]})</span>}
                        </button>
                    ))}
                </div>
                <button onClick={onSync} disabled={isSyncing} className="flex items-center gap-2 px-3 py-2 text-sm font-medium text-white bg-blue-600 rounded-lg">
                    <CloudDownloadIcon className={`h-4 w-4 ${isSyncing ? 'animate-bounce' : ''}`} /> Sync Data
                </button>
            </div>

            <div className="mt-6 overflow-x-auto">
                <table className="w-full text-sm text-left text-gray-600">
                    <thead className="text-xs text-gray-700 uppercase bg-gray-50">
                        <tr>
                            <th className="p-4 w-4"></th>
                            <th className="px-6 py-3">Sales Order #</th>
                            <th className="px-6 py-3">Status</th>
                            <th className="px-6 py-3">Channel</th>
                            <th className="px-6 py-3">Store</th>
                            <th className="px-6 py-3">Qty / Amt</th>
                            <th className="px-6 py-3">Order Date</th>
                            <th className="px-6 py-3 text-center">Action</th>
                        </tr>
                    </thead>
                    <tbody>
                        {filteredOrders.map((po) => {
                            const isExpanded = expandedRowId === po.id;
                            const poSelectedItems = selectedPoItems[po.id] || [];
                            const selectableItems = (po.items || []).filter(i => !i.eeOrderRefId);
                            const allSelectableSelected = selectableItems.length > 0 && poSelectedItems.length === selectableItems.length;

                            return (
                                <Fragment key={po.id}>
                                    <tr className={`border-b hover:bg-gray-50 cursor-pointer ${isExpanded ? 'bg-gray-50' : 'bg-white'}`} onClick={() => toggleRowExpansion(po.id)}>
                                        <td className="p-4 text-center">
                                            <div className="text-gray-400 hover:text-partners-green">
                                                {isExpanded ? <ChevronDownIcon /> : <ChevronRightIcon />}
                                            </div>
                                        </td>
                                        <td className="px-6 py-4 font-medium text-partners-green whitespace-nowrap">{po.poNumber}</td>
                                        <td className="px-6 py-4"><StatusBadge status={po.status} /></td>
                                        <td className="px-6 py-4">{po.channel}</td>
                                        <td className="px-6 py-4">{po.storeCode}</td>
                                        <td className="px-6 py-4">{po.qty} / ₹{po.amount.toLocaleString('en-IN')}</td>
                                        <td className="px-6 py-4 whitespace-nowrap">{po.orderDate}</td>
                                        <td className="px-6 py-4 text-center" onClick={(e) => e.stopPropagation()}>
                                            <button className="text-gray-400 hover:text-gray-600 p-1">
                                                <DotsVerticalIcon className="h-4 w-4" />
                                            </button>
                                        </td>
                                    </tr>
                                    {isExpanded && (
                                        <tr className="bg-gray-50">
                                            <td colSpan={8} className="px-4 py-6 sm:px-12">
                                                <div className="bg-white border border-gray-200 rounded-lg p-6 shadow-sm space-y-6">
                                                    {(po.eeReferenceCode || po.eeOrderId) && (
                                                        <div className="bg-blue-50 border border-blue-100 p-4 rounded-lg">
                                                            <h4 className="text-sm font-bold text-blue-800 flex items-center gap-2 mb-3">
                                                                <GlobeIcon className="h-4 w-4" /> EasyEcom Stats
                                                            </h4>
                                                            <div className="grid grid-cols-2 md:grid-cols-4 gap-4 text-[10px]">
                                                                <div><p className="text-gray-400 uppercase">Ref</p><p className="font-bold">{po.eeReferenceCode || '-'}</p></div>
                                                                <div><p className="text-gray-400 uppercase">Status</p><p className="font-bold text-blue-600">{po.eeOrderStatus || 'Processing'}</p></div>
                                                                <div><p className="text-gray-400 uppercase">Manifest</p><p className="font-bold">{po.eeManifestDate || '-'}</p></div>
                                                                <div><p className="text-gray-400 uppercase">Invoice</p><p className="font-bold">{po.eeInvoiceDate || '-'}</p></div>
                                                            </div>
                                                        </div>
                                                    )}
                                                    <div>
                                                        <h4 className="text-sm font-bold text-gray-800 flex items-center gap-2 mb-4">
                                                            <CubeIcon className="h-4 w-4 text-partners-green" /> Line Items
                                                        </h4>
                                                        <div className="overflow-x-auto">
                                                            <table className="w-full text-[11px] text-left">
                                                                <thead className="bg-gray-50 text-gray-500 uppercase">
                                                                    <tr>
                                                                        <th className="py-2 w-8 text-center"><input type="checkbox" className="h-3 w-3" checked={allSelectableSelected} onChange={() => handleSelectAllItems(po)} disabled={selectableItems.length === 0} /></th>
                                                                        <th className="py-2 px-3">SKU</th>
                                                                        <th className="py-2 text-right">Qty</th>
                                                                        <th className="py-2 px-3">Status</th>
                                                                        <th className="py-2">EE Ref</th>
                                                                        <th className="py-2 text-right">Ship/Canc</th>
                                                                    </tr>
                                                                </thead>
                                                                <tbody className="divide-y divide-gray-100">
                                                                    {po.items?.map((item, idx) => (
                                                                        <tr key={idx} className={item.eeOrderRefId ? 'bg-gray-50 text-gray-400' : ''}>
                                                                            <td className="py-2 text-center">
                                                                                {!item.eeOrderRefId ? <input type="checkbox" className="h-3 w-3 text-green-600" checked={poSelectedItems.includes(item.articleCode)} onChange={() => handleItemSelect(po.id, item.articleCode)} /> : <CheckCircleIcon className="h-4 w-4 text-green-500 mx-auto" />}
                                                                            </td>
                                                                            <td className="py-2 px-3 font-medium">{item.masterSku || item.articleCode}</td>
                                                                            <td className="py-2 text-right font-bold">{item.qty}</td>
                                                                            <td className="py-2 px-3">
                                                                                {item.itemStatus ? <span className="bg-blue-100 text-blue-700 px-1 py-0.5 rounded text-[9px] font-bold uppercase">{item.itemStatus}</span> : item.eeOrderRefId ? 'Pushed' : '-'}
                                                                            </td>
                                                                            <td className="py-2 font-mono text-[9px]">{item.eeOrderRefId || '-'}</td>
                                                                            <td className="py-2 text-right">{item.shippedQuantity || 0}/{item.cancelledQuantity || 0}</td>
                                                                        </tr>
                                                                    ))}
                                                                </tbody>
                                                            </table>
                                                        </div>
                                                    </div>
                                                    <div className="flex justify-end pt-4 border-t">
                                                         <button onClick={() => handlePushToEasyEcom(po)} disabled={poSelectedItems.length === 0 || pushingToEasyEcom[po.id]}
                                                            className={`flex items-center gap-2 px-6 py-2 text-xs font-bold text-white rounded-lg transition-all ${poSelectedItems.length > 0 ? 'bg-blue-600 hover:bg-blue-700' : 'bg-gray-300 cursor-not-allowed'}`}
                                                        >
                                                            <UploadIcon className={`h-4 w-4 ${pushingToEasyEcom[po.id] ? 'animate-bounce' : ''}`} />
                                                            {pushingToEasyEcom[po.id] ? 'Processing...' : `Push ${poSelectedItems.length > 0 ? poSelectedItems.length : ''} Items`}
                                                        </button>
                                                    </div>
                                                </div>
                                            </td>
                                        </tr>
                                    )}
                                </Fragment>
                            );
                        })}
                    </tbody>
                </table>
            </div>
        </div>
    );
};

