                                                                        <th className="py-2 px-3">SKU / Item Name</th>
                                                                        <th className="py-2 text-right">Order Qty</th>
                                                                        <th className="py-2 px-3 text-center">Status</th>
                                                                        <th className="py-2">EE Ref ID</th>
                                                                        <th className="py-2 text-right">Ship/Canc Qty</th>
                                                                    </tr>
                                                                </thead>
                                                                <tbody className="divide-y divide-gray-100">
                                                                    {po.items?.map((item, idx) => (
                                                                        <tr key={idx}>
                                                                            <td className="py-3 px-3">
                                                                                <p className="font-medium text-gray-800">{item.masterSku || item.articleCode}</p>
                                                                                <p className="text-[10px] text-gray-400 truncate max-w-[200px]">{item.itemName}</p>
                                                                            </td>
                                                                            <td className="py-3 text-right font-bold text-gray-700">{item.qty}</td>
                                                                            <td className="py-3 px-3 text-center">
                                                                                {item.itemStatus ? (
                                                                                    <span className="bg-green-100 text-green-700 px-1.5 py-0.5 rounded text-[9px] font-bold uppercase">{item.itemStatus}</span>
                                                                                ) : (
                                                                                    <span className="text-gray-400 font-medium italic">{item.eeOrderRefId ? 'Pushed' : 'Not Pushed'}</span>
                                                                                )}
                                                                            </td>
                                                                            <td className="py-3 font-mono text-[9px] text-gray-500">{item.eeOrderRefId || '-'}</td>
                                                                            <td className="py-3 text-right font-bold text-gray-700">
                                                                                <span className="text-green-600">{item.shippedQuantity || 0}</span> / <span className="text-red-600">{item.cancelledQuantity || 0}</span>
                                                                            </td>
                                                                        </tr>
                                                                    ))}
                                                                </tbody>
                                                            </table>
                                                        </div>
                                                    </div>
                                                </div>
                                            </td>
                                        </tr>
                                    )}
                                </Fragment>
                            );
                        })}
                    </tbody>
                </table>
            </div>
        </div>
    );
};

