import React from 'react';
import { POStatus } from '../types';

interface StatusBadgeProps {
  status: POStatus;
}

const StatusBadge: React.FC<StatusBadgeProps> = ({ status }) => {
  const getStatusStyles = () => {
    switch (status) {
      case POStatus.NewPO:
        return 'bg-blue-100 text-blue-800';
      case POStatus.BelowThreshold:
        return 'bg-orange-100 text-orange-800';
      case POStatus.POCPending:
      case POStatus.AppointmentPending:
        return 'bg-yellow-100 text-yellow-800';
      case POStatus.InTransit:
        return 'bg-purple-100 text-purple-800';
      case POStatus.Delivered:
        return 'bg-green-100 text-green-800';
      case POStatus.GRNPending:
        return 'bg-indigo-100 text-indigo-800';
      case POStatus.GRNUpdated:
        return 'bg-pink-100 text-pink-800';
      case POStatus.Closed:
        return 'bg-green-200 text-green-900';
      case POStatus.RTO:
        return 'bg-partners-light-red text-red-700';
      case POStatus.Pushed:
        return 'bg-green-600 text-white shadow-sm';
      case POStatus.PartiallyProcessed:
        return 'bg-amber-500 text-white shadow-sm';
      default:
        return 'bg-gray-100 text-gray-700';
    }
  };

  return (
    <span className={`px-3 py-1 text-[10px] font-bold rounded-full capitalize ${getStatusStyles()}`}>
      {status}
    </span>
  );
};

