import React, { useState, useEffect, Fragment } from 'react';
import { POStatus, type PurchaseOrder, POItem, InventoryItem } from '../types';
import StatusBadge from './StatusBadge';
import { DotsVerticalIcon, ChevronDownIcon, ChevronRightIcon, CloudDownloadIcon, CubeIcon, CheckCircleIcon, UploadIcon, XCircleIcon, InfoIcon } from './icons/Icons';
import { pushToEasyEcom } from '../services/api';

interface PoTableProps {
    activeFilter: string;
    setActiveFilter: (filter: string) => void;
    purchaseOrders: PurchaseOrder[];
    setPurchaseOrders: React.Dispatch<React.SetStateAction<PurchaseOrder[]>>;
    tabCounts: { [key: string]: number };
    addLog: (action: string, details: string) => void;
    addNotification: (message: string, type?: 'info' | 'success' | 'warning' | 'error') => void;
    onSync: () => void;
    isSyncing: boolean;
    inventoryItems?: InventoryItem[];
}

const PoTable: React.FC<PoTableProps> = ({ activeFilter, setActiveFilter, purchaseOrders, tabCounts, onSync, isSyncing, addLog, addNotification }) => {
    const [filteredOrders, setFilteredOrders] = useState<PurchaseOrder[]>([]);
    const [expandedRowId, setExpandedRowId] = useState<string | null>(null);
    const [selectedPoItems, setSelectedPoItems] = useState<{ [key: string]: string[] }>({});
    const [pushingToEasyEcom, setPushingToEasyEcom] = useState<{ [key: string]: boolean }>({});

    const tabs = [
        { name: 'All POs' }, { name: 'New PO' }, { name: 'POC Verification'}, { name: 'Appointment to be taken' },
        { name: 'In-Transit' }, { name: 'GRN Pending' }, { name: 'GRN Updated' }, { name: 'RTO' }, { name: 'Closed' },
    ];

    useEffect(() => {
        let orders = [...purchaseOrders];
        if (activeFilter !== 'All POs') {
            const filterMapping: { [key: string]: POStatus } = {
                'New PO': POStatus.NewPO, 'POC Verification': POStatus.POCPending, 'Appointment to be taken': POStatus.AppointmentPending,
                'In-Transit': POStatus.InTransit, 'GRN Pending': POStatus.GRNPending, 'GRN Updated': POStatus.GRNUpdated,
                'RTO': POStatus.RTO, 'Closed': POStatus.Closed,
            };
            const statusToFilter = filterMapping[activeFilter];
            if (statusToFilter) orders = orders.filter(po => po.status === statusToFilter);
        }
        setFilteredOrders(orders);
    }, [activeFilter, purchaseOrders]);

    const toggleRowExpansion = (poId: string) => setExpandedRowId(expandedRowId === poId ? null : poId);

    const handleItemSelect = (poId: string, articleCode: string) => {
        setSelectedPoItems(prev => {
            const currentSelected = prev[poId] || [];
            const isSelected = currentSelected.includes(articleCode);
            return { ...prev, [poId]: isSelected ? currentSelected.filter(code => code !== articleCode) : [...currentSelected, articleCode] };
        });
    };

    const handleSelectAllItems = (po: PurchaseOrder) => {
        const selectableArticleCodes = (po.items || []).filter(i => !i.eeOrderRefId).map(item => item.articleCode);
        const currentSelected = selectedPoItems[po.id] || [];
        const allSelected = selectableArticleCodes.length > 0 && currentSelected.length === selectableArticleCodes.length;
        setSelectedPoItems(prev => ({ ...prev, [po.id]: allSelected ? [] : selectableArticleCodes }));
    };

    const handlePushToEasyEcom = async (po: PurchaseOrder) => {
        const selected = selectedPoItems[po.id] || [];
        if (selected.length === 0) return;
        setPushingToEasyEcom(prev => ({ ...prev, [po.id]: true }));
        try {
            const res = await pushToEasyEcom(po, selected);
            if (res.status === 'success') {
                addNotification(res.message, 'success');
                addLog('EasyEcom Sync', `Pushed ${selected.length} items from PO ${po.poNumber} to EasyEcom.`);
                setSelectedPoItems(prev => ({ ...prev, [po.id]: [] }));
                onSync();
            } else {
                addNotification('Failed: ' + res.message, 'error');
            }
        } catch (e) {
            addNotification('Network error pushing to EasyEcom', 'error');
        } finally {
            setPushingToEasyEcom(prev => ({ ...prev, [po.id]: false }));
        }
    };

    const getDisplayPoStatus = (po: PurchaseOrder): POStatus => {
        const items = po.items || [];
        const pushedCount = items.filter(i => !!i.eeOrderRefId).length;

        if (items.length > 0 && pushedCount === items.length) {
            return POStatus.Pushed;
        } else if (pushedCount > 0) {
            return POStatus.PartiallyProcessed;
        }
        return po.status;
    };

    return (
        <div className="bg-white p-6 rounded-xl shadow-sm">
            <div className="flex flex-col md:flex-row justify-between items-center gap-4 mb-6">
                <div className="flex flex-wrap items-center gap-2">
                    {tabs.map(tab => (
                        <button key={tab.name} onClick={() => setActiveFilter(tab.name)}
                            className={`px-3 py-1.5 text-sm font-semibold rounded-full border transition-colors ${
                                activeFilter === tab.name ? 'bg-partners-green text-white border-partners-green' : 'bg-white text-gray-600 border-partners-border hover:bg-gray-50'
                            }`}
                        >
                            {tab.name} {tabCounts[tab.name] > 0 && <span className="ml-1 text-xs opacity-80">({tabCounts[tab.name]})</span>}
                        </button>
                    ))}
                </div>
                <button onClick={onSync} disabled={isSyncing} className="flex items-center gap-2 px-3 py-2 text-sm font-medium text-white bg-blue-600 rounded-lg shadow-sm hover:bg-blue-700 active:scale-95 transition-all">
                    <CloudDownloadIcon className={`h-4 w-4 ${isSyncing ? 'animate-bounce' : ''}`} /> Sync Data
                </button>
            </div>

            <div className="mt-6 overflow-x-auto border border-gray-100 rounded-xl shadow-inner">
                <table className="w-full text-sm text-left text-gray-600">
                    <thead className="text-[11px] text-gray-500 uppercase bg-gray-50/50 border-b border-gray-100">
                        <tr>
                            <th className="p-4 w-4"></th>
                            <th className="px-6 py-4">PO Number</th>
                            <th className="px-6 py-4">Status</th>
                            <th className="px-6 py-4">Channel</th>
                            <th className="px-6 py-4">Store</th>
                            <th className="px-6 py-4">Qty / Total (Inc. 5% GST)</th>
                            <th className="px-6 py-4">Order Date</th>
                            <th className="px-6 py-4 text-center">Action</th>
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-gray-100/50">
                        {filteredOrders.map((po) => {
                            const isExpanded = expandedRowId === po.id;
                            const poSelectedItems = selectedPoItems[po.id] || [];
                            const items = po.items || [];
                            const pushedItems = items.filter(i => !!i.eeOrderRefId);
                            const selectableItems = items.filter(i => !i.eeOrderRefId);
                            const allSelectableSelected = selectableItems.length > 0 && poSelectedItems.length === selectableItems.length;
                            const poStatus = getDisplayPoStatus(po);

                            // Calculate amount including 5% tax
                            const amountIncTax = po.amount * 1.05;

                            return (
                                <Fragment key={po.id}>
                                    <tr className={`hover:bg-gray-50/80 cursor-pointer transition-colors ${isExpanded ? 'bg-partners-light-green/30' : 'bg-white'}`} onClick={() => toggleRowExpansion(po.id)}>
                                        <td className="p-4 text-center">
                                            <div className="text-gray-400 hover:text-partners-green transition-colors">
                                                {isExpanded ? <ChevronDownIcon className="h-4 w-4" /> : <ChevronRightIcon className="h-4 w-4" />}
                                            </div>
                                        </td>
                                        <td className="px-6 py-4 font-bold text-partners-green whitespace-nowrap">{po.poNumber}</td>
                                        <td className="px-6 py-4"><StatusBadge status={poStatus} /></td>
                                        <td className="px-6 py-4 font-medium text-gray-700">{po.channel}</td>
                                        <td className="px-6 py-4 text-gray-500">{po.storeCode}</td>
                                        <td className="px-6 py-4 font-bold text-gray-900">{po.qty} / ₹{amountIncTax.toLocaleString('en-IN', { minimumFractionDigits: 0, maximumFractionDigits: 0 })}</td>
                                        <td className="px-6 py-4 whitespace-nowrap text-gray-400">{po.orderDate}</td>
                                        <td className="px-6 py-4 text-center" onClick={(e) => e.stopPropagation()}>
                                            <button className="text-gray-400 hover:text-gray-600 p-2 hover:bg-gray-100 rounded-full transition-colors">
                                                <DotsVerticalIcon className="h-4 w-4" />
                                            </button>
                                        </td>
                                    </tr>
                                    {isExpanded && (
                                        <tr className="bg-gray-50/50">
                                            <td colSpan={8} className="px-4 py-8 sm:px-12">
                                                <div className="bg-white border border-partners-border rounded-xl p-6 space-y-6 shadow-sm ring-1 ring-black/5">
                                                    <div className="flex justify-between items-center border-b border-gray-100 pb-4">
                                                        <h4 className="text-sm font-bold text-gray-800 flex items-center gap-2">
                                                            <CubeIcon className="h-4 w-4 text-partners-green" /> Item List & Fulfillment
                                                        </h4>
                                                        <div className="flex items-center gap-3">
                                                             <span className="text-xs font-semibold text-gray-500 bg-gray-100 px-2 py-1 rounded-md">{poSelectedItems.length} items selected</span>
                                                             {pushedItems.length > 0 && (
                                                                 <span className="text-xs font-bold text-green-600 bg-green-50 px-2 py-1 rounded-md border border-green-100">{pushedItems.length} Processed</span>
                                                             )}
                                                        </div>
                                                    </div>

                                                    <div className="overflow-x-auto border border-gray-100 rounded-lg">
                                                        <table className="w-full text-xs text-left">
                                                            <thead className="bg-gray-50 text-gray-500 uppercase tracking-tight">
                                                                <tr>
                                                                    <th className="py-3 w-8 text-center">
                                                                        <input 
                                                                            type="checkbox" 
                                                                            className="h-3.5 w-3.5 rounded border-gray-300 text-partners-green focus:ring-partners-green cursor-pointer"
                                                                            checked={allSelectableSelected}
                                                                            onChange={() => handleSelectAllItems(po)}
                                                                            disabled={selectableItems.length === 0}
                                                                        />
                                                                    </th>
                                                                    <th className="py-3 px-3">Item Name / SKU</th>
                                                                    <th className="py-3 text-right">PO Qty</th>
                                                                    <th className="py-3 text-right">Fulfillable</th>
                                                                    <th className="py-3 px-3 text-center">Price Check</th>
                                                                    <th className="py-3 text-right">Unit Cost</th>
                                                                    <th className="py-3 text-right">MRP</th>
                                                                    <th className="py-3 text-center">Status</th>
                                                                </tr>
                                                            </thead>
                                                            <tbody className="divide-y divide-gray-100">
                                                                {items.map((item, idx) => {
                                                                    const isMismatch = item.priceCheckStatus === 'Mismatch';
                                                                    const isPushed = !!item.eeOrderRefId;
                                                                    // If some items in the PO are pushed but this one isn't, it's "Waiting"
                                                                    const showWaiting = !isPushed && pushedItems.length > 0;

                                                                    return (
                                                                        <tr key={idx} className={`${isPushed ? 'bg-gray-50/50' : 'hover:bg-gray-50/30'}`}>
                                                                            <td className="py-4 text-center">
                                                                                {!isPushed ? (
                                                                                    <input 
                                                                                        type="checkbox" 
                                                                                        className="h-3.5 w-3.5 rounded border-gray-300 text-partners-green focus:ring-partners-green cursor-pointer"
                                                                                        checked={poSelectedItems.includes(item.articleCode)}
                                                                                        onChange={() => handleItemSelect(po.id, item.articleCode)}
                                                                                    />
                                                                                ) : (
                                                                                    <CheckCircleIcon className="h-5 w-5 text-green-500 mx-auto" />
                                                                                )}
                                                                            </td>
                                                                            <td className="py-4 px-3">
                                                                                <p className={`font-bold ${isPushed ? 'text-gray-400' : 'text-gray-800'}`}>{item.itemName}</p>
                                                                                <p className="text-[10px] text-gray-400 truncate max-w-[200px] font-mono mt-0.5">{item.masterSku || item.articleCode}</p>
                                                                            </td>
                                                                            <td className={`py-4 text-right font-medium ${isPushed ? 'text-gray-400' : 'text-gray-700'}`}>{item.qty}</td>
                                                                            <td className={`py-4 text-right font-bold ${isPushed ? 'text-gray-400' : 'text-green-600'}`}>{item.fulfillableQty ?? '-'}</td>
                                                                            <td className="py-4 px-3 text-center">
                                                                                <span className={`px-2 py-0.5 rounded-full text-[9px] font-bold border ${
                                                                                    isMismatch ? 'bg-red-50 text-red-600 border-red-100' : 'bg-green-50 text-green-600 border-green-100'
                                                                                }`}>
                                                                                    {item.priceCheckStatus || 'OK'}
                                                                                </span>
                                                                            </td>
                                                                            <td className={`py-4 text-right ${isPushed ? 'text-gray-400' : 'text-gray-600'}`}>₹{item.unitCost}</td>
                                                                            <td className={`py-4 text-right ${isPushed ? 'text-gray-400' : 'text-gray-600'}`}>₹{item.mrp}</td>
                                                                            <td className="py-4 text-center">
                                                                                {isPushed ? (
                                                                                    <div className="flex flex-col items-center">
                                                                                        <span className="text-[9px] font-bold text-green-700 bg-green-100/50 px-2 py-0.5 rounded border border-green-200 uppercase" title={item.eeOrderRefId}>
                                                                                            Pushed
                                                                                        </span>
                                                                                        <span className="text-[8px] font-mono text-gray-400 mt-1">{item.eeOrderRefId}</span>
                                                                                    </div>
                                                                                ) : showWaiting ? (
                                                                                    <span className="text-[9px] font-bold text-amber-700 bg-amber-50 px-2 py-0.5 rounded border border-amber-200 uppercase animate-pulse">
                                                                                        Waiting
                                                                                    </span>
                                                                                ) : (
                                                                                    <span className="text-gray-300 text-[10px] font-medium">-</span>
                                                                                )}
                                                                            </td>
                                                                        </tr>
                                                                    );
                                                                })}
                                                            </tbody>
                                                        </table>
                                                    </div>

                                                    <div className="flex justify-end pt-4 border-t border-gray-100">
                                                         <button 
                                                            onClick={() => handlePushToEasyEcom(po)}
                                                            disabled={poSelectedItems.length === 0 || pushingToEasyEcom[po.id]}
                                                            className={`flex items-center gap-2 px-6 py-3 text-sm font-bold text-white rounded-xl transition-all shadow-sm active:scale-95 ${
                                                                poSelectedItems.length > 0 ? 'bg-blue-600 hover:bg-blue-700 shadow-blue-200' : 'bg-gray-300 cursor-not-allowed grayscale'
                                                            }`}
                                                        >
                                                            <UploadIcon className={`h-4 w-4 ${pushingToEasyEcom[po.id] ? 'animate-bounce' : ''}`} />
                                                            {pushingToEasyEcom[po.id] ? 'Processing Order...' : `Push ${poSelectedItems.length > 0 ? poSelectedItems.length : ''} Items to EasyEcom`}
                                                        </button>
                                                    </div>
                                                </div>
                                            </td>
                                        </tr>
                                    )}
                                </Fragment>
                            );
                        })}
                    </tbody>
                </table>
            </div>
        </div>
    );
};

