import { pushToEasyEcom } from '../services/api';

interface PoTableProps {
    activeFilter: string;
    setActiveFilter: (filter: string) => void;
    purchaseOrders: PurchaseOrder[];
    setPurchaseOrders: React.Dispatch<React.SetStateAction<PurchaseOrder[]>>;
    tabCounts: { [key: string]: number };
    addLog: (action: string, details: string) => void;
    addNotification: (message: string, type?: 'info' | 'success' | 'warning' | 'error') => void;
    onSync: () => void;
    isSyncing: boolean;
    inventoryItems?: InventoryItem[];
}

const PoTable: React.FC<PoTableProps> = ({ activeFilter, setActiveFilter, purchaseOrders, tabCounts, onSync, isSyncing, addLog, addNotification }) => {
    const [filteredOrders, setFilteredOrders] = useState<PurchaseOrder[]>([]);
    const [expandedRowId, setExpandedRowId] = useState<string | null>(null);
    const [selectedPoItems, setSelectedPoItems] = useState<{ [key: string]: string[] }>({});
    const [pushingToEasyEcom, setPushingToEasyEcom] = useState<{ [key: string]: boolean }>({});

    const tabs = [
        { name: 'All POs' }, { name: 'New PO' }, { name: 'POC Verification'}, { name: 'Appointment to be taken' },
        { name: 'In-Transit' }, { name: 'GRN Pending' }, { name: 'GRN Updated' }, { name: 'RTO' }, { name: 'Closed' },
    ];

    useEffect(() => {
        let orders = [...purchaseOrders];
        if (activeFilter !== 'All POs') {
            const filterMapping: { [key: string]: POStatus } = {
                'New PO': POStatus.NewPO, 'POC Verification': POStatus.POCPending, 'Appointment to be taken': POStatus.AppointmentPending,
                'In-Transit': POStatus.InTransit, 'GRN Pending': POStatus.GRNPending, 'GRN Updated': POStatus.GRNUpdated,
                'RTO': POStatus.RTO, 'Closed': POStatus.Closed,
            };
            const statusToFilter = filterMapping[activeFilter];
            if (statusToFilter) orders = orders.filter(po => po.status === statusToFilter);
        }
        setFilteredOrders(orders);
    }, [activeFilter, purchaseOrders]);

    const toggleRowExpansion = (poId: string) => setExpandedRowId(expandedRowId === poId ? null : poId);

    const handleItemSelect = (poId: string, articleCode: string) => {
        setSelectedPoItems(prev => {
            const currentSelected = prev[poId] || [];
            const isSelected = currentSelected.includes(articleCode);
            return { ...prev, [poId]: isSelected ? currentSelected.filter(code => code !== articleCode) : [...currentSelected, articleCode] };
        });
    };

    const handleSelectAllItems = (po: PurchaseOrder) => {
        const selectableArticleCodes = (po.items || []).filter(i => !i.eeOrderRefId).map(item => item.articleCode);
        const currentSelected = selectedPoItems[po.id] || [];
        const allSelected = selectableArticleCodes.length > 0 && currentSelected.length === selectableArticleCodes.length;
        setSelectedPoItems(prev => ({ ...prev, [po.id]: allSelected ? [] : selectableArticleCodes }));
    };

    const handlePushToEasyEcom = async (po: PurchaseOrder) => {
        const selected = selectedPoItems[po.id] || [];
        if (selected.length === 0) return;
        setPushingToEasyEcom(prev => ({ ...prev, [po.id]: true }));
        try {
            const res = await pushToEasyEcom(po, selected);
            if (res.status === 'success') {
                addNotification(res.message, 'success');
                addLog('EasyEcom Sync', `Pushed ${selected.length} items from PO ${po.poNumber} to EasyEcom.`);
                setSelectedPoItems(prev => ({ ...prev, [po.id]: [] }));
                onSync();
            } else {
                addNotification('Failed: ' + res.message, 'error');
            }
        } catch (e) {
            addNotification('Network error pushing to EasyEcom', 'error');
        } finally {
            setPushingToEasyEcom(prev => ({ ...prev, [po.id]: false }));
        }
    };

    const getDisplayPoStatus = (po: PurchaseOrder): POStatus => {
        const items = po.items || [];
        const pushedCount = items.filter(i => !!i.eeOrderRefId).length;

        if (items.length > 0 && pushedCount === items.length) {
            return POStatus.Pushed;
        } else if (pushedCount > 0) {
            return POStatus.PartiallyProcessed;
        }
        return po.status;
    };

    return (
        <div className="bg-white p-6 rounded-xl shadow-sm">
            <div className="flex flex-col md:flex-row justify-between items-center gap-4 mb-6">
                <div className="flex flex-wrap items-center gap-2">
                    {tabs.map(tab => (
                        <button key={tab.name} onClick={() => setActiveFilter(tab.name)}
                            className={`px-3 py-1.5 text-sm font-semibold rounded-full border transition-colors ${
                                activeFilter === tab.name ? 'bg-partners-green text-white border-partners-green' : 'bg-white text-gray-600 border-partners-border hover:bg-gray-50'
                            }`}
                        >
                            {tab.name} {tabCounts[tab.name] > 0 && <span className="ml-1 text-xs opacity-80">({tabCounts[tab.name]})</span>}
                        </button>
                    ))}
                </div>
                <button onClick={onSync} disabled={isSyncing} className="flex items-center gap-2 px-3 py-2 text-sm font-medium text-white bg-blue-600 rounded-lg shadow-sm hover:bg-blue-700 active:scale-95 transition-all">
                    <CloudDownloadIcon className={`h-4 w-4 ${isSyncing ? 'animate-bounce' : ''}`} /> Sync Data
                </button>
            </div>

            <div className="mt-6 overflow-x-auto border border-gray-100 rounded-xl shadow-inner">
                <table className="w-full text-sm text-left text-gray-600">
                    <thead className="text-[11px] text-gray-500 uppercase bg-gray-50/50 border-b border-gray-100">
                        <tr>
                            <th className="p-4 w-4"></th>
                            <th className="px-6 py-4">PO Number</th>
                            <th className="px-6 py-4">Status</th>
                            <th className="px-6 py-4">Channel</th>
                            <th className="px-6 py-4">Store</th>
                            <th className="px-6 py-4">Qty / Total (Inc. 5% GST)</th>
                            <th className="px-6 py-4">Order Date</th>
                            <th className="px-6 py-4 text-center">Action</th>
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-gray-100/50">
                        {filteredOrders.map((po) => {
                            const isExpanded = expandedRowId === po.id;
                            const poSelectedItems = selectedPoItems[po.id] || [];
                            const items = po.items || [];
                            const pushedItems = items.filter(i => !!i.eeOrderRefId);
                            const selectableItems = items.filter(i => !i.eeOrderRefId);
                            const allSelectableSelected = selectableItems.length > 0 && poSelectedItems.length === selectableItems.length;
                            const poStatus = getDisplayPoStatus(po);

                            // Calculate amount including 5% tax
                            const amountIncTax = po.amount * 1.05;

                            return (
                                <Fragment key={po.id}>
                                    <tr className={`hover:bg-gray-50/80 cursor-pointer transition-colors ${isExpanded ? 'bg-partners-light-green/30' : 'bg-white'}`} onClick={() => toggleRowExpansion(po.id)}>
                                        <td className="p-4 text-center">
                                            <div className="text-gray-400 hover:text-partners-green transition-colors">
                                                {isExpanded ? <ChevronDownIcon className="h-4 w-4" /> : <ChevronRightIcon className="h-4 w-4" />}
                                            </div>
                                        </td>
                                        <td className="px-6 py-4 font-bold text-partners-green whitespace-nowrap">{po.poNumber}</td>
                                        <td className="px-6 py-4"><StatusBadge status={poStatus} /></td>
                                        <td className="px-6 py-4 font-medium text-gray-700">{po.channel}</td>
                                        <td className="px-6 py-4 text-gray-500">{po.storeCode}</td>
                                        <td className="px-6 py-4 font-bold text-gray-900">{po.qty} / ₹{amountIncTax.toLocaleString('en-IN', { minimumFractionDigits: 0, maximumFractionDigits: 0 })}</td>
                                        <td className="px-6 py-4 whitespace-nowrap text-gray-400">{po.orderDate}</td>
                                        <td className="px-6 py-4 text-center" onClick={(e) => e.stopPropagation()}>
                                            <button className="text-gray-400 hover:text-gray-600 p-2 hover:bg-gray-100 rounded-full transition-colors">
                                                <DotsVerticalIcon className="h-4 w-4" />
                                            </button>
                                        </td>
                                    </tr>
                                    {isExpanded && (
                                        <tr className="bg-gray-50/50">
                                            <td colSpan={8} className="px-4 py-8 sm:px-12">
                                                <div className="bg-white border border-partners-border rounded-xl p-6 space-y-6 shadow-sm ring-1 ring-black/5">

                                                    {/* PO Lifecycle & Ref Header (Mirroring Sales Orders) */}
                                                    <div className="pb-6 border-b border-gray-100">
                                                        <h4 className="text-xs font-bold text-gray-400 uppercase tracking-widest mb-4 flex items-center gap-2">
                                                            <CalendarIcon className="h-4 w-4 text-blue-500" /> PO Lifecycle & Ref
                                                        </h4>
                                                        <div className="grid grid-cols-2 md:grid-cols-5 gap-4 p-4 bg-gray-50 rounded-lg border border-gray-100">
                                                            <div>
                                                                <p className="text-[10px] uppercase font-bold text-gray-400">PO Ref</p>
                                                                <p className="text-xs font-bold text-partners-green truncate">{po.poNumber}</p>
                                                            </div>
                                                            <div>
                                                                <p className="text-[10px] uppercase font-bold text-gray-400">PO Date</p>
                                                                <p className="text-xs font-bold text-gray-700">{po.orderDate || 'N/A'}</p>
                                                            </div>
                                                            <div>
                                                                <p className="text-[10px] uppercase font-bold text-gray-400">PO EDD</p>
                                                                <p className="text-xs font-bold text-blue-600">{po.poEdd || 'N/A'}</p>
                                                            </div>
                                                            <div>
                                                                <p className="text-[10px] uppercase font-bold text-gray-400">Expiry Date</p>
                                                                <p className="text-xs font-bold text-red-600">{po.poExpiryDate || 'N/A'}</p>
                                                            </div>
                                                            <div>
                                                                <p className="text-[10px] uppercase font-bold text-gray-400">PO PDF</p>
                                                                {po.poPdfUrl ? (
                                                                    <a href={po.poPdfUrl} target="_blank" rel="noopener noreferrer" className="text-partners-green hover:underline flex items-center gap-1 text-xs font-bold mt-0.5">
                                                                        <PaperclipIcon className="h-3 w-3" /> View PO PDF
                                                                    </a>
                                                                ) : (
                                                                    <p className="text-xs text-gray-300 font-bold italic mt-0.5">Not Uploaded</p>
                                                                )}
                                                            </div>
                                                        </div>
                                                    </div>

                                                    <div className="flex justify-between items-center border-b border-gray-100 pb-4">
                                                        <h4 className="text-sm font-bold text-gray-800 flex items-center gap-2">
                                                            <CubeIcon className="h-4 w-4 text-partners-green" /> Item List & Fulfillment
                                                        </h4>
                                                        <div className="flex items-center gap-3">
                                                             <span className="text-xs font-semibold text-gray-500 bg-gray-100 px-2 py-1 rounded-md">{poSelectedItems.length} items selected</span>
                                                             {pushedItems.length > 0 && (
                                                                 <span className="text-xs font-bold text-green-600 bg-green-50 px-2 py-1 rounded-md border border-green-100">{pushedItems.length} Processed</span>
                                                             )}
                                                        </div>
                                                    </div>

                                                    <div className="overflow-x-auto border border-gray-100 rounded-lg">
                                                        <table className="w-full text-xs text-left">
                                                            <thead className="bg-gray-50 text-gray-500 uppercase tracking-tight">
                                                                <tr>
                                                                    <th className="py-3 w-8 text-center">
                                                                        <input 
                                                                            type="checkbox" 
                                                                            className="h-3.5 w-3.5 rounded border-gray-300 text-partners-green focus:ring-partners-green cursor-pointer"
                                                                            checked={allSelectableSelected}
                                                                            onChange={() => handleSelectAllItems(po)}
                                                                            disabled={selectableItems.length === 0}
                                                                        />
                                                                    </th>
                                                                    <th className="py-3 px-3">Item Name / SKU</th>
                                                                    <th className="py-3 text-right">PO Qty</th>
                                                                    <th className="py-3 text-right">Fulfillable</th>
                                                                    <th className="py-3 px-3 text-center">Price Check</th>
                                                                    <th className="py-3 text-right">Unit Cost</th>
                                                                    <th className="py-3 text-right">MRP</th>
                                                                    <th className="py-3 text-center">Status</th>
                                                                </tr>
                                                            </thead>
                                                            <tbody className="divide-y divide-gray-100">
                                                                {items.map((item, idx) => {
                                                                    const isMismatch = item.priceCheckStatus === 'Mismatch';
                                                                    const isPushed = !!item.eeOrderRefId;
                                                                    // If some items in the PO are pushed but this one isn't, it's "Waiting"
                                                                    const showWaiting = !isPushed && pushedItems.length > 0;

                                                                    return (
                                                                        <tr key={idx} className={`${isPushed ? 'bg-gray-50/50' : 'hover:bg-gray-50/30'}`}>
                                                                            <td className="py-4 text-center">
                                                                                {!isPushed ? (
                                                                                    <input 
                                                                                        type="checkbox" 
                                                                                        className="h-3.5 w-3.5 rounded border-gray-300 text-partners-green focus:ring-partners-green cursor-pointer"
                                                                                        checked={poSelectedItems.includes(item.articleCode)}
                                                                                        onChange={() => handleItemSelect(po.id, item.articleCode)}
                                                                                    />
                                                                                ) : (
                                                                                    <CheckCircleIcon className="h-5 w-5 text-green-500 mx-auto" />
                                                                                )}
                                                                            </td>
                                                                            <td className="py-4 px-3">
                                                                                <p className={`font-bold ${isPushed ? 'text-gray-400' : 'text-gray-800'}`}>{item.itemName}</p>
                                                                                <p className="text-[10px] text-gray-400 truncate max-w-[200px] font-mono mt-0.5">{item.masterSku || item.articleCode}</p>
                                                                            </td>
                                                                            <td className={`py-4 text-right font-medium ${isPushed ? 'text-gray-400' : 'text-gray-700'}`}>{item.qty}</td>
                                                                            <td className={`py-4 text-right font-bold ${isPushed ? 'text-gray-400' : 'text-green-600'}`}>{item.fulfillableQty ?? '-'}</td>
                                                                            <td className="py-4 px-3 text-center">
                                                                                <span className={`px-2 py-0.5 rounded-full text-[9px] font-bold border ${
                                                                                    isMismatch ? 'bg-red-50 text-red-600 border-red-100' : 'bg-green-50 text-green-600 border-green-100'
                                                                                }`}>
                                                                                    {item.priceCheckStatus || 'OK'}
                                                                                </span>
                                                                            </td>
                                                                            <td className={`py-4 text-right ${isPushed ? 'text-gray-400' : 'text-gray-600'}`}>₹{item.unitCost}</td>
                                                                            <td className={`py-4 text-right ${isPushed ? 'text-gray-400' : 'text-gray-600'}`}>₹{item.mrp}</td>
                                                                            <td className="py-4 text-center">
                                                                                {isPushed ? (
                                                                                    <div className="flex flex-col items-center">
                                                                                        <span className="text-[9px] font-bold text-green-700 bg-green-100/50 px-2 py-0.5 rounded border border-green-200 uppercase" title={item.eeOrderRefId}>
                                                                                            Pushed
                                                                                        </span>
                                                                                        <span className="text-[8px] font-mono text-gray-400 mt-1">{item.eeOrderRefId}</span>
                                                                                    </div>
                                                                                ) : showWaiting ? (
                                                                                    <span className="text-[9px] font-bold text-amber-700 bg-amber-50 px-2 py-0.5 rounded border border-amber-200 uppercase animate-pulse">
                                                                                        Waiting
                                                                                    </span>
                                                                                ) : (
                                                                                    <span className="text-gray-300 text-[10px] font-medium">-</span>
                                                                                )}
                                                                            </td>
                                                                        </tr>
                                                                    );
                                                                })}
                                                            </tbody>
                                                        </table>
                                                    </div>

                                                    <div className="flex justify-end pt-4 border-t border-gray-100">
                                                         <button 
                                                            onClick={() => handlePushToEasyEcom(po)}
                                                            disabled={poSelectedItems.length === 0 || pushingToEasyEcom[po.id]}
                                                            className={`flex items-center gap-2 px-6 py-3 text-sm font-bold text-white rounded-xl transition-all shadow-sm active:scale-95 ${
                                                                poSelectedItems.length > 0 ? 'bg-blue-600 hover:bg-blue-700 shadow-blue-200' : 'bg-gray-300 cursor-not-allowed grayscale'
                                                            }`}
                                                        >
                                                            <UploadIcon className={`h-4 w-4 ${pushingToEasyEcom[po.id] ? 'animate-bounce' : ''}`} />
                                                            {pushingToEasyEcom[po.id] ? 'Processing Order...' : `Push ${poSelectedItems.length > 0 ? poSelectedItems.length : ''} Items to EasyEcom`}
                                                        </button>
                                                    </div>
                                                </div>
                                            </td>
                                        </tr>
                                    )}
                                </Fragment>
                            );
                        })}
                    </tbody>
                </table>
            </div>
        </div>
    );
};

export default PoTable;

import React, { useEffect, useState } from 'react';
import { CheckCircleIcon, XCircleIcon, InfoIcon, XIcon } from './icons/Icons';
import { NotificationItem } from '../types';

interface ToastProps {
    notification: NotificationItem;
    onClose: (id: string) => void;
}

const ToastCard: React.FC<ToastProps> = ({ notification, onClose }) => {
    const [isVisible, setIsVisible] = useState(false);

    useEffect(() => {
        // Trigger enter animation
        const timer = setTimeout(() => setIsVisible(true), 10);

        // Auto close after 5 seconds
        const closeTimer = setTimeout(() => {
            setIsVisible(false);
            setTimeout(() => onClose(notification.id), 300); // Wait for exit animation
        }, 5000);

        return () => {
            clearTimeout(timer);
            clearTimeout(closeTimer);
        };
    }, [notification, onClose]);

    const getIcon = () => {
        switch (notification.type) {
            case 'success': return <CheckCircleIcon className="h-6 w-6 text-green-500" />;
            case 'error': return <XCircleIcon className="h-6 w-6 text-red-500" />;
            case 'warning': return <InfoIcon className="h-6 w-6 text-yellow-500" />;
            default: return <InfoIcon className="h-6 w-6 text-blue-500" />;
        }
    };

    const getBorderColor = () => {
        switch (notification.type) {
            case 'success': return 'border-green-500';
            case 'error': return 'border-red-500';
            case 'warning': return 'border-yellow-500';
            default: return 'border-blue-500';
        }
    };

    return (
        <div 
            className={`flex items-center w-80 p-4 mb-4 text-gray-800 bg-white rounded-xl shadow-2xl border-l-4 ${getBorderColor()} transform transition-all duration-300 ease-in-out ${
                isVisible ? 'translate-x-0 opacity-100' : 'translate-x-full opacity-0'
            }`}
        >
            <div className="flex-shrink-0">
                {getIcon()}
            </div>
            <div className="ml-3 text-sm font-semibold flex-1">
                {notification.message}
                <div className="text-[10px] font-normal text-gray-400 mt-0.5">Auto-closing in 5s</div>
            </div>
            <button 
                onClick={() => {
                    setIsVisible(false);
                    setTimeout(() => onClose(notification.id), 300);
                }}
                className="ml-auto -mx-1.5 -my-1.5 bg-white text-gray-400 hover:text-gray-900 rounded-lg p-1.5 inline-flex h-8 w-8 transition-colors"
            >
                <XIcon className="h-4 w-4" />
            </button>
        </div>
    );
};

interface ToastContainerProps {
    toasts: NotificationItem[];
    onRemove: (id: string) => void;
}

const ToastContainer: React.FC<ToastContainerProps> = ({ toasts, onRemove }) => {
    return (
        <div className="fixed bottom-6 right-6 z-[100] flex flex-col items-end pointer-events-none">
            <div className="pointer-events-auto">
                {toasts.map(toast => (
                    <ToastCard key={toast.id} notification={toast} onClose={onRemove} />
                ))}
            </div>
        </div>
    );
};

export default ToastContainer;

import React, { useState, useMemo, useEffect, useCallback } from 'react';
import Sidebar from './components/Sidebar';
import Header from './components/Header';
import SummaryCard from './components/SummaryCard';
import PoTable from './components/PoTable';
import SalesOrderTable from './components/SalesOrderTable';
import PocVerification from './components/PocVerification';
import AppointmentManager from './components/AppointmentManager';
import AdminPanel from './components/AdminPanel';
import FinanceManager from './components/FinanceManager';
import InventoryManager from './components/InventoryManager';
import ReportsManager from './components/ReportsManager';
import ToastContainer from './components/ToastContainer';
import { MenuIcon, XIcon, QuestionMarkCircleIcon, RefreshIcon } from './components/icons/Icons';
import { initialUsers, initialRolePermissions } from './data/mockData';
import { type PurchaseOrder, POStatus, ActivityLog, NotificationItem, ViewType, User, RolePermissions, InventoryItem, ChannelConfig } from './types';
import { fetchPurchaseOrders, fetchInventoryFromSheet, fetchChannelConfigs } from './services/api';

const App: React.FC = () => {
  const [isSidebarOpen, setSidebarOpen] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [lastSynced, setLastSynced] = useState<number>(0);

  const [users, setUsers] = useState<User[]>(initialUsers);
  const [currentUser, setCurrentUser] = useState<User>(initialUsers[0]);
  const [rolePermissions, setRolePermissions] = useState<RolePermissions>(initialRolePermissions);

  const [activeView, setActiveView] = useState<ViewType>('Dashboard');
  const [activeFilter, setActiveFilter] = useState('All POs');

  const [purchaseOrders, setPurchaseOrders] = useState<PurchaseOrder[]>([]);
  const [inventoryItems, setInventoryItems] = useState<InventoryItem[]>([]);
  const [channelConfigs, setChannelConfigs] = useState<ChannelConfig[]>([]);

  const [logs, setLogs] = useState<ActivityLog[]>([
    { id: '1', user: 'System', action: 'Init', details: 'System initialized', timestamp: new Date().toLocaleString() }
  ]);
  const [notifications, setNotifications] = useState<NotificationItem[]>([]);
  const [toasts, setToasts] = useState<NotificationItem[]>([]);

  const addLog = useCallback((action: string, details: string) => {
    const newLog: ActivityLog = {
        id: Date.now().toString() + Math.random().toString(36).substring(7),
        user: currentUser.name, 
        action,
        details,
        timestamp: new Date().toLocaleString()
    };
    setLogs(prev => [newLog, ...prev]);
  }, [currentUser]);

  const addNotification = useCallback((message: string, type: 'info' | 'success' | 'warning' | 'error' = 'info') => {
    const newNotification: NotificationItem = {
        id: Date.now().toString() + Math.random().toString(36).substring(7),
        message,
        timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
        read: false,
        type
    };

    // Add to history (Bell icon)
    setNotifications(prev => [newNotification, ...prev]);

    // Trigger toast (Floating card) for major actions or if specified
    setToasts(prev => [...prev, newNotification]);
  }, []);

  const removeToast = useCallback((id: string) => {
    setToasts(prev => prev.filter(t => t.id !== id));
  }, []);

  const refreshData = useCallback(async (force = false) => {
      if (!force && purchaseOrders.length > 0 && Date.now() - lastSynced < 1800000) return; 

      setIsLoading(true);
      try {
          const [poData, invData, channelData] = await Promise.all([
              fetchPurchaseOrders(),
              fetchInventoryFromSheet(),
              fetchChannelConfigs()
          ]);

          if (poData.length > 0) {
              setPurchaseOrders(poData);
          }
          if (invData.length > 0) setInventoryItems(invData);
          if (channelData.length > 0) setChannelConfigs(channelData);
          setLastSynced(Date.now());
      } catch (e) {
          addNotification('Failed to sync data from Google Sheets.', 'error');
      } finally {
          setIsLoading(false);
      }
  }, [lastSynced, purchaseOrders.length, addNotification]);

  useEffect(() => {
    refreshData();
    const intervalId = setInterval(() => refreshData(true), 30 * 60 * 1000);
    return () => clearInterval(intervalId);
  }, [refreshData]);

  const summaryData = useMemo(() => {
    const totalActive = purchaseOrders.filter(p => p.status !== POStatus.Closed).length;
    const belowThreshold = purchaseOrders.filter(p => p.status === POStatus.BelowThreshold).length;
    const pocsPending = purchaseOrders.filter(p => p.status === POStatus.POCPending).length;
    const awaitingAppointment = purchaseOrders.filter(p => p.status === POStatus.AppointmentPending).length;
    const inTransit = purchaseOrders.filter(p => p.status === POStatus.InTransit).length;
    const rtoShipments = purchaseOrders.filter(p => p.status === POStatus.RTO).length;
    const closedShipments = purchaseOrders.filter(p => p.status === POStatus.Closed).length;

    return [
      { title: 'Total Active POs', value: totalActive.toString(), change: 'across all stages', color: 'green', targetView: 'Purchase Orders', targetFilter: 'All POs' },
      { title: 'Below Threshold', value: belowThreshold.toString(), change: 'low value orders', color: 'yellow', targetView: 'Purchase Orders', targetFilter: 'Below Threshold' },
      { title: 'POCs Pending', value: pocsPending.toString(), change: 'verification needed', color: 'yellow', targetView: 'POC Verification', targetFilter: '' },
      { title: 'Awaiting Appointment', value: awaitingAppointment.toString(), change: 'follow-up required', color: 'yellow', targetView: 'Appointments', targetFilter: '' },
      { title: 'Sales Orders In-Transit', value: inTransit.toString(), change: 'currently shipping', color: 'blue', targetView: 'Sales Orders', targetFilter: 'In-Transit' },
      { title: 'RTO Shipments', value: rtoShipments.toString(), change: 'in last 30 days', color: 'red', targetView: 'Sales Orders', targetFilter: 'RTO' },
      { title: 'Closed Sales Orders', value: closedShipments.toString(), change: 'in last 30 days', color: 'green', targetView: 'Sales Orders', targetFilter: 'Closed' },
    ];
  }, [purchaseOrders]);

  const tabCounts = useMemo(() => {
    const statusToTabMap: { [key in POStatus]?: string } = {
        [POStatus.NewPO]: 'New PO',
        [POStatus.BelowThreshold]: 'Below Threshold',
        [POStatus.POCPending]: 'POC Verification',
        [POStatus.AppointmentPending]: 'Appointment to be taken',
        [POStatus.InTransit]: 'In-Transit',
        [POStatus.GRNPending]: 'GRN Pending',
        [POStatus.GRNUpdated]: 'GRN Updated',
        [POStatus.RTO]: 'RTO',
        [POStatus.Closed]: 'Closed',
    };
    const initialCounts = Object.values(statusToTabMap).reduce((acc, tabName) => {
        if(tabName) acc[tabName] = 0;
        return acc;
    }, {} as { [key: string]: number });
    const countsByStatus = purchaseOrders.reduce((acc, po) => {
        const tabName = statusToTabMap[po.status];
        if (tabName) acc[tabName] = (acc[tabName] || 0) + 1;
        return acc;
    }, initialCounts);
    return { 'All POs': purchaseOrders.length, ...countsByStatus };
  }, [purchaseOrders]);

  const handleCardClick = (view: ViewType, filter?: string) => {
      if (rolePermissions[currentUser.role]?.includes(view)) {
          setActiveView(view);
          if (filter) setActiveFilter(filter);
      } else {
          addNotification(`Access Denied: Permission required for ${view}.`, 'error');
      }
  };

  const renderContent = () => {
    if (isLoading && purchaseOrders.length === 0) {
        return (
            <div className="flex-1 flex flex-col items-center justify-center">
                <RefreshIcon className="h-10 w-10 text-partners-green animate-spin mb-4" />
                <p className="text-gray-600 font-medium">Fetching Data...</p>
            </div>
        );
    }

    switch (activeView) {
        case 'Dashboard':
            return (
                <div className="p-4 sm:p-6 lg:p-8 flex-1">
                    <Header notifications={notifications} onMarkRead={(id) => setNotifications(n => n.map(i => i.id === id ? {...i, read: true} : i))} onClearAll={() => setNotifications([])} onViewLogs={() => setActiveView('Admin')} />
                    <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 2xl:grid-cols-7 gap-6 my-6">
                        {summaryData.map((card, index) => (
                            <SummaryCard key={index} title={card.title} value={card.value} changeText={card.change} color={card.color as any} onClick={() => handleCardClick(card.targetView as ViewType, card.targetFilter)} />
                        ))}
                    </div>
                </div>
            );
        case 'POC Verification': return <PocVerification purchaseOrders={purchaseOrders} setPurchaseOrders={setPurchaseOrders} addLog={addLog} />;
        case 'Appointments': return <AppointmentManager purchaseOrders={purchaseOrders} setPurchaseOrders={setPurchaseOrders} addLog={addLog} />;
        case 'Finance': return <FinanceManager purchaseOrders={purchaseOrders} setPurchaseOrders={setPurchaseOrders} addLog={addLog} />;
        case 'Inventory': return <InventoryManager addLog={addLog} inventoryItems={inventoryItems} setInventoryItems={setInventoryItems} onSync={() => refreshData(true)} isSyncing={isLoading} />;
        case 'Reports': return <ReportsManager purchaseOrders={purchaseOrders} inventoryItems={inventoryItems} />;
        case 'Purchase Orders':
        case 'Uploads':
        case 'GRN / POD':
            return (
                <div className="p-4 sm:p-6 lg:p-8 flex-1">
                    <h1 className="text-2xl font-bold text-gray-800 mb-6">{activeView}</h1>
                    <PoTable activeFilter={activeFilter} setActiveFilter={setActiveFilter} purchaseOrders={purchaseOrders} setPurchaseOrders={setPurchaseOrders} tabCounts={tabCounts} addLog={addLog} addNotification={addNotification} onSync={() => refreshData(true)} isSyncing={isLoading} />
                </div>
            );
        case 'Sales Orders':
             return (
                <div className="p-4 sm:p-6 lg:p-8 flex-1">
                    <h1 className="text-2xl font-bold text-gray-800 mb-6">Sales Orders</h1>
                    <SalesOrderTable activeFilter={activeFilter} setActiveFilter={setActiveFilter} purchaseOrders={purchaseOrders} setPurchaseOrders={setPurchaseOrders} tabCounts={tabCounts} addLog={addLog} addNotification={addNotification} onSync={() => refreshData(true)} isSyncing={isLoading} />
                </div>
            );
        case 'Admin': return <AdminPanel logs={logs} users={users} setUsers={setUsers} rolePermissions={rolePermissions} setRolePermissions={setRolePermissions} addLog={addLog} currentUser={currentUser} channelConfigs={channelConfigs} onSync={() => refreshData(true)} />;
        default: return <div className="p-8 text-center text-gray-500">Section Under Construction</div>;
    }
  };

  return (
    <div className="flex h-screen bg-partners-gray-bg font-sans">
      <ToastContainer toasts={toasts} onRemove={removeToast} />
      {isSidebarOpen && <div className="fixed inset-0 bg-black opacity-50 z-20 lg:hidden" onClick={() => setSidebarOpen(false)}></div>}
      <div className={`fixed lg:relative inset-y-0 left-0 transform ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full'} lg:translate-x-0 transition-transform duration-300 ease-in-out z-30`}>
        <Sidebar activeView={activeView} setActiveView={setActiveView} currentUser={currentUser} permissions={rolePermissions} onSwitchUser={(id) => { const u = users.find(x => x.id === id); if(u) setCurrentUser(u); }} allUsers={users} />
      </div>
      <main className="flex-1 flex flex-col overflow-y-auto">
        <div className="flex items-center justify-between p-4 lg:hidden">
            <button onClick={() => setSidebarOpen(!isSidebarOpen)} className="text-gray-500 focus:outline-none">{isSidebarOpen ? <XIcon /> : <MenuIcon />}</button>
        </div>
        {renderContent()}
      </main>
      <button className="fixed bottom-6 right-6 bg-green-600 text-white p-3 rounded-full shadow-lg hover:bg-green-700 transition-colors flex items-center gap-2 z-40">
        <QuestionMarkCircleIcon /><span className="font-semibold">Help</span>
      </button>
    </div>
  );
};

