                                                     {po.followUpCount && <span className="mt-1 text-xs font-semibold bg-blue-100 text-blue-700 px-2 py-0.5 rounded-full w-fit">Follow-up {po.followUpCount}</span>}
                                                </div>
                                            ) : po.appointmentDate ? (
                                                <span className="font-semibold text-green-600">Scheduled</span>
                                            ) : (
                                                 <span className="font-semibold text-gray-500">Request Pending</span>
                                            )}
                                        </td>
                                        <td className="px-6 py-4">
                                            {po.appointmentDate ? (
                                                <div>
                                                    <p className="font-semibold">{po.appointmentDate} at {po.appointmentTime}</p>
                                                    <p className="text-xs text-gray-500">ID: {po.appointmentId}</p>
                                                </div>
                                            ) : (
                                                <span className="text-gray-400 italic">Not scheduled</span>
                                            )}
                                        </td>
                                        <td className="px-6 py-4">
                                            <div className="flex items-center gap-2">
                                                {!po.appointmentRequestDate && (
                                                    <button onClick={() => setModalState({ type: 'request', po })} className="px-3 py-1 text-xs font-semibold text-white bg-blue-600 rounded-md hover:bg-blue-700">Request</button>
                                                )}
                                                {po.appointmentRequestDate && !po.appointmentDate && (
                                                    <>
                                                        <button onClick={() => setModalState({ type: 'update', po })} className="px-3 py-1 text-xs font-semibold text-white bg-partners-green rounded-md hover:bg-green-700">Update</button>
                                                        <button onClick={() => handleFollowUp(po.id)} title="Log Follow-up" className="p-1.5 text-gray-500 hover:text-blue-600 bg-gray-100 rounded-md"><ReplyIcon className="h-4 w-4"/></button>
                                                    </>
                                                )}
                                                {po.appointmentDate && (
                                                     <button onClick={() => setModalState({ type: 'update', po })} className="px-3 py-1 text-xs font-semibold text-gray-700 bg-gray-200 rounded-md hover:bg-gray-300">Edit</button>
                                                )}
                                            </div>
                                        </td>
                                    </tr>
                                ))}
                            </tbody>
                        </table>
                    </div>
                    )}
                </div>
            </div>
        </>
    );
};

export default AppointmentManager;

import React, { useState, useRef, useEffect } from 'react';
import { DownloadIcon, BellIcon, CheckCircleIcon, InfoIcon, AdminIcon } from './icons/Icons';
import { NotificationItem, ViewType } from '../types';

interface HeaderProps {
    notifications: NotificationItem[];
    onMarkRead: (id: string) => void;
    onClearAll: () => void;
    onViewLogs: () => void;
    activeView: ViewType;
}

const Header: React.FC<HeaderProps> = ({ notifications, onMarkRead, onClearAll, onViewLogs, activeView }) => {
  const [isNotificationsOpen, setIsNotificationsOpen] = useState(false);
  const dropdownRef = useRef<HTMLDivElement>(null);

  const unreadCount = notifications.filter(n => !n.read).length;

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
        setIsNotificationsOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const getSubtext = () => {
    switch(activeView) {
        case 'Dashboard': return 'Real-time tracking of all purchase orders and shipment stages';
        case 'Purchase Orders': return 'Manage and process incoming purchase orders';
        case 'Sales Orders': return 'Track fulfillment and shipping status of processed orders';
        case 'Inventory': return 'Mapping and stock management synced from EasyEcom';
        case 'Reports': return 'Visual analytics and performance reporting';
        case 'Admin': return 'System configuration and user management';
        default: return 'Cubelelo Purchase Order Management Portal';
    }
  };

  return (
    <header className="flex flex-col md:flex-row justify-between md:items-center bg-white border-b border-gray-200 px-4 sm:px-6 lg:px-8 py-4 sticky top-0 z-40">
      <div>
        <h1 className="text-2xl font-bold text-gray-800">{activeView === 'Dashboard' ? 'PO Dashboard' : activeView}</h1>
        <p className="text-xs text-gray-500 mt-0.5">{getSubtext()}</p>
      </div>

      <div className="mt-4 md:mt-0 flex items-center gap-4">
        <div className="relative" ref={dropdownRef}>
            <button 
                onClick={() => setIsNotificationsOpen(!isNotificationsOpen)}
                className="p-2 text-gray-500 hover:bg-gray-100 rounded-full relative focus:outline-none transition-colors border border-transparent hover:border-gray-200"
                aria-label="Toggle notifications"
            >
                <BellIcon className="h-6 w-6" />
                {unreadCount > 0 && (
                    <span className="absolute top-1 right-1 h-4 w-4 bg-red-500 text-white text-[10px] font-bold rounded-full flex items-center justify-center border-2 border-white shadow-sm">
                        {unreadCount}
                    </span>
                )}
            </button>

            {isNotificationsOpen && (
                <div className="absolute right-0 mt-2 w-80 bg-white rounded-xl shadow-2xl border border-gray-100 z-50 overflow-hidden ring-1 ring-black ring-opacity-5">
                    <div className="p-3 border-b border-gray-100 flex justify-between items-center bg-gray-50">
                        <h3 className="font-bold text-sm text-gray-700">Notifications History</h3>
                        {notifications.length > 0 && (
                            <button onClick={onClearAll} className="text-[10px] font-bold text-gray-400 hover:text-red-500 transition-colors uppercase tracking-wider">
                                Clear all
                            </button>
                        )}
                    </div>
                    <div className="max-h-80 overflow-y-auto">
                        {notifications.length === 0 ? (
                            <div className="p-8 text-center text-gray-500 text-sm flex flex-col items-center gap-2">
                                <BellIcon className="h-8 w-8 text-gray-200" />
                                <p>No notifications yet.</p>
                            </div>
                        ) : (
                            <ul className="divide-y divide-gray-50">
                                {notifications.map((notification) => (
                                    <li 
                                        key={notification.id} 
                                        className={`p-4 hover:bg-gray-50 transition-colors cursor-pointer group ${!notification.read ? 'bg-blue-50/50' : ''}`}
                                        onClick={() => onMarkRead(notification.id)}
                                    >
                                        <div className="flex items-start gap-3">
                                            <div className={`mt-1 p-2 rounded-full flex-shrink-0 ${
                                                notification.type === 'success' ? 'bg-green-100 text-green-600' : 
                                                notification.type === 'error' ? 'bg-red-100 text-red-600' :
                                                'bg-blue-100 text-blue-600'
                                            }`}>
                                                {notification.type === 'success' ? <CheckCircleIcon className="h-4 w-4"/> : <InfoIcon className="h-4 w-4"/>}
                                            </div>
                                            <div className="flex-1">
                                                <p className={`text-sm leading-tight ${!notification.read ? 'font-bold text-gray-900' : 'text-gray-600'}`}>{notification.message}</p>
                                                <p className="text-[10px] text-gray-400 mt-1.5 flex items-center gap-1">
                                                    <span className="h-1 w-1 rounded-full bg-gray-300"></span>
                                                    {notification.timestamp}
                                                </p>
                                            </div>
                                            {!notification.read && (
                                                <span className="h-2 w-2 bg-blue-500 rounded-full mt-2 ring-4 ring-blue-50"></span>
                                            )}
                                        </div>
                                    </li>
                                ))}
                            </ul>
                        )}
                    </div>
                    <div className="p-3 bg-gray-50 border-t border-gray-100 text-center">
                        <button 
                            onClick={() => { setIsNotificationsOpen(false); onViewLogs(); }} 
                            className="text-[10px] font-bold text-partners-green hover:text-green-700 flex items-center justify-center w-full py-1.5 gap-2 uppercase tracking-widest transition-colors"
                        >
                            <AdminIcon className="h-4 w-4" />
                            Admin Activity Logs
                        </button>
                    </div>
                </div>
            )}
        </div>

        {(activeView === 'Purchase Orders' || activeView === 'Dashboard' || activeView === 'Sales Orders') && (
            <button className="hidden sm:flex items-center gap-2 px-4 py-2 text-sm font-bold text-partners-green border border-partners-green rounded-lg hover:bg-partners-light-green transition-all active:scale-95 shadow-sm">
                <DownloadIcon className="h-4 w-4" />
                <span>Bulk Export</span>
            </button>
        )}
      </div>
    </header>
  );
};

export default Header;

import React, { useState, useMemo, useEffect, useCallback } from 'react';
import Sidebar from './components/Sidebar';
import Header from './components/Header';
import SummaryCard from './components/SummaryCard';
import PoTable from './components/PoTable';
import SalesOrderTable from './components/SalesOrderTable';
import PocVerification from './components/PocVerification';
import AppointmentManager from './components/AppointmentManager';
import AdminPanel from './components/AdminPanel';
import FinanceManager from './components/FinanceManager';
import InventoryManager from './components/InventoryManager';
import ReportsManager from './components/ReportsManager';
import ToastContainer from './components/ToastContainer';
import { MenuIcon, XIcon, QuestionMarkCircleIcon, RefreshIcon } from './components/icons/Icons';
import { initialUsers, initialRolePermissions } from './data/mockData';
import { type PurchaseOrder, POStatus, ActivityLog, NotificationItem, ViewType, User, RolePermissions, InventoryItem, ChannelConfig } from './types';
import { fetchPurchaseOrders, fetchInventoryFromSheet, fetchChannelConfigs } from './services/api';

const App: React.FC = () => {
  const [isSidebarOpen, setSidebarOpen] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [lastSynced, setLastSynced] = useState<number>(0);

  const [users, setUsers] = useState<User[]>(initialUsers);
  const [currentUser, setCurrentUser] = useState<User>(initialUsers[0]);
  const [rolePermissions, setRolePermissions] = useState<RolePermissions>(initialRolePermissions);

  const [activeView, setActiveView] = useState<ViewType>('Dashboard');
  const [activeFilter, setActiveFilter] = useState('All POs');

  const [purchaseOrders, setPurchaseOrders] = useState<PurchaseOrder[]>([]);
  const [inventoryItems, setInventoryItems] = useState<InventoryItem[]>([]);
  const [channelConfigs, setChannelConfigs] = useState<ChannelConfig[]>([]);

  const [logs, setLogs] = useState<ActivityLog[]>([
    { id: '1', user: 'System', action: 'Init', details: 'System initialized', timestamp: new Date().toLocaleString() }
  ]);
  const [notifications, setNotifications] = useState<NotificationItem[]>([]);
  const [toasts, setToasts] = useState<NotificationItem[]>([]);

  const addLog = useCallback((action: string, details: string) => {
    const newLog: ActivityLog = {
        id: Date.now().toString() + Math.random().toString(36).substring(7),
        user: currentUser.name, 
        action,
        details,
        timestamp: new Date().toLocaleString()
    };
    setLogs(prev => [newLog, ...prev]);
  }, [currentUser]);

  const addNotification = useCallback((message: string, type: 'info' | 'success' | 'warning' | 'error' = 'info') => {
    const newNotification: NotificationItem = {
        id: Date.now().toString() + Math.random().toString(36).substring(7),
        message,
        timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
        read: false,
        type
    };

    // Add to history (Bell icon)
    setNotifications(prev => [newNotification, ...prev]);

    // Trigger toast (Floating card) for major actions or if specified
    setToasts(prev => [...prev, newNotification]);
  }, []);

  const removeToast = useCallback((id: string) => {
    setToasts(prev => prev.filter(t => t.id !== id));
  }, []);

  const refreshData = useCallback(async (force = false) => {
      if (!force && purchaseOrders.length > 0 && Date.now() - lastSynced < 1800000) return; 

      setIsLoading(true);
      try {
          const [poData, invData, channelData] = await Promise.all([
              fetchPurchaseOrders(),
              fetchInventoryFromSheet(),
              fetchChannelConfigs()
          ]);

          if (poData.length > 0) {
              setPurchaseOrders(poData);
          }
          if (invData.length > 0) setInventoryItems(invData);
          if (channelData.length > 0) setChannelConfigs(channelData);
          setLastSynced(Date.now());
      } catch (e) {
          addNotification('Failed to sync data from Google Sheets.', 'error');
      } finally {
          setIsLoading(false);
      }
  }, [lastSynced, purchaseOrders.length, addNotification]);

  useEffect(() => {
    refreshData();
    const intervalId = setInterval(() => refreshData(true), 30 * 60 * 1000);
    return () => clearInterval(intervalId);
  }, [refreshData]);

  const summaryData = useMemo(() => {
    const totalActive = purchaseOrders.filter(p => p.status !== POStatus.Closed).length;
    const belowThreshold = purchaseOrders.filter(p => p.status === POStatus.BelowThreshold).length;
    const pocsPending = purchaseOrders.filter(p => p.status === POStatus.POCPending).length;
    const awaitingAppointment = purchaseOrders.filter(p => p.status === POStatus.AppointmentPending).length;
    const inTransit = purchaseOrders.filter(p => p.status === POStatus.InTransit).length;
    const rtoShipments = purchaseOrders.filter(p => p.status === POStatus.RTO).length;
    const closedShipments = purchaseOrders.filter(p => p.status === POStatus.Closed).length;

    return [
      { title: 'Total Active POs', value: totalActive.toString(), change: 'across all stages', color: 'green', targetView: 'Purchase Orders', targetFilter: 'All POs' },
      { title: 'Below Threshold', value: belowThreshold.toString(), change: 'low value orders', color: 'yellow', targetView: 'Purchase Orders', targetFilter: 'Below Threshold' },
      { title: 'POCs Pending', value: pocsPending.toString(), change: 'verification needed', color: 'yellow', targetView: 'POC Verification', targetFilter: '' },
      { title: 'Awaiting Appointment', value: awaitingAppointment.toString(), change: 'follow-up required', color: 'yellow', targetView: 'Appointments', targetFilter: '' },
      { title: 'Sales Orders In-Transit', value: inTransit.toString(), change: 'currently shipping', color: 'blue', targetView: 'Sales Orders', targetFilter: 'In-Transit' },
      { title: 'RTO Shipments', value: rtoShipments.toString(), change: 'in last 30 days', color: 'red', targetView: 'Sales Orders', targetFilter: 'RTO' },
      { title: 'Closed Sales Orders', value: closedShipments.toString(), change: 'in last 30 days', color: 'green', targetView: 'Sales Orders', targetFilter: 'Closed' },
    ];
  }, [purchaseOrders]);

  const tabCounts = useMemo(() => {
    const statusToTabMap: { [key in POStatus]?: string } = {
        [POStatus.NewPO]: 'New PO',
        [POStatus.BelowThreshold]: 'Below Threshold',
        [POStatus.POCPending]: 'POC Verification',
        [POStatus.AppointmentPending]: 'Appointment to be taken',
        [POStatus.InTransit]: 'In-Transit',
        [POStatus.GRNPending]: 'GRN Pending',
        [POStatus.GRNUpdated]: 'GRN Updated',
        [POStatus.RTO]: 'RTO',
        [POStatus.Closed]: 'Closed',
    };
    const initialCounts = Object.values(statusToTabMap).reduce((acc, tabName) => {
        if(tabName) acc[tabName] = 0;
        return acc;
    }, {} as { [key: string]: number });
    const countsByStatus = purchaseOrders.reduce((acc, po) => {
        const tabName = statusToTabMap[po.status];
        if (tabName) acc[tabName] = (acc[tabName] || 0) + 1;
        return acc;
    }, initialCounts);
    return { 'All POs': purchaseOrders.length, ...countsByStatus };
  }, [purchaseOrders]);

  const handleCardClick = (view: ViewType, filter?: string) => {
      if (rolePermissions[currentUser.role]?.includes(view)) {
          setActiveView(view);
          if (filter) setActiveFilter(filter);
      } else {
          addNotification(`Access Denied: Permission required for ${view}.`, 'error');
      }
  };

  const renderContent = () => {
    if (isLoading && purchaseOrders.length === 0) {
        return (
            <div className="flex-1 flex flex-col items-center justify-center p-8">
                <RefreshIcon className="h-12 w-12 text-partners-green animate-spin mb-4" />
                <p className="text-gray-600 font-bold text-lg">Synchronizing your Dashboard...</p>
                <p className="text-gray-400 text-sm mt-1">Connecting to Google Sheets and EasyEcom</p>
            </div>
        );
    }

    switch (activeView) {
        case 'Dashboard':
            return (
                <div className="p-4 sm:p-6 lg:p-8 flex-1">
                    <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 2xl:grid-cols-7 gap-6">
                        {summaryData.map((card, index) => (
                            <SummaryCard key={index} title={card.title} value={card.value} changeText={card.change} color={card.color as any} onClick={() => handleCardClick(card.targetView as ViewType, card.targetFilter)} />
                        ))}
                    </div>
                </div>
            );
        case 'POC Verification': return <PocVerification purchaseOrders={purchaseOrders} setPurchaseOrders={setPurchaseOrders} addLog={addLog} addNotification={addNotification} />;
        case 'Appointments': return <AppointmentManager purchaseOrders={purchaseOrders} setPurchaseOrders={setPurchaseOrders} addLog={addLog} addNotification={addNotification} />;
        case 'Finance': return <FinanceManager purchaseOrders={purchaseOrders} setPurchaseOrders={setPurchaseOrders} addLog={addLog} />;
        case 'Inventory': return <InventoryManager addLog={addLog} inventoryItems={inventoryItems} setInventoryItems={setInventoryItems} onSync={() => refreshData(true)} isSyncing={isLoading} />;
        case 'Reports': return <ReportsManager purchaseOrders={purchaseOrders} inventoryItems={inventoryItems} />;
        case 'Purchase Orders':
        case 'Uploads':
        case 'GRN / POD':
            return (
                <div className="p-4 sm:p-6 lg:p-8 flex-1">
                    <PoTable activeFilter={activeFilter} setActiveFilter={setActiveFilter} purchaseOrders={purchaseOrders} setPurchaseOrders={setPurchaseOrders} tabCounts={tabCounts} addLog={addLog} addNotification={addNotification} onSync={() => refreshData(true)} isSyncing={isLoading} />
                </div>
            );
        case 'Sales Orders':
             return (
                <div className="p-4 sm:p-6 lg:p-8 flex-1">
                    <SalesOrderTable activeFilter={activeFilter} setActiveFilter={setActiveFilter} purchaseOrders={purchaseOrders} setPurchaseOrders={setPurchaseOrders} tabCounts={tabCounts} addLog={addLog} addNotification={addNotification} onSync={() => refreshData(true)} isSyncing={isLoading} />
                </div>
            );
        case 'Admin': return <AdminPanel logs={logs} users={users} setUsers={setUsers} rolePermissions={rolePermissions} setRolePermissions={setRolePermissions} addLog={addLog} currentUser={currentUser} channelConfigs={channelConfigs} onSync={() => refreshData(true)} />;
        default: return <div className="p-8 text-center text-gray-500">Section Under Construction</div>;
    }
  };

  return (
    <div className="flex h-screen bg-partners-gray-bg font-sans">
      <ToastContainer toasts={toasts} onRemove={removeToast} />
      {isSidebarOpen && <div className="fixed inset-0 bg-black opacity-50 z-20 lg:hidden" onClick={() => setSidebarOpen(false)}></div>}
      <div className={`fixed lg:relative inset-y-0 left-0 transform ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full'} lg:translate-x-0 transition-transform duration-300 ease-in-out z-30`}>
        <Sidebar activeView={activeView} setActiveView={setActiveView} currentUser={currentUser} permissions={rolePermissions} onSwitchUser={(id) => { const u = users.find(x => x.id === id); if(u) setCurrentUser(u); }} allUsers={users} />
      </div>
      <main className="flex-1 flex flex-col overflow-y-auto">
        {/* Mobile Header Toggle */}
        <div className="flex items-center justify-between p-4 lg:hidden bg-white border-b border-gray-200">
            <button onClick={() => setSidebarOpen(!isSidebarOpen)} className="text-gray-500 focus:outline-none p-2 hover:bg-gray-100 rounded-lg">
                {isSidebarOpen ? <XIcon className="h-6 w-6" /> : <MenuIcon className="h-6 w-6" />}
            </button>
            <div className="font-bold text-gray-800">PO Portal</div>
            <div className="w-10"></div> {/* Spacer for alignment */}
        </div>

        {/* Global Unified Header */}
        <Header 
            notifications={notifications} 
            onMarkRead={(id) => setNotifications(n => n.map(i => i.id === id ? {...i, read: true} : i))} 
            onClearAll={() => setNotifications([])} 
            onViewLogs={() => setActiveView('Admin')} 
            activeView={activeView}
        />

        {/* View Content */}
        {renderContent()}
      </main>

      <button className="fixed bottom-6 right-6 bg-green-600 text-white p-3 rounded-full shadow-lg hover:bg-green-700 transition-all hover:scale-110 flex items-center gap-2 z-40">
        <QuestionMarkCircleIcon className="h-6 w-6" />
        <span className="font-bold text-sm pr-1">Help</span>
      </button>
    </div>
  );
};

export default App;

import React, { useState, useMemo } from 'react';
import { POStatus, type PurchaseOrder } from '../types';
import { CheckCircleIcon, XCircleIcon, SearchIcon, ProfileIcon } from './icons/Icons';

interface PocVerificationProps {
    purchaseOrders: PurchaseOrder[];
    setPurchaseOrders: React.Dispatch<React.SetStateAction<PurchaseOrder[]>>;
    addLog: (action: string, details: string) => void;
    addNotification: (message: string, type?: 'info' | 'success' | 'warning' | 'error') => void;
}

const PocVerification: React.FC<PocVerificationProps> = ({ purchaseOrders, setPurchaseOrders, addLog, addNotification }) => {
    const [last4Digits, setLast4Digits] = useState<{ [key: string]: string }>({});
    const [verificationStatus, setVerificationStatus] = useState<{ [key: string]: 'success' | 'error' | null }>({});

    const ordersToVerify = useMemo(() => {
        return purchaseOrders.filter(po => po.status === POStatus.POCPending && po.pocPhoneNumber);
    }, [purchaseOrders]);

    const handleInputChange = (poId: string, value: string) => {
        if (/^\d{0,4}$/.test(value)) {
            setLast4Digits(prev => ({...prev, [poId]: value}));
        }
    };

    const handleVerify = (po: PurchaseOrder) => {
        const enteredDigits = last4Digits[po.id] || '';
        if (!po.pocPhoneNumber || enteredDigits.length !== 4) return;

        const actualLast4 = po.pocPhoneNumber.slice(-4);

        if (enteredDigits === actualLast4) {
            setVerificationStatus(prev => ({ ...prev, [po.id]: 'success' }));
            addLog('Verification', `POC Contact verified for PO ${po.poNumber}`);
            addNotification(`POC Contact verified for PO ${po.poNumber}`, 'success');
            setTimeout(() => {
                setPurchaseOrders(prev => prev.map(order => 
                    order.id === po.id ? { 
                        ...order, 
                        contactVerified: true, 
                        status: POStatus.AppointmentPending,
                        actionToBeTaken: 'Take Appointment' 
                    } : order
                ));
            }, 1000);
        } else {
            setVerificationStatus(prev => ({ ...prev, [po.id]: 'error' }));
            addLog('Verification Failed', `Failed POC verification attempt for PO ${po.poNumber}`);
            addNotification(`Invalid POC verification for PO ${po.poNumber}`, 'error');
             setTimeout(() => {
                setVerificationStatus(prev => ({ ...prev, [po.id]: null }));
            }, 2000);
        }
    };

    const getButtonState = (poId: string) => {
        const status = verificationStatus[poId];
        if (status === 'success') return 'bg-green-500 hover:bg-green-600';
        if (status === 'error') return 'bg-red-500 hover:bg-red-600';
        return 'bg-partners-green hover:bg-green-700 disabled:bg-gray-400';
    };

    const getButtonContent = (po: PurchaseOrder) => {
        const status = verificationStatus[po.id];
        if (status === 'success') return <CheckCircleIcon className="h-5 w-5" />;
        if (status === 'error') return <XCircleIcon className="h-5 w-5" />;
        return 'Verify';
    }

    return (
        <div className="p-4 sm:p-6 lg:p-8 flex-1">
            <div className="bg-white p-6 rounded-xl shadow-sm border border-gray-100">
                {ordersToVerify.length === 0 ? (
                    <div className="text-center py-12">
                        <ProfileIcon className="mx-auto h-16 w-16 text-gray-200"/>
                        <h3 className="mt-4 text-lg font-bold text-gray-800">All Clear!</h3>
                        <p className="mt-1 text-gray-400">There are no pending POC verifications at this time.</p>
                    </div>
                ) : (
                <div className="overflow-x-auto">
                    <table className="w-full text-sm text-left text-gray-600">
                        <thead className="text-[11px] text-gray-500 uppercase bg-gray-50/50">
                            <tr>
                                <th scope="col" className="px-6 py-4">PO Number</th>
                                <th scope="col" className="px-6 py-4">Store Code</th>
                                <th scope="col" className="px-6 py-4">Masked Phone Number</th>
                                <th scope="col" className="px-6 py-4">Enter Last 4 Digits</th>
                                <th scope="col" className="px-6 py-4">Action</th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-gray-100">
                            {ordersToVerify.map(po => (
                                <tr key={po.id} className="bg-white hover:bg-gray-50/80 transition-colors">
                                    <td className="px-6 py-4 font-bold text-partners-green whitespace-nowrap">{po.poNumber}</td>
                                    <td className="px-6 py-4 whitespace-nowrap font-medium text-gray-600">{po.storeCode}</td>
                                    <td className="px-6 py-4 whitespace-nowrap font-mono text-gray-400 tracking-wider">{`******${po.pocPhoneNumber?.slice(-4)}`}</td>
                                    <td className="px-6 py-4">
                                        <input 
                                            type="text"
                                            maxLength={4}
                                            value={last4Digits[po.id] || ''}
                                            onChange={(e) => handleInputChange(po.id, e.target.value)}
                                            className="w-24 p-2 border border-gray-300 rounded-lg focus:ring-partners-green focus:border-partners-green font-mono tracking-widest text-center shadow-inner"
                                            placeholder="XXXX"
                                        />
                                    </td>
                                    <td className="px-6 py-4">
                                        <button 
                                            onClick={() => handleVerify(po)}
                                            disabled={!last4Digits[po.id] || last4Digits[po.id]?.length !== 4 || !!verificationStatus[po.id]}
                                            className={`px-4 py-2 text-white font-bold rounded-lg transition-all text-xs w-24 flex justify-center items-center shadow-sm active:scale-95 ${getButtonState(po.id)}`}
                                        >
                                            {getButtonContent(po)}
                                        </button>
                                    </td>
                                </tr>
                            ))}
                        </tbody>
                    </table>
                </div>
                )}
            </div>
        </div>
    );
};

export default PocVerification;

import React, { useState, useRef, useEffect } from 'react';
import { DownloadIcon, BellIcon, CheckCircleIcon, InfoIcon, AdminIcon } from './icons/Icons';
import { NotificationItem, ViewType } from '../types';

interface HeaderProps {
    notifications: NotificationItem[];
    onMarkRead: (id: string) => void;
    onClearAll: () => void;
    onViewLogs: () => void;
    activeView: ViewType;
}

const Header: React.FC<HeaderProps> = ({ notifications, onMarkRead, onClearAll, onViewLogs, activeView }) => {
  const [isNotificationsOpen, setIsNotificationsOpen] = useState(false);
  const dropdownRef = useRef<HTMLDivElement>(null);

  const unreadCount = notifications.filter(n => !n.read).length;

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
        setIsNotificationsOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const getSubtext = () => {
    switch(activeView) {
        case 'Dashboard': return 'Real-time tracking of all purchase orders and shipment stages';
        case 'Purchase Orders': return 'Manage and process incoming purchase orders';
        case 'Uploads': return 'Upload and parse new PO documents';
        case 'POC Verification': return 'Verify Point-of-Contact mobile numbers';
        case 'Appointments': return 'Schedule and track warehouse delivery slots';
        case 'Sales Orders': return 'Track fulfillment and shipping status of processed orders';
        case 'GRN / POD': return 'Manage Goods Received Notes and Proof of Delivery';
        case 'Inventory': return 'Mapping and stock management synced from EasyEcom';
        case 'Finance': return 'Track PO values, payments received, and customer accounts';
        case 'Reports': return 'Visual analytics and performance reporting';
        case 'Admin': return 'System configuration, role permissions, and activity logs';
        default: return 'Cubelelo Purchase Order Management Portal';
    }
  };

  return (
    <header className="flex flex-col md:flex-row justify-between md:items-center bg-white border-b border-gray-200 px-4 sm:px-6 lg:px-8 py-4 sticky top-0 z-40">
      <div>
        <h1 className="text-2xl font-bold text-gray-800">{activeView === 'Dashboard' ? 'PO Dashboard' : activeView}</h1>
        <p className="text-xs text-gray-500 mt-0.5">{getSubtext()}</p>
      </div>

      <div className="mt-4 md:mt-0 flex items-center gap-4">
        <div className="relative" ref={dropdownRef}>
            <button 
                onClick={() => setIsNotificationsOpen(!isNotificationsOpen)}
                className="p-2 text-gray-500 hover:bg-gray-100 rounded-full relative focus:outline-none transition-colors border border-transparent hover:border-gray-200"
                aria-label="Toggle notifications"
            >
                <BellIcon className="h-6 w-6" />
                {unreadCount > 0 && (
                    <span className="absolute top-1 right-1 h-4 w-4 bg-red-500 text-white text-[10px] font-bold rounded-full flex items-center justify-center border-2 border-white shadow-sm">
                        {unreadCount}
                    </span>
                )}
            </button>

            {isNotificationsOpen && (
                <div className="absolute right-0 mt-2 w-80 bg-white rounded-xl shadow-2xl border border-gray-100 z-50 overflow-hidden ring-1 ring-black ring-opacity-5">
                    <div className="p-3 border-b border-gray-100 flex justify-between items-center bg-gray-50">
                        <h3 className="font-bold text-sm text-gray-700">Notifications History</h3>
                        {notifications.length > 0 && (
                            <button onClick={onClearAll} className="text-[10px] font-bold text-gray-400 hover:text-red-500 transition-colors uppercase tracking-wider">
                                Clear all
                            </button>
                        )}
                    </div>
                    <div className="max-h-80 overflow-y-auto">
                        {notifications.length === 0 ? (
                            <div className="p-8 text-center text-gray-500 text-sm flex flex-col items-center gap-2">
                                <BellIcon className="h-8 w-8 text-gray-200" />
                                <p>No notifications yet.</p>
                            </div>
                        ) : (
                            <ul className="divide-y divide-gray-50">
                                {notifications.map((notification) => (
                                    <li 
                                        key={notification.id} 
                                        className={`p-4 hover:bg-gray-50 transition-colors cursor-pointer group ${!notification.read ? 'bg-blue-50/50' : ''}`}
                                        onClick={() => onMarkRead(notification.id)}
                                    >
                                        <div className="flex items-start gap-3">
                                            <div className={`mt-1 p-2 rounded-full flex-shrink-0 ${
                                                notification.type === 'success' ? 'bg-green-100 text-green-600' : 
                                                notification.type === 'error' ? 'bg-red-100 text-red-600' :
                                                'bg-blue-100 text-blue-600'
                                            }`}>
                                                {notification.type === 'success' ? <CheckCircleIcon className="h-4 w-4"/> : <InfoIcon className="h-4 w-4"/>}
                                            </div>
                                            <div className="flex-1">
                                                <p className={`text-sm leading-tight ${!notification.read ? 'font-bold text-gray-900' : 'text-gray-600'}`}>{notification.message}</p>
                                                <p className="text-[10px] text-gray-400 mt-1.5 flex items-center gap-1">
                                                    <span className="h-1 w-1 rounded-full bg-gray-300"></span>
                                                    {notification.timestamp}
                                                </p>
                                            </div>
                                            {!notification.read && (
                                                <span className="h-2 w-2 bg-blue-500 rounded-full mt-2 ring-4 ring-blue-50"></span>
                                            )}
                                        </div>
                                    </li>
                                ))}
                            </ul>
                        )}
                    </div>
                    <div className="p-3 bg-gray-50 border-t border-gray-100 text-center">
                        <button 
                            onClick={() => { setIsNotificationsOpen(false); onViewLogs(); }} 
                            className="text-[10px] font-bold text-partners-green hover:text-green-700 flex items-center justify-center w-full py-1.5 gap-2 uppercase tracking-widest transition-colors"
                        >
                            <AdminIcon className="h-4 w-4" />
                            Admin Activity Logs
                        </button>
                    </div>
                </div>
            )}
        </div>

        {(activeView === 'Purchase Orders' || activeView === 'Dashboard' || activeView === 'Sales Orders') && (
            <button className="hidden sm:flex items-center gap-2 px-4 py-2 text-sm font-bold text-partners-green border border-partners-green rounded-lg hover:bg-partners-light-green transition-all active:scale-95 shadow-sm">
                <DownloadIcon className="h-4 w-4" />
                <span>Bulk Export</span>
            </button>
        )}
      </div>
    </header>
  );
};

export default Header;

import React, { useState, useMemo, useEffect, useCallback } from 'react';
import Sidebar from './components/Sidebar';
import Header from './components/Header';
import SummaryCard from './components/SummaryCard';
import PoTable from './components/PoTable';
import SalesOrderTable from './components/SalesOrderTable';
import PocVerification from './components/PocVerification';
import AppointmentManager from './components/AppointmentManager';
import AdminPanel from './components/AdminPanel';
import FinanceManager from './components/FinanceManager';
import InventoryManager from './components/InventoryManager';
import ReportsManager from './components/ReportsManager';
import ToastContainer from './components/ToastContainer';
import { MenuIcon, XIcon, QuestionMarkCircleIcon, RefreshIcon } from './components/icons/Icons';
import { initialUsers, initialRolePermissions } from './data/mockData';
import { type PurchaseOrder, POStatus, ActivityLog, NotificationItem, ViewType, User, RolePermissions, InventoryItem, ChannelConfig } from './types';
import { fetchPurchaseOrders, fetchInventoryFromSheet, fetchChannelConfigs } from './services/api';

const App: React.FC = () => {
  const [isSidebarOpen, setSidebarOpen] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [lastSynced, setLastSynced] = useState<number>(0);

  const [users, setUsers] = useState<User[]>(initialUsers);
  const [currentUser, setCurrentUser] = useState<User>(initialUsers[0]);
  const [rolePermissions, setRolePermissions] = useState<RolePermissions>(initialRolePermissions);

  const [activeView, setActiveView] = useState<ViewType>('Dashboard');
  const [activeFilter, setActiveFilter] = useState('All POs');

  const [purchaseOrders, setPurchaseOrders] = useState<PurchaseOrder[]>([]);
  const [inventoryItems, setInventoryItems] = useState<InventoryItem[]>([]);
  const [channelConfigs, setChannelConfigs] = useState<ChannelConfig[]>([]);

  const [logs, setLogs] = useState<ActivityLog[]>([
    { id: '1', user: 'System', action: 'Init', details: 'System initialized', timestamp: new Date().toLocaleString() }
  ]);
  const [notifications, setNotifications] = useState<NotificationItem[]>([]);
  const [toasts, setToasts] = useState<NotificationItem[]>([]);

  const addLog = useCallback((action: string, details: string) => {
    const newLog: ActivityLog = {
        id: Date.now().toString() + Math.random().toString(36).substring(7),
        user: currentUser.name, 
        action,
        details,
        timestamp: new Date().toLocaleString()
    };
    setLogs(prev => [newLog, ...prev]);
  }, [currentUser]);

  const addNotification = useCallback((message: string, type: 'info' | 'success' | 'warning' | 'error' = 'info') => {
    const newNotification: NotificationItem = {
        id: Date.now().toString() + Math.random().toString(36).substring(7),
        message,
        timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
        read: false,
        type
    };

    // Add to history (Bell icon)
    setNotifications(prev => [newNotification, ...prev]);

    // Trigger toast (Floating card) for major actions or if specified
    setToasts(prev => [...prev, newNotification]);
  }, []);

  const removeToast = useCallback((id: string) => {
    setToasts(prev => prev.filter(t => t.id !== id));
  }, []);

  const refreshData = useCallback(async (force = false) => {
      if (!force && purchaseOrders.length > 0 && Date.now() - lastSynced < 1800000) return; 

      setIsLoading(true);
      try {
          const [poData, invData, channelData] = await Promise.all([
              fetchPurchaseOrders(),
              fetchInventoryFromSheet(),
              fetchChannelConfigs()
          ]);

          if (poData.length > 0) {
              setPurchaseOrders(poData);
          }
          if (invData.length > 0) setInventoryItems(invData);
          if (channelData.length > 0) setChannelConfigs(channelData);
          setLastSynced(Date.now());
      } catch (e) {
          addNotification('Failed to sync data from Google Sheets.', 'error');
      } finally {
          setIsLoading(false);
      }
  }, [lastSynced, purchaseOrders.length, addNotification]);

  useEffect(() => {
    refreshData();
    const intervalId = setInterval(() => refreshData(true), 30 * 60 * 1000);
    return () => clearInterval(intervalId);
  }, [refreshData]);

  const summaryData = useMemo(() => {
    const totalActive = purchaseOrders.filter(p => p.status !== POStatus.Closed).length;
    const belowThreshold = purchaseOrders.filter(p => p.status === POStatus.BelowThreshold).length;
    const pocsPending = purchaseOrders.filter(p => p.status === POStatus.POCPending).length;
    const awaitingAppointment = purchaseOrders.filter(p => p.status === POStatus.AppointmentPending).length;
    const inTransit = purchaseOrders.filter(p => p.status === POStatus.InTransit).length;
    const rtoShipments = purchaseOrders.filter(p => p.status === POStatus.RTO).length;
    const closedShipments = purchaseOrders.filter(p => p.status === POStatus.Closed).length;

    return [
      { title: 'Total Active POs', value: totalActive.toString(), change: 'across all stages', color: 'green', targetView: 'Purchase Orders', targetFilter: 'All POs' },
      { title: 'Below Threshold', value: belowThreshold.toString(), change: 'low value orders', color: 'yellow', targetView: 'Purchase Orders', targetFilter: 'Below Threshold' },
      { title: 'POCs Pending', value: pocsPending.toString(), change: 'verification needed', color: 'yellow', targetView: 'POC Verification', targetFilter: '' },
      { title: 'Awaiting Appointment', value: awaitingAppointment.toString(), change: 'follow-up required', color: 'yellow', targetView: 'Appointments', targetFilter: '' },
      { title: 'Sales Orders In-Transit', value: inTransit.toString(), change: 'currently shipping', color: 'blue', targetView: 'Sales Orders', targetFilter: 'In-Transit' },
      { title: 'RTO Shipments', value: rtoShipments.toString(), change: 'in last 30 days', color: 'red', targetView: 'Sales Orders', targetFilter: 'RTO' },
      { title: 'Closed Sales Orders', value: closedShipments.toString(), change: 'in last 30 days', color: 'green', targetView: 'Sales Orders', targetFilter: 'Closed' },
    ];
  }, [purchaseOrders]);

  const tabCounts = useMemo(() => {
    const statusToTabMap: { [key in POStatus]?: string } = {
        [POStatus.NewPO]: 'New PO',
        [POStatus.BelowThreshold]: 'Below Threshold',
        [POStatus.POCPending]: 'POC Verification',
        [POStatus.AppointmentPending]: 'Appointment to be taken',
        [POStatus.InTransit]: 'In-Transit',
        [POStatus.GRNPending]: 'GRN Pending',
        [POStatus.GRNUpdated]: 'GRN Updated',
        [POStatus.RTO]: 'RTO',
        [POStatus.Closed]: 'Closed',
    };
    const initialCounts = Object.values(statusToTabMap).reduce((acc, tabName) => {
        if(tabName) acc[tabName] = 0;
        return acc;
    }, {} as { [key: string]: number });
    const countsByStatus = purchaseOrders.reduce((acc, po) => {
        const tabName = statusToTabMap[po.status];
        if (tabName) acc[tabName] = (acc[tabName] || 0) + 1;
        return acc;
    }, initialCounts);
    return { 'All POs': purchaseOrders.length, ...countsByStatus };
  }, [purchaseOrders]);

  const handleCardClick = (view: ViewType, filter?: string) => {
      if (rolePermissions[currentUser.role]?.includes(view)) {
          setActiveView(view);
          if (filter) setActiveFilter(filter);
      } else {
          addNotification(`Access Denied: Permission required for ${view}.`, 'error');
      }
  };

  const renderContent = () => {
    if (isLoading && purchaseOrders.length === 0) {
        return (
            <div className="flex-1 flex flex-col items-center justify-center p-8">
                <RefreshIcon className="h-12 w-12 text-partners-green animate-spin mb-4" />
                <p className="text-gray-600 font-bold text-lg">Synchronizing your Dashboard...</p>
                <p className="text-gray-400 text-sm mt-1">Connecting to Google Sheets and EasyEcom</p>
            </div>
        );
    }

    switch (activeView) {
        case 'Dashboard':
            return (
                <div className="p-4 sm:p-6 lg:p-8 flex-1">
                    <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 2xl:grid-cols-7 gap-6">
                        {summaryData.map((card, index) => (
                            <SummaryCard key={index} title={card.title} value={card.value} changeText={card.change} color={card.color as any} onClick={() => handleCardClick(card.targetView as ViewType, card.targetFilter)} />
                        ))}
                    </div>
                </div>
            );
        case 'POC Verification': return <PocVerification purchaseOrders={purchaseOrders} setPurchaseOrders={setPurchaseOrders} addLog={addLog} addNotification={addNotification} />;
        case 'Appointments': return <AppointmentManager purchaseOrders={purchaseOrders} setPurchaseOrders={setPurchaseOrders} addLog={addLog} addNotification={addNotification} />;
        case 'Finance': return <FinanceManager purchaseOrders={purchaseOrders} setPurchaseOrders={setPurchaseOrders} addLog={addLog} />;
        case 'Inventory': return <InventoryManager addLog={addLog} inventoryItems={inventoryItems} setInventoryItems={setInventoryItems} onSync={() => refreshData(true)} isSyncing={isLoading} />;
        case 'Reports': return <ReportsManager purchaseOrders={purchaseOrders} inventoryItems={inventoryItems} />;
        case 'Purchase Orders':
        case 'Uploads':
        case 'GRN / POD':
            return (
                <div className="p-4 sm:p-6 lg:p-8 flex-1">
                    <PoTable activeFilter={activeFilter} setActiveFilter={setActiveFilter} purchaseOrders={purchaseOrders} setPurchaseOrders={setPurchaseOrders} tabCounts={tabCounts} addLog={addLog} addNotification={addNotification} onSync={() => refreshData(true)} isSyncing={isLoading} />
                </div>
            );
        case 'Sales Orders':
             return (
                <div className="p-4 sm:p-6 lg:p-8 flex-1">
                    <SalesOrderTable activeFilter={activeFilter} setActiveFilter={setActiveFilter} purchaseOrders={purchaseOrders} setPurchaseOrders={setPurchaseOrders} tabCounts={tabCounts} addLog={addLog} addNotification={addNotification} onSync={() => refreshData(true)} isSyncing={isLoading} />
                </div>
            );
        case 'Admin': return <AdminPanel logs={logs} users={users} setUsers={setUsers} rolePermissions={rolePermissions} setRolePermissions={setRolePermissions} addLog={addLog} currentUser={currentUser} channelConfigs={channelConfigs} onSync={() => refreshData(true)} />;
        default: return <div className="p-8 text-center text-gray-500">Section Under Construction</div>;
    }
  };

  return (
    <div className="flex h-screen bg-partners-gray-bg font-sans">
      <ToastContainer toasts={toasts} onRemove={removeToast} />
      {isSidebarOpen && <div className="fixed inset-0 bg-black opacity-50 z-20 lg:hidden" onClick={() => setSidebarOpen(false)}></div>}
      <div className={`fixed lg:relative inset-y-0 left-0 transform ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full'} lg:translate-x-0 transition-transform duration-300 ease-in-out z-30`}>
        <Sidebar activeView={activeView} setActiveView={setActiveView} currentUser={currentUser} permissions={rolePermissions} onSwitchUser={(id) => { const u = users.find(x => x.id === id); if(u) setCurrentUser(u); }} allUsers={users} />
      </div>
      <main className="flex-1 flex flex-col overflow-y-auto">
        {/* Mobile Header Toggle */}
        <div className="flex items-center justify-between p-4 lg:hidden bg-white border-b border-gray-200">
            <button onClick={() => setSidebarOpen(!isSidebarOpen)} className="text-gray-500 focus:outline-none p-2 hover:bg-gray-100 rounded-lg">
                {isSidebarOpen ? <XIcon className="h-6 w-6" /> : <MenuIcon className="h-6 w-6" />}
            </button>
            <div className="font-bold text-gray-800">PO Portal</div>
            <div className="w-10"></div>
        </div>

        {/* Global Unified Header */}
        <Header 
            notifications={notifications} 
            onMarkRead={(id) => setNotifications(n => n.map(i => i.id === id ? {...i, read: true} : i))} 
            onClearAll={() => setNotifications([])} 
            onViewLogs={() => setActiveView('Admin')} 
            activeView={activeView}
        />

        {/* View Content */}
        {renderContent()}
      </main>

      <button className="fixed bottom-6 right-6 bg-green-600 text-white p-3 rounded-full shadow-lg hover:bg-green-700 transition-all hover:scale-110 flex items-center gap-2 z-40">
        <QuestionMarkCircleIcon className="h-6 w-6" />
        <span className="font-bold text-sm pr-1">Help</span>
      </button>
    </div>
  );
};

export default App;

import React, { useState, useMemo } from 'react';
import { POStatus, type PurchaseOrder } from '../types';
import { CheckCircleIcon, XCircleIcon, ProfileIcon } from './icons/Icons';

interface PocVerificationProps {
    purchaseOrders: PurchaseOrder[];
    setPurchaseOrders: React.Dispatch<React.SetStateAction<PurchaseOrder[]>>;
    addLog: (action: string, details: string) => void;
    addNotification: (message: string, type?: 'info' | 'success' | 'warning' | 'error') => void;
}

const PocVerification: React.FC<PocVerificationProps> = ({ purchaseOrders, setPurchaseOrders, addLog, addNotification }) => {
    const [last4Digits, setLast4Digits] = useState<{ [key: string]: string }>({});
    const [verificationStatus, setVerificationStatus] = useState<{ [key: string]: 'success' | 'error' | null }>({});

    const ordersToVerify = useMemo(() => {
        return purchaseOrders.filter(po => po.status === POStatus.POCPending && po.pocPhoneNumber);
    }, [purchaseOrders]);

    const handleInputChange = (poId: string, value: string) => {
        if (/^\d{0,4}$/.test(value)) {
            setLast4Digits(prev => ({...prev, [poId]: value}));
        }
    };

    const handleVerify = (po: PurchaseOrder) => {
        const enteredDigits = last4Digits[po.id] || '';
        if (!po.pocPhoneNumber || enteredDigits.length !== 4) return;

        const actualLast4 = po.pocPhoneNumber.slice(-4);

        if (enteredDigits === actualLast4) {
            setVerificationStatus(prev => ({ ...prev, [po.id]: 'success' }));
            addLog('Verification', `POC Contact verified for PO ${po.poNumber}`);
            addNotification(`POC Contact verified for PO ${po.poNumber}`, 'success');
            setTimeout(() => {
                setPurchaseOrders(prev => prev.map(order => 
                    order.id === po.id ? { 
                        ...order, 
                        contactVerified: true, 
                        status: POStatus.AppointmentPending,
                        actionToBeTaken: 'Take Appointment' 
                    } : order
                ));
            }, 1000);
        } else {
            setVerificationStatus(prev => ({ ...prev, [po.id]: 'error' }));
            addLog('Verification Failed', `Failed POC verification attempt for PO ${po.poNumber}`);
            addNotification(`Invalid POC verification for PO ${po.poNumber}`, 'error');
             setTimeout(() => {
                setVerificationStatus(prev => ({ ...prev, [po.id]: null }));
            }, 2000);
        }
    };

    const getButtonState = (poId: string) => {
        const status = verificationStatus[poId];
        if (status === 'success') return 'bg-green-500 hover:bg-green-600';
        if (status === 'error') return 'bg-red-500 hover:bg-red-600';
        return 'bg-partners-green hover:bg-green-700 disabled:bg-gray-400';
    };

    const getButtonContent = (po: PurchaseOrder) => {
        const status = verificationStatus[po.id];
        if (status === 'success') return <CheckCircleIcon className="h-5 w-5" />;
        if (status === 'error') return <XCircleIcon className="h-5 w-5" />;
        return 'Verify';
    }

    return (
        <div className="p-4 sm:p-6 lg:p-8 flex-1">
            <div className="bg-white p-6 rounded-xl shadow-sm border border-gray-100">
                {ordersToVerify.length === 0 ? (
                    <div className="text-center py-12">
                        <ProfileIcon className="mx-auto h-16 w-16 text-gray-200"/>
                        <h3 className="mt-4 text-lg font-bold text-gray-800">All Clear!</h3>
                        <p className="mt-1 text-gray-400">There are no pending POC verifications at this time.</p>
                    </div>
                ) : (
                <div className="overflow-x-auto">
                    <table className="w-full text-sm text-left text-gray-600">
                        <thead className="text-[11px] text-gray-500 uppercase bg-gray-50/50">
                            <tr>
                                <th scope="col" className="px-6 py-4">PO Number</th>
                                <th scope="col" className="px-6 py-4">Store Code</th>
                                <th scope="col" className="px-6 py-4">Masked Phone Number</th>
                                <th scope="col" className="px-6 py-4">Enter Last 4 Digits</th>
                                <th scope="col" className="px-6 py-4">Action</th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-gray-100">
                            {ordersToVerify.map(po => (
                                <tr key={po.id} className="bg-white hover:bg-gray-50/80 transition-colors">
                                    <td className="px-6 py-4 font-bold text-partners-green whitespace-nowrap">{po.poNumber}</td>
                                    <td className="px-6 py-4 whitespace-nowrap font-medium text-gray-600">{po.storeCode}</td>
                                    <td className="px-6 py-4 whitespace-nowrap font-mono text-gray-400 tracking-wider">{`******${po.pocPhoneNumber?.slice(-4)}`}</td>
                                    <td className="px-6 py-4">
                                        <input 
                                            type="text"
                                            maxLength={4}
                                            value={last4Digits[po.id] || ''}
                                            onChange={(e) => handleInputChange(po.id, e.target.value)}
                                            className="w-24 p-2 border border-gray-300 rounded-lg focus:ring-partners-green focus:border-partners-green font-mono tracking-widest text-center shadow-inner"
                                            placeholder="XXXX"
                                        />
                                    </td>
                                    <td className="px-6 py-4">
                                        <button 
                                            onClick={() => handleVerify(po)}
                                            disabled={!last4Digits[po.id] || last4Digits[po.id]?.length !== 4 || !!verificationStatus[po.id]}
                                            className={`px-4 py-2 text-white font-bold rounded-lg transition-all text-xs w-24 flex justify-center items-center shadow-sm active:scale-95 ${getButtonState(po.id)}`}
                                        >
                                            {getButtonContent(po)}
                                        </button>
                                    </td>
                                </tr>
                            ))}
                        </tbody>
                    </table>
                </div>
                )}
            </div>
        </div>
    );
};

