// --- Helper Functions ---
const EXCLUDED_DATES = ['2025-12-25', '2026-01-01']; // Example holiday dates

const formatDate = (date: Date): string => {
    return new Intl.DateTimeFormat('en-GB', { day: 'numeric', month: 'short', year: '2-digit' }).format(date);
};

const getSuggestedAppointmentDate = (): Date => {
    let date = new Date();
    date.setDate(date.getDate() + 1); // Start from tomorrow
    while (true) {
        const dayOfWeek = date.getDay();
        const dateString = date.toISOString().split('T')[0];
        if (dayOfWeek !== 0 && !EXCLUDED_DATES.includes(dateString)) {
            return date;
        }
        date.setDate(date.getDate() + 1);
    }
};

const calculateAwaitingDays = (requestDateStr?: string): number => {
    if (!requestDateStr) return 0;
    const requestDate = new Date(requestDateStr.replace(/(\d+ \w+) (\d+)/, '$1 20$2'));
    const today = new Date();
    const diffTime = Math.abs(today.getTime() - requestDate.getTime());
    return Math.ceil(diffTime / (1000 * 60 * 60 * 24));
};

