interface AppointmentManagerProps {
    purchaseOrders: PurchaseOrder[];
    setPurchaseOrders: React.Dispatch<React.SetStateAction<PurchaseOrder[]>>;
    addLog: (action: string, details: string) => void;
    addNotification: (message: string, type?: 'info' | 'success' | 'warning' | 'error') => void;
}

const AppointmentManager: React.FC<AppointmentManagerProps> = ({ purchaseOrders, setPurchaseOrders, addLog, addNotification }) => {
    const [modalState, setModalState] = useState<{ type: 'request' | 'update' | null, po: PurchaseOrder | null }>({ type: null, po: null });

    const relevantOrders = useMemo(() => {
        return purchaseOrders.filter(po => po.status === POStatus.AppointmentPending || po.appointmentDate);
    }, [purchaseOrders]);

    const handleSave = (poId: string, updatedData: Partial<PurchaseOrder>) => {
        setPurchaseOrders(prev => prev.map(p => p.id === poId ? { ...p, ...updatedData } : p));
    };

    const handleFollowUp = (poId: string) => {
        setPurchaseOrders(prev => prev.map(p => p.id === poId ? { ...p, followUpCount: (p.followUpCount || 0) + 1 } : p));
        const po = purchaseOrders.find(p => p.id === poId);
        addLog('Follow Up', `Triggered follow up for PO ${po?.poNumber}`);
        addNotification(`Follow-up logged for PO ${po?.poNumber}`, 'info');
    };

    return (
        <>
            {modalState.po && modalState.type === 'request' && (
                <RequestAppointmentModal 
                    po={modalState.po} 
                    onClose={() => setModalState({ type: null, po: null })}
                    onSave={(data) => handleSave(modalState.po!.id, data)}
                    addLog={addLog}
                    addNotification={addNotification}
                />
            )}
            {modalState.po && modalState.type === 'update' && (
                <UpdateAppointmentModal 
                    po={modalState.po} 
                    onClose={() => setModalState({ type: null, po: null })}
                    onSave={(data) => handleSave(modalState.po!.id, data)}
                    addLog={addLog}
                    addNotification={addNotification}
                />
            )}

            <div className="p-4 sm:p-6 lg:p-8 flex-1">
                <div className="bg-white p-6 rounded-xl shadow-sm border border-gray-100">
                    {relevantOrders.length === 0 ? (
                        <div className="text-center py-12">
                            <CalendarIcon className="mx-auto h-16 w-16 text-gray-200"/>
                            <h3 className="mt-4 text-lg font-bold text-gray-800">No Appointments Pending</h3>
                            <p className="mt-1 text-gray-400">There are no orders currently awaiting an appointment.</p>
                        </div>
                    ) : (
                    <div className="overflow-x-auto">
                        <table className="w-full text-sm text-left text-gray-600">
                            <thead className="text-[11px] text-gray-500 uppercase bg-gray-50/50">
                                <tr>
                                    <th className="px-6 py-4">PO Number</th>
                                    <th className="px-6 py-4">Awaiting / Status</th>
                                    <th className="px-6 py-4">Appointment Details</th>
                                    <th className="px-6 py-4">Actions</th>
                                </tr>
                            </thead>
                            <tbody className="divide-y divide-gray-100">
                                {relevantOrders.map(po => (
                                    <tr key={po.id} className="bg-white hover:bg-gray-50 transition-colors">
                                        <td className="px-6 py-4 font-bold text-partners-green whitespace-nowrap">{po.poNumber} <br/> <span className="text-gray-400 font-normal text-xs">{po.storeCode}</span></td>
                                        <td className="px-6 py-4">
                                            {po.appointmentRequestDate && !po.appointmentDate ? (
                                                <div className="flex flex-col">
                                                    <span className="font-bold text-yellow-600 uppercase text-[10px]">Awaiting Response</span>
                                                    <span className="text-xs text-gray-400">{calculateAwaitingDays(po.appointmentRequestDate)} days</span>
                                                     {po.followUpCount && <span className="mt-1 text-[9px] font-bold bg-blue-50 text-blue-600 px-2 py-0.5 rounded border border-blue-100 w-fit">Follow-up {po.followUpCount}</span>}
                                                </div>
                                            ) : po.appointmentDate ? (
                                                <span className="font-bold text-green-600 uppercase text-[10px]">Scheduled</span>
                                            ) : (
                                                 <span className="font-bold text-gray-400 uppercase text-[10px]">Request Pending</span>
                                            )}
                                        </td>
                                        <td className="px-6 py-4">
                                            {po.appointmentDate ? (
                                                <div>
                                                    <p className="font-bold text-gray-800 text-xs">{po.appointmentDate} at {po.appointmentTime}</p>
                                                    <p className="text-[10px] text-gray-400 font-mono">ID: {po.appointmentId}</p>
                                                </div>
                                            ) : (
                                                <span className="text-gray-300 italic text-xs">Not scheduled</span>
                                            )}
                                        </td>
                                        <td className="px-6 py-4">
                                            <div className="flex items-center gap-2">
                                                {!po.appointmentRequestDate && (
                                                    <button onClick={() => setModalState({ type: 'request', po })} className="px-3 py-1 text-[10px] font-bold text-white bg-blue-600 rounded-lg hover:bg-blue-700 shadow-sm transition-all active:scale-95">Request</button>
                                                )}
                                                {po.appointmentRequestDate && !po.appointmentDate && (
                                                    <>
                                                        <button onClick={() => setModalState({ type: 'update', po })} className="px-3 py-1 text-[10px] font-bold text-white bg-partners-green rounded-lg hover:bg-green-700 shadow-sm transition-all active:scale-95">Update</button>
                                                        <button onClick={() => handleFollowUp(po.id)} title="Log Follow-up" className="p-1.5 text-gray-400 hover:text-blue-600 bg-gray-50 rounded-lg transition-colors"><ReplyIcon className="h-4 w-4"/></button>
                                                    </>
                                                )}
                                                {po.appointmentDate && (
                                                     <button onClick={() => setModalState({ type: 'update', po })} className="px-3 py-1 text-[10px] font-bold text-gray-600 bg-gray-100 rounded-lg hover:bg-gray-200 transition-all active:scale-95">Edit</button>
                                                )}
                                            </div>
                                        </td>
                                    </tr>
                                ))}
                            </tbody>
                        </table>
                    </div>
                    )}
                </div>
            </div>
        </>
    );
};

