import React, { useState, useMemo, useEffect, useCallback } from 'react';
import Sidebar from './components/Sidebar';
import Header from './components/Header';
import SummaryCard from './components/SummaryCard';
import PoTable from './components/PoTable';
import SalesOrderTable from './components/SalesOrderTable';
import PocVerification from './components/PocVerification';
import AppointmentManager from './components/AppointmentManager';
import AdminPanel from './components/AdminPanel';
import FinanceManager from './components/FinanceManager';
import InventoryManager from './components/InventoryManager';
import ReportsManager from './components/ReportsManager';
import ToastContainer from './components/ToastContainer';
import { MenuIcon, XIcon, QuestionMarkCircleIcon, RefreshIcon } from './components/icons/Icons';
import { initialUsers, initialRolePermissions } from './data/mockData';
import { type PurchaseOrder, POStatus, ActivityLog, NotificationItem, ViewType, User, RolePermissions, InventoryItem, ChannelConfig } from './types';
import { fetchPurchaseOrders, fetchInventoryFromSheet, fetchChannelConfigs } from './services/api';

const App: React.FC = () => {
  const [isSidebarOpen, setSidebarOpen] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [lastSynced, setLastSynced] = useState<number>(0);

  const [users, setUsers] = useState<User[]>(initialUsers);
  const [currentUser, setCurrentUser] = useState<User>(initialUsers[0]);
  const [rolePermissions, setRolePermissions] = useState<RolePermissions>(initialRolePermissions);

  const [activeView, setActiveView] = useState<ViewType>('Dashboard');
  const [activeFilter, setActiveFilter] = useState('All POs');
  const [adminTab, setAdminTab] = useState<'users' | 'roles' | 'channels' | 'integrations' | 'logs'>('users');

  const [purchaseOrders, setPurchaseOrders] = useState<PurchaseOrder[]>([]);
  const [inventoryItems, setInventoryItems] = useState<InventoryItem[]>([]);
  const [channelConfigs, setChannelConfigs] = useState<ChannelConfig[]>([]);

  const [logs, setLogs] = useState<ActivityLog[]>([
    { id: '1', user: 'System', action: 'Init', details: 'System initialized and logged in as ' + currentUser.name, timestamp: new Date().toLocaleString() }
  ]);
  const [notifications, setNotifications] = useState<NotificationItem[]>([]);
  const [toasts, setToasts] = useState<NotificationItem[]>([]);

  const addLog = useCallback((action: string, details: string) => {
    const newLog: ActivityLog = {
        id: Date.now().toString() + Math.random().toString(36).substring(7),
        user: currentUser.name, 
        action,
        details,
        timestamp: new Date().toLocaleString()
    };
    setLogs(prev => [newLog, ...prev]);
  }, [currentUser]);

  const addNotification = useCallback((message: string, type: 'info' | 'success' | 'warning' | 'error' = 'info') => {
    const newNotification: NotificationItem = {
        id: Date.now().toString() + Math.random().toString(36).substring(7),
        message,
        timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
        read: false,
        type
    };

    // Add to history (Bell icon)
    setNotifications(prev => [newNotification, ...prev]);

    // Trigger toast (Floating card) for major actions or if specified
    setToasts(prev => [...prev, newNotification]);
  }, []);

  const removeToast = useCallback((id: string) => {
    setToasts(prev => prev.filter(t => t.id !== id));
  }, []);

  const refreshData = useCallback(async (force = false) => {
      if (!force && purchaseOrders.length > 0 && Date.now() - lastSynced < 1800000) return; 

      setIsLoading(true);
      try {
          const [poData, invData, channelData] = await Promise.all([
              fetchPurchaseOrders(),
              fetchInventoryFromSheet(),
              fetchChannelConfigs()
          ]);

          if (poData.length > 0) {
              setPurchaseOrders(poData);
          }
          if (invData.length > 0) setInventoryItems(invData);
          if (channelData.length > 0) setChannelConfigs(channelData);
          setLastSynced(Date.now());
      } catch (e) {
          addNotification('Failed to sync data from Google Sheets.', 'error');
      } finally {
          setIsLoading(false);
      }
  }, [lastSynced, purchaseOrders.length, addNotification]);

  useEffect(() => {
    refreshData();
    const intervalId = setInterval(() => refreshData(true), 30 * 60 * 1000);
    return () => clearInterval(intervalId);
  }, [refreshData]);

  const summaryData = useMemo(() => {
    const totalActive = purchaseOrders.filter(p => p.status !== POStatus.Closed).length;
    const belowThreshold = purchaseOrders.filter(p => p.status === POStatus.BelowThreshold).length;
    const pocsPending = purchaseOrders.filter(p => p.status === POStatus.POCPending).length;
    const awaitingAppointment = purchaseOrders.filter(p => p.status === POStatus.AppointmentPending).length;
    const inTransit = purchaseOrders.filter(p => p.status === POStatus.InTransit).length;
    const rtoShipments = purchaseOrders.filter(p => p.status === POStatus.RTO).length;
    const closedShipments = purchaseOrders.filter(p => p.status === POStatus.Closed).length;

    return [
      { title: 'Total Active POs', value: totalActive.toString(), change: 'across all stages', color: 'green', targetView: 'Purchase Orders', targetFilter: 'All POs' },
      { title: 'Below Threshold', value: belowThreshold.toString(), change: 'low value orders', color: 'yellow', targetView: 'Purchase Orders', targetFilter: 'Below Threshold' },
      { title: 'POCs Pending', value: pocsPending.toString(), change: 'verification needed', color: 'yellow', targetView: 'POC Verification', targetFilter: '' },
      { title: 'Awaiting Appointment', value: awaitingAppointment.toString(), change: 'follow-up required', color: 'yellow', targetView: 'Appointments', targetFilter: '' },
      { title: 'Sales Orders In-Transit', value: inTransit.toString(), change: 'currently shipping', color: 'blue', targetView: 'Sales Orders', targetFilter: 'In-Transit' },
      { title: 'RTO Shipments', value: rtoShipments.toString(), change: 'in last 30 days', color: 'red', targetView: 'Sales Orders', targetFilter: 'RTO' },
      { title: 'Closed Sales Orders', value: closedShipments.toString(), change: 'in last 30 days', color: 'green', targetView: 'Sales Orders', targetFilter: 'Closed' },
    ];
  }, [purchaseOrders]);

  const tabCounts = useMemo(() => {
    const statusToTabMap: { [key in POStatus]?: string } = {
        [POStatus.NewPO]: 'New PO',
        [POStatus.BelowThreshold]: 'Below Threshold',
        [POStatus.POCPending]: 'POC Verification',
        [POStatus.AppointmentPending]: 'Appointment to be taken',
        [POStatus.InTransit]: 'In-Transit',
        [POStatus.GRNPending]: 'GRN Pending',
        [POStatus.GRNUpdated]: 'GRN Updated',
        [POStatus.RTO]: 'RTO',
        [POStatus.Closed]: 'Closed',
    };
    const initialCounts = Object.values(statusToTabMap).reduce((acc, tabName) => {
        if(tabName) acc[tabName] = 0;
        return acc;
    }, {} as { [key: string]: number });
    const countsByStatus = purchaseOrders.reduce((acc, po) => {
        const tabName = statusToTabMap[po.status];
        if (tabName) acc[tabName] = (acc[tabName] || 0) + 1;
        return acc;
    }, initialCounts);
    return { 'All POs': purchaseOrders.length, ...countsByStatus };
  }, [purchaseOrders]);

  const handleCardClick = (view: ViewType, filter?: string) => {
      if (rolePermissions[currentUser.role]?.includes(view)) {
          setActiveView(view);
          if (filter) setActiveFilter(filter);
      } else {
          addNotification(`Access Denied: Permission required for ${view}.`, 'error');
      }
  };

  const renderContent = () => {
    if (isLoading && purchaseOrders.length === 0) {
        return (
            <div className="flex-1 flex flex-col items-center justify-center p-8">
                <RefreshIcon className="h-12 w-12 text-partners-green animate-spin mb-4" />
                <p className="text-gray-600 font-bold text-lg">Synchronizing your Dashboard...</p>
                <p className="text-gray-400 text-sm mt-1">Connecting to Google Sheets and EasyEcom</p>
            </div>
        );
    }

    switch (activeView) {
        case 'Dashboard':
            return (
                <div className="p-4 sm:p-6 lg:p-8 flex-1">
                    <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 2xl:grid-cols-7 gap-6">
                        {summaryData.map((card, index) => (
                            <SummaryCard key={index} title={card.title} value={card.value} changeText={card.change} color={card.color as any} onClick={() => handleCardClick(card.targetView as ViewType, card.targetFilter)} />
                        ))}
                    </div>
                </div>
            );
        case 'POC Verification': return <PocVerification purchaseOrders={purchaseOrders} setPurchaseOrders={setPurchaseOrders} addLog={addLog} addNotification={addNotification} />;
        case 'Appointments': return <AppointmentManager purchaseOrders={purchaseOrders} setPurchaseOrders={setPurchaseOrders} addLog={addLog} addNotification={addNotification} />;
        case 'Finance': return <FinanceManager purchaseOrders={purchaseOrders} setPurchaseOrders={setPurchaseOrders} addLog={addLog} />;
        case 'Inventory': return <InventoryManager addLog={addLog} inventoryItems={inventoryItems} setInventoryItems={setInventoryItems} onSync={() => refreshData(true)} isSyncing={isLoading} />;
        case 'Reports': return <ReportsManager purchaseOrders={purchaseOrders} inventoryItems={inventoryItems} />;
        case 'Purchase Orders':
        case 'Uploads':
        case 'GRN / POD':
            return (
                <div className="p-4 sm:p-6 lg:p-8 flex-1">
                    <PoTable activeFilter={activeFilter} setActiveFilter={setActiveFilter} purchaseOrders={purchaseOrders} setPurchaseOrders={setPurchaseOrders} tabCounts={tabCounts} addLog={addLog} addNotification={addNotification} onSync={() => refreshData(true)} isSyncing={isLoading} />
                </div>
            );
        case 'Sales Orders':
             return (
                <div className="p-4 sm:p-6 lg:p-8 flex-1">
                    <SalesOrderTable activeFilter={activeFilter} setActiveFilter={setActiveFilter} purchaseOrders={purchaseOrders} setPurchaseOrders={setPurchaseOrders} tabCounts={tabCounts} addLog={addLog} addNotification={addNotification} onSync={() => refreshData(true)} isSyncing={isLoading} />
                </div>
            );
        case 'Admin': return (
            <AdminPanel 
                logs={logs} 
                users={users} 
                setUsers={setUsers} 
                rolePermissions={rolePermissions} 
                setRolePermissions={setRolePermissions} 
                addLog={addLog} 
                currentUser={currentUser} 
                channelConfigs={channelConfigs} 
                onSync={() => refreshData(true)}
                activeTab={adminTab}
                setActiveTab={setAdminTab}
            />
        );
        default: return <div className="p-8 text-center text-gray-500">Section Under Construction</div>;
    }
  };

  return (
    <div className="flex h-screen bg-partners-gray-bg font-sans">
      <ToastContainer toasts={toasts} onRemove={removeToast} />
      {isSidebarOpen && <div className="fixed inset-0 bg-black opacity-50 z-20 lg:hidden" onClick={() => setSidebarOpen(false)}></div>}
      <div className={`fixed lg:relative inset-y-0 left-0 transform ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full'} lg:translate-x-0 transition-transform duration-300 ease-in-out z-30`}>
        <Sidebar activeView={activeView} setActiveView={setActiveView} currentUser={currentUser} permissions={rolePermissions} onSwitchUser={(id) => { const u = users.find(x => x.id === id); if(u) setCurrentUser(u); }} allUsers={users} />
      </div>
      <main className="flex-1 flex flex-col overflow-y-auto">
        {/* Mobile Header Toggle */}
        <div className="flex items-center justify-between p-4 lg:hidden bg-white border-b border-gray-200">
            <button onClick={() => setSidebarOpen(!isSidebarOpen)} className="text-gray-500 focus:outline-none p-2 hover:bg-gray-100 rounded-lg">
                {isSidebarOpen ? <XIcon className="h-6 w-6" /> : <MenuIcon className="h-6 w-6" />}
            </button>
            <div className="font-bold text-gray-800">PO Portal</div>
            <div className="w-10"></div>
        </div>

        {/* Global Unified Header */}
        <Header 
            notifications={notifications} 
            onMarkRead={(id) => setNotifications(n => n.map(i => i.id === id ? {...i, read: true} : i))} 
            onClearAll={() => setNotifications([])} 
            onViewLogs={() => { setActiveView('Admin'); setAdminTab('logs'); }} 
            activeView={activeView}
        />

        {/* View Content */}
        {renderContent()}
      </main>

      <button className="fixed bottom-6 right-6 bg-green-600 text-white p-3 rounded-full shadow-lg hover:bg-green-700 transition-all hover:scale-110 flex items-center gap-2 z-40">
        <QuestionMarkCircleIcon className="h-6 w-6" />
        <span className="font-bold text-sm pr-1">Help</span>
      </button>
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { ActivityLog, User, Role, ViewType, RolePermissions, ChannelConfig } from '../types';
import { ShieldCheckIcon, UserGroupIcon, LockClosedIcon, PencilIcon, TrashIcon, CheckCircleIcon, XCircleIcon, PlusIcon, AdminIcon, CogIcon, RefreshIcon, GlobeIcon } from './icons/Icons';
import { saveChannelConfig, saveSystemConfig, fetchSystemConfig } from '../services/api';

interface AdminPanelProps {
    logs: ActivityLog[];
    users: User[];
    setUsers: React.Dispatch<React.SetStateAction<User[]>>;
    rolePermissions: RolePermissions;
    setRolePermissions: React.Dispatch<React.SetStateAction<RolePermissions>>;
    addLog: (action: string, details: string) => void;
    currentUser: User;
    channelConfigs: ChannelConfig[];
    onSync: () => void;
    activeTab: 'users' | 'roles' | 'channels' | 'integrations' | 'logs';
    setActiveTab: (tab: 'users' | 'roles' | 'channels' | 'integrations' | 'logs') => void;
}

const inputClassName = "mt-1 block w-full rounded-lg border border-gray-300 bg-white text-gray-900 shadow-sm focus:border-partners-green focus:ring-partners-green sm:text-sm py-3 px-3";
const disabledInputClassName = "mt-1 block w-full rounded-lg border border-gray-300 bg-gray-100 text-gray-500 shadow-sm sm:text-sm py-3 px-3 cursor-not-allowed";

// Sub-component: User Modal
interface UserModalProps {
    user?: User;
    onClose: () => void;
    onSave: (user: User) => void;
}

const UserModal: React.FC<UserModalProps> = ({ user, onClose, onSave }) => {
    const [formData, setFormData] = useState<Partial<User>>(user || {
        name: '', email: '', contactNumber: '', role: 'Limited Access', avatarInitials: ''
    });

    const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
        setFormData({ ...formData, [e.target.name]: e.target.value });
    };

    const handleSave = () => {
        if (!formData.name || !formData.email || !formData.role) return;

        const initials = formData.name.split(' ').map(n => n[0]).join('').toUpperCase().slice(0, 2);

        onSave({
            id: user?.id || Date.now().toString(),
            name: formData.name,
            email: formData.email,
            contactNumber: formData.contactNumber || '',
            role: formData.role as Role,
            avatarInitials: initials
        });
    };

    return (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
            <div className="bg-white rounded-lg shadow-xl w-full max-w-md">
                <div className="p-6 border-b">
                    <h3 className="text-lg font-semibold text-gray-800">{user ? 'Edit User' : 'Create New User'}</h3>
                </div>
                <div className="p-6 space-y-4">
                    <div>
                        <label className="block text-sm font-medium text-gray-700">Full Name</label>
                        <input name="name" value={formData.name} onChange={handleChange} className={inputClassName} />
                    </div>
                    <div>
                        <label className="block text-sm font-medium text-gray-700">Email</label>
                        <input name="email" type="email" value={formData.email} onChange={handleChange} className={inputClassName} />
                    </div>
                    <div>
                        <label className="block text-sm font-medium text-gray-700">Contact Number</label>
                        <input name="contactNumber" value={formData.contactNumber} onChange={handleChange} className={inputClassName} />
                    </div>
                    <div>
                        <label className="block text-sm font-medium text-gray-700">Role</label>
                        <select name="role" value={formData.role} onChange={handleChange} className={inputClassName}>
                            <option value="Admin">Admin</option>
                            <option value="Key Account Manager">Key Account Manager</option>
                            <option value="Finance Manager">Finance Manager</option>
                            <option value="Supply Chain Manager">Supply Chain Manager</option>
                            <option value="Limited Access">Limited Access</option>
                        </select>
                    </div>
                </div>
                <div className="px-6 py-4 bg-gray-50 flex justify-end gap-3 rounded-b-lg">
                    <button onClick={onClose} className="px-4 py-2 text-sm font-medium text-gray-700 bg-white border border-gray-300 rounded-md hover:bg-gray-50">Cancel</button>
                    <button onClick={handleSave} className="px-4 py-2 text-sm font-medium text-white bg-partners-green border border-transparent rounded-md hover:bg-green-700">Save User</button>
                </div>
            </div>
        </div>
    );
};

// Sub-component: Channel Modal
interface ChannelModalProps {
    channel?: ChannelConfig;
    onClose: () => void;
    onSave: (config: ChannelConfig) => void;
}

const ChannelModal: React.FC<ChannelModalProps> = ({ channel, onClose, onSave }) => {
    const [formData, setFormData] = useState<ChannelConfig>(channel || {
        id: '',
        channelName: '',
        status: 'Active',
        sourceEmail: '',
        searchKeyword: '',
        minOrderThreshold: 0,
        pocName: '',
        pocEmail: '',
        pocPhone: ''
    });

    const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
        const value = e.target.type === 'number' ? Number(e.target.value) : e.target.value;
        setFormData({ ...formData, [e.target.name]: value });
    };

    const handleSave = () => {
        if (!formData.channelName) return;
        onSave({ ...formData, id: formData.channelName }); // Ensure ID is set
    };

    return (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
            <div className="bg-white rounded-lg shadow-xl w-full max-w-2xl">
                <div className="p-6 border-b">
                    <h3 className="text-lg font-semibold text-gray-800">{channel ? 'Edit Channel' : 'Add New Channel'}</h3>
                </div>
                <div className="p-6 grid grid-cols-1 md:grid-cols-2 gap-4">
                    <div className="col-span-1 md:col-span-2">
                        <label className="block text-sm font-medium text-gray-700">Channel Name (Unique ID)</label>
                        <input name="channelName" value={formData.channelName} onChange={handleChange} disabled={!!channel} className={channel ? disabledInputClassName : inputClassName} />
                    </div>
                    <div>
                        <label className="block text-sm font-medium text-gray-700">Status</label>
                        <select name="status" value={formData.status} onChange={handleChange} className={inputClassName}>
                            <option value="Active">Active</option>
                            <option value="Inactive">Inactive</option>
                        </select>
                    </div>
                    <div>
                         <label className="block text-sm font-medium text-gray-700">Min Order Threshold (₹)</label>
                         <input type="number" name="minOrderThreshold" value={formData.minOrderThreshold} onChange={handleChange} className={inputClassName} />
                    </div>
                    <div className="col-span-1 md:col-span-2">
                         <h4 className="text-sm font-semibold text-gray-600 mb-2 mt-2 border-b pb-1">Integration Details</h4>
                    </div>
                    <div>
                        <label className="block text-sm font-medium text-gray-700">Source Email</label>
                        <input name="sourceEmail" value={formData.sourceEmail} onChange={handleChange} placeholder="orders@channel.com" className={inputClassName} />
                    </div>
                    <div>
                        <label className="block text-sm font-medium text-gray-700">Search Keyword</label>
                        <input name="searchKeyword" value={formData.searchKeyword} onChange={handleChange} placeholder="Subject contains..." className={inputClassName} />
                    </div>
                     <div className="col-span-1 md:col-span-2">
                         <h4 className="text-sm font-semibold text-gray-600 mb-2 mt-2 border-b pb-1">POC Details</h4>
                    </div>
                    <div>
                        <label className="block text-sm font-medium text-gray-700">POC Name</label>
                        <input name="pocName" value={formData.pocName} onChange={handleChange} className={inputClassName} />
                    </div>
                    <div>
                         <label className="block text-sm font-medium text-gray-700">POC Email</label>
                        <input name="pocEmail" value={formData.pocEmail} onChange={handleChange} className={inputClassName} />
                    </div>
                    <div>
                         <label className="block text-sm font-medium text-gray-700">POC Phone</label>
                        <input name="pocPhone" value={formData.pocPhone} onChange={handleChange} className={inputClassName} />
                    </div>
                </div>
                <div className="px-6 py-4 bg-gray-50 flex justify-end gap-3 rounded-b-lg">
                    <button onClick={onClose} className="px-4 py-2 text-sm font-medium text-gray-700 bg-white border border-gray-300 rounded-md hover:bg-gray-50">Cancel</button>
                    <button onClick={handleSave} className="px-4 py-2 text-sm font-medium text-white bg-partners-green border border-transparent rounded-md hover:bg-green-700">Save Configuration</button>
                </div>
            </div>
        </div>
    );
}

const AdminPanel: React.FC<AdminPanelProps> = ({ logs, users, setUsers, rolePermissions, setRolePermissions, addLog, currentUser, channelConfigs, onSync, activeTab, setActiveTab }) => {
    const [userModal, setUserModal] = useState<{ isOpen: boolean, user?: User }>({ isOpen: false });

    // Channel Config State
    const [channelModal, setChannelModal] = useState<{ isOpen: boolean, channel?: ChannelConfig }>({ isOpen: false });

    // System Config State
    const [systemConfig, setSystemConfig] = useState({ easyecom_url: '', easyecom_token: '', easyecom_email: '' });
    const [configLoading, setConfigLoading] = useState(false);

    useEffect(() => {
        if (activeTab === 'integrations') {
            loadSystemConfig();
        }
    }, [activeTab]);

    const loadSystemConfig = async () => {
        setConfigLoading(true);
        const config = await fetchSystemConfig();
        if (config) {
            setSystemConfig({
                easyecom_url: config['easyecom_url'] || 'https://api.easyecom.io/orders/create',
                easyecom_token: config['easyecom_token'] || '',
                easyecom_email: config['easyecom_email'] || ''
            });
        }
        setConfigLoading(false);
    };

    const handleSaveSystemConfig = async () => {
        setConfigLoading(true);
        try {
            const res = await saveSystemConfig(systemConfig);
            if (res.status === 'success') {
                addLog('System Config', 'Updated EasyEcom integration credentials');
                alert('Configuration saved successfully.');
            } else {
                alert('Failed to save configuration.');
            }
        } catch (e) {
            alert('Error saving configuration');
        } finally {
            setConfigLoading(false);
        }
    };

    const handleSaveUser = (userData: User) => {
        if (userModal.user) {
            setUsers(prev => prev.map(u => u.id === userData.id ? userData : u));
            addLog('Update User', `Updated details for user ${userData.name}`);
        } else {
            setUsers(prev => [...prev, userData]);
            addLog('Create User', `Created new user ${userData.name} with role ${userData.role}`);
        }
        setUserModal({ isOpen: false });
    };

    const handleDeleteUser = (userId: string) => {
        if (confirm('Are you sure you want to delete this user?')) {
            const user = users.find(u => u.id === userId);
            setUsers(prev => prev.filter(u => u.id !== userId));
            addLog('Delete User', `Deleted user ${user?.name}`);
        }
    };

    const handleSaveChannel = async (config: ChannelConfig) => {
        // Close modal first
        setChannelModal({ isOpen: false });
        addLog('Update Channel', `Saving configuration for ${config.channelName}...`);

        // API Call
        try {
            const res = await saveChannelConfig(config);
            if (res.status === 'success') {
                addLog('Success', `Configuration saved for ${config.channelName}. Refreshing data...`);
                onSync(); // Trigger global refresh
            } else {
                alert('Failed to save to Google Sheet: ' + res.message);
            }
        } catch (e) {
            console.error(e);
            alert('Network error saving channel config.');
        }
    };

    const handlePermissionChange = (role: string, view: ViewType) => {
        setRolePermissions(prev => {
            const currentPermissions = prev[role] || [];
            const hasPermission = currentPermissions.includes(view);
            let newPermissions;
            if (hasPermission) {
                newPermissions = currentPermissions.filter(p => p !== view);
            } else {
                newPermissions = [...currentPermissions, view];
            }
            return { ...prev, [role]: newPermissions };
        });
    };

    const allViews: ViewType[] = ['Dashboard', 'Purchase Orders', 'Uploads', 'POC Verification', 'Appointments', 'Sales Orders', 'GRN / POD', 'Reports', 'Finance', 'Inventory', 'Admin'];

    return (
        <>
            {userModal.isOpen && (
                <UserModal 
                    user={userModal.user} 
                    onClose={() => setUserModal({ isOpen: false })} 
                    onSave={handleSaveUser} 
                />
            )}
            {channelModal.isOpen && (
                <ChannelModal
                    channel={channelModal.channel}
                    onClose={() => setChannelModal({ isOpen: false })}
                    onSave={handleSaveChannel}
                />
            )}

            <div className="p-4 sm:p-6 lg:p-8 flex-1">
                {/* Tabs */}
                <div className="flex border-b border-gray-200 mb-6 overflow-x-auto">
                    <button 
                        onClick={() => setActiveTab('users')}
                        className={`px-4 py-2 text-sm font-medium border-b-2 flex items-center gap-2 whitespace-nowrap ${activeTab === 'users' ? 'border-partners-green text-partners-green' : 'border-transparent text-gray-500 hover:text-gray-700'}`}
                    >
                        <UserGroupIcon className="h-4 w-4" /> Users
                    </button>
                    <button 
                         onClick={() => setActiveTab('roles')}
                         className={`px-4 py-2 text-sm font-medium border-b-2 flex items-center gap-2 whitespace-nowrap ${activeTab === 'roles' ? 'border-partners-green text-partners-green' : 'border-transparent text-gray-500 hover:text-gray-700'}`}
                    >
                        <LockClosedIcon className="h-4 w-4" /> Roles & Permissions
                    </button>
                    <button 
                         onClick={() => setActiveTab('channels')}
                         className={`px-4 py-2 text-sm font-medium border-b-2 flex items-center gap-2 whitespace-nowrap ${activeTab === 'channels' ? 'border-partners-green text-partners-green' : 'border-transparent text-gray-500 hover:text-gray-700'}`}
                    >
                        <CogIcon className="h-4 w-4" /> Channel Config
                    </button>
                    <button 
                         onClick={() => setActiveTab('integrations')}
                         className={`px-4 py-2 text-sm font-medium border-b-2 flex items-center gap-2 whitespace-nowrap ${activeTab === 'integrations' ? 'border-partners-green text-partners-green' : 'border-transparent text-gray-500 hover:text-gray-700'}`}
                    >
                        <GlobeIcon className="h-4 w-4" /> Integrations
                    </button>
                    <button 
                         onClick={() => setActiveTab('logs')}
                         className={`px-4 py-2 text-sm font-medium border-b-2 flex items-center gap-2 whitespace-nowrap ${activeTab === 'logs' ? 'border-partners-green text-partners-green' : 'border-transparent text-gray-500 hover:text-gray-700'}`}
                    >
                        <ShieldCheckIcon className="h-4 w-4" /> Activity Logs
                    </button>
                </div>

                {/* Content */}
                <div className="bg-white rounded-xl shadow-sm overflow-hidden border border-gray-100">
                    {activeTab === 'users' && (
                        <div className="p-6">
                            <div className="flex justify-between items-center mb-4">
                                <h3 className="text-lg font-semibold text-gray-800">User Management</h3>
                                <button onClick={() => setUserModal({ isOpen: true })} className="flex items-center gap-2 px-4 py-2 bg-partners-green text-white text-sm font-medium rounded-lg hover:bg-green-700 shadow-sm transition-all active:scale-95">
                                    <PlusIcon className="h-4 w-4" /> Add User
                                </button>
                            </div>
                            <div className="overflow-x-auto">
                                <table className="w-full text-sm text-left text-gray-600">
                                    <thead className="text-xs text-gray-700 uppercase bg-gray-50">
                                        <tr>
                                            <th className="px-6 py-3">User</th>
                                            <th className="px-6 py-3">Contact</th>
                                            <th className="px-6 py-3">Role</th>
                                            <th className="px-6 py-3 text-right">Actions</th>
                                        </tr>
                                    </thead>
                                    <tbody>
                                        {users.map(user => (
                                            <tr key={user.id} className="border-b hover:bg-gray-50 transition-colors">
                                                <td className="px-6 py-4">
                                                    <div className="flex items-center gap-3">
                                                        <div className="h-8 w-8 rounded-full bg-blue-100 flex items-center justify-center text-xs font-bold text-blue-700">
                                                            {user.avatarInitials}
                                                        </div>
                                                        <div>
                                                            <p className="font-medium text-gray-900">{user.name}</p>
                                                            <p className="text-xs text-gray-500">{user.email}</p>
                                                        </div>
                                                    </div>
                                                </td>
                                                <td className="px-6 py-4">{user.contactNumber}</td>
                                                <td className="px-6 py-4">
                                                    <span className={`px-2 py-1 text-xs font-medium rounded-full ${
                                                        user.role === 'Admin' ? 'bg-purple-100 text-purple-800' :
                                                        user.role === 'Limited Access' ? 'bg-gray-100 text-gray-800' :
                                                        'bg-blue-100 text-blue-800'
                                                    }`}>
                                                        {user.role}
                                                    </span>
                                                </td>
                                                <td className="px-6 py-4 text-right">
                                                    <div className="flex justify-end gap-2">
                                                        <button onClick={() => setUserModal({ isOpen: true, user })} className="p-1.5 text-gray-500 hover:text-blue-600 hover:bg-blue-50 rounded-md transition-colors">
                                                            <PencilIcon className="h-4 w-4" />
                                                        </button>
                                                        {user.id !== currentUser.id && ( // Prevent self-deletion
                                                            <button onClick={() => handleDeleteUser(user.id)} className="p-1.5 text-gray-500 hover:text-red-600 hover:bg-red-50 rounded-md transition-colors">
                                                                <TrashIcon className="h-4 w-4" />
                                                            </button>
                                                        )}
                                                    </div>
                                                </td>
                                            </tr>
                                        ))}
                                    </tbody>
                                </table>
                            </div>
                        </div>
                    )}

                    {activeTab === 'roles' && (
                        <div className="p-6">
                             <div className="mb-4">
                                <h3 className="text-lg font-semibold text-gray-800">Role Permissions</h3>
                                <p className="text-sm text-gray-500">Define which sections each role can access.</p>
                            </div>
                            <div className="overflow-x-auto">
                                <table className="w-full text-sm text-left text-gray-600">
                                    <thead className="text-xs text-gray-700 uppercase bg-gray-50">
                                        <tr>
                                            <th className="px-4 py-3 bg-gray-50 sticky left-0 z-10">Section / Role</th>
                                            {Object.keys(rolePermissions).map(role => (
                                                <th key={role} className="px-4 py-3 text-center">{role}</th>
                                            ))}
                                        </tr>
                                    </thead>
                                    <tbody>
                                        {allViews.map(view => (
                                            <tr key={view} className="border-b hover:bg-gray-50">
                                                <td className="px-4 py-3 font-medium text-gray-900 bg-gray-50 sticky left-0 z-10">{view}</td>
                                                {Object.keys(rolePermissions).map(role => {
                                                    const isAllowed = rolePermissions[role].includes(view);
                                                    const isAdmin = role === 'Admin';
                                                    return (
                                                        <td key={role} className="px-4 py-3 text-center">
                                                            <input 
                                                                type="checkbox" 
                                                                checked={isAllowed} 
                                                                onChange={() => !isAdmin && handlePermissionChange(role, view)}
                                                                disabled={isAdmin} // Admin always has full access
                                                                className={`h-4 w-4 rounded border-gray-300 ${isAdmin ? 'text-gray-400 cursor-not-allowed' : 'text-partners-green focus:ring-partners-green cursor-pointer'}`}
                                                            />
                                                        </td>
                                                    );
                                                })}
                                            </tr>
                                        ))}
                                    </tbody>
                                </table>
                            </div>
                             <div className="mt-4 p-3 bg-yellow-50 rounded-lg border border-yellow-200 text-xs text-yellow-800 flex items-start gap-2">
                                <AdminIcon className="h-4 w-4 mt-0.5" />
                                <span>Note: The 'Admin' role is locked to have full access to all sections to prevent system lockout. Changes to other roles are saved automatically.</span>
                            </div>
                        </div>
                    )}

                     {activeTab === 'channels' && (
                        <div className="p-6">
                            <div className="flex justify-between items-center mb-4">
                                <div>
                                    <h3 className="text-lg font-semibold text-gray-800">Channel Configurations</h3>
                                    <p className="text-sm text-gray-500">Manage integration details and thresholds for sales channels.</p>
                                </div>
                                <div className="flex gap-2">
                                     <button onClick={onSync} className="p-2 text-gray-500 hover:bg-gray-100 rounded-lg transition-colors" title="Refresh">
                                        <RefreshIcon className="h-5 w-5" />
                                    </button>
                                    <button onClick={() => setChannelModal({ isOpen: true })} className="flex items-center gap-2 px-4 py-2 bg-partners-green text-white text-sm font-medium rounded-lg hover:bg-green-700 shadow-sm transition-all active:scale-95">
                                        <PlusIcon className="h-4 w-4" /> Add Channel
                                    </button>
                                </div>
                            </div>

