export default PoTable;

const SHEET_PO = "PO_Database";
const SHEET_INVENTORY = "Master_SKU_Mapping";
const SHEET_CHANNEL_CONFIG = "Channel_Config";
const SHEET_SHIPMENT_LOG = "EE Shipment Log";
const SHEET_EE_CUSTOMERS = "EE_Customers";
const LOG_ORDER_SHEET = "EE Shipment Log";

// Handle GET requests
function doGet(e) {
  const action = e.parameter.action;
  if (action === 'getPurchaseOrders') return getPurchaseOrders();
  if (action === 'getInventory') return getInventory();
  if (action === 'getChannelConfigs') return getChannelConfigs();
  if (action === 'getSystemConfig') return getSystemConfig();
  return responseJSON({status: 'error', message: 'Invalid action'});
}

// Handle POST requests
function doPost(e) {
  try {
    const data = JSON.parse(e.postData.contents);
    const action = data.action;
    if (action === 'createItem') return createInventoryItem(data);
    if (action === 'updatePrice') return updateInventoryPrice(data);
    if (action === 'saveChannelConfig') return saveChannelConfig(data);
    if (action === 'saveSystemConfig') return saveSystemConfig(data);
    if (action === 'pushToEasyEcom') return pushToEasyEcom(data);
    if (action === 'createEasyEcomCustomer') return createEasyEcomCustomer(data);
    return responseJSON({status: 'error', message: 'Invalid action'});
  } catch (error) {
    return responseJSON({status: 'error', message: error.toString()});
  }
}

// --- Data Fetchers ---
function getPurchaseOrders() {
  const sheet = SpreadsheetApp.getActiveSpreadsheet().getSheetByName(SHEET_PO);
  if (!sheet) return responseJSON({status: 'error', message: 'PO sheet not found'});
  return responseJSON({status: 'success', data: getDataAsJSON(sheet)});
}

function getInventory() {
  const sheet = SpreadsheetApp.getActiveSpreadsheet().getSheetByName(SHEET_INVENTORY);
  if (!sheet) return responseJSON({status: 'error', message: 'Inventory sheet not found'});
  return responseJSON({status: 'success', data: getDataAsJSON(sheet)});
}

function getChannelConfigs() {
  const sheet = SpreadsheetApp.getActiveSpreadsheet().getSheetByName(SHEET_CHANNEL_CONFIG);
  if (!sheet) return responseJSON({status: 'error', message: 'Config sheet not found'});
  return responseJSON({status: 'success', data: getDataAsJSON(sheet)});
}

function getSystemConfig() {
  const props = PropertiesService.getScriptProperties();
  return responseJSON({
    status: 'success',
    data: {
      easyecom_url: "https://api.easyecom.io/webhook/v2/createOrder",
      easyecom_email: props.getProperty('EASY_ECOM_EMAIL') || '',
      easyecom_token: props.getProperty('EASY_ECOM_TOKEN') ? '********' : ''
    }
  });
}

// --- Main EasyEcom Customer Creation Logic ---

function createEasyEcomCustomer(data) {
  const post_b2b_url = "https://api.easyecom.io/Wholesale/CreateCustomer";
  const token = getEasyEcomToken();
  const scriptProperties = PropertiesService.getScriptProperties();
  const X_API_KEY = scriptProperties.getProperty('EASY_ECOM_API_KEY');

  const payload = {
    "companyName": data.companyName,
    "taxIdentificationNumber" : data.taxIdentificationNumber || "URP",
    "password": "test@1234",
    "email": data.email || 'sunil@cubelelo.com',
    "contactNumber": data.contactNumber,
    "country": "India",
    "billingStateId": data.billingStateId || "27",
    "billingStreet": data.billingStreet,
    "billingCity": data.billingCity,
    "billingPostalCode": data.billingPostalCode,
    "currency": "INR",
    "description": "Auto-created via PO Portal",
    "dispatchStateId": data.billingStateId || "27",
    "dispatchStreet": data.billingStreet,
    "dispatchCity": data.billingCity,
    "dispatchPostalCode": data.billingPostalCode
  };

  const options = {
    "method": "POST",
    "headers": {
      "Authorization": "Bearer " + token,
      "x-api-key": X_API_KEY,
      "Content-Type": "application/json"
    },
    "payload": JSON.stringify(payload),
    "muteHttpExceptions": true
  };

  try {
    const response = UrlFetchApp.fetch(post_b2b_url, options);
    const json = JSON.parse(response.getContentText());

    if (response.getResponseCode() === 200 && json.code === 200) {
      // 1. Log to Customers Sheet
      const cId = json.data ? json.data.customerId : "";
      const ss = SpreadsheetApp.getActiveSpreadsheet();
      let cSheet = ss.getSheetByName(SHEET_EE_CUSTOMERS);
      if (cSheet) {
        cSheet.appendRow([cId, data.companyName, data.email, data.contactNumber, data.billingStreet, data.billingCity, data.billingPostalCode, data.billingStateId, "India"]);
      }

      // 2. Update PO_Database to link this specific PO and any future ones with same channel/store
      if (data.poNumber) {
        updatePoDatabaseWithCustomerId(data.poNumber, cId);
      }

      return responseJSON({status: 'success', customerId: cId, message: 'Customer created successfully'});
    } else {
      return responseJSON({status: 'error', message: json.message || 'API Error'});
    }
  } catch (e) {
    return responseJSON({status: 'error', message: e.toString()});
  }
}

function updatePoDatabaseWithCustomerId(poNumber, customerId) {
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  const sheet = ss.getSheetByName(SHEET_PO);
  if (!sheet) return;

  const data = sheet.getDataRange().getValues();
  const headers = data[0].map(h => String(h).trim());

  const poIdx = headers.indexOf('PO Number');
  const channelIdx = headers.indexOf('Channel Name');
  const storeIdx = headers.indexOf('Store Code');
  let eeCustIdx = headers.indexOf('EE Customer ID');

  if (eeCustIdx === -1) {
    eeCustIdx = headers.length;
    sheet.getRange(1, eeCustIdx + 1).setValue('EE Customer ID');
  }

  // Find the Channel and Store for this specific PO to update all similar ones
  let targetChannel = "";
  let targetStore = "";
  for (let i = 1; i < data.length; i++) {
    if (String(data[i][poIdx]).trim() === String(poNumber).trim()) {
      targetChannel = data[i][channelIdx];
      targetStore = data[i][storeIdx];
      break;
    }
  }

  // Bulk update all POs with same channel/store
  for (let i = 1; i < data.length; i++) {
    if (data[i][channelIdx] === targetChannel && data[i][storeIdx] === targetStore) {
      sheet.getRange(i + 1, eeCustIdx + 1).setValue(customerId);
    }
  }
}

// --- Main EasyEcom Push Logic ---

function pushToEasyEcom(data) {
  let poRef = data.poNumber;
  if (data.isPartial) {
    poRef = getNextPoVariant(data.poNumber);
  }

  const formattedItems = data.items.map(item => ({
    "Sku": item.masterSku || item.articleCode,
    "Quantity": Number(item.qty),
    "Price": Number(item.unitCost || 0)
  }));

  const result = createEasyEcomB2BOrder(poRef, data.eeCustomerId, formattedItems);

  if (result.success) {
    updatePoDatabaseWithRef(data.poNumber, data.items.map(i => i.articleCode), poRef);
    return responseJSON({status: 'success', message: `Order ${poRef} created successfully.`, poRef: poRef});
  } else {
    return responseJSON({status: 'error', message: result.message});
  }
}

function updatePoDatabaseWithRef(poNumber, articleCodes, eeRefId) {
  const sheet = SpreadsheetApp.getActiveSpreadsheet().getSheetByName(SHEET_PO);
  if (!sheet) return;

  const data = sheet.getDataRange().getValues();
  const headers = data[0].map(h => String(h).trim());

  const poIdx = headers.indexOf('PO Number');
  let skuIdx = headers.indexOf('Item Code');
  if (skuIdx === -1) skuIdx = headers.indexOf('Article Code');

  let refIdx = headers.indexOf('EE Order Ref ID');
  if (refIdx === -1) {
    refIdx = headers.length;
    sheet.getRange(1, refIdx + 1).setValue('EE Order Ref ID');
  }

  if (poIdx === -1 || skuIdx === -1) return;

  const codesToFind = articleCodes.map(c => String(c).trim());

  for (let i = 1; i < data.length; i++) {
    const rowPo = String(data[i][poIdx]).trim();
    const rowSku = String(data[i][skuIdx]).trim();

    if (rowPo === String(poNumber).trim() && codesToFind.includes(rowSku)) {
      sheet.getRange(i + 1, refIdx + 1).setValue(eeRefId);
    }
  }
}

function getNextPoVariant(basePoNumber) {
  const sheet = SpreadsheetApp.getActiveSpreadsheet().getSheetByName(SHEET_SHIPMENT_LOG);
  if (!sheet) return basePoNumber + "-1";
  const lastRow = sheet.getLastRow();
  if (lastRow < 2) return basePoNumber + "-1";
  const poNumbers = sheet.getRange(2, 2, lastRow - 1, 1).getValues().flat();
  let maxSuffix = 0;
  const escapedBase = basePoNumber.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'); 
  const regex = new RegExp(`^${escapedBase}-(\\d+)$`, 'i');
  poNumbers.forEach(po => {
    const match = String(po).match(regex);
    if (match) {
      const suffix = parseInt(match[1], 10);
      if (suffix > maxSuffix) maxSuffix = suffix;
    }
  });
  return basePoNumber + "-" + (maxSuffix + 1);
}

function createEasyEcomB2BOrder(poRef, customerId, items) {
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  const addressDetails = getCustomerAddressFromSheet(ss, customerId);

  if (!addressDetails) {
    return { success: false, message: `Customer ID ${customerId} not found in EE_Customers.` };
  }

  const timeZone = Session.getScriptTimeZone();
  const now = new Date();
  const deliveryDate = new Date();
  deliveryDate.setDate(now.getDate() + 10); 

  const orderDateStr = Utilities.formatDate(now, timeZone, "yyyy-MM-dd HH:mm:ss");
  const deliveryDateStr = Utilities.formatDate(deliveryDate, timeZone, "yyyy-MM-dd HH:mm:ss");

  const payload = {
    "orderType": "businessorder",
    "orderNumber": String(poRef), 
    "orderDate": orderDateStr,
    "expDeliveryDate": deliveryDateStr,
    "remarks1": "B2B Shipment via API",
    "paymentMode": "5", 
    "shippingMethod": "1",
    "customer": [{
      "customerId": String(customerId),
      "billing": addressDetails,
      "shipping": addressDetails
    }],
    "items": items,
    "queue": 0
  };

  const token = getEasyEcomToken();
  if (!token) return { success: false, message: "Auth Token Failed" };

  const scriptProperties = PropertiesService.getScriptProperties();
  const X_API_KEY = scriptProperties.getProperty('EASY_ECOM_API_KEY');

  var url = "https://api.easyecom.io/webhook/v2/createOrder";

  const options = {
    method: "POST", 
    headers: {
      "Authorization": "Bearer " + token,
      "x-api-key": X_API_KEY,
      "Content-Type": "application/json"
    },
    payload: JSON.stringify(payload),
    muteHttpExceptions: true
  };

  try {
    const response = UrlFetchApp.fetch(url, options);
    const text = response.getContentText();
    if (text.trim().startsWith("<")) return { success: false, message: "API Error: Endpoint issue." };
    const json = JSON.parse(text);

    if (response.getResponseCode() === 200 && json.code === 200) {
      const orderId = json.data ? json.data.order_id : (json.order_id || "");
      logOrderCreation(ss, poRef, customerId, "Success", orderId, JSON.stringify(json));
      return { success: true, message: "Order Created"};
    } else {
      const errorMsg = json.message || JSON.stringify(json);
      logOrderCreation(ss, poRef, customerId, "Failed", "", errorMsg);
      return { success: false, message: errorMsg };
    }
  } catch (e) {
    logOrderCreation(ss, poRef, customerId, "Error", "", e.message);
    return { success: false, message: e.message };
  }
}

function getEasyEcomToken() {
   return PropertiesService.getScriptProperties().getProperty('EASY_ECOM_TOKEN');
}

function getCustomerAddressFromSheet(ss, targetCId) {
  const sheet = ss.getSheetByName(SHEET_EE_CUSTOMERS);
  if (!sheet) return null;
  const data = sheet.getDataRange().getValues();
  for (let i = 1; i < data.length; i++) {
    const rowId = String(data[i][0]).trim();
    if (rowId === String(targetCId).trim()) {
      let rawPhone = data[i][3];
      let cleanPhone = (typeof rawPhone === 'number') ? Math.floor(rawPhone).toString() : String(rawPhone || "").trim();
      let rawZip = data[i][6];
      let cleanZip = (typeof rawZip === 'number') ? Math.floor(rawZip).toString() : String(rawZip || "").trim();
      return {
        "name": String(data[i][1] || "").trim(),
        "addressLine1": String(data[i][4] || "").trim(),
        "addressLine2": "",
        "postalCode": cleanZip,
        "city": String(data[i][5] || "").trim(),
        "state": String(data[i][7] || "").trim(),
        "country": String(data[i][8] || "India").trim(),
        "contact": cleanPhone,
        "email": String(data[i][2] || "").trim()
      };
    }
  }
  return null;
}

function logOrderCreation(ss, poRef, customerId, status, eeOrderId, message) {
  let sheet = ss.getSheetByName(LOG_ORDER_SHEET);
  if (!sheet) {
    sheet = ss.insertSheet(LOG_ORDER_SHEET);
    sheet.appendRow(["Timestamp", "PO Reference", "Customer ID", "Status", "EE Order ID", "API Message"]);
    sheet.getRange(1, 1, 1, 6).setFontWeight("Bold");
  }
  sheet.appendRow([new Date(), poRef, customerId, status, eeOrderId || "N/A", message]);
}

function createInventoryItem(data) {
  const sheet = SpreadsheetApp.getActiveSpreadsheet().getSheetByName(SHEET_INVENTORY);
  if (!sheet) return responseJSON({status: 'error', message: 'Sheet not found.'});
  sheet.appendRow([data.channel, data.articleCode, data.sku, data.spIncTax || 0, data.stock || 0, data.ean || '', data.itemName || '', data.mrp || 0]);
  return responseJSON({status: 'success', message: 'Item created'});
}

function updateInventoryPrice(data) {
  const sheet = SpreadsheetApp.getActiveSpreadsheet().getSheetByName(SHEET_INVENTORY);
  if (!sheet) return responseJSON({status: 'error', message: 'Sheet not found.'});
  const rows = sheet.getDataRange().getValues();
  const headers = rows[0].map(h => String(h).toLowerCase().trim());
  const colChannel = headers.indexOf('channel');
  let colArticle = headers.indexOf('channel item code');
  if (colArticle === -1) colArticle = headers.findIndex(h => h.includes('item code') || h.includes('article'));
  let colPrice = headers.indexOf('selling price');
  if (colPrice === -1) colPrice = headers.findIndex(h => h.includes('selling') || h.includes('sp'));
  if (colChannel === -1 || colArticle === -1 || colPrice === -1) return responseJSON({status: 'error', message: 'Columns not found'});
  for (let i = 1; i < rows.length; i++) {
    if (String(rows[i][colChannel]).trim().toLowerCase() === data.channel.toLowerCase() && String(rows[i][colArticle]).trim() === String(data.articleCode)) {
      sheet.getRange(i + 1, colPrice + 1).setValue(data.newPrice);
      return responseJSON({status: 'success', message: 'Price updated'});
    }
  }
  return responseJSON({status: 'error', message: 'Item not found'});
}

function saveChannelConfig(data) {
  const sheet = SpreadsheetApp.getActiveSpreadsheet().getSheetByName(SHEET_CHANNEL_CONFIG);
  if (!sheet) return responseJSON({status: 'error', message: `Sheet not found.`});
  const rows = sheet.getDataRange().getValues();
  const headers = rows[0] ? rows[0].map(h => String(h).toLowerCase().trim()) : [];
  const nameIdx = headers.indexOf('channel name');
  let rowIndex = -1;
  for (let i = 1; i < rows.length; i++) {
    if (String(rows[i][nameIdx]).toLowerCase() === data.channelName.toLowerCase()) { rowIndex = i + 1; break; }
  }
  const getCol = (name) => { const idx = headers.findIndex(h => h === name.toLowerCase()); return idx === -1 ? -1 : idx + 1; };
  if (rowIndex > 0) {
      sheet.getRange(rowIndex, getCol('Status')).setValue(data.status);
      sheet.getRange(rowIndex, getCol('Source Email')).setValue(data.sourceEmail);
      sheet.getRange(rowIndex, getCol('Search Keyword')).setValue(data.searchKeyword);
      sheet.getRange(rowIndex, getCol('Min Order Threshold')).setValue(data.minOrderThreshold);
      sheet.getRange(rowIndex, getCol('POC Name')).setValue(data.pocName);
      sheet.getRange(rowIndex, getCol('POC Email')).setValue(data.pocEmail);
      sheet.getRange(rowIndex, getCol('POC Phone')).setValue(data.pocPhone);
      return responseJSON({status: 'success', message: 'Channel updated'});
  }
  const newRow = new Array(headers.length).fill('');
  newRow[nameIdx] = data.channelName;
  newRow[getCol('Status')-1] = data.status;
  newRow[getCol('Source Email')-1] = data.sourceEmail;
  newRow[getCol('Search Keyword')-1] = data.searchKeyword;
  newRow[getCol('Min Order Threshold')-1] = data.minOrderThreshold;
  newRow[getCol('POC Name')-1] = data.pocName;
  newRow[getCol('POC Email')-1] = data.pocEmail;
  newRow[getCol('POC Phone')-1] = data.pocPhone;
  sheet.appendRow(newRow);
  return responseJSON({status: 'success', message: 'Channel created'});
}

function saveSystemConfig(data) {
  const props = PropertiesService.getScriptProperties();
  if (data.easyecom_token) props.setProperty('EASY_ECOM_TOKEN', data.easyecom_token);
  if (data.easyecom_email) props.setProperty('EASY_ECOM_EMAIL', data.easyecom_email);
  return responseJSON({status: 'success', message: 'Config saved'});
}

function getDataAsJSON(sheet) {
  const rawData = sheet.getDataRange().getValues();
  if (rawData.length === 0) return [];
  const headers = rawData[0];
  const data = [];
  for (let i = 1; i < rawData.length; i++) {
    const row = rawData[i];
    if (row[0] === "" && row[1] === "") continue;
    const obj = {};
    for (let j = 0; j < headers.length; j++) { obj[headers[j]] = row[j]; }
    data.push(obj);
  }
  return data;
}

function responseJSON(data) {
  return ContentService.createTextOutput(JSON.stringify(data)).setMimeType(ContentService.MimeType.JSON);
}

