                                                            <div>
                                                                <p className="text-[10px] uppercase font-bold text-gray-400">EasyEcom Cust ID</p>
                                                                <p className={`text-xs font-bold ${po.eeCustomerId ? 'text-blue-600' : 'text-red-500 italic'}`}>{po.eeCustomerId || 'Not Mapped'}</p>
