                                                                    const isMismatch = item.priceCheckStatus === 'Mismatch';
                                                                    const isPushed = !!item.eeOrderRefId;
                                                                    const showWaiting = !isPushed && pushedItems.length > 0;

                                                                    return (
                                                                        <tr key={idx} className={`${isPushed ? 'bg-gray-50/50' : 'hover:bg-gray-50/30'}`}>
