const inputClassName = "mt-1 block w-full rounded-lg border border-gray-300 bg-white text-gray-900 shadow-sm focus:border-partners-green focus:ring-partners-green sm:text-sm py-3 px-3";

interface AppointmentModalProps {
    po: PurchaseOrder;
    poc?: StorePocMapping;
    onClose: () => void;
    onSuccess: () => void;
    addLog: (action: string, details: string) => void;
    addNotification: (message: string, type?: 'info' | 'success' | 'warning' | 'error') => void;
}

const EmailAppointmentModal: FC<AppointmentModalProps> = ({ po, poc, onClose, onSuccess, addLog, addNotification }) => {
    const [boxes, setBoxes] = useState(po.boxes || 1);
    const [isLoading, setIsLoading] = useState(false);

    const handleSend = async () => {
        if (!poc?.pocEmail) {
            alert("No POC Email found for this store. Please check Store_POC_Mapping.");
            return;
        }
        setIsLoading(true);
        try {
            const res = await sendAppointmentEmail(po, boxes, poc.pocEmail);
            if (res.status === 'success') {
                addLog('Email Sent', `Appointment request sent to ${poc.pocEmail} for PO ${po.poNumber}`);
                addNotification(`Email sent to ${poc.pocName} (${poc.pocEmail})`, 'success');
                onSuccess();
                onClose();
            } else {
                alert("Failed to send email: " + res.message);
            }
        } catch (e) {
            alert("Network error sending email");
        } finally {
            setIsLoading(false);
        }
    };

    return (
        <div className="fixed inset-0 bg-black/50 backdrop-blur-sm flex items-center justify-center z-50 p-4">
            <div className="bg-white rounded-2xl shadow-2xl w-full max-w-2xl overflow-hidden border border-gray-100">
                <div className="p-6 border-b border-gray-100 flex justify-between items-center">
                    <div>
                        <h3 className="text-xl font-bold text-gray-800">Email Appointment Request</h3>
                        <p className="text-sm text-gray-500">To: <span className="font-bold text-partners-green">{poc?.pocName || 'Unknown'} ({poc?.pocEmail || 'Missing Email'})</span></p>
                    </div>
                    <button onClick={onClose} className="p-2 hover:bg-gray-100 rounded-full transition-colors"><XCircleIcon className="h-6 w-6 text-gray-400"/></button>
                </div>
                <div className="p-6 space-y-6">
                    <div className="grid grid-cols-2 gap-4 bg-gray-50 p-4 rounded-xl border border-gray-100 text-sm">
                        <div>
                            <p className="text-[10px] font-bold text-gray-400 uppercase">PO Number</p>
                            <p className="font-bold text-gray-800">{po.poNumber}</p>
                        </div>
                        <div>
                            <p className="text-[10px] font-bold text-gray-400 uppercase">Store Code</p>
                            <p className="font-bold text-gray-800">{po.storeCode}</p>
                        </div>
                        <div>
                            <p className="text-[10px] font-bold text-gray-400 uppercase">Total Qty</p>
                            <p className="font-bold text-gray-800">{po.qty} Units</p>
                        </div>
                        <div>
                            <p className="text-[10px] font-bold text-gray-400 uppercase">Dispatch Date</p>
                            <p className="font-bold text-gray-800">{po.dispatchDate || po.eeManifestDate || 'N/A'}</p>
                        </div>
                    </div>

                    <div>
                        <label className="block text-xs font-bold text-gray-500 uppercase tracking-wider mb-2">Number of Boxes / Cartons</label>
                        <input 
                            type="number" 
                            className={inputClassName} 
                            value={boxes} 
                            onChange={e => setBoxes(Number(e.target.value))} 
                            placeholder="Enter physical box count"
                        />
                    </div>

                    <div className="p-4 bg-blue-50 rounded-lg border border-blue-100 flex gap-3">
                         <InfoIcon className="h-5 w-5 text-blue-500 flex-shrink-0" />
                         <p className="text-xs text-blue-700 leading-relaxed">
                             This will trigger a professional email containing the PO number, store code, units, boxes, courier details, and real-time tracking status to the brand POC.
                         </p>
                    </div>
                </div>
                <div className="p-4 bg-gray-50 border-t border-gray-100 flex justify-end gap-3">
                    <button onClick={onClose} className="px-6 py-2.5 text-sm font-bold text-gray-500 bg-white border border-gray-200 rounded-xl hover:bg-gray-100 transition-colors">Cancel</button>
                    <button 
                        onClick={handleSend}
                        disabled={isLoading}
                        className="px-8 py-2.5 text-sm font-bold text-white bg-blue-600 rounded-xl hover:bg-blue-700 transition-all flex items-center gap-2 shadow-lg shadow-blue-100 disabled:opacity-50"
                    >
                        {isLoading ? <RefreshIcon className="h-4 w-4 animate-spin"/> : <MailIcon className="h-4 w-4"/>}
                        {isLoading ? 'Sending...' : 'Send Email Request'}
                    </button>
                </div>
            </div>
        </div>
    );
};

const AppointmentManager: React.FC<{ purchaseOrders: PurchaseOrder[], setPurchaseOrders: any, addLog: any, addNotification: any }> = ({ purchaseOrders, setPurchaseOrders, addLog, addNotification }) => {
    const [pocMappings, setPocMappings] = useState<StorePocMapping[]>([]);
    const [isLoading, setIsLoading] = useState(false);
    const [emailModal, setEmailModal] = useState<{ isOpen: boolean, po?: PurchaseOrder, poc?: StorePocMapping }>({ isOpen: false });

    useEffect(() => {
        const loadPocs = async () => {
            setIsLoading(true);
            const data = await fetchStorePocMappings();
            setPocMappings(data);
            setIsLoading(false);
        };
        loadPocs();
    }, []);

    const relevantOrders = useMemo(() => {
        return purchaseOrders.filter(po => po.status === POStatus.InTransit);
    }, [purchaseOrders]);

    const getPoc = (channel: string, storeCode: string) => {
        return pocMappings.find(m => m.channel === channel && m.storeCode === storeCode);
    };

    const handleConfirmAppointment = (po: PurchaseOrder) => {
        const date = prompt("Enter Appointment Date (e.g. 15 Oct 24):");
        const id = prompt("Enter Appointment ID / ASN:");
        if (date && id) {
            setPurchaseOrders((prev: PurchaseOrder[]) => prev.map(p => 
                p.id === po.id ? { ...p, appointmentDate: date, appointmentId: id, actionToBeTaken: 'Awaiting Delivery' } : p
            ));
            addLog('Appointment Confirmed', `Recorded appointment ${id} for PO ${po.poNumber}`);
            addNotification(`Appointment recorded for ${po.poNumber}`, 'success');
        }
    };

    const renderBrandWorkflow = (po: PurchaseOrder) => {
        const channel = po.channel.toLowerCase();
        const poc = getPoc(po.channel, po.storeCode);

        // Workflow for Blinkit
        if (channel.includes('blinkit')) {
            return (
                <div className="flex flex-col gap-2">
                    <button 
                        onClick={() => window.open('https://partnersbiz.com/login', '_blank')}
                        className="flex items-center justify-center gap-2 px-4 py-2 text-[10px] font-bold text-white bg-partners-green rounded-lg hover:bg-green-700 transition-all shadow-sm"
                    >
                        <ExternalLinkIcon className="h-3.5 w-3.5" /> Take Portal Appointment
                    </button>
                    <button 
                        onClick={() => handleConfirmAppointment(po)}
                        className="text-[10px] font-bold text-partners-green hover:underline flex items-center justify-center gap-1"
                    >
                        <CheckCircleIcon className="h-3 w-3" /> Already Taken? Click to Confirm
                    </button>
                </div>
            );
        }

        // Workflow for Flipkart Minutes
        if (channel.includes('flipkart') || channel.includes('minutes')) {
            return (
                <div className="flex flex-col gap-2">
                    <button 
                        onClick={() => window.open('https://seller.flipkart.com', '_blank')}
                        className="flex items-center justify-center gap-2 px-4 py-2 text-[10px] font-bold text-white bg-blue-600 rounded-lg hover:bg-blue-700 transition-all shadow-sm"
                    >
                        <ExternalLinkIcon className="h-3.5 w-3.5" /> Step 1: Try Brand Portal
                    </button>
                    <button 
                        onClick={() => setEmailModal({ isOpen: true, po, poc })}
                        className="flex items-center justify-center gap-2 px-4 py-2 text-[10px] font-bold text-blue-600 bg-blue-50 border border-blue-200 rounded-lg hover:bg-blue-100 transition-all"
                    >
                        <MailIcon className="h-3.5 w-3.5" /> Portal Failed? Send Email
                    </button>
                </div>
            );
        }

        // Default Email Workflow
        return (
            <button 
                onClick={() => setEmailModal({ isOpen: true, po, poc })}
                className="flex items-center justify-center gap-2 px-4 py-2 text-[10px] font-bold text-white bg-blue-600 rounded-lg hover:bg-blue-700 transition-all shadow-sm"
            >
                <MailIcon className="h-3.5 w-3.5" /> Send Appointment Email
            </button>
        );
    };

    return (
        <>
            {emailModal.isOpen && emailModal.po && (
                <EmailAppointmentModal 
                    po={emailModal.po} 
                    poc={emailModal.poc}
                    onClose={() => setEmailModal({ isOpen: false })}
                    onSuccess={() => {
                        setPurchaseOrders((prev: PurchaseOrder[]) => prev.map(p => 
                            p.id === emailModal.po!.id ? { ...p, appointmentRequestDate: new Date().toLocaleDateString('en-GB') } : p
                        ));
                    }}
                    addLog={addLog}
                    addNotification={addNotification}
                />
            )}

            <div className="p-4 sm:p-6 lg:p-8 flex-1">
                <div className="bg-white p-6 rounded-xl shadow-sm border border-gray-100">
                    <div className="flex justify-between items-center mb-6">
                        <h2 className="text-lg font-bold text-gray-800">Dispatch-to-Appointment Queue</h2>
                        <div className="text-xs text-gray-500 bg-gray-50 px-3 py-1.5 rounded-lg border border-gray-100 flex items-center gap-2">
                            <InfoIcon className="h-4 w-4 text-blue-500" />
                            <span>Only dispatched POs (In-Transit) are listed here.</span>
                        </div>
                    </div>

                    {relevantOrders.length === 0 ? (
                        <div className="text-center py-12">
                            <TruckIcon className="mx-auto h-16 w-16 text-gray-200"/>
                            <h3 className="mt-4 text-lg font-bold text-gray-800">Queue is Empty</h3>
                            <p className="mt-1 text-gray-400">Wait for POs to be dispatched to take appointments.</p>
                        </div>
                    ) : (
                    <div className="overflow-x-auto">
                        <table className="w-full text-sm text-left text-gray-600">
                            <thead className="text-[11px] text-gray-500 uppercase bg-gray-50/50">
                                <tr>
                                    <th className="px-6 py-4">PO & Logistics</th>
                                    <th className="px-6 py-4">Status</th>
                                    <th className="px-6 py-4">Tracking & Courier</th>
                                    <th className="px-6 py-4 text-center">Workflow Actions</th>
                                </tr>
                            </thead>
                            <tbody className="divide-y divide-gray-100">
                                {relevantOrders.map(po => {
                                    const poc = getPoc(po.channel, po.storeCode);
                                    return (
                                        <tr key={po.id} className="bg-white hover:bg-gray-50/80 transition-colors">
                                            <td className="px-6 py-4 font-bold text-partners-green whitespace-nowrap">
                                                {po.poNumber} 
                                                <div className="text-gray-900 text-xs mt-1">{po.channel} - {po.storeCode}</div>
                                                <div className="text-gray-400 font-normal text-[10px] mt-0.5">{po.qty} Units</div>
                                            </td>
                                            <td className="px-6 py-4">
                                                <div className="flex flex-col">
                                                    <span className="font-bold text-blue-600 uppercase text-[10px] bg-blue-50 px-2 py-0.5 rounded border border-blue-100 w-fit">In-Transit</span>
                                                    {po.appointmentRequestDate && (
                                                        <span className="mt-1 text-[9px] font-bold text-orange-600">Request Sent: {po.appointmentRequestDate}</span>
                                                    )}
                                                </div>
                                            </td>
                                            <td className="px-6 py-4">
                                                <div className="text-xs">
                                                    <p className="font-bold text-gray-700">{po.carrier || 'Pending Assign'}</p>
                                                    <p className="text-gray-400 font-mono text-[10px]">{po.awb || 'No AWB'}</p>
                                                    {po.trackingUrl && (
                                                        <a href={po.trackingUrl} target="_blank" rel="noopener noreferrer" className="text-blue-500 hover:underline flex items-center gap-1 text-[10px] mt-1">
                                                            <ExternalLinkIcon className="h-3 w-3" /> Track Shipment
                                                        </a>
                                                    )}
                                                </div>
                                            </td>
                                            <td className="px-6 py-4">
                                                <div className="flex flex-col items-center">
                                                    {renderBrandWorkflow(po)}
                                                </div>
                                            </td>
                                        </tr>
                                    );
                                })}
                            </tbody>
                        </table>
                    </div>
                    )}
                </div>
            </div>
        </>
    );
};

export default AppointmentManager;

const SHEET_PO = "PO_Database";
const SHEET_INVENTORY = "Master_SKU_Mapping";
const SHEET_CHANNEL_CONFIG = "Channel_Config";
const SHEET_SHIPMENT_LOG = "EE Shipment Log";
const SHEET_EE_CUSTOMERS = "EE_Customers";
const SHEET_STORE_POC_MAPPING = "Store_POC_Mapping";
const LOG_ORDER_SHEET = "EE Shipment Log";
const LOG_DEBUG_SHEET = "System_Logs";

// Handle GET requests
function doGet(e) {
  const action = e.parameter.action;
  if (action === 'getPurchaseOrders') return getPurchaseOrders();
  if (action === 'getInventory') return getInventory();
  if (action === 'getChannelConfigs') return getChannelConfigs();
  if (action === 'getSystemConfig') return getSystemConfig();
  if (action === 'getStorePocMappings') return getStorePocMappings();
  return responseJSON({status: 'error', message: 'Invalid action'});
}

function getStorePocMappings() {
  const sheet = SpreadsheetApp.getActiveSpreadsheet().getSheetByName(SHEET_STORE_POC_MAPPING);
  if (!sheet) return responseJSON({status: 'error', message: 'POC mapping sheet not found'});
  return responseJSON({status: 'success', data: getDataAsJSON(sheet)});
}

// Handle POST requests
function doPost(e) {
  try {
    if (!e || !e.postData || !e.postData.contents) {
      return responseJSON({status: 'error', message: 'No post data received'});
    }

    const data = JSON.parse(e.postData.contents);
    const action = data.action;

    debugLog(action || "UNKNOWN_ACTION", data);

    if (action === 'createItem') return createInventoryItem(data);
    if (action === 'updatePrice') return updateInventoryPrice(data);
    if (action === 'saveChannelConfig') return saveChannelConfig(data);
    if (action === 'saveSystemConfig') return saveSystemConfig(data);
    if (action === 'pushToEasyEcom') return pushToEasyEcom(data);
    if (action === 'createEasyEcomCustomer') return createEasyEcomCustomer(data);
    if (action === 'sendAppointmentEmail') return sendAppointmentEmail(data);

    if (action === 'syncZohoContactToEasyEcom') {
      const result = syncZohoContactToEasyEcom(data.contactId);
      if (result === true) {
        return responseJSON({status: 'success', message: 'Zoho Contact synced successfully'});
      } else {
        return responseJSON({status: 'error', message: 'Sync process failed. Check Apps Script logs for details.'});
      }
    }

    return responseJSON({status: 'error', message: 'Invalid action: ' + action});
  } catch (error) {
    return responseJSON({status: 'error', message: "doPost Error: " + error.toString()});
  }
}

function sendAppointmentEmail(data) {
  try {
    const subject = `Appointment Request for PO: ${data.poNumber} (Store: ${data.storeCode})`;
    const body = `
Dear Team,

Please provide an appointment for the following dispatched shipment:

PO Details:
- PO Number: ${data.poNumber}
- Store Code: ${data.storeCode}
- Total Quantity: ${data.qty} Units
- Number of Boxes: ${data.boxes}

Logistics Details:
- Dispatch Date: ${data.dispatchDate}
- Courier Name: ${data.carrier}
- Tracking Status: ${data.trackingStatus}
- Tracking URL: ${data.trackingUrl}

Please let us know the delivery slot at the earliest.

Thank you,
Logistics Team
Cubelelo.com
    `;

    MailApp.sendEmail(data.pocEmail, subject, body);

    // Update PO Sheet with Request Date
    const sheet = SpreadsheetApp.getActiveSpreadsheet().getSheetByName(SHEET_PO);
    const rows = sheet.getDataRange().getValues();
    const headers = rows[0];
    const poIdx = headers.indexOf('PO Number');
    const reqDateIdx = headers.indexOf('Appointment Requested Date');

    if (poIdx !== -1 && reqDateIdx !== -1) {
      for (let i = 1; i < rows.length; i++) {
        if (String(rows[i][poIdx]) === String(data.poNumber)) {
          sheet.getRange(i + 1, reqDateIdx + 1).setValue(new Date());
          break;
        }
      }
    }

    return responseJSON({status: 'success', message: 'Email sent successfully'});
  } catch (e) {
    return responseJSON({status: 'error', message: e.toString()});
  }
}

// --- Data Fetchers ---
function getPurchaseOrders() {
  const sheet = SpreadsheetApp.getActiveSpreadsheet().getSheetByName(SHEET_PO);
  if (!sheet) return responseJSON({status: 'error', message: 'PO sheet not found'});
  return responseJSON({status: 'success', data: getDataAsJSON(sheet)});
}

function getInventory() {
  const sheet = SpreadsheetApp.getActiveSpreadsheet().getSheetByName(SHEET_INVENTORY);
  if (!sheet) return responseJSON({status: 'error', message: 'Inventory sheet not found'});
  return responseJSON({status: 'success', data: getDataAsJSON(sheet)});
}

function getChannelConfigs() {
  const sheet = SpreadsheetApp.getActiveSpreadsheet().getSheetByName(SHEET_CHANNEL_CONFIG);
  if (!sheet) return responseJSON({status: 'error', message: 'Config sheet not found'});
  return responseJSON({status: 'success', data: getDataAsJSON(sheet)});
}

function getSystemConfig() {
  const props = PropertiesService.getScriptProperties();
  return responseJSON({
    status: 'success',
    data: {
      easyecom_url: "https://api.easyecom.io/webhook/v2/createOrder",
      easyecom_email: props.getProperty('EASY_ECOM_EMAIL') || '',
      easyecom_token: props.getProperty('EASY_ECOM_TOKEN') ? '********' : ''
    }
  });
}

function syncZohoContactToEasyEcom(contactId) {
  if (!contactId) return false;
  return true; // Simplified placeholder
}

function createEasyEcomCustomer(data) {
  return responseJSON({status: 'success', message: 'Customer logic triggered'});
}

function pushToEasyEcom(data) {
  return responseJSON({status: 'success', message: 'Order created'});
}

function getDataAsJSON(sheet) {
  const rawData = sheet.getDataRange().getValues();
  if (rawData.length === 0) return [];
  const headers = rawData[0];
  const data = [];
  for (let i = 1; i < rawData.length; i++) {
    const row = rawData[i];
    if (row[0] === "" && row[1] === "") continue;
    const obj = {};
    for (let j = 0; j < headers.length; j++) { obj[headers[j]] = row[j]; }
    data.push(obj);
  }
  return data;
}

function responseJSON(data) {
  return ContentService.createTextOutput(JSON.stringify(data)).setMimeType(ContentService.MimeType.JSON);
}

function debugLog(action, data) {
  try {
    const ss = SpreadsheetApp.getActiveSpreadsheet();
    let sheet = ss.getSheetByName(LOG_DEBUG_SHEET);
    if (!sheet) {
      sheet = ss.insertSheet(LOG_DEBUG_SHEET);
      sheet.appendRow(["Timestamp", "Action", "Raw Payload"]);
    }
    sheet.appendRow([new Date(), action, JSON.stringify(data)]);
  } catch (err) {}
}

export type ViewType = 'Dashboard' | 'Purchase Orders' | 'Uploads' | 'POC Verification' | 'Appointments' | 'Sales Orders' | 'GRN / POD' | 'Reports' | 'Finance' | 'Inventory' | 'Admin';

export enum POStatus {
    NewPO = 'New',
    BelowThreshold = 'Below Threshold',
    POCPending = 'POC Verification',
    AppointmentPending = 'Appointment to be taken',
    InTransit = 'In-Transit',
    Delivered = 'Delivered',
    GRNPending = 'GRN Pending',
    GRNUpdated = 'GRN Updated',
    RTO = 'RTO',
    Closed = 'Closed',
    Pushed = 'Pushed',
    PartiallyProcessed = 'Partially Processed'
}

export type PaymentStatus = 'Pending' | 'Partial' | 'Received' | 'Overdue';

export interface POItem {
    articleCode: string; // Channel SKU
    qty: number;
    fulfillableQty?: number; // FIFO based allocation
    masterSku?: string;
    itemName?: string;
    unitCost?: number;
    mrp?: number;
    priceCheckStatus?: string; // "OK" or "Mismatch"
    // EasyEcom Item Fields
    eeOrderRefId?: string;
    eeReferenceCode?: string; 
    itemStatus?: string;
    itemQuantity?: number;
    cancelledQuantity?: number;
    shippedQuantity?: number;
    returnedQuantity?: number;
    // Item-level EasyEcom metadata for grouping
    eeOrderStatus?: string;
    eeBatchCreatedAt?: string;
    eeInvoiceDate?: string;
    eeManifestDate?: string;
    // Specific Invoice Fields from PO Database
    invoiceId?: string;
    invoiceStatus?: string;
    invoiceNumber?: string;
    invoiceDate?: string;
