const UserModal: React.FC<UserModalProps> = ({ user, onClose, onSave, isSaving }) => {
    const [formData, setFormData] = useState<Partial<User>>(user || {
        name: '', email: '', contactNumber: '', role: 'Limited Access', avatarInitials: ''
