                                                                                    </div>
                                                                                </div>
                                                                            </td>
                                                                            <td className={`py-4 text-right font-medium ${isPushed ? 'text-gray-400' : 'text-gray-700'}`}>{item.qty}</td>
                                                                            <td className={`py-4 text-right font-bold ${isPushed ? 'text-gray-400' : isFulfillable ? 'text-green-600' : 'text-red-600'}`}>
