                                                                                    isMismatch ? 'bg-red-50 text-red-600 border-red-100' : 'bg-green-50 text-green-600 border-green-100'
                                                                                }`}>
                                                                                    {item.priceCheckStatus || 'OK'}
                                                                                </span>
                                                                            </td>
                                                                            <td className={`py-4 text-right font-bold ${isPushed ? 'text-gray-400' : 'text-blue-600'}`}>₹{unitPriceIncTax}</td>
                                                                            <td className={`py-4 text-right ${isPushed ? 'text-gray-400' : 'text-gray-600'}`}>₹{item.mrp}</td>
                                                                            <td className="py-4 text-center">
                                                                                {isPushed ? (
                                                                                    <div className="flex flex-col items-center">
                                                                                        <span className="text-[9px] font-bold text-green-700 bg-green-100/50 px-2 py-0.5 rounded border border-green-200 uppercase" title={item.eeOrderRefId}>
                                                                                            Pushed
                                                                                        </span>
                                                                                        <span className="text-[8px] font-mono text-gray-400 mt-1">{item.eeOrderRefId}</span>
                                                                                    </div>
                                                                                ) : showWaiting ? (
                                                                                    <span className="text-[9px] font-bold text-amber-700 bg-amber-50 px-2 py-0.5 rounded border border-amber-200 uppercase animate-pulse">
                                                                                        Waiting
                                                                                    </span>
                                                                                ) : !isFulfillable ? (
                                                                                    <span className="text-[9px] font-bold text-red-700 bg-red-50 px-2 py-0.5 rounded border border-red-200 uppercase">
                                                                                        Insufficient
                                                                                    </span>
                                                                                ) : (
                                                                                    <span className="text-gray-300 text-[10px] font-medium">-</span>
                                                                                )}
                                                                            </td>
                                                                        </tr>
                                                                    );
                                                                })}
                                                            </tbody>
                                                        </table>
                                                    </div>

                                                    <div className="flex justify-end pt-4 border-t border-gray-100 items-center gap-4">
                                                         {!po.zohoContactId ? (
                                                             <div className="flex flex-col items-end gap-1">
                                                                 <span className="text-[10px] font-bold text-orange-600 flex items-center gap-1 uppercase tracking-tighter">
                                                                     <InfoIcon className="h-3 w-3"/> Step 1 Required
                                                                 </span>
                                                                 <button 
                                                                    onClick={() => window.open('https://books.zoho.in/app#/contacts/new', '_blank')}
                                                                    className="flex items-center gap-2 px-6 py-3 text-sm font-bold text-white rounded-xl transition-all shadow-sm active:scale-95 bg-orange-600 hover:bg-orange-700 shadow-orange-100"
                                                                >
                                                                    Create Customer on Zoho Books <ExternalLinkIcon className="h-4 w-4" />
                                                                </button>
                                                             </div>
                                                         ) : !po.eeCustomerId ? (
                                                             <div className="flex flex-col items-end gap-1">
                                                                 <span className="text-[10px] font-bold text-blue-600 flex items-center gap-1 uppercase tracking-tighter">
                                                                     <InfoIcon className="h-3 w-3"/> Step 2: Linked Zoho ID {po.zohoContactId}
                                                                 </span>
                                                                 <button 
                                                                    onClick={() => handleSyncZohoToEE(po)}
                                                                    disabled={!!isSyncingZoho}
                                                                    className="flex items-center gap-2 px-6 py-3 text-sm font-bold text-white rounded-xl transition-all shadow-sm active:scale-95 bg-blue-600 hover:bg-blue-700 shadow-blue-100"
                                                                >
                                                                    {isSyncingZoho === po.id ? <RefreshIcon className="h-4 w-4 animate-spin"/> : <BuildingIcon className="h-4 w-4" />}
                                                                    {isSyncingZoho === po.id ? 'Syncing...' : 'Sync Zoho Contact to EasyEcom'}
                                                                </button>
                                                             </div>
                                                         ) : (
                                                            <div className="flex flex-col items-end gap-2">
                                                                {selectableItems.length === 0 && pushedItems.length < items.length && (
                                                                    <p className="text-xs font-bold text-red-500 bg-red-50 px-3 py-1 rounded-md border border-red-100">
                                                                        Stock Unavailable for remaining items.
                                                                    </p>
                                                                )}
                                                                <button 
                                                                    onClick={() => handlePushToEasyEcom(po)}
                                                                    disabled={poSelectedItems.length === 0 || pushingToEasyEcom[po.id]}
                                                                    className={`flex items-center gap-2 px-6 py-3 text-sm font-bold text-white rounded-xl transition-all shadow-sm active:scale-95 ${
                                                                        poSelectedItems.length > 0 ? 'bg-partners-green hover:bg-green-700 shadow-green-200' : 'bg-gray-300 cursor-not-allowed grayscale'
                                                                    }`}
                                                                >
                                                                    <UploadIcon className={`h-4 w-4 ${pushingToEasyEcom[po.id] ? 'animate-bounce' : ''}`} />
                                                                    {pushingToEasyEcom[po.id] ? 'Processing Order...' : `Push ${poSelectedItems.length > 0 ? poSelectedItems.length : ''} Items (Inc. 5% Tax)`}
                                                                </button>
                                                            </div>
                                                         )}
                                                    </div>
                                                </div>
                                            </td>
                                        </tr>
                                    )}
                                </Fragment>
                            );
                        })}
                    </tbody>
                </table>
            </div>
        </div>
    );
};

