import React, { useState, useMemo, useEffect, useCallback } from 'react';
import Sidebar from './components/Sidebar';
import Header from './components/Header';
import SummaryCard from './components/SummaryCard';
import PoTable from './components/PoTable';
import SalesOrderTable from './components/SalesOrderTable';
import PocVerification from './components/PocVerification';
import AppointmentManager from './components/AppointmentManager';
import AdminPanel from './components/AdminPanel';
import FinanceManager from './components/FinanceManager';
import InventoryManager from './components/InventoryManager';
import ReportsManager from './components/ReportsManager';
import ToastContainer from './components/ToastContainer';
import { MenuIcon, XIcon, QuestionMarkCircleIcon, RefreshIcon } from './components/icons/Icons';
import { initialUsers, initialRolePermissions } from './data/mockData';
import { type PurchaseOrder, POStatus, ActivityLog, NotificationItem, ViewType, User, RolePermissions, InventoryItem, ChannelConfig } from './types';
import { fetchPurchaseOrders, fetchInventoryFromSheet, fetchChannelConfigs, fetchUsers } from './services/api';

const App: React.FC = () => {
  const [isSidebarOpen, setSidebarOpen] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [lastSynced, setLastSynced] = useState<number>(0);

  // Initialize with empty array and a placeholder user for loading state
  const loadingUser: User = { id: 'loading', name: 'Syncing...', email: '', contactNumber: '', role: 'Limited Access', avatarInitials: '...' };
  const [users, setUsers] = useState<User[]>([]);
  const [currentUser, setCurrentUser] = useState<User>(loadingUser);
  const [rolePermissions, setRolePermissions] = useState<RolePermissions>(initialRolePermissions);

  const [activeView, setActiveView] = useState<ViewType>('Dashboard');
  const [activeFilter, setActiveFilter] = useState('All POs');
  const [adminTab, setAdminTab] = useState<'users' | 'roles' | 'channels' | 'integrations' | 'logs'>('users');

  const [purchaseOrders, setPurchaseOrders] = useState<PurchaseOrder[]>([]);
  const [inventoryItems, setInventoryItems] = useState<InventoryItem[]>([]);
  const [channelConfigs, setChannelConfigs] = useState<ChannelConfig[]>([]);

  const [logs, setLogs] = useState<ActivityLog[]>([
    { id: '1', user: 'System', action: 'Init', details: 'System initialized.', timestamp: new Date().toLocaleString() }
  ]);
  const [notifications, setNotifications] = useState<NotificationItem[]>([]);
  const [toasts, setToasts] = useState<NotificationItem[]>([]);

  const addLog = useCallback((action: string, details: string) => {
    const newLog: ActivityLog = {
        id: Date.now().toString() + Math.random().toString(36).substring(7),
        user: currentUser.name, 
        action,
        details,
        timestamp: new Date().toLocaleString()
    };
    setLogs(prev => [newLog, ...prev]);
  }, [currentUser]);

  const addNotification = useCallback((message: string, type: 'info' | 'success' | 'warning' | 'error' = 'info') => {
    const newNotification: NotificationItem = {
        id: Date.now().toString() + Math.random().toString(36).substring(7),
        message,
        timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
        read: false,
        type
    };
    setNotifications(prev => [newNotification, ...prev]);
    setToasts(prev => [...prev, newNotification]);
  }, []);

  const removeToast = useCallback((id: string) => {
    setToasts(prev => prev.filter(t => t.id !== id));
  }, []);

  const refreshData = useCallback(async (force = false) => {
      if (!force && purchaseOrders.length > 0 && Date.now() - lastSynced < 1800000) return; 

      setIsLoading(true);
      try {
          const [poData, invData, channelData, userData] = await Promise.all([
              fetchPurchaseOrders(),
              fetchInventoryFromSheet(),
              fetchChannelConfigs(),
              fetchUsers()
          ]);

          if (poData.length > 0) {
              setPurchaseOrders(poData);
          }
          if (invData.length > 0) setInventoryItems(invData);
          if (channelData.length > 0) setChannelConfigs(channelData);

          if (userData.length > 0) {
              setUsers(userData);
              if (currentUser.id === 'loading') {
                  setCurrentUser(userData[0]);
              } else {
                  const updatedCurrent = userData.find(u => u.id === currentUser.id);
                  if (updatedCurrent) setCurrentUser(updatedCurrent);
              }
          } else if (force && userData.length === 0) {
              addNotification('No users found in database.', 'warning');
          }

          setLastSynced(Date.now());
      } catch (e) {
          addNotification('Failed to sync data from Google Sheets.', 'error');
      } finally {
          setIsLoading(false);
      }
  }, [lastSynced, purchaseOrders.length, addNotification, currentUser.id, currentUser.name]);

  useEffect(() => {
    refreshData();
    const intervalId = setInterval(() => refreshData(true), 30 * 60 * 1000);
    return () => clearInterval(intervalId);
  }, [refreshData]);

  const getCalculatedStatus = (po: PurchaseOrder): POStatus => {
    const items = po.items || [];
    if (po.status === POStatus.Cancelled) return POStatus.Cancelled;

    const pushedCount = items.filter(i => !!i.eeOrderRefId).length;
    if (items.length > 0 && pushedCount === items.length) return POStatus.Pushed;
    if (pushedCount > 0) return POStatus.PartiallyProcessed;
    return POStatus.NewPO;
  };

  const summaryData = useMemo(() => {
    const totalActive = purchaseOrders.filter(p => p.status !== POStatus.Closed && p.status !== POStatus.Cancelled).length;
    const belowThreshold = purchaseOrders.filter(p => p.status === POStatus.BelowThreshold).length;

    // Summary based on push status
    const pushed = purchaseOrders.filter(p => getCalculatedStatus(p) === POStatus.Pushed).length;
    const partiallyPushed = purchaseOrders.filter(p => getCalculatedStatus(p) === POStatus.PartiallyProcessed).length;

    return [
      { title: 'Total Active POs', value: totalActive.toString(), change: 'across all stages', color: 'green', targetView: 'Purchase Orders', targetFilter: 'All POs' },
      { title: 'Fully Pushed', value: pushed.toString(), change: 'to EasyEcom', color: 'green', targetView: 'Purchase Orders', targetFilter: 'Pushed POs' },
      { title: 'Partially Pushed', value: partiallyPushed.toString(), change: 'pending items', color: 'yellow', targetView: 'Purchase Orders', targetFilter: 'Partially Pushed POs' },
      { title: 'Below Threshold', value: belowThreshold.toString(), change: 'low value orders', color: 'yellow', targetView: 'Purchase Orders', targetFilter: 'All POs' },
    ];
  }, [purchaseOrders]);

  const tabCounts = useMemo(() => {
    const counts = {
        'All POs': purchaseOrders.length,
        'New POs': 0,
        'Pushed POs': 0,
        'Partially Pushed POs': 0,
        'Cancelled POs': 0
    };

    purchaseOrders.forEach(po => {
        const status = getCalculatedStatus(po);
        if (status === POStatus.NewPO) counts['New POs']++;
        else if (status === POStatus.Pushed) counts['Pushed POs']++;
        else if (status === POStatus.PartiallyProcessed) counts['Partially Pushed POs']++;
        else if (status === POStatus.Cancelled) counts['Cancelled POs']++;
    });

    return counts;
  }, [purchaseOrders]);

  const handleCardClick = (view: ViewType, filter?: string) => {
      if (rolePermissions[currentUser.role]?.includes(view)) {
          setActiveView(view);
          if (filter) setActiveFilter(filter);
      } else {
          addNotification(`Access Denied: Permission required for ${view}.`, 'error');
      }
  };

  const renderContent = () => {
    if (isLoading && purchaseOrders.length === 0) {
        return (
            <div className="flex-1 flex flex-col items-center justify-center p-8">
                <RefreshIcon className="h-12 w-12 text-partners-green animate-spin mb-4" />
                <p className="text-gray-600 font-bold text-lg">Synchronizing your Dashboard...</p>
                <p className="text-gray-400 text-sm mt-1">Connecting to Google Sheets and EasyEcom</p>
            </div>
        );
    }

    switch (activeView) {
        case 'Dashboard':
            return (
                <div className="p-4 sm:p-6 lg:p-8 flex-1">
                    <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
                        {summaryData.map((card, index) => (
                            <SummaryCard key={index} title={card.title} value={card.value} changeText={card.change} color={card.color as any} onClick={() => handleCardClick(card.targetView as ViewType, card.targetFilter)} />
                        ))}
                    </div>
                </div>
            );
        case 'POC Verification': return <PocVerification purchaseOrders={purchaseOrders} setPurchaseOrders={setPurchaseOrders} addLog={addLog} addNotification={addNotification} />;
        case 'Appointments': return <AppointmentManager purchaseOrders={purchaseOrders} setPurchaseOrders={setPurchaseOrders} addLog={addLog} addNotification={addNotification} />;
        case 'Finance': return <FinanceManager purchaseOrders={purchaseOrders} setPurchaseOrders={setPurchaseOrders} addLog={addLog} />;
        case 'Inventory': return <InventoryManager addLog={addLog} inventoryItems={inventoryItems} setInventoryItems={setInventoryItems} onSync={() => refreshData(true)} isSyncing={isLoading} />;
        case 'Reports': return <ReportsManager purchaseOrders={purchaseOrders} inventoryItems={inventoryItems} />;
        case 'Purchase Orders':
        case 'Uploads':
        case 'GRN / POD':
            return (
                <div className="p-4 sm:p-6 lg:p-8 flex-1">
                    <PoTable activeFilter={activeFilter} setActiveFilter={setActiveFilter} purchaseOrders={purchaseOrders} setPurchaseOrders={setPurchaseOrders} tabCounts={tabCounts} addLog={addLog} addNotification={addNotification} onSync={() => refreshData(true)} isSyncing={isLoading} />
                </div>
            );
        case 'Sales Orders':
             return (
                <div className="p-4 sm:p-6 lg:p-8 flex-1">
                    <SalesOrderTable activeFilter={activeFilter} setActiveFilter={setActiveFilter} purchaseOrders={purchaseOrders} setPurchaseOrders={setPurchaseOrders} tabCounts={tabCounts} addLog={addLog} addNotification={addNotification} onSync={() => refreshData(true)} isSyncing={isLoading} />
                </div>
            );
        case 'Admin': return (
            <AdminPanel 
                logs={logs} 
                users={users} 
                setUsers={setUsers} 
                rolePermissions={rolePermissions} 
                setRolePermissions={setRolePermissions} 
                addLog={addLog} 
                currentUser={currentUser} 
                channelConfigs={channelConfigs} 
                onSync={() => refreshData(true)}
                activeTab={adminTab}
                setActiveTab={setAdminTab}
            />
        );
        default: return <div className="p-8 text-center text-gray-500">Section Under Construction</div>;
    }
  };

  return (
    <div className="flex h-screen bg-partners-gray-bg font-sans">
      <ToastContainer toasts={toasts} onRemove={removeToast} />
      {isSidebarOpen && <div className="fixed inset-0 bg-black opacity-50 z-20 lg:hidden" onClick={() => setSidebarOpen(false)}></div>}
      <div className={`fixed lg:relative inset-y-0 left-0 transform ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full'} lg:translate-x-0 transition-transform duration-300 ease-in-out z-30`}>
        <Sidebar activeView={activeView} setActiveView={setActiveView} currentUser={currentUser} permissions={rolePermissions} onSwitchUser={(id) => { const u = users.find(x => x.id === id); if(u) setCurrentUser(u); }} allUsers={users} />
      </div>
      <main className="flex-1 flex flex-col overflow-y-auto">
        <div className="flex items-center justify-between p-4 lg:hidden bg-white border-b border-gray-200">
            <button onClick={() => setSidebarOpen(!isSidebarOpen)} className="text-gray-500 focus:outline-none p-2 hover:bg-gray-100 rounded-lg">
                {isSidebarOpen ? <XIcon className="h-6 w-6" /> : <MenuIcon className="h-6 w-6" />}
            </button>
            <div className="font-bold text-gray-800">PO Portal</div>
            <div className="w-10"></div>
        </div>
        <Header 
            notifications={notifications} 
            onMarkRead={(id) => setNotifications(n => n.map(i => i.id === id ? {...i, read: true} : i))} 
            onClearAll={() => setNotifications([])} 
            onViewLogs={() => { setActiveView('Admin'); setAdminTab('logs'); }} 
            activeView={activeView}
        />
        {renderContent()}
      </main>
      <button className="fixed bottom-6 right-6 bg-green-600 text-white p-3 rounded-full shadow-lg hover:bg-green-700 transition-all hover:scale-110 flex items-center gap-2 z-40">
        <QuestionMarkCircleIcon className="h-6 w-6" />
        <span className="font-bold text-sm pr-1">Help</span>
      </button>
    </div>
  );
};

export default App;

import React, { useState, useEffect, Fragment } from 'react';
import { POStatus, type PurchaseOrder, POItem, InventoryItem } from '../types';
import StatusBadge from './StatusBadge';
import { DotsVerticalIcon, ChevronDownIcon, ChevronRightIcon, CloudDownloadIcon, CubeIcon, CheckCircleIcon, UploadIcon, XCircleIcon, InfoIcon, CalendarIcon, PaperclipIcon, BuildingIcon, ProfileIcon, MailIcon, RefreshIcon, ExternalLinkIcon } from './icons/Icons';
import { pushToEasyEcom, createEasyEcomCustomer, requestZohoSync } from '../services/api';

interface PoTableProps {
    activeFilter: string;
    setActiveFilter: (filter: string) => void;
    purchaseOrders: PurchaseOrder[];
    setPurchaseOrders: React.Dispatch<React.SetStateAction<PurchaseOrder[]>>;
    tabCounts: { [key: string]: number };
    addLog: (action: string, details: string) => void;
    addNotification: (message: string, type?: 'info' | 'success' | 'warning' | 'error') => void;
    onSync: () => void;
    isSyncing: boolean;
    inventoryItems?: InventoryItem[];
}

const inputClassName = "mt-1 block w-full rounded-lg border border-gray-300 bg-white text-gray-900 shadow-sm focus:border-partners-green focus:ring-partners-green sm:text-sm py-2 px-3";

const PoTable: React.FC<PoTableProps> = ({ activeFilter, setActiveFilter, purchaseOrders, tabCounts, onSync, isSyncing, addLog, addNotification }) => {
    const [filteredOrders, setFilteredOrders] = useState<PurchaseOrder[]>([]);
    const [expandedRowId, setExpandedRowId] = useState<string | null>(null);
    const [selectedPoItems, setSelectedPoItems] = useState<{ [key: string]: string[] }>({});
    const [pushingToEasyEcom, setPushingToEasyEcom] = useState<{ [key: string]: boolean }>({});
    const [isSyncingZoho, setIsSyncingZoho] = useState<string | null>(null);

    const tabs = [
        { name: 'New POs' },
        { name: 'Pushed POs' },
        { name: 'Partially Pushed POs' },
        { name: 'Cancelled POs' },
        { name: 'All POs' }
    ];

    const getCalculatedStatus = (po: PurchaseOrder): POStatus => {
        const items = po.items || [];
        if (po.status === POStatus.Cancelled) return POStatus.Cancelled;

        const pushedCount = items.filter(i => !!i.eeOrderRefId).length;
        if (items.length > 0 && pushedCount === items.length) return POStatus.Pushed;
        if (pushedCount > 0) return POStatus.PartiallyProcessed;
        return POStatus.NewPO;
    };

    useEffect(() => {
        let orders = [...purchaseOrders];
        if (activeFilter !== 'All POs') {
            orders = orders.filter(po => {
                const status = getCalculatedStatus(po);
                if (activeFilter === 'New POs') return status === POStatus.NewPO;
                if (activeFilter === 'Pushed POs') return status === POStatus.Pushed;
                if (activeFilter === 'Partially Pushed POs') return status === POStatus.PartiallyProcessed;
                if (activeFilter === 'Cancelled POs') return status === POStatus.Cancelled;
                return true;
            });
        }
        setFilteredOrders(orders);
    }, [activeFilter, purchaseOrders]);

    const toggleRowExpansion = (poId: string) => setExpandedRowId(expandedRowId === poId ? null : poId);

    const handleItemSelect = (poId: string, articleCode: string) => {
        setSelectedPoItems(prev => {
            const currentSelected = prev[poId] || [];
            const isSelected = currentSelected.includes(articleCode);
            return { ...prev, [poId]: isSelected ? currentSelected.filter(code => code !== articleCode) : [...currentSelected, articleCode] };
        });
    };

    const handleSelectAllItems = (po: PurchaseOrder) => {
        const selectableArticleCodes = (po.items || [])
            .filter(i => !i.eeOrderRefId && (i.fulfillableQty ?? 0) >= i.qty)
            .map(item => item.articleCode);

        const currentSelected = selectedPoItems[po.id] || [];
        const allSelected = selectableArticleCodes.length > 0 && currentSelected.length === selectableArticleCodes.length;
        setSelectedPoItems(prev => ({ ...prev, [po.id]: allSelected ? [] : selectableArticleCodes }));
    };

    const handlePushToEasyEcom = async (po: PurchaseOrder) => {
        const selected = selectedPoItems[po.id] || [];
        if (selected.length === 0) return;

        setPushingToEasyEcom(prev => ({ ...prev, [po.id]: true }));
        try {
            const res = await pushToEasyEcom(po, selected);
            if (res.status === 'success') {
                addNotification(res.message, 'success');
                addLog('EasyEcom Sync', `Pushed ${selected.length} items from PO ${po.poNumber} to EasyEcom.`);
                setSelectedPoItems(prev => ({ ...prev, [po.id]: [] }));
                onSync();
            } else {
                addNotification('Failed: ' + res.message, 'error');
            }
        } catch (e) {
            addNotification('Network error pushing to EasyEcom', 'error');
        } finally {
            setPushingToEasyEcom(prev => ({ ...prev, [po.id]: false }));
        }
    };

    const handleSyncZohoToEE = async (po: PurchaseOrder) => {
        if (!po.zohoContactId) {
            addNotification('Missing Zoho Contact ID for this order.', 'warning');
            return;
        }
        setIsSyncingZoho(po.id);
        try {
            const res = await requestZohoSync(po.zohoContactId);
            if (res.status === 'success') {
                addNotification('Zoho Contact mapped to EasyEcom successfully', 'success');
                onSync();
            } else {
                addNotification(`Backend Error: ${res.message || 'The sync script failed.'}`, 'error');
            }
        } catch (e) {
            addNotification(`Sync Exception`, 'error');
        } finally {
            setIsSyncingZoho(null);
        }
    };

    return (
        <div className="bg-white p-6 rounded-xl shadow-sm">
            <div className="flex flex-col md:flex-row justify-between items-center gap-4 mb-6">
                <div className="flex flex-wrap items-center gap-2">
                    {tabs.map(tab => (
                        <button key={tab.name} onClick={() => setActiveFilter(tab.name)}
                            className={`px-3 py-1.5 text-sm font-semibold rounded-full border transition-colors ${
                                activeFilter === tab.name ? 'bg-partners-green text-white border-partners-green' : 'bg-white text-gray-600 border-partners-border hover:bg-gray-50'
                            }`}
                        >
                            {tab.name} {tabCounts[tab.name] > 0 && <span className="ml-1 text-xs opacity-80">({tabCounts[tab.name]})</span>}
                        </button>
                    ))}
                </div>
                <button onClick={onSync} disabled={isSyncing} className="flex items-center gap-2 px-3 py-2 text-sm font-medium text-white bg-blue-600 rounded-lg shadow-sm hover:bg-blue-700 active:scale-95 transition-all">
                    <CloudDownloadIcon className={`h-4 w-4 ${isSyncing ? 'animate-bounce' : ''}`} /> Sync Data
                </button>
            </div>

            <div className="mt-6 overflow-x-auto border border-gray-100 rounded-xl shadow-inner">
                <table className="w-full text-sm text-left text-gray-600">
                    <thead className="text-[11px] text-gray-500 uppercase bg-gray-50/50 border-b border-gray-100">
                        <tr>
                            <th className="p-4 w-4"></th>
                            <th className="px-6 py-4">PO Number</th>
                            <th className="px-6 py-4">Status</th>
                            <th className="px-6 py-4">Channel</th>
                            <th className="px-6 py-4">Store</th>
                            <th className="px-6 py-4">Qty / Total (Inc. 5% GST)</th>
                            <th className="px-6 py-4">Order Date</th>
                            <th className="px-6 py-4 text-center">Action</th>
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-gray-100/50">
                        {filteredOrders.map((po) => {
                            const isExpanded = expandedRowId === po.id;
                            const poSelectedItems = selectedPoItems[po.id] || [];
                            const items = po.items || [];
                            const pushedItems = items.filter(i => !!i.eeOrderRefId);

                            const selectableItems = items.filter(i => !i.eeOrderRefId && (i.fulfillableQty ?? 0) >= i.qty);
                            const stockShortageItems = items.filter(i => !i.eeOrderRefId && (i.fulfillableQty ?? 0) < i.qty);

                            const allSelectableSelected = selectableItems.length > 0 && poSelectedItems.length === selectableItems.length;
                            const poStatus = getCalculatedStatus(po);
                            const amountIncTax = po.amount * 1.05;

                            return (
                                <Fragment key={po.id}>
