import React, { useState, useEffect } from 'react';
import { ActivityLog, User, Role, ViewType, RolePermissions, ChannelConfig } from '../types';
import { ShieldCheckIcon, UserGroupIcon, LockClosedIcon, PencilIcon, TrashIcon, CheckCircleIcon, XCircleIcon, PlusIcon, AdminIcon, CogIcon, RefreshIcon, GlobeIcon, MailIcon, RefreshIcon as ResetIcon } from './icons/Icons';
import { saveChannelConfig, saveSystemConfig, fetchSystemConfig, saveUserToSheet, deleteUserFromSheet, resetUserPassword } from '../services/api';

interface AdminPanelProps {
    logs: ActivityLog[];
    users: User[];
    setUsers: React.Dispatch<React.SetStateAction<User[]>>;
    rolePermissions: RolePermissions;
    setRolePermissions: React.Dispatch<React.SetStateAction<RolePermissions>>;
    addLog: (action: string, details: string) => void;
    currentUser: User;
    channelConfigs: ChannelConfig[];
    onSync: () => void;
    activeTab: 'users' | 'roles' | 'channels' | 'integrations' | 'logs';
    setActiveTab: (tab: 'users' | 'roles' | 'channels' | 'integrations' | 'logs') => void;
}

const inputClassName = "mt-1 block w-full rounded-lg border border-gray-300 bg-white text-gray-900 shadow-sm focus:border-partners-green focus:ring-partners-green sm:text-sm py-3 px-3";

// Sub-component: User Modal
interface UserModalProps {
    user?: User;
    onClose: () => void;
    onSave: (user: User) => void;
    isSaving?: boolean;
}

const UserModal: React.FC<UserModalProps> = ({ user, onClose, onSave, isSaving }) => {
    const [formData, setFormData] = useState<Partial<User>>(user || {
        name: '', email: '', contactNumber: '', role: 'Limited Access', avatarInitials: ''
    });

    const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
        setFormData({ ...formData, [e.target.name]: e.target.value });
    };

    const handleSave = () => {
        if (!formData.name || !formData.email || !formData.role) return;
        const initials = formData.name.split(' ').map(n => n[0]).join('').toUpperCase().slice(0, 2);
        onSave({
            id: user?.id || Date.now().toString(),
            name: formData.name,
            email: formData.email,
            contactNumber: formData.contactNumber || '',
            role: formData.role as Role,
            avatarInitials: initials,
            isInitialized: user?.isInitialized || false
        });
    };

    return (
        <div className="fixed inset-0 bg-black/60 backdrop-blur-sm flex items-center justify-center z-[100] p-4">
            <div className="bg-white rounded-3xl shadow-2xl w-full max-w-md overflow-hidden">
                <div className="p-6 bg-gray-50 border-b border-gray-100 flex justify-between items-center">
                    <h3 className="text-xl font-bold text-gray-800">{user ? 'Edit User' : 'Create New User'}</h3>
                    <button onClick={onClose} className="p-2 hover:bg-white rounded-full transition-colors"><XCircleIcon className="h-6 w-6 text-gray-400"/></button>
                </div>
                <div className="p-6 space-y-4">
                    {!user && (
                        <div className="p-4 bg-blue-50 rounded-2xl border border-blue-100 flex items-start gap-3">
                            <MailIcon className="h-5 w-5 text-blue-500 mt-0.5" />
                            <p className="text-xs text-blue-700 leading-relaxed">
                                A setup link will be emailed to this user automatically upon creation. They can set their own password via the link.
                            </p>
                        </div>
                    )}
                    <div>
                        <label className="block text-[10px] font-bold text-gray-400 uppercase tracking-widest mb-1">Full Name</label>
                        <input name="name" value={formData.name} onChange={handleChange} className={inputClassName} placeholder="Sunil Sharma" />
                    </div>
                    <div>
                        <label className="block text-[10px] font-bold text-gray-400 uppercase tracking-widest mb-1">Work Email</label>
                        <input name="email" type="email" value={formData.email} onChange={handleChange} className={inputClassName} placeholder="sunil@cubelelo.com" />
                    </div>
                    <div>
                        <label className="block text-[10px] font-bold text-gray-400 uppercase tracking-widest mb-1">Mobile Number</label>
                        <input name="contactNumber" value={formData.contactNumber} onChange={handleChange} className={inputClassName} placeholder="+91 98..." />
                    </div>
                    <div>
                        <label className="block text-[10px] font-bold text-gray-400 uppercase tracking-widest mb-1">Access Role</label>
                        <select name="role" value={formData.role} onChange={handleChange} className={inputClassName}>
                            <option value="Admin">Admin</option>
                            <option value="Key Account Manager">Key Account Manager</option>
                            <option value="Finance Manager">Finance Manager</option>
                            <option value="Supply Chain Manager">Supply Chain Manager</option>
                            <option value="Limited Access">Limited Access</option>
                        </select>
                    </div>
                </div>
                <div className="px-6 py-4 bg-gray-50 flex justify-end gap-3 border-t border-gray-100">
                    <button onClick={onClose} className="px-6 py-2.5 text-sm font-bold text-gray-500 hover:text-gray-700 transition-colors">Cancel</button>
                    <button 
                        onClick={handleSave} 
                        disabled={isSaving}
                        className="px-8 py-2.5 text-sm font-bold text-white bg-partners-green rounded-xl hover:bg-green-700 shadow-lg shadow-green-100 transition-all flex items-center gap-2 active:scale-95 disabled:opacity-50"
                    >
                        {isSaving ? <RefreshIcon className="h-4 w-4 animate-spin"/> : <CheckCircleIcon className="h-4 w-4"/>}
                        {isSaving ? 'Processing...' : user ? 'Save Changes' : 'Create & Invite'}
                    </button>
                </div>
            </div>
        </div>
    );
};

const AdminPanel: React.FC<AdminPanelProps> = ({ logs, users, setUsers, rolePermissions, setRolePermissions, addLog, currentUser, channelConfigs, onSync, activeTab, setActiveTab }) => {
    const [userModal, setUserModal] = useState<{ isOpen: boolean, user?: User }>({ isOpen: false });
    const [isSavingUser, setIsSavingUser] = useState(false);
    const [resettingPwId, setResettingPwId] = useState<string | null>(null);

    const handleSaveUser = async (userData: User) => {
        setIsSavingUser(true);
        try {
            const res = await saveUserToSheet(userData);
            if (res.status === 'success') {
                if (userModal.user) {
                    addLog('Update User', `Updated details for ${userData.name}`);
                } else {
                    addLog('Create User', `Created & Invited ${userData.name}. Auth email triggered.`);
                }
                setUserModal({ isOpen: false });
                onSync();
            } else {
                alert('Failed to save user: ' + res.message);
            }
        } catch (e) {
            alert('Network error saving user.');
        } finally {
            setIsSavingUser(false);
        }
    };

    const handlePasswordReset = async (user: User) => {
        if (!confirm(`Trigger a password reset email for ${user.name}? This will lock their current access until they set a new password.`)) return;
        setResettingPwId(user.id);
        try {
            const res = await resetUserPassword(user.id);
            if (res.status === 'success') {
                addLog('Password Reset', `Triggered reset email for ${user.name}`);
                alert('Reset instructions have been sent to ' + user.email);
                onSync();
            } else {
                alert('Error: ' + res.message);
            }
        } catch (e) {
            alert('Reset service unavailable.');
        } finally {
            setResettingPwId(null);
        }
    };

    return (
        <>
            {userModal.isOpen && (
                <UserModal 
                    user={userModal.user} 
                    onClose={() => setUserModal({ isOpen: false })} 
                    onSave={handleSaveUser} 
                    isSaving={isSavingUser}
                />
            )}

            <div className="p-4 sm:p-6 lg:p-8 flex-1">
                <div className="flex border-b border-gray-200 mb-6 overflow-x-auto">
                    {['users', 'roles', 'channels', 'integrations', 'logs'].map(tab => (
                        <button 
                            key={tab}
                            onClick={() => setActiveTab(tab as any)}
                            className={`px-6 py-3 text-xs font-bold uppercase tracking-widest border-b-2 flex items-center gap-2 whitespace-nowrap transition-all ${
                                activeTab === tab ? 'border-partners-green text-partners-green bg-green-50/50' : 'border-transparent text-gray-400 hover:text-gray-700'
                            }`}
                        >
                            {tab === 'users' ? <UserGroupIcon className="h-4 w-4" /> : 
                             tab === 'roles' ? <LockClosedIcon className="h-4 w-4" /> :
                             tab === 'channels' ? <CogIcon className="h-4 w-4" /> :
                             tab === 'integrations' ? <GlobeIcon className="h-4 w-4" /> :
                             <ShieldCheckIcon className="h-4 w-4" />}
                            {tab}
                        </button>
