import React, { useState, useEffect, Fragment } from 'react';
import { POStatus, type PurchaseOrder, POItem } from '../types';
import StatusBadge from './StatusBadge';
import { DotsVerticalIcon, ChevronDownIcon, ChevronRightIcon, CloudDownloadIcon, CubeIcon, CheckCircleIcon, UploadIcon, XCircleIcon, InfoIcon, CalendarIcon, PaperclipIcon, BuildingIcon, RefreshIcon, ExternalLinkIcon } from './icons/Icons';
import { pushToEasyEcom, requestZohoSync } from '../services/api';

interface PoTableProps {
    activeFilter: string;
    setActiveFilter: (filter: string) => void;
    purchaseOrders: PurchaseOrder[];
    setPurchaseOrders: React.Dispatch<React.SetStateAction<PurchaseOrder[]>>;
    tabCounts: { [key: string]: number };
    addLog: (action: string, details: string) => void;
    addNotification: (message: string, type?: 'info' | 'success' | 'warning' | 'error') => void;
    onSync: () => void;
    isSyncing: boolean;
}

const PoTable: React.FC<PoTableProps> = ({ activeFilter, setActiveFilter, purchaseOrders, tabCounts, onSync, isSyncing, addLog, addNotification }) => {
    const [filteredOrders, setFilteredOrders] = useState<PurchaseOrder[]>([]);
    const [expandedRowId, setExpandedRowId] = useState<string | null>(null);
    const [selectedPoItems, setSelectedPoItems] = useState<{ [key: string]: string[] }>({});
    const [pushingToEasyEcom, setPushingToEasyEcom] = useState<{ [key: string]: boolean }>({});
    const [isSyncingZoho, setIsSyncingZoho] = useState<string | null>(null);

    const tabs = [
        { name: 'New POs' },
        { name: 'Pushed POs' },
        { name: 'Partially Pushed POs' },
        { name: 'Cancelled POs' },
        { name: 'All POs' }
    ];

    const getCalculatedStatus = (po: PurchaseOrder): POStatus => {
        if (po.status === POStatus.Cancelled) return POStatus.Cancelled;
        const items = po.items || [];
        const pushedCount = items.filter(i => !!i.eeOrderRefId).length;
        if (items.length > 0 && pushedCount === items.length) return POStatus.Pushed;
        if (pushedCount > 0) return POStatus.PartiallyProcessed;
        return POStatus.NewPO;
    };

    useEffect(() => {
        let orders = [...purchaseOrders];
        if (activeFilter !== 'All POs') {
            orders = orders.filter(po => {
                const s = getCalculatedStatus(po);
                if (activeFilter === 'New POs') return s === POStatus.NewPO;
                if (activeFilter === 'Pushed POs') return s === POStatus.Pushed;
                if (activeFilter === 'Partially Pushed POs') return s === POStatus.PartiallyProcessed;
                if (activeFilter === 'Cancelled POs') return s === POStatus.Cancelled;
                return true;
            });
        }
        setFilteredOrders(orders);
    }, [activeFilter, purchaseOrders]);

    const toggleRowExpansion = (poId: string) => setExpandedRowId(expandedRowId === poId ? null : poId);

    const handleItemSelect = (poId: string, articleCode: string) => {
        setSelectedPoItems(prev => {
            const currentSelected = prev[poId] || [];
            const isSelected = currentSelected.includes(articleCode);
            return { ...prev, [poId]: isSelected ? currentSelected.filter(code => code !== articleCode) : [...currentSelected, articleCode] };
        });
    };

    const handleSelectAllItems = (po: PurchaseOrder) => {
        const selectableArticleCodes = (po.items || [])
            .filter(i => !i.eeOrderRefId && (i.fulfillableQty ?? 0) >= i.qty)
            .map(item => item.articleCode);

        const currentSelected = selectedPoItems[po.id] || [];
        const allSelected = selectableArticleCodes.length > 0 && currentSelected.length === selectableArticleCodes.length;
        setSelectedPoItems(prev => ({ ...prev, [po.id]: allSelected ? [] : selectableArticleCodes }));
    };

    const handlePushToEasyEcom = async (po: PurchaseOrder) => {
        const selected = selectedPoItems[po.id] || [];
        if (selected.length === 0) return;
        setPushingToEasyEcom(prev => ({ ...prev, [po.id]: true }));
        try {
            const res = await pushToEasyEcom(po, selected);
            if (res.status === 'success') {
                addNotification(res.message, 'success');
                setSelectedPoItems(prev => ({ ...prev, [po.id]: [] }));
                onSync();
            } else {
                addNotification('Failed: ' + res.message, 'error');
            }
        } catch (e) { addNotification('Sync error', 'error'); } 
        finally { setPushingToEasyEcom(prev => ({ ...prev, [po.id]: false })); }
    };

    const handleSyncZohoToEE = async (po: PurchaseOrder) => {
        if (!po.zohoContactId) { addNotification('Missing Zoho ID', 'warning'); return; }
        setIsSyncingZoho(po.id);
        try {
            const res = await requestZohoSync(po.zohoContactId);
            if (res.status === 'success') { addNotification('Mapped successfully', 'success'); onSync(); } 
            else { addNotification('Sync failed', 'error'); }
        } finally { setIsSyncingZoho(null); }
    };

    return (
        <div className="bg-white p-6 rounded-xl shadow-sm">
            <div className="flex flex-col md:flex-row justify-between items-center gap-4 mb-6">
                <div className="flex flex-wrap items-center gap-2">
                    {tabs.map(tab => (
                        <button key={tab.name} onClick={() => setActiveFilter(tab.name)}
                            className={`px-3 py-1.5 text-sm font-semibold rounded-full border transition-colors ${
                                activeFilter === tab.name ? 'bg-partners-green text-white border-partners-green' : 'bg-white text-gray-600 border-partners-border hover:bg-gray-50'
                            }`}
                        >
                            {tab.name} {tabCounts[tab.name] > 0 && <span className="ml-1 text-xs opacity-80">({tabCounts[tab.name]})</span>}
                        </button>
                    ))}
                </div>
                <button onClick={onSync} disabled={isSyncing} className="flex items-center gap-2 px-3 py-2 text-sm font-medium text-white bg-blue-600 rounded-lg shadow-sm hover:bg-blue-700 active:scale-95 transition-all">
                    <CloudDownloadIcon className={`h-4 w-4 ${isSyncing ? 'animate-bounce' : ''}`} /> Sync Data
                </button>
            </div>

            <div className="mt-6 overflow-x-auto border border-gray-100 rounded-xl shadow-inner">
                <table className="w-full text-sm text-left text-gray-600">
                    <thead className="text-[11px] text-gray-500 uppercase bg-gray-50/50 border-b border-gray-100">
                        <tr>
                            <th className="p-4 w-4"></th>
                            <th className="px-6 py-4">PO Number</th>
                            <th className="px-6 py-4">Status</th>
                            <th className="px-6 py-4">Channel</th>
                            <th className="px-6 py-4">Store</th>
                            <th className="px-6 py-4">Qty / Total (Inc. 5% GST)</th>
                            <th className="px-6 py-4">Order Date</th>
                            <th className="px-6 py-4 text-center">Action</th>
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-gray-100/50">
                        {filteredOrders.map((po) => {
                            const isExpanded = expandedRowId === po.id;
                            const poSelectedItems = selectedPoItems[po.id] || [];
                            const items = po.items || [];
                            const poStatus = getCalculatedStatus(po);
                            const amountIncTax = po.amount * 1.05;
                            const isCancelled = poStatus === POStatus.Cancelled;

                            return (
                                <Fragment key={po.id}>
                                    <tr className={`hover:bg-gray-50/80 cursor-pointer transition-colors ${isExpanded ? 'bg-partners-light-green/30' : 'bg-white'} ${isCancelled ? 'opacity-50' : ''}`} onClick={() => toggleRowExpansion(po.id)}>
                                        <td className="p-4 text-center">
                                            <div className="text-gray-400 hover:text-partners-green">
                                                {isExpanded ? <ChevronDownIcon className="h-4 w-4" /> : <ChevronRightIcon className="h-4 w-4" />}
                                            </div>
                                        </td>
                                        <td className="px-6 py-4 font-bold text-partners-green whitespace-nowrap">{po.poNumber}</td>
                                        <td className="px-6 py-4"><StatusBadge status={poStatus} /></td>
                                        <td className="px-6 py-4 font-medium text-gray-700">{po.channel}</td>
                                        <td className="px-6 py-4 text-gray-500">{po.storeCode}</td>
                                        <td className="px-6 py-4 font-bold text-gray-900">{po.qty} / ₹{amountIncTax.toLocaleString('en-IN', { maximumFractionDigits: 0 })}</td>
                                        <td className="px-6 py-4 whitespace-nowrap text-gray-400">{po.orderDate}</td>
                                        <td className="px-6 py-4 text-center" onClick={(e) => e.stopPropagation()}>
                                            <button className="text-gray-400 hover:text-gray-600 p-2 hover:bg-gray-100 rounded-full transition-colors">
                                                <DotsVerticalIcon className="h-4 w-4" />
                                            </button>
                                        </td>
                                    </tr>
                                    {isExpanded && (
                                        <tr className="bg-gray-50/50">
                                            <td colSpan={8} className="px-4 py-8 sm:px-12">
                                                <div className={`bg-white border border-partners-border rounded-xl p-6 space-y-6 shadow-sm ring-1 ring-black/5 ${isCancelled ? 'grayscale pointer-events-none opacity-80' : ''}`}>
                                                    <div className="pb-6 border-b border-gray-100">
                                                        <h4 className="text-xs font-bold text-gray-400 uppercase tracking-widest mb-4 flex items-center gap-2">
                                                            <CalendarIcon className="h-4 w-4 text-blue-500" /> Fulfillment Status
                                                        </h4>
                                                        <div className="grid grid-cols-2 md:grid-cols-5 gap-4 p-4 bg-gray-50 rounded-lg border border-gray-100">
                                                            <div><p className="text-[10px] uppercase font-bold text-gray-400">PO Ref</p><p className="text-xs font-bold text-partners-green truncate">{po.poNumber}</p></div>
                                                            <div><p className="text-[10px] uppercase font-bold text-gray-400">PO Date</p><p className="text-xs font-bold text-gray-700">{po.orderDate || 'N/A'}</p></div>
                                                            <div><p className="text-[10px] uppercase font-bold text-gray-400">EasyEcom ID</p><p className={`text-xs font-bold ${po.eeCustomerId ? 'text-blue-600' : 'text-red-500 italic'}`}>{po.eeCustomerId || 'Not Mapped'}</p></div>
                                                            <div><p className="text-[10px] uppercase font-bold text-gray-400">Expiry</p><p className="text-xs font-bold text-red-600">{po.poExpiryDate || 'N/A'}</p></div>
                                                            <div><p className="text-[10px] uppercase font-bold text-gray-400">PO PDF</p>{po.poPdfUrl ? <a href={po.poPdfUrl} target="_blank" rel="noopener noreferrer" className="text-partners-green hover:underline flex items-center gap-1 text-xs font-bold mt-0.5"><PaperclipIcon className="h-3 w-3" /> View</a> : <p className="text-xs text-gray-300 font-bold italic mt-0.5">Not Uploaded</p>}</div>
                                                        </div>
                                                    </div>

                                                    <div className="overflow-x-auto border border-gray-100 rounded-lg">
                                                        <table className="w-full text-xs text-left">
                                                            <thead className="bg-gray-50 text-gray-500 uppercase tracking-tight">
                                                                <tr>
                                                                    <th className="py-3 w-8 text-center">
                                                                        <input type="checkbox" className="h-3.5 w-3.5 rounded border-gray-300 text-partners-green" checked={items.filter(i => !i.eeOrderRefId && (i.fulfillableQty ?? 0) >= i.qty).length > 0 && poSelectedItems.length === items.filter(i => !i.eeOrderRefId && (i.fulfillableQty ?? 0) >= i.qty).length} onChange={() => handleSelectAllItems(po)} disabled={isCancelled || items.filter(i => !i.eeOrderRefId && (i.fulfillableQty ?? 0) >= i.qty).length === 0} />
                                                                    </th>
                                                                    <th className="py-3 px-3">Item / SKU</th>
                                                                    <th className="py-3 text-right">PO Qty</th>
                                                                    <th className="py-3 text-right">Fulfillable</th>
                                                                    <th className="py-3 text-right">Unit Cost (Inc. 5%)</th>
                                                                    <th className="py-3 text-center">Push Status</th>
                                                                </tr>
                                                            </thead>
                                                            <tbody className="divide-y divide-gray-100">
                                                                {items.map((item, idx) => {
                                                                    const isPushed = !!item.eeOrderRefId;
                                                                    const isFull = (item.fulfillableQty ?? 0) >= item.qty;
                                                                    const isPart = !isFull && (item.fulfillableQty ?? 0) > 0;
                                                                    return (
                                                                        <tr key={idx} className={`${isPushed ? 'bg-gray-50' : ''}`}>
                                                                            <td className="py-4 text-center">
                                                                                {isPushed ? <CheckCircleIcon className="h-5 w-5 text-green-500 mx-auto" /> : <input type="checkbox" className="h-3.5 w-3.5 rounded border-gray-300" checked={poSelectedItems.includes(item.articleCode)} onChange={() => handleItemSelect(po.id, item.articleCode)} disabled={!isFull || isCancelled} />}
                                                                            </td>
                                                                            <td className="py-4 px-3"><p className={`font-bold ${isPushed ? 'text-gray-400' : 'text-gray-800'}`}>{item.itemName}</p><p className="text-[10px] text-gray-400 font-mono">{item.masterSku || item.articleCode}</p></td>
                                                                            <td className="py-4 text-right font-medium">{item.qty}</td>
                                                                            <td className={`py-4 text-right font-bold ${isFull ? 'text-green-600' : isPart ? 'text-amber-600' : 'text-red-600'}`}>{item.fulfillableQty ?? 0}</td>
                                                                            <td className="py-4 text-right">₹{((item.unitCost || 0) * 1.05).toFixed(2)}</td>
                                                                            <td className="py-4 text-center">
                                                                                {isPushed ? <div className="flex flex-col items-center"><span className="text-[9px] font-bold text-green-700 bg-green-50 px-2 py-0.5 rounded border border-green-200">PUSHED</span><span className="text-[8px] text-gray-400 mt-1">{item.eeOrderRefId}</span></div> :
                                                                                 isCancelled ? <span className="text-[9px] font-bold text-gray-400 uppercase">VOID</span> :
                                                                                 !isFull ? <span className="text-[9px] font-bold text-orange-600 bg-orange-50 px-2 py-0.5 rounded border border-orange-200 uppercase">{isPart ? 'Partial' : 'No Stock'}</span> :
                                                                                 <span className="text-gray-300 text-[10px]">-</span>}
                                                                            </td>
                                                                        </tr>
                                                                    );
                                                                })}
                                                            </tbody>
                                                        </table>
                                                    </div>

                                                    <div className="flex justify-end pt-4 border-t border-gray-100 items-center gap-4">
                                                         {isCancelled ? <p className="text-sm font-bold text-red-600 bg-red-50 px-4 py-2 rounded-lg">PO has been cancelled.</p> : 
                                                          !po.eeCustomerId ? <button onClick={() => handleSyncZohoToEE(po)} className="flex items-center gap-2 px-6 py-3 text-sm font-bold text-white bg-blue-600 rounded-xl hover:bg-blue-700 shadow-lg shadow-blue-100">{isSyncingZoho === po.id ? <RefreshIcon className="h-4 w-4 animate-spin"/> : <BuildingIcon className="h-4 w-4" />}Sync Customer Mapping</button> :
                                                          <button onClick={() => handlePushToEasyEcom(po)} disabled={poSelectedItems.length === 0 || pushingToEasyEcom[po.id]} className={`flex items-center gap-2 px-6 py-3 text-sm font-bold text-white rounded-xl transition-all shadow-sm ${poSelectedItems.length > 0 ? 'bg-partners-green hover:bg-green-700' : 'bg-gray-300 grayscale'}`}>{pushingToEasyEcom[po.id] ? 'Pushing...' : `Push ${poSelectedItems.length > 0 ? poSelectedItems.length : ''} Items`}</button>}
                                                    </div>
                                                </div>
                                            </td>
                                        </tr>
                                    )}
                                </Fragment>
                            );
                        })}
                    </tbody>
                </table>
            </div>
        </div>
    );
};

export default PoTable;

export type ViewType = 'Dashboard' | 'Purchase Orders' | 'Uploads' | 'File Uploader' | 'POC Verification' | 'Appointments' | 'Sales Orders' | 'GRN / POD' | 'Reports' | 'Finance' | 'Inventory' | 'Admin';

export enum POStatus {
    NewPO = 'New',
    BelowThreshold = 'Below Threshold',
    POCPending = 'POC Verification',
    AppointmentPending = 'Appointment to be taken',
    InTransit = 'In-Transit',
    Delivered = 'Delivered',
    GRNPending = 'GRN Pending',
    GRNUpdated = 'GRN Updated',
    RTO = 'RTO',
    Closed = 'Closed',
    Pushed = 'Pushed',
    PartiallyProcessed = 'Partially Processed',
    Cancelled = 'Cancelled'
}

export type PaymentStatus = 'Pending' | 'Partial' | 'Received' | 'Overdue';

export interface POItem {
    articleCode: string;
    qty: number;
    fulfillableQty?: number;
    masterSku?: string;
    itemName?: string;
    unitCost?: number;
    mrp?: number;
    priceCheckStatus?: string;
    eeOrderRefId?: string;
    eeReferenceCode?: string; 
    itemStatus?: string;
    itemQuantity?: number;
    cancelledQuantity?: number;
    shippedQuantity?: number;
    returnedQuantity?: number;
    eeOrderStatus?: string;
    eeBatchCreatedAt?: string;
    eeInvoiceDate?: string;
    eeManifestDate?: string;
    invoiceId?: string;
    invoiceStatus?: string;
    invoiceNumber?: string;
    invoiceDate?: string;
    invoiceTotal?: number;
    invoiceUrl?: string;
}

export interface PurchaseOrder {
    id: string;
    poNumber: string;
    status: POStatus;
    channel: string;
    storeCode: string;
    qty: number;
    items?: POItem[];
    amount: number;
    orderDate: string;
    source?: 'Manual' | 'Email' | 'API';
    billDate?: string;
    invoiceId?: string;
    carrier?: string;
    awb?: string;
    dispatchDate?: string;
    boxes?: number;
    trackingUrl?: string;
    appointmentDate?: string;
    grnDate?: string;
    latestTrackingStatus?: string;
    actionToBeTaken?: string;
    poPdfUrl?: string;
    podImageUrl?: string;
    pocPhoneNumber?: string;
    contactVerified: boolean;
    pocEmail?: string;
    appointmentRequestDate?: string;
    appointmentTime?: string;
    appointmentId?: string;
    followUpCount?: number;
    appointmentRemarks?: string;
    paymentStatus?: PaymentStatus;
    paymentDueDate?: string;
    amountReceived?: number;
    lastPaymentReminderDate?: string;
    paymentFollowUpCount?: number;
    poEdd?: string;
    poExpiryDate?: string;
    eeCustomerId?: string;
    zohoContactId?: string;
    eeReferenceCode?: string;
    eeOrderDate?: string;
    eeOrderId?: string;
    eeOrderStatus?: string;
    eeBatchCreatedAt?: string;
    eeInvoiceDate?: string;
    eeManifestDate?: string;
}

export interface User {
    id: string;
    name: string;
    email: string;
    contactNumber: string;
    role: Role;
    avatarInitials: string;
    password?: string;
    isInitialized?: boolean;
}

export interface Customer {
    id: string;
    customerCode: string;
    contactId: string;
    contactName: string;
    companyName: string;
    email: string;
    phone: string;
    gstNo: string;
    shippingAddressId: string;
    shippingAttention: string;
    shippingAddress: string;
    shippingStreet2: string;
    shippingCity: string;
    shippingStateCode: string;
    shippingState: string;
    shippingZip: string;
    shippingPhone: string;
    stateCode: string;
    stnCode: string;
}

export interface StorePocMapping {
    channel: string;
    storeCode: string;
    pocName: string;
    pocEmail: string;
    pocPhone?: string;
}

export interface UploadMetadata {
    id: string;
    functionName: string;
    lastUploadedBy: string;
    lastUploadedAt: string;
    status: 'Success' | 'Error' | 'Pending';
}

export type Role = 'Admin' | 'Key Account Manager' | 'Finance Manager' | 'Supply Chain Manager' | 'Limited Access';
export interface RolePermissions { [key: string]: ViewType[]; }
export interface ActivityLog { id: string; user: string; action: string; details: string; timestamp: string; }
export interface NotificationItem { id: string; message: string; timestamp: string; read: boolean; type: 'info' | 'success' | 'warning' | 'error'; }
export interface InventoryItem { id: string; channel: string; articleCode: string; sku: string; ean: string; itemName: string; mrp: number; basicPrice: number; spIncTax: number; stock: number; }
export interface ChannelConfig { id: string; channelName: string; status: 'Active' | 'Inactive'; sourceEmail: string; searchKeyword: string; minOrderThreshold: number; pocName: string; pocEmail: string; pocPhone: string; }
export type ReportTimeRange = '30_days' | 'last_month' | 'this_quarter' | 'ytd' | 'all';

import React, { useState, useMemo, useEffect, useCallback } from 'react';
import Sidebar from './components/Sidebar';
import Header from './components/Header';
import SummaryCard from './components/SummaryCard';
import PoTable from './components/PoTable';
import SalesOrderTable from './components/SalesOrderTable';
import AdminPanel from './components/AdminPanel';
import FinanceManager from './components/FinanceManager';
import InventoryManager from './components/InventoryManager';
import ReportsManager from './components/ReportsManager';
import FileUploader from './components/FileUploader';
import ToastContainer from './components/ToastContainer';
import Login from './components/Login';
import { MenuIcon, XIcon, QuestionMarkCircleIcon, RefreshIcon } from './components/icons/Icons';
import { initialRolePermissions } from './data/mockData';
import { type PurchaseOrder, POStatus, ActivityLog, NotificationItem, ViewType, User, RolePermissions, InventoryItem, ChannelConfig } from './types';
import { fetchPurchaseOrders, fetchInventoryFromSheet, fetchChannelConfigs, fetchUsers } from './services/api';

const App: React.FC = () => {
  const [isSidebarOpen, setSidebarOpen] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [lastSynced, setLastSynced] = useState<number>(0);

  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [isAuthChecked, setIsAuthChecked] = useState(false);

  const [users, setUsers] = useState<User[]>([]);
  const [rolePermissions] = useState<RolePermissions>(initialRolePermissions);

  const [activeView, setActiveView] = useState<ViewType>('Dashboard');
  const [activeFilter, setActiveFilter] = useState('All POs');
  const [adminTab, setAdminTab] = useState<'users' | 'roles' | 'channels' | 'integrations' | 'logs'>('users');

  const [purchaseOrders, setPurchaseOrders] = useState<PurchaseOrder[]>([]);
  const [inventoryItems, setInventoryItems] = useState<InventoryItem[]>([]);
  const [channelConfigs, setChannelConfigs] = useState<ChannelConfig[]>([]);

  const [logs, setLogs] = useState<ActivityLog[]>([
    { id: '1', user: 'System', action: 'Init', details: 'System initialized.', timestamp: new Date().toLocaleString() }
  ]);
  const [notifications, setNotifications] = useState<NotificationItem[]>([]);
  const [toasts, setToasts] = useState<NotificationItem[]>([]);

  useEffect(() => {
    const savedUser = localStorage.getItem('cube_session');
    if (savedUser) {
        try {
            setCurrentUser(JSON.parse(savedUser));
        } catch (e) {
            localStorage.removeItem('cube_session');
        }
    }
    setIsAuthChecked(true);
  }, []);

  const handleLogin = (user: User) => {
    setCurrentUser(user);
    localStorage.setItem('cube_session', JSON.stringify(user));
  };

  const handleLogout = () => {
    setCurrentUser(null);
    localStorage.removeItem('cube_session');
  };

  const addLog = useCallback((action: string, details: string) => {
    const newLog: ActivityLog = {
        id: Date.now().toString(),
        user: currentUser?.name || 'System', 
        action,
        details,
        timestamp: new Date().toLocaleString()
    };
    setLogs(prev => [newLog, ...prev]);
  }, [currentUser]);

  const addNotification = useCallback((message: string, type: 'info' | 'success' | 'warning' | 'error' = 'info') => {
    const newNotification: NotificationItem = {
        id: Date.now().toString(),
        message,
        timestamp: new Date().toLocaleTimeString(),
        read: false,
        type
    };
    setNotifications(prev => [newNotification, ...prev]);
    setToasts(prev => [...prev, newNotification]);
  }, []);

  const removeToast = useCallback((id: string) => {
    setToasts(prev => prev.filter(t => t.id !== id));
  }, []);

  const refreshData = useCallback(async (force = false) => {
      if (!force && purchaseOrders.length > 0 && Date.now() - lastSynced < 1800000) return; 

      setIsLoading(true);
      try {
          const [poData, invData, channelData, userData] = await Promise.all([
              fetchPurchaseOrders(),
              fetchInventoryFromSheet(),
              fetchChannelConfigs(),
              fetchUsers()
          ]);

          if (poData.length > 0) setPurchaseOrders(poData);
          if (invData.length > 0) setInventoryItems(invData);
          if (channelData.length > 0) setChannelConfigs(channelData);
          if (userData.length > 0) setUsers(userData);

          setLastSynced(Date.now());
      } catch (e) {
          addNotification('Failed to sync data.', 'error');
      } finally {
          setIsLoading(false);
      }
  }, [lastSynced, purchaseOrders.length, addNotification]);

  useEffect(() => {
    if (currentUser) {
        refreshData();
        const intervalId = setInterval(() => refreshData(true), 30 * 60 * 1000);
        return () => clearInterval(intervalId);
    }
  }, [refreshData, currentUser]);

  const getCalculatedStatus = (po: PurchaseOrder): POStatus => {
    const items = po.items || [];
    if (po.status === POStatus.Cancelled) return POStatus.Cancelled;
    const pushedCount = items.filter(i => !!i.eeOrderRefId).length;
    if (items.length > 0 && pushedCount === items.length) return POStatus.Pushed;
    if (pushedCount > 0) return POStatus.PartiallyProcessed;
    return POStatus.NewPO;
  };

  const summaryData = useMemo(() => {
    const totalActive = purchaseOrders.filter(p => p.status !== POStatus.Closed && p.status !== POStatus.Cancelled).length;
    const pushed = purchaseOrders.filter(p => getCalculatedStatus(p) === POStatus.Pushed).length;
    const partiallyPushed = purchaseOrders.filter(p => getCalculatedStatus(p) === POStatus.PartiallyProcessed).length;

    return [
      { title: 'Total Active POs', value: totalActive.toString(), change: 'Across all stages', color: 'blue', targetView: 'Purchase Orders', targetFilter: 'All POs' },
      { title: 'Fully Pushed', value: pushed.toString(), change: 'To EasyEcom', color: 'green', targetView: 'Purchase Orders', targetFilter: 'Pushed POs' },
      { title: 'Partially Pushed', value: partiallyPushed.toString(), change: 'Pending items', color: 'yellow', targetView: 'Purchase Orders', targetFilter: 'Partially Pushed POs' },
    ];
  }, [purchaseOrders]);

  const tabCounts = useMemo(() => {
    const counts = { 'All POs': purchaseOrders.length, 'New POs': 0, 'Pushed POs': 0, 'Partially Pushed POs': 0, 'Cancelled POs': 0 };
    purchaseOrders.forEach(po => {
        const status = getCalculatedStatus(po);
        if (status === POStatus.NewPO) counts['New POs']++;
        else if (status === POStatus.Pushed) counts['Pushed POs']++;
        else if (status === POStatus.PartiallyProcessed) counts['Partially Pushed POs']++;
        else if (status === POStatus.Cancelled) counts['Cancelled POs']++;
    });
    return counts;
  }, [purchaseOrders]);

  const handleCardClick = (view: ViewType, filter?: string) => {
      if (currentUser && rolePermissions[currentUser.role]?.includes(view)) {
          setActiveView(view);
          if (filter) setActiveFilter(filter);
      } else {
          addNotification(`Access Denied.`, 'error');
      }
  };

  const renderContent = () => {
    if (!currentUser) return null;
    if (isLoading && purchaseOrders.length === 0) {
        return <div className="flex-1 flex flex-col items-center justify-center p-8"><RefreshIcon className="h-12 w-12 text-partners-green animate-spin mb-4" /><p className="text-gray-600 font-bold text-lg">Syncing Dashboard...</p></div>;
    }

    switch (activeView) {
        case 'Dashboard':
            return (
                <div className="p-4 sm:p-6 lg:p-8 flex-1">
                    <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
                        {summaryData.map((card, index) => (
                            <SummaryCard key={index} {...card as any} onClick={() => handleCardClick(card.targetView as ViewType, card.targetFilter)} />
                        ))}
                    </div>
                </div>
            );
        case 'Purchase Orders':
        case 'Uploads':
            return (
                <div className="p-4 sm:p-6 lg:p-8 flex-1">
                    <PoTable activeFilter={activeFilter} setActiveFilter={setActiveFilter} purchaseOrders={purchaseOrders} setPurchaseOrders={setPurchaseOrders} tabCounts={tabCounts} addLog={addLog} addNotification={addNotification} onSync={() => refreshData(true)} isSyncing={isLoading} />
                </div>
            );
        case 'File Uploader':
            return <FileUploader currentUser={currentUser} addLog={addLog} addNotification={addNotification} />;
        case 'Inventory': return <InventoryManager addLog={addLog} inventoryItems={inventoryItems} setInventoryItems={setInventoryItems} onSync={() => refreshData(true)} isSyncing={isLoading} />;
        case 'Finance': return <FinanceManager purchaseOrders={purchaseOrders} setPurchaseOrders={setPurchaseOrders} addLog={addLog} />;
        case 'Reports': return <ReportsManager purchaseOrders={purchaseOrders} inventoryItems={inventoryItems} />;
        case 'Sales Orders':
             return (
                <div className="p-4 sm:p-6 lg:p-8 flex-1">
                    <SalesOrderTable activeFilter={activeFilter} setActiveFilter={setActiveFilter} purchaseOrders={purchaseOrders} setPurchaseOrders={setPurchaseOrders} tabCounts={tabCounts} addLog={addLog} addNotification={addNotification} onSync={() => refreshData(true)} isSyncing={isLoading} />
                </div>
            );
        case 'Admin': return (
            <AdminPanel logs={logs} users={users} setUsers={setUsers} rolePermissions={rolePermissions} setRolePermissions={() => {}} addLog={addLog} currentUser={currentUser} channelConfigs={channelConfigs} onSync={() => refreshData(true)} activeTab={adminTab} setActiveTab={setAdminTab} />
        );
        default: return <div className="p-8 text-center text-gray-500">Section Under Construction</div>;
    }
  };

  if (!isAuthChecked) return null;
  if (!currentUser) return <Login onLoginSuccess={handleLogin} />;

  return (
    <div className="flex h-screen bg-partners-gray-bg font-sans">
      <ToastContainer toasts={toasts} onRemove={removeToast} />
      <div className={`fixed lg:relative inset-y-0 left-0 transform ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full'} lg:translate-x-0 transition-transform duration-300 ease-in-out z-30`}>
        <Sidebar activeView={activeView} setActiveView={setActiveView} currentUser={currentUser} permissions={rolePermissions} onLogout={handleLogout} />
      </div>
      <main className="flex-1 flex flex-col overflow-y-auto">
        <Header notifications={notifications} onMarkRead={() => {}} onClearAll={() => {}} onViewLogs={() => { setActiveView('Admin'); setAdminTab('logs'); }} activeView={activeView} />
        {renderContent()}
      </main>
