const API_URL = 'https://script.google.com/macros/s/AKfycbwBDSNnN_xKlZc4cTwwKthd7-Nq8IE83csNdNHODP55EnVEz-gfWzcvzYdxGeNbJSPzZQ/exec'; 

const postToScript = async (payload: any) => {
    if (!API_URL || API_URL.includes('YOUR_SCRIPT_ID')) throw new Error("API URL is not configured.");
    try {
        const response = await fetch(API_URL, {
            method: 'POST',
            mode: 'cors',
            redirect: 'follow',
            body: JSON.stringify(payload)
        });
        if (!response.ok) throw new Error(`HTTP Error ${response.status}`);
        return response;
    } catch (error: any) {
        console.error("Fetch failed:", error);
        throw error;
    }
};

export const logFileUpload = async (functionId: string, userName: string): Promise<{status: string, message?: string}> => {
    const response = await postToScript({ action: 'logFileUpload', functionId, userName });
