            // Log the upload attempt to the backend
            const res = await logFileUpload(selectedFunction, currentUser.name);

            if (res.status === 'success') {
                addLog('File Upload', `Successfully uploaded ${file.name} for ${selectedFunction}`);
                addNotification(`File "${file.name}" processed successfully.`, 'success');
                setIsModalOpen(false);
                loadMetadata();
            } else {
                addNotification('Upload failed. Please try again.', 'error');
