            const res = await createZohoInvoice(eeReferenceCode);
            if (res.status === 'success') {
                addNotification('Invoice creation triggered in Zoho.', 'success');
                addLog('Invoice Creation', `Triggered Zoho Invoice for Reference: ${eeReferenceCode}`);
                // Refresh data to potentially see the new invoice number if synced immediately
                onSync();
            } else {
                addNotification('Error: ' + (res.message || 'Failed to trigger invoice creation.'), 'error');
            }
