                    </thead>
                    <tbody>
                        {salesOrders.length === 0 ? (
                            <tr>
                                <td colSpan={8} className="px-6 py-10 text-center text-gray-500 italic">
                                    No sales orders found with an EasyEcom reference code.
                                </td>
                            </tr>
                        ) : (
                            salesOrders.map((so) => {
                                const isExpanded = expandedRowId === so.id;
                                const totalAmountIncTax = so.amount * 1.05;
                                const hasBatch = !!so.batchCreatedAt;
                                const hasInvoice = !!so.invoiceNumber;

                                return (
                                    <Fragment key={so.id}>
                                        <tr className={`border-b hover:bg-gray-50 cursor-pointer ${isExpanded ? 'bg-gray-50' : 'bg-white'}`} onClick={() => toggleRowExpansion(so.id)}>
                                            <td className="p-4 text-center">
                                                <div className="text-gray-400 hover:text-partners-green">
                                                    {isExpanded ? <ChevronDownIcon /> : <ChevronRightIcon />}
                                                </div>
                                            </td>
                                            <td className="px-6 py-4 font-bold text-blue-600 whitespace-nowrap">{so.id}</td>
                                            <td className="px-6 py-4">
                                                <span className={`px-2 py-0.5 rounded-full text-[10px] font-bold uppercase ${
                                                    so.status === 'Invoiced' ? 'bg-indigo-100 text-indigo-700' :
                                                    so.status === 'Batch Created' ? 'bg-amber-100 text-amber-700' :
                                                    so.status.toLowerCase().includes('closed') || so.status.toLowerCase().includes('delivered') ? 'bg-green-100 text-green-700' : 
                                                    'bg-blue-100 text-blue-700'
                                                }`}>
                                                    {so.status}
                                                </span>
                                            </td>
                                            <td className="px-6 py-4">{so.channel}</td>
                                            <td className="px-6 py-4">{so.storeCode}</td>
                                            <td className="px-6 py-4 font-medium text-gray-900">{so.qty} / ₹{totalAmountIncTax.toLocaleString('en-IN', { minimumFractionDigits: 0, maximumFractionDigits: 0 })}</td>
                                            <td className="px-6 py-4 whitespace-nowrap text-gray-400">{so.orderDate}</td>
                                            <td className="px-6 py-4 text-center" onClick={(e) => e.stopPropagation()}>
                                                <button className="text-gray-400 hover:text-gray-600 p-1">
                                                    <DotsVerticalIcon className="h-4 w-4" />
