function handleCreateZohoInvoice(eeReferenceCode) {
  try {
    if (typeof createZohoInvoiceByReferenceCode === 'function') {
      const result = createZohoInvoiceByReferenceCode(eeReferenceCode);
      return responseJSON({ status: 'success', message: result || 'Invoice creation triggered successfully.' });
    } else {
      return responseJSON({ status: 'error', message: 'Backend function createZohoInvoiceByReferenceCode is not defined.' });
    }
  } catch (e) {
    return responseJSON({ status: 'error', message: e.toString() });
  }
}

function logFileUpload(data) {
  const sheet = getOrCreateSheet(SHEET_UPLOAD_LOGS, ["ID", "FunctionName", "LastUploadedBy", "LastUploadedAt", "Status", "FileName"]);
  const now = new Date().toLocaleString();
  const functionNameMap = { 'b2b-packing-list': 'B2B Packing List Data' };

  let processingResult = "Logged successfully.";
  let status = 'Success';

  if (data.functionId === 'b2b-packing-list') {
    try {
      if (typeof UpdatePackingListData === "function") {
        UpdatePackingListData(data.fileData, data.fileName);
        processingResult = "Function 'UpdatePackingListData' executed successfully.";
      } else {
        processingResult = "Warning: 'UpdatePackingListData' is not defined. Logged only.";
        status = 'Pending';
      }
    } catch (e) {
      processingResult = "Error: " + e.toString();
      status = 'Error';
      sheet.appendRow([data.functionId, functionNameMap[data.functionId] || data.functionId, data.userName, now, status, data.fileName || 'N/A']);
      return responseJSON({status: 'error', message: processingResult});
    }
  }

  sheet.appendRow([data.functionId, functionNameMap[data.functionId] || data.functionId, data.userName, now, status, data.fileName || 'N/A']);
  return responseJSON({status: 'success', message: processingResult});
}

function UpdatePackingListData(base64Data, fileName) {
  console.log("Processing packing list file: " + fileName);
}

function loginUser(email, password) {
  const sheet = SpreadsheetApp.getActiveSpreadsheet().getSheetByName(SHEET_USERS);
  const rows = getDataAsJSON(sheet);
  const user = rows.find(r => String(r['Email']).toLowerCase() === String(email).toLowerCase());

  if (!user) return responseJSON({status: 'error', message: 'User not found'});
  if (String(user['Password']) === String(password)) {
    const userOutput = {...user};
    delete userOutput['Password'];
    return responseJSON({status: 'success', user: userOutput});
  }
  return responseJSON({status: 'error', message: 'Incorrect password'});
}

function resetPassword(userId) {
  const sheet = SpreadsheetApp.getActiveSpreadsheet().getSheetByName(SHEET_USERS);
  const rows = sheet.getDataRange().getValues();
  const headers = rows[0];
  const idIdx = headers.indexOf('ID');
  const passIdx = headers.indexOf('Password');
  const initIdx = headers.indexOf('IsInitialized');

  for (let i = 1; i < rows.length; i++) {
    if (String(rows[i][idIdx]) === String(userId)) {
      const tempPass = Math.random().toString(36).slice(-8);
      sheet.getRange(i + 1, passIdx + 1).setValue(tempPass);
      sheet.getRange(i + 1, initIdx + 1).setValue(false);
      const userEmail = rows[i][headers.indexOf('Email')];
      sendSetupEmail(userEmail, tempPass);
      return responseJSON({status: 'success', message: 'Reset email sent'});
    }
  }
  return responseJSON({status: 'error', message: 'User not found'});
}

function saveUser(data) {
  const sheet = getOrCreateSheet(SHEET_USERS, ["ID", "Name", "Email", "Contact", "Role", "Avatar", "Password", "IsInitialized"]);
  const rows = sheet.getDataRange().getValues();
  const headers = rows[0];
  const idIdx = headers.indexOf('ID');
  let isNew = true;
  for (let i = 1; i < rows.length; i++) {
    if (String(rows[i][idIdx]) === String(data.id)) {
      isNew = false;
      const range = sheet.getRange(i + 1, 1, 1, headers.length);
      const updatedRow = headers.map(h => {
        if (h === 'ID') return data.id;
        if (h === 'Name') return data.name;
        if (h === 'Email') return data.email;
        if (h === 'Contact') return data.contactNumber;
        if (h === 'Role') return data.role;
        if (h === 'Avatar') return data.avatarInitials;
        return rows[i][headers.indexOf(h)];
      });
      range.setValues([updatedRow]);
      break;
    }
  }
  if (isNew) {
    const tempPass = Math.random().toString(36).slice(-8);
    sheet.appendRow([data.id, data.name, data.email, data.contactNumber, data.role, data.avatarInitials, tempPass, false]);
    sendSetupEmail(data.email, tempPass);
  }
  return responseJSON({status: 'success', message: isNew ? 'Invite sent' : 'User updated'});
}

function sendSetupEmail(email, tempPass) {
  try {
    const subject = "Welcome to Cubelelo PO Portal - Setup your account";
    const body = `Your account has been created.\n\nLogin: ${email}\nTemp Pass: ${tempPass}\n\nPlease change it immediately.`;
    MailApp.sendEmail(email, subject, body);
  } catch (e) {}
}

function getOrCreateSheet(name, headers) {
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  let sheet = ss.getSheetByName(name);
  if (!sheet) {
    sheet = ss.insertSheet(name);
    sheet.appendRow(headers);
  }
  return sheet;
}

function deleteUser(userId) {
  const sheet = SpreadsheetApp.getActiveSpreadsheet().getSheetByName(SHEET_USERS);
  const rows = sheet.getDataRange().getValues();
  const idIdx = rows[0].indexOf('ID');
  for (let i = 1; i < rows.length; i++) {
    if (String(rows[i][idIdx]) === String(userId)) {
      sheet.deleteRow(i + 1);
      break;
    }
  }
  return responseJSON({status: 'success'});
}

function getPurchaseOrders() {
  const sheet = SpreadsheetApp.getActiveSpreadsheet().getSheetByName(SHEET_PO);
  return responseJSON({status: 'success', data: getDataAsJSON(sheet)});
}

function getInventory() {
  const sheet = SpreadsheetApp.getActiveSpreadsheet().getSheetByName(SHEET_INVENTORY);
  return responseJSON({status: 'success', data: getDataAsJSON(sheet)});
}

function getChannelConfigs() {
  const sheet = SpreadsheetApp.getActiveSpreadsheet().getSheetByName(SHEET_CHANNEL_CONFIG);
  return responseJSON({status: 'success', data: getDataAsJSON(sheet)});
}

function getSystemConfig() {
  const props = PropertiesService.getScriptProperties();
  return responseJSON({ status: 'success', data: { easyecom_email: props.getProperty('EASY_ECOM_EMAIL') || '' } });
}

function getDataAsJSON(sheet) {
  if (!sheet) return [];
  const rawData = sheet.getDataRange().getValues();
  if (rawData.length <= 1) return [];
  const headers = rawData[0];
  const data = [];
  for (let i = 1; i < rawData.length; i++) {
    const row = rawData[i];
    if (row.every(cell => cell === "")) continue;
    const obj = {};
    for (let j = 0; j < headers.length; j++) { obj[headers[j]] = row[j]; }
    data.push(obj);
  }
  return data;
}

function responseJSON(data) {
  return ContentService.createTextOutput(JSON.stringify(data)).setMimeType(ContentService.MimeType.JSON);
}

function debugLog(action, data) {
  try {
    const ss = SpreadsheetApp.getActiveSpreadsheet();
    let sheet = getOrCreateSheet(LOG_DEBUG_SHEET, ["Timestamp", "Action", "Raw Payload"]);
    sheet.appendRow([new Date(), action, JSON.stringify(data)]);
  } catch (err) {}
}

import React, { useState, Fragment, useMemo } from 'react';
import { type PurchaseOrder, type InventoryItem, POItem } from '../types';
import { DotsVerticalIcon, CloudDownloadIcon, ChevronDownIcon, ChevronRightIcon, TruckIcon, CalendarIcon, CheckCircleIcon, CubeIcon, InvoiceIcon, ClipboardListIcon, ExternalLinkIcon, PaperclipIcon, RefreshIcon, PlusIcon, SendIcon, LockClosedIcon } from './icons/Icons';
import { createZohoInvoice, pushToNimbusPost } from '../services/api';

interface SalesOrderTableProps {
    activeFilter: string;
    setActiveFilter: (filter: string) => void;
    purchaseOrders: PurchaseOrder[];
    setPurchaseOrders: React.Dispatch<React.SetStateAction<PurchaseOrder[]>>;
    tabCounts: { [key: string]: number };
    addLog: (action: string, details: string) => void;
    addNotification: (message: string, type?: 'info' | 'success' | 'warning' | 'error') => void;
    onSync: () => void;
    isSyncing: boolean;
    inventoryItems?: InventoryItem[];
}

interface GroupedSalesOrder {
    id: string;
    poReference: string;
    status: string; // Dynamic Status
    originalEeStatus: string;
    channel: string;
    storeCode: string;
    orderDate: string; // PO Date
    poEdd?: string;
    poExpiryDate?: string;
    poPdfUrl?: string;
    qty: number;
    amount: number; // Base aggregated amount for this Sales Order
    items: POItem[];
    // Dates associated with the Reference Code
    batchCreatedAt?: string;
    invoiceDate?: string; // Strictly from "Invoice Date" sheet column
    manifestDate?: string;
    // Specific Invoice Info
    invoiceId?: string;
    invoiceStatus?: string;
    invoiceNumber?: string;
    invoiceTotal?: number;
    invoiceUrl?: string;
}

const parseDate = (dateStr: string): Date => {
    try {
        if (!dateStr) return new Date(0);
        const parts = dateStr.match(/(\d+)\s+(\w+)\s+(\d+)/);
        if (parts && parts.length === 4) {
            const day = parts[1];
            const month = parts[2];
            let year = parts[3];
            if (year.length === 2) year = '20' + year;
            return new Date(`${day} ${month} ${year}`);
        }
        return new Date(dateStr);
    } catch (e) {
        return new Date(0);
    }
};

const SalesOrderTable: React.FC<SalesOrderTableProps> = ({ activeFilter, setActiveFilter, purchaseOrders, onSync, isSyncing, addLog, addNotification }) => {
    const [expandedRowId, setExpandedRowId] = useState<string | null>(null);
    const [isCreatingInvoice, setIsCreatingInvoice] = useState<string | null>(null);
    const [isPushingNimbus, setIsPushingNimbus] = useState<string | null>(null);

    const tabs = [
        { name: 'All POs' }, { name: 'In-Transit' }, { name: 'GRN Pending' }, { name: 'GRN Updated' }, { name: 'RTO' }, { name: 'Closed' },
    ];

    // Grouping logic strictly based on item-level eeReferenceCode
    const salesOrders = useMemo(() => {
        const groups: Record<string, GroupedSalesOrder> = {};

        purchaseOrders.forEach(po => {
            (po.items || []).forEach(item => {
                const rawRef = item.eeReferenceCode;
                if (rawRef === undefined || rawRef === null || String(rawRef).trim() === "") return;

                const refCode = String(rawRef).trim();

                const effectiveQty = (item.itemQuantity !== undefined && item.itemQuantity !== 0) ? item.itemQuantity : item.qty;
                const effectiveLineAmount = effectiveQty * (item.unitCost || 0);

                const batchDate = item.eeBatchCreatedAt || po.eeBatchCreatedAt;
                const invNum = item.invoiceNumber;
                const maniDate = item.eeManifestDate || po.eeManifestDate;
                const eeStatus = (item.eeOrderStatus || po.eeOrderStatus || 'Processing').trim();

                // Priority Status Mapping
                let displayStatus = eeStatus;
                if (maniDate) {
                    displayStatus = 'Shipped';
                } else if (invNum) {
                    displayStatus = 'Invoiced';
                } else if (batchDate) {
                    displayStatus = 'Batch Created';
                } else if (eeStatus.toLowerCase() === 'confirmed') {
                    displayStatus = 'Confirmed';
                }

                if (!groups[refCode]) {
                    groups[refCode] = {
                        id: refCode,
                        poReference: String(po.poNumber || ''),
                        status: displayStatus,
                        originalEeStatus: eeStatus,
                        channel: po.channel,
                        storeCode: po.storeCode,
                        orderDate: po.orderDate,
                        poEdd: po.poEdd,
                        poExpiryDate: po.poExpiryDate,
                        poPdfUrl: po.poPdfUrl,
                        qty: 0,
                        amount: 0,
                        items: [],
                        batchCreatedAt: batchDate,
                        invoiceDate: item.invoiceDate,
                        manifestDate: maniDate,
                        invoiceId: item.invoiceId,
                        invoiceStatus: item.invoiceStatus,
                        invoiceNumber: invNum,
                        invoiceTotal: item.invoiceTotal,
                        invoiceUrl: item.invoiceUrl
                    };
                } else {
                    const currentPoNum = String(po.poNumber || '');
                    if (!groups[refCode].poReference.includes(currentPoNum)) {
                        groups[refCode].poReference += `, ${currentPoNum}`;
                    }

                    // Update grouping status if a more advanced one is found
                    const statusRank = (s: string) => {
                        if (s === 'Shipped') return 5;
                        if (s === 'Invoiced') return 4;
                        if (s === 'Batch Created') return 3;
                        if (s === 'Confirmed') return 2;
                        return 1;
                    };

                    if (statusRank(displayStatus) > statusRank(groups[refCode].status)) {
                        groups[refCode].status = displayStatus;
                    }

                    if (!groups[refCode].batchCreatedAt) groups[refCode].batchCreatedAt = batchDate;
                    if (!groups[refCode].invoiceDate) groups[refCode].invoiceDate = item.invoiceDate;
                    if (!groups[refCode].manifestDate) groups[refCode].manifestDate = maniDate;

                    if (!groups[refCode].invoiceId) groups[refCode].invoiceId = item.invoiceId;
                    if (!groups[refCode].invoiceStatus) groups[refCode].invoiceStatus = item.invoiceStatus;
                    if (!groups[refCode].invoiceNumber) groups[refCode].invoiceNumber = invNum;
                    if (!groups[refCode].invoiceTotal) groups[refCode].invoiceTotal = item.invoiceTotal;
                    if (!groups[refCode].invoiceUrl) groups[refCode].invoiceUrl = item.invoiceUrl;
                    if (!groups[refCode].poPdfUrl) groups[refCode].poPdfUrl = po.poPdfUrl;
                }

                groups[refCode].items.push(item);
                groups[refCode].qty += effectiveQty;
                groups[refCode].amount += effectiveLineAmount;
            });
        });

        let results = Object.values(groups);

        if (activeFilter !== 'All POs') {
             results = results.filter(so => {
                 const status = so.status.toLowerCase();
                 if (activeFilter === 'In-Transit') return status.includes('transit') || status.includes('shipped') || status.includes('manifest') || status.includes('batch') || status.includes('invoiced');
                 if (activeFilter === 'Closed') return status.includes('closed') || status.includes('delivered');
                 if (activeFilter === 'RTO') return status.includes('rto');
                 return true;
             });
        }

        results.sort((a, b) => {
            const dateA = parseDate(a.orderDate).getTime();
            const dateB = parseDate(b.orderDate).getTime();
            return dateB - dateA;
        });

        return results;
    }, [purchaseOrders, activeFilter]);

    const toggleRowExpansion = (soId: string) => setExpandedRowId(expandedRowId === soId ? null : soId);

    const handleCreateZohoInvoice = async (eeReferenceCode: string) => {
        setIsCreatingInvoice(eeReferenceCode);
        try {
            const res = await createZohoInvoice(eeReferenceCode);
            if (res.status === 'success') {
                addNotification(res.message || 'Invoice creation triggered in Zoho.', 'success');
                addLog('Invoice Creation', `Backend Response: ${res.message || 'Success'}. Ref: ${eeReferenceCode}`);
                onSync();
            } else {
                addNotification('Error: ' + (res.message || 'Failed to trigger invoice creation.'), 'error');
            }
        } catch (e) {
            addNotification('Network error triggering invoice creation.', 'error');
        } finally {
            setIsCreatingInvoice(null);
        }
    };

    const handlePushToNimbus = async (eeReferenceCode: string) => {
        setIsPushingNimbus(eeReferenceCode);
        try {
            const res = await pushToNimbusPost(eeReferenceCode);
            if (res.status === 'success') {
                addNotification(res.message || 'Order pushed to Nimbus Post successfully.', 'success');
                addLog('Nimbus Shipping', `Backend Response: ${res.message || 'Success'}. Ref: ${eeReferenceCode}`);
                onSync();
            } else {
                addNotification('Shipping Error: ' + (res.message || 'Failed to push to Nimbus Post.'), 'error');
            }
        } catch (e) {
            addNotification('Network error pushing to Nimbus Post.', 'error');
        } finally {
            setIsPushingNimbus(null);
        }
    };

    const TimelineStep = ({ label, date, icon, isLast = false }: { label: string, date?: string, icon: React.ReactNode, isLast?: boolean }) => {
        const isActive = !!date;
        return (
            <div className="flex items-center flex-1 last:flex-none">
