                                                                                <InvoiceIcon className="h-8 w-8 text-purple-200 mb-2" />
                                                                                <p className="text-xs font-bold text-purple-400 uppercase">No Invoice Generated</p>

                                                                                {!canCreateInvoice ? (
                                                                                    <div className="mt-4 px-3 py-1.5 bg-gray-100 text-gray-400 text-[10px] font-bold rounded-lg flex items-center gap-2 border border-gray-200">
                                                                                        <LockClosedIcon className="h-3 w-3" /> Awaiting EE Confirmation
                                                                                    </div>
                                                                                ) : (
                                                                                    <button 
                                                                                        onClick={() => handleCreateZohoInvoice(so.id)}
                                                                                        disabled={isCreatingInvoice === so.id}
                                                                                        className="mt-4 px-4 py-2 bg-purple-600 text-white text-[11px] font-bold rounded-lg shadow-sm hover:bg-purple-700 transition-all active:scale-95 flex items-center gap-2"
                                                                                    >
                                                                                        {isCreatingInvoice === so.id ? <RefreshIcon className="h-3 w-3 animate-spin" /> : <PlusIcon className="h-3 w-3" />}
                                                                                        {isCreatingInvoice === so.id ? 'Processing...' : 'Create Zoho Invoice'}
                                                                                    </button>
                                                                                )}
                                                                            </div>
                                                                        )}
                                                                    </div>
                                                                </div>

                                                                <div>
                                                                    <h4 className="text-xs font-bold text-gray-400 uppercase tracking-widest mb-4 flex items-center gap-2">
                                                                        <TruckIcon className="h-4 w-4 text-blue-500" /> Nimbus Post Shipping
                                                                    </h4>
                                                                    <div className={`p-4 rounded-lg border transition-all ${canShipWithNimbus ? 'bg-blue-50 border-blue-100 shadow-sm' : isShipped ? 'bg-emerald-50 border-emerald-100' : 'bg-gray-50 border-gray-200 opacity-60'}`}>
                                                                        {isShipped ? (
                                                                            <div className="flex flex-col items-center gap-2 py-2">
                                                                                <CheckCircleIcon className="h-6 w-6 text-emerald-500" />
                                                                                <p className="text-xs font-bold text-emerald-700">Shipped with Courier</p>
                                                                                <p className="text-[10px] text-emerald-500 font-medium">{so.manifestDate}</p>
                                                                            </div>
                                                                        ) : (
                                                                            <div className="flex flex-col gap-3">
                                                                                <div className="flex items-center justify-between">
                                                                                    <span className="text-[10px] font-bold text-blue-600 uppercase tracking-tighter">B2B Order Push</span>
                                                                                    {!canShipWithNimbus && <span className="text-[9px] font-bold bg-white px-1.5 rounded border border-gray-200 text-gray-400 flex items-center gap-1"><LockClosedIcon className="h-2 w-2" /> Locked</span>}
                                                                                </div>

                                                                                {!canShipWithNimbus ? (
                                                                                    <p className="text-[10px] text-gray-400 italic text-center py-2">Enable after Invoicing</p>
                                                                                ) : (
                                                                                    <button 
                                                                                        onClick={() => handlePushToNimbus(so.id)}
                                                                                        disabled={isPushingNimbus === so.id}
                                                                                        className="w-full py-2.5 bg-blue-600 text-white text-[11px] font-bold rounded-lg shadow-md hover:bg-blue-700 transition-all flex items-center justify-center gap-2 active:scale-95"
                                                                                    >
                                                                                        {isPushingNimbus === so.id ? <RefreshIcon className="h-3 w-3 animate-spin" /> : <SendIcon className="h-3 w-3" />}
                                                                                        {isPushingNimbus === so.id ? 'Pushing to Nimbus...' : 'Ship with Nimbus Post'}
                                                                                    </button>
                                                                                )}
                                                                            </div>
                                                                        )}
                                                                    </div>
                                                                </div>
                                                            </div>

                                                            <div>
                                                                <h4 className="text-xs font-bold text-gray-400 uppercase tracking-widest mb-4 flex items-center gap-2">
                                                                    <TruckIcon className="h-4 w-4 text-partners-green" /> Logistics Timeline (EE Ref: {so.id})
                                                                </h4>
                                                                <div className="flex px-4 pt-2">
                                                                    <TimelineStep label="Batch Created" date={so.batchCreatedAt} icon={<CubeIcon className="h-4 w-4" />} />
                                                                    <TimelineStep label="Invoiced" date={so.invoiceDate} icon={<InvoiceIcon className="h-4 w-4" />} />
                                                                    <TimelineStep label="Shipped" date={so.manifestDate} icon={<CheckCircleIcon className="h-4 w-4" />} isLast />
                                                                </div>
                                                            </div>
                                                        </div>

                                                        <div>
                                                            <h4 className="text-xs font-bold text-gray-400 uppercase tracking-widest mb-4 flex items-center gap-2">
                                                                <DotsVerticalIcon className="h-4 w-4 text-partners-green rotate-90" /> SKU Breakdown for this Sales Order
                                                            </h4>
                                                            <div className="overflow-x-auto border rounded-xl">
                                                                <table className="w-full text-[11px] text-left">
                                                                    <thead className="bg-gray-50 text-gray-500 uppercase">
                                                                        <tr>
                                                                            <th className="py-2.5 px-4">Item Name / SKU</th>
                                                                            <th className="py-2.5 text-right w-24">EE Item Qty</th>
                                                                            <th className="py-2.5 text-right w-24 text-red-600">Cancelled</th>
                                                                            <th className="py-2.5 text-right w-24 text-green-600">Shipped</th>
                                                                            <th className="py-2.5 text-right w-24 text-orange-600">Returned</th>
                                                                            <th className="py-2.5 px-4 text-center w-28">Item status</th>
                                                                        </tr>
                                                                    </thead>
                                                                    <tbody className="divide-y divide-gray-100">
                                                                        {so.items.map((item, idx) => (
                                                                            <tr key={idx} className="hover:bg-gray-50">
                                                                                <td className="py-3 px-4">
                                                                                    <p className="font-bold text-gray-800">{item.itemName}</p>
                                                                                    <p className="text-[10px] text-gray-400 truncate max-w-[350px] font-mono">{item.masterSku || item.articleCode}</p>
                                                                                </td>
                                                                                <td className="py-3 text-right font-bold text-gray-900 w-24">{item.itemQuantity || 0}</td>
                                                                                <td className="py-3 text-right text-red-600 font-bold w-24">{item.cancelledQuantity || 0}</td>
                                                                                <td className="py-3 text-right text-green-600 font-bold w-24">{item.shippedQuantity || 0}</td>
                                                                                <td className="py-3 text-right text-orange-600 font-bold w-24">{item.returnedQuantity || 0}</td>
                                                                                <td className="py-3 px-4 text-center w-28">
                                                                                    <span className={`px-1.5 py-0.5 rounded text-[9px] font-bold uppercase inline-block w-full ${
                                                                                        item.itemStatus?.toLowerCase().includes('ship') || item.itemStatus?.toLowerCase().includes('transit') ? 'bg-green-50 text-green-700' : 'bg-gray-100 text-gray-600'
                                                                                    }`}>
                                                                                        {item.itemStatus || 'Processing'}
                                                                                    </span>
                                                                                </td>
                                                                            </tr>
                                                                        ))}
                                                                    </tbody>
                                                                </table>
                                                            </div>
                                                        </div>
                                                    </div>
                                                </td>
                                            </tr>
                                        )}
                                    </Fragment>
                                );
                            })
                        )}
                    </tbody>
                </table>
            </div>
        </div>
    );
};

