const parseDate = (dateStr: string): Date => {
    try {
        if (!dateStr) return new Date(0);
        const parts = dateStr.match(/(\d+)\s+(\w+)\s+(\d+)/);
        if (parts && parts.length === 4) {
            const day = parts[1];
            const month = parts[2];
            let year = parts[3];
            if (year.length === 2) year = '20' + year;
            return new Date(`${day} ${month} ${year}`);
        }
        return new Date(dateStr);
    } catch (e) {
        return new Date(0);
    }
};

const SalesOrderTable: React.FC<SalesOrderTableProps> = ({ activeFilter, setActiveFilter, purchaseOrders, onSync, isSyncing, addLog, addNotification }) => {
    const [expandedRowId, setExpandedRowId] = useState<string | null>(null);
    const [isCreatingInvoice, setIsCreatingInvoice] = useState<string | null>(null);
    const [isPushingNimbus, setIsPushingNimbus] = useState<string | null>(null);
    const [blinkitModal, setBlinkitModal] = useState<{ isOpen: boolean, so: GroupedSalesOrder | null }>({ isOpen: false, so: null });

    const tabs = [
        { name: 'All POs' }, { name: 'In-Transit' }, { name: 'GRN Pending' }, { name: 'GRN Updated' }, { name: 'RTO' }, { name: 'Closed' },
    ];

    const salesOrders = useMemo(() => {
        const groups: Record<string, GroupedSalesOrder> = {};

        purchaseOrders.forEach(po => {
            (po.items || []).forEach(item => {
                const rawRef = item.eeReferenceCode;
                if (rawRef === undefined || rawRef === null || String(rawRef).trim() === "") return;

                const refCode = String(rawRef).trim();
                const effectiveQty = (item.itemQuantity !== undefined && item.itemQuantity !== 0) ? item.itemQuantity : item.qty;
                const effectiveLineAmount = effectiveQty * (item.unitCost || 0);

                const batchDate = item.eeBatchCreatedAt || po.eeBatchCreatedAt;
                const invNum = item.invoiceNumber;
                const maniDate = item.eeManifestDate || po.eeManifestDate;
                const eeStatus = (item.eeOrderStatus || po.eeOrderStatus || 'Processing').trim();

                let displayStatus = eeStatus;
                if (maniDate) displayStatus = 'Shipped';
                else if (invNum) displayStatus = 'Invoiced';
                else if (batchDate) displayStatus = 'Batch Created';
                else if (eeStatus.toLowerCase() === 'confirmed') displayStatus = 'Confirmed';

                if (!groups[refCode]) {
                    groups[refCode] = {
                        id: refCode,
                        poReference: String(po.poNumber || ''),
                        status: displayStatus,
                        originalEeStatus: eeStatus,
                        channel: po.channel,
                        storeCode: po.storeCode,
                        orderDate: po.orderDate,
                        poEdd: po.poEdd,
                        poExpiryDate: po.poExpiryDate,
                        poPdfUrl: po.poPdfUrl,
                        qty: 0,
                        amount: 0,
                        items: [],
                        batchCreatedAt: batchDate,
                        invoiceDate: item.invoiceDate,
                        manifestDate: maniDate,
                        invoiceId: item.invoiceId,
                        invoiceStatus: item.invoiceStatus,
                        invoiceNumber: invNum,
                        invoiceTotal: item.invoiceTotal,
                        invoiceUrl: item.invoiceUrl,
                        carrier: po.carrier,
                        awb: po.awb,
                        bookedDate: po.bookedDate,
                        trackingStatus: po.trackingStatus,
                        edd: po.edd,
                        latestStatus: po.latestStatus,
                        latestStatusDate: po.latestStatusDate,
                        currentLocation: po.currentLocation,
                        deliveredDate: po.deliveredDate,
                        rtoStatus: po.rtoStatus,
                        rtoAwb: po.rtoAwb
                    };
                } else {
                    const currentPoNum = String(po.poNumber || '');
                    if (!groups[refCode].poReference.includes(currentPoNum)) {
                        groups[refCode].poReference += `, ${currentPoNum}`;
                    }

                    const statusRank = (s: string) => {
                        if (s === 'Shipped') return 5;
                        if (s === 'Invoiced') return 4;
                        if (s === 'Batch Created') return 3;
                        if (s === 'Confirmed') return 2;
                        return 1;
                    };

                    if (statusRank(displayStatus) > statusRank(groups[refCode].status)) {
                        groups[refCode].status = displayStatus;
                    }

                    if (!groups[refCode].batchCreatedAt) groups[refCode].batchCreatedAt = batchDate;
                    if (!groups[refCode].invoiceDate) groups[refCode].invoiceDate = item.invoiceDate;
                    if (!groups[refCode].manifestDate) groups[refCode].manifestDate = maniDate;
                    if (!groups[refCode].invoiceId) groups[refCode].invoiceId = item.invoiceId;
                    if (!groups[refCode].invoiceStatus) groups[refCode].invoiceStatus = item.invoiceStatus;
                    if (!groups[refCode].invoiceNumber) groups[refCode].invoiceNumber = invNum;
                    if (!groups[refCode].invoiceTotal) groups[refCode].invoiceTotal = item.invoiceTotal;
                    if (!groups[refCode].invoiceUrl) groups[refCode].invoiceUrl = item.invoiceUrl;
                    if (!groups[refCode].poPdfUrl) groups[refCode].poPdfUrl = po.poPdfUrl;
                }

                groups[refCode].items.push(item);
                groups[refCode].qty += effectiveQty;
                groups[refCode].amount += effectiveLineAmount;
            });
        });

        let results = Object.values(groups);

        if (activeFilter !== 'All POs') {
             results = results.filter(so => {
                 const status = so.status.toLowerCase();
                 if (activeFilter === 'In-Transit') return status.includes('transit') || status.includes('shipped') || status.includes('manifest') || status.includes('batch') || status.includes('invoiced');
                 if (activeFilter === 'Closed') return status.includes('closed') || status.includes('delivered');
                 if (activeFilter === 'RTO') return status.includes('rto');
                 return true;
             });
        }

        results.sort((a, b) => {
            const dateA = parseDate(a.orderDate).getTime();
            const dateB = parseDate(b.orderDate).getTime();
            return dateB - dateA;
        });

        return results;
    }, [purchaseOrders, activeFilter]);

    const toggleRowExpansion = (soId: string) => setExpandedRowId(expandedRowId === soId ? null : soId);

    const handleCreateZohoInvoice = async (eeReferenceCode: string) => {
        setIsCreatingInvoice(eeReferenceCode);
        try {
            const res = await createZohoInvoice(eeReferenceCode);
            if (res.status === 'success') {
                addNotification(res.message || 'Invoice creation triggered in Zoho.', 'success');
                addLog('Invoice Creation', `Backend Response: ${res.message || 'Success'}. Ref: ${eeReferenceCode}`);
                onSync();
            } else {
                addNotification('Error: ' + (res.message || 'Failed to trigger invoice creation.'), 'error');
            }
        } catch (e) {
            addNotification('Network error triggering invoice creation.', 'error');
        } finally {
            setIsCreatingInvoice(null);
        }
    };

    const handlePushToNimbus = async (eeReferenceCode: string) => {
        setIsPushingNimbus(eeReferenceCode);
        try {
            const res = await pushToNimbusPost(eeReferenceCode);
            if (res.status === 'success') {
                addNotification(res.message || 'Order pushed to Nimbus Post successfully.', 'success');
                addLog('Nimbus Shipping', `Backend Response: ${res.message || 'Success'}. Ref: ${eeReferenceCode}`);
                onSync();
            } else {
                addNotification('Shipping Error: ' + (res.message || 'Failed to push to Nimbus Post.'), 'error');
            }
        } catch (e) {
            addNotification('Network error pushing to Nimbus Post.', 'error');
        } finally {
            setIsPushingNimbus(null);
        }
    };

    const TimelineStep = ({ label, date, icon, isLast = false }: { label: string, date?: string, icon: React.ReactNode, isLast?: boolean }) => {
        const isActive = !!date;
        return (
            <div className="flex items-center flex-1 last:flex-none">
                <div className="flex flex-col items-center">
                    <div className={`flex items-center justify-center w-8 h-8 rounded-full border-2 transition-colors ${
                        isActive ? 'bg-partners-green border-partners-green text-white shadow-sm' : 'bg-white border-gray-200 text-gray-300'
                    }`}>
                        {icon}
                    </div>
                    <div className="mt-2 text-center">
                        <p className={`text-[10px] font-bold uppercase tracking-wider ${isActive ? 'text-gray-800' : 'text-gray-400'}`}>{label}</p>
                        <p className="text-[11px] font-medium text-gray-500 whitespace-nowrap mt-0.5">{date || 'Pending'}</p>
                    </div>
                </div>
                {!isLast && (
                    <div className={`h-0.5 flex-1 mx-4 -mt-6 transition-colors ${isActive ? 'bg-partners-green' : 'bg-gray-200'}`}></div>
                )}
            </div>
        );
    };

