                            <th className="p-4 w-4"></th>
                            <th className="px-6 py-3 text-blue-600">Sales Order ID (EE Ref)</th>
                            <th className="px-6 py-3">EE Order Status</th>
                            <th className="px-6 py-3">Channel</th>
                            <th className="px-6 py-3">Store</th>
                            <th className="px-6 py-3">Qty / Total (Inc. 5% GST)</th>
                            <th className="px-6 py-3">Order Date</th>
                            <th className="px-6 py-3 text-center">Action</th>
                        </tr>
                    </thead>
                    <tbody>
                        {salesOrders.length === 0 ? (
                            <tr>
                                <td colSpan={8} className="px-6 py-10 text-center text-gray-500 italic">
                                    No sales orders found with an EasyEcom reference code.
                                </td>
                            </tr>
                        ) : (
                            salesOrders.map((so) => {
                                const isExpanded = expandedRowId === so.id;
                                const totalAmountIncTax = so.amount * 1.05;

