                                                                            <a href={so.poPdfUrl} target="_blank" rel="noopener noreferrer" className="text-partners-green hover:underline flex items-center gap-1 text-xs font-bold mt-0.5">
                                                                                <PaperclipIcon className="h-3 w-3" /> View PO PDF
                                                                            </a>
                                                                        ) : (
                                                                            <p className="text-xs text-gray-300 font-bold italic mt-0.5">Not Uploaded</p>
