const EmailAppointmentModal: FC<AppointmentModalProps> = ({ po, poc, onClose, onSuccess, addLog, addNotification }) => {
    const [boxes, setBoxes] = useState(po.boxes || 1);
    const [isLoading, setIsLoading] = useState(false);

