                                                    {isRTO ? `RTO: ${so.rtoStatus}` : so.status}
                                                </span>
                                            </td>
                                            <td className="px-6 py-4">{so.channel}</td>
                                            <td className="px-6 py-4">{so.storeCode}</td>
                                            <td className="px-6 py-4 font-medium text-gray-900">{so.qty} / ₹{totalAmountIncTax.toLocaleString('en-IN', { minimumFractionDigits: 0, maximumFractionDigits: 0 })}</td>
                                            <td className="px-6 py-4 whitespace-nowrap text-gray-400">{so.orderDate}</td>
                                            <td className="px-6 py-4 text-center" onClick={(e) => e.stopPropagation()}>
                                                <button className="text-gray-400 hover:text-gray-600 p-1">
                                                    <DotsVerticalIcon className="h-4 w-4" />
                                                </button>
                                            </td>
                                        </tr>
                                        {isExpanded && (
                                            <tr className="bg-gray-50">
                                                <td colSpan={8} className="px-4 py-8 sm:px-12">
                                                    <div className="bg-white border border-gray-200 rounded-xl p-6 shadow-sm space-y-8">

                                                        <div className="grid grid-cols-1 lg:grid-cols-3 gap-8 items-start">
                                                            <div>
                                                                <h4 className="text-xs font-bold text-gray-400 uppercase tracking-widest mb-4 flex items-center gap-2">
                                                                    <CalendarIcon className="h-4 w-4 text-blue-500" /> Fulfillment Ref
                                                                </h4>
                                                                <div className="grid grid-cols-2 gap-x-4 gap-y-3 p-4 bg-gray-50 rounded-lg border border-gray-100">
                                                                    <div>
                                                                        <p className="text-[10px] uppercase font-bold text-gray-400">PO Ref</p>
                                                                        <p className="text-xs font-bold text-partners-green truncate" title={so.poReference}>{so.poReference}</p>
                                                                    </div>
                                                                    <div>
                                                                        <p className="text-[10px] uppercase font-bold text-gray-400">PO Date</p>
                                                                        <p className="text-xs font-bold text-gray-700">{so.orderDate || 'N/A'}</p>
                                                                    </div>
                                                                    <div>
                                                                        <p className="text-[10px] uppercase font-bold text-gray-400">EE Status</p>
                                                                        <p className="text-xs font-bold text-cyan-600">{so.originalEeStatus || 'Processing'}</p>
                                                                    </div>
                                                                    <div>
                                                                        <p className="text-[10px] uppercase font-bold text-gray-400">Booked Date</p>
                                                                        <p className="text-xs font-bold text-gray-700">{so.bookedDate || 'N/A'}</p>
                                                                    </div>
                                                                    <div className="col-span-2 mt-1 pt-2 border-t border-gray-200">
                                                                        <p className="text-[10px] uppercase font-bold text-gray-400">PO PDF</p>
                                                                        {so.poPdfUrl ? (
                                                                            <a href={so.poPdfUrl} target="_blank" rel="noopener noreferrer" className="text-partners-green hover:underline flex items-center gap-1 text-xs font-bold mt-0.5">
                                                                                <PaperclipIcon className="h-3 w-3" /> View PO PDF
                                                                            </a>
                                                                        ) : (
                                                                            <p className="text-xs text-gray-300 font-bold italic mt-0.5">Not Uploaded</p>
                                                                        )}
                                                                    </div>
                                                                </div>
                                                            </div>

                                                            <div className="lg:col-span-1">
                                                                <h4 className="text-xs font-bold text-gray-400 uppercase tracking-widest mb-4 flex items-center gap-2">
                                                                    <InvoiceIcon className="h-4 w-4 text-partners-purple" /> Invoice Information
                                                                </h4>
                                                                <div className={`grid grid-cols-2 gap-x-4 gap-y-3 p-4 rounded-lg border min-h-[140px] transition-all ${isInvoiced || isShipped ? 'bg-purple-50 border-purple-100' : 'bg-gray-50 border-gray-200'}`}>
                                                                    {isInvoiced || isShipped ? (
                                                                        <>
                                                                            <div className="col-span-2">
                                                                                <p className="text-[10px] uppercase font-bold text-purple-400">Invoice ID</p>
                                                                                <p className="text-xs font-bold text-purple-700 font-mono truncate" title={so.invoiceId}>{so.invoiceId || 'N/A'}</p>
                                                                            </div>
                                                                            <div>
                                                                                <p className="text-[10px] uppercase font-bold text-purple-400">Invoice Number</p>
                                                                                <p className="text-xs font-bold text-purple-700">{so.invoiceNumber || 'N/A'}</p>
                                                                            </div>
                                                                            <div>
                                                                                <p className="text-[10px] uppercase font-bold text-purple-400">Status</p>
                                                                                <p className="text-xs font-bold text-purple-700">{so.invoiceStatus || 'N/A'}</p>
                                                                            </div>
                                                                            <div>
                                                                                <p className="text-[10px] uppercase font-bold text-purple-400">Total (Inc. Tax)</p>
                                                                                <p className="text-xs font-bold text-purple-700">₹{so.invoiceTotal?.toLocaleString('en-IN') || '0'}</p>
                                                                            </div>
                                                                            <div>
                                                                                <p className="text-[10px] uppercase font-bold text-purple-400">Link</p>
                                                                                {so.invoicePdfUrl ? (
                                                                                    <a href={so.invoicePdfUrl} target="_blank" rel="noopener noreferrer" className="text-blue-600 hover:underline flex items-center gap-1 text-xs font-bold">
                                                                                        View PDF <ExternalLinkIcon className="h-3 w-3" />
                                                                                    </a>
                                                                                ) : (
                                                                                    <p className="text-xs text-purple-300 font-bold italic">No URL</p>
                                                                                )}
                                                                            </div>
                                                                        </>
                                                                    ) : (
                                                                        <div className="col-span-2 flex flex-col items-center justify-center py-4 text-center">
                                                                            <InvoiceIcon className="h-8 w-8 text-purple-200 mb-2" />
                                                                            <p className="text-xs font-bold text-purple-400 uppercase">No Invoice Generated</p>

                                                                            {!canCreateInvoice ? (
                                                                                <div className="mt-4 px-3 py-1.5 bg-gray-100 text-gray-400 text-[10px] font-bold rounded-lg flex items-center gap-2 border border-gray-200">
                                                                                    <LockClosedIcon className="h-3 w-3" /> Awaiting EE Confirmation
                                                                                </div>
                                                                            ) : (
                                                                                <button 
                                                                                    onClick={() => handleCreateZohoInvoice(so.id)}
                                                                                    disabled={isCreatingInvoice === so.id}
                                                                                    className="mt-4 px-4 py-2 bg-purple-600 text-white text-[11px] font-bold rounded-lg shadow-sm hover:bg-purple-700 transition-all active:scale-95 flex items-center gap-2"
                                                                                >
                                                                                    {isCreatingInvoice === so.id ? <RefreshIcon className="h-3 w-3 animate-spin" /> : <PlusIcon className="h-3 w-3" />}
                                                                                    {isCreatingInvoice === so.id ? 'Processing...' : 'Create Zoho Invoice'}
                                                                                </button>
                                                                            )}
                                                                        </div>
                                                                    )}
                                                                </div>
                                                            </div>

                                                            <div>
                                                                <h4 className="text-xs font-bold text-gray-400 uppercase tracking-widest mb-4 flex items-center gap-2">
                                                                    <TruckIcon className="h-4 w-4 text-partners-green" /> Logistics Timeline (EE Ref: {so.id})
                                                                </h4>
                                                                <div className="flex px-4 pt-2">
                                                                    <TimelineStep label="Batch Created" date={so.batchCreatedAt} icon={<CubeIcon className="h-4 w-4" />} />
                                                                    <TimelineStep label="Invoiced" date={so.invoiceDate} icon={<InvoiceIcon className="h-4 w-4" />} />
                                                                    <TimelineStep label="Shipped" date={so.manifestDate} icon={<CheckCircleIcon className="h-4 w-4" />} isLast />
                                                                </div>
                                                            </div>
                                                        </div>

                                                        {/* Unified Shipping & Tracking Section */}
                                                        <div className="pt-6 border-t border-gray-100">
                                                            <div className="flex justify-between items-center mb-4">
                                                                <h4 className="text-xs font-bold text-gray-400 uppercase tracking-widest flex items-center gap-2">
                                                                    <GlobeIcon className="h-4 w-4 text-blue-600" /> Logistics & Shipment Status
                                                                </h4>
                                                                {canShipWithNimbus ? (
                                                                    <button 
                                                                        onClick={() => handlePushToNimbus(so.id)}
                                                                        disabled={isPushingNimbus === so.id}
                                                                        className="flex items-center gap-2 px-6 py-2 bg-blue-600 text-white text-[11px] font-bold rounded-lg shadow-md hover:bg-blue-700 transition-all active:scale-95"
                                                                    >
                                                                        {isPushingNimbus === so.id ? <RefreshIcon className="h-3 w-3 animate-spin" /> : <SendIcon className="h-3 w-3" />}
                                                                        {isPushingNimbus === so.id ? 'Pushing to Nimbus...' : 'Ship with Nimbus Post'}
                                                                    </button>
                                                                ) : isInvoiced && !so.awb && (
                                                                    <div className="flex items-center gap-2 px-4 py-2 bg-gray-100 text-gray-400 text-[10px] font-bold rounded-lg border border-gray-200">
                                                                        <LockClosedIcon className="h-3 w-3" /> Box Count Required (>0)
                                                                    </div>
                                                                )}
                                                            </div>

                                                            <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
                                                                {/* Box Count Indicator */}
                                                                <div className={`p-4 rounded-xl border transition-all ${so.boxCount > 0 ? 'bg-partners-light-green border-partners-green/20' : 'bg-red-50 border-red-100'}`}>
                                                                    <p className="text-[10px] font-bold text-gray-400 uppercase mb-2">Package Detail</p>
                                                                    <div className="flex items-center gap-2">
                                                                        <CubeIcon className={`h-5 w-5 ${so.boxCount > 0 ? 'text-partners-green' : 'text-red-400'}`} />
                                                                        <div>
                                                                            <p className="text-sm font-bold text-gray-800">Box Count</p>
                                                                            <p className={`text-lg font-black ${so.boxCount > 0 ? 'text-partners-green' : 'text-red-600'}`}>{so.boxCount || 0}</p>
                                                                        </div>
                                                                    </div>
                                                                </div>

                                                                {so.awb ? (
                                                                    <>
                                                                        <div className="p-4 bg-blue-50 rounded-xl border border-blue-100 col-span-1 md:col-span-1">
                                                                            <div className="flex flex-col h-full justify-between">
                                                                                <div>
                                                                                    <p className="text-[10px] font-bold text-blue-400 uppercase">Carrier & AWB</p>
                                                                                    <p className="text-sm font-bold text-gray-900 truncate">{so.carrier || 'Pending'}</p>
                                                                                    <p className="text-xs font-mono text-blue-600 font-bold tracking-wider">{so.awb}</p>
                                                                                </div>
                                                                                <span className={`mt-2 w-fit px-2 py-0.5 rounded text-[10px] font-bold border ${so.trackingStatus?.toLowerCase().includes('deliv') ? 'bg-green-100 text-green-700 border-green-200' : 'bg-blue-100 text-blue-700 border-blue-200'}`}>
                                                                                    {so.trackingStatus || 'In-Transit'}
                                                                                </span>
                                                                            </div>
                                                                        </div>

                                                                        <div className="p-4 bg-gray-50 rounded-xl border border-gray-100">
                                                                            <p className="text-[10px] font-bold text-gray-400 uppercase mb-2">Delivery SLA</p>
                                                                            <div className="space-y-3">
                                                                                <div>
                                                                                    <p className="text-[9px] font-bold text-gray-400">Exp Delivery Date</p>
                                                                                    <p className="text-sm font-bold text-partners-green">{so.edd || 'TBD'}</p>
                                                                                </div>
                                                                                <div>
                                                                                    <p className="text-[9px] font-bold text-gray-400">Delivered Date</p>
                                                                                    <p className="text-sm font-bold text-gray-800">{so.deliveredDate || '-'}</p>
                                                                                </div>
                                                                            </div>
                                                                        </div>

                                                                        <div className={`p-4 rounded-xl border ${so.rtoStatus ? 'bg-red-50 border-red-100' : 'bg-gray-50 border-gray-100'}`}>
                                                                            <p className="text-[10px] font-bold text-gray-400 uppercase mb-2">Return Status (RTO)</p>
                                                                            {so.rtoStatus ? (
                                                                                <div className="space-y-2">
                                                                                    <p className="text-xs font-bold text-red-600">{so.rtoStatus}</p>
                                                                                    <div>
                                                                                        <p className="text-[9px] font-bold text-gray-400">Return AWB</p>
                                                                                        <p className="text-xs font-mono font-bold text-red-600">{so.rtoAwb || 'N/A'}</p>
                                                                                    </div>
                                                                                </div>
                                                                            ) : (
                                                                                <div className="flex flex-col items-center justify-center py-2">
                                                                                    <CheckCircleIcon className="h-6 w-6 text-gray-200" />
                                                                                    <p className="text-[10px] font-bold text-gray-400 mt-1 uppercase">No Returns</p>
                                                                                </div>
                                                                            )}
                                                                        </div>
                                                                    </>
                                                                ) : (
                                                                    <div className="md:col-span-3 p-12 border-2 border-dashed border-gray-100 rounded-2xl flex flex-col items-center justify-center text-center">
                                                                        {!isInvoiced ? (
