const parseDate = (dateStr: string): number => {
    try {
        if (!dateStr) return 0;
        const parts = dateStr.match(/(\d+)\s+(\w+)\s+(\d+)/);
        if (parts && parts.length === 4) {
            const day = parts[1];
            const month = parts[2];
            let year = parts[3];
            if (year.length === 2) year = '20' + year;
            return new Date(`${day} ${month} ${year}`).getTime();
        }
        return new Date(dateStr).getTime() || 0;
    } catch (e) { return 0; }
};

const SalesOrderTable: React.FC<SalesOrderTableProps> = ({ activeFilter, setActiveFilter, purchaseOrders, onSync, isSyncing, addLog, addNotification }) => {
    const [expandedRowId, setExpandedRowId] = useState<string | null>(null);
    const [isCreatingInvoice, setIsCreatingInvoice] = useState<string | null>(null);
    const [isPushingNimbus, setIsPushingNimbus] = useState<string | null>(null);
    const [blinkitModal, setBlinkitModal] = useState<{ isOpen: boolean, so: GroupedSalesOrder | null }>({ isOpen: false, so: null });

    // Filtering states
    const [columnFilters, setColumnFilters] = useState<{ [key: string]: string }>({});
    const [activeFilterColumn, setActiveFilterColumn] = useState<string | null>(null);
    const filterMenuRef = useRef<HTMLDivElement>(null);

    const tabs = [
        { name: 'All POs' }, { name: 'In-Transit' }, { name: 'GRN Pending' }, { name: 'GRN Updated' }, { name: 'RTO' }, { name: 'Closed' },
    ];

    const salesOrders = useMemo(() => {
        const groups: Record<string, GroupedSalesOrder> = {};
        purchaseOrders.forEach(po => {
            (po.items || []).forEach(item => {
                const rawRef = item.eeReferenceCode;
                if (!rawRef || String(rawRef).trim() === "") return;
                const refCode = String(rawRef).trim();
                const effectiveQty = (item.itemQuantity !== undefined && item.itemQuantity !== 0) ? item.itemQuantity : item.qty;
                const effectiveLineAmount = effectiveQty * (item.unitCost || 0);
                const batchDate = item.eeBatchCreatedAt || po.eeBatchCreatedAt;
                const invNum = item.invoiceNumber;
                const maniDate = item.eeManifestDate || po.eeManifestDate;
                const eeStatus = (item.eeOrderStatus || po.eeOrderStatus || 'Processing').trim();

                let displayStatus = eeStatus;
                if (maniDate) displayStatus = 'Shipped';
                else if (invNum) displayStatus = 'Invoiced';
                else if (batchDate) displayStatus = 'Batch Created';
                else if (eeStatus.toLowerCase() === 'confirmed') displayStatus = 'Confirmed';

                if (!groups[refCode]) {
                    groups[refCode] = { id: refCode, poReference: String(po.poNumber || ''), status: displayStatus, originalEeStatus: eeStatus, channel: po.channel, storeCode: po.storeCode, orderDate: po.orderDate, poEdd: po.poEdd, poExpiryDate: po.poExpiryDate, poPdfUrl: po.poPdfUrl, qty: 0, amount: 0, items: [], batchCreatedAt: batchDate, invoiceDate: item.invoiceDate, manifestDate: maniDate, invoiceId: item.invoiceId, invoiceStatus: item.invoiceStatus, invoiceNumber: invNum, invoiceTotal: item.invoiceTotal, invoiceUrl: item.invoiceUrl, invoicePdfUrl: item.invoicePdfUrl, carrier: po.carrier, awb: po.awb, bookedDate: po.bookedDate, trackingStatus: po.trackingStatus, edd: po.edd, latestStatus: po.latestStatus, latestStatusDate: po.latestStatusDate, currentLocation: po.currentLocation, deliveredDate: po.deliveredDate, rtoStatus: po.rtoStatus, rtoAwb: po.rtoAwb, boxCount: po.boxes || 0 };
                } else {
                    const curPo = String(po.poNumber || '');
                    if (!groups[refCode].poReference.includes(curPo)) groups[refCode].poReference += `, ${curPo}`;
                    const statusRank = (s: string) => { if (s === 'Shipped') return 5; if (s === 'Invoiced') return 4; if (s === 'Batch Created') return 3; if (s === 'Confirmed') return 2; return 1; };
                    if (statusRank(displayStatus) > statusRank(groups[refCode].status)) groups[refCode].status = displayStatus;
                    if (!groups[refCode].batchCreatedAt) groups[refCode].batchCreatedAt = batchDate;
                    if (!groups[refCode].invoiceDate) groups[refCode].invoiceDate = item.invoiceDate;
                    if (!groups[refCode].manifestDate) groups[refCode].manifestDate = maniDate;
                    if (!groups[refCode].invoiceId) groups[refCode].invoiceId = item.invoiceId;
                    if (!groups[refCode].invoiceStatus) groups[refCode].invoiceStatus = item.invoiceStatus;
                    if (!groups[refCode].invoiceNumber) groups[refCode].invoiceNumber = invNum;
                    if (!groups[refCode].invoiceTotal) groups[refCode].invoiceTotal = item.invoiceTotal;
                    if (!groups[refCode].invoiceUrl) groups[refCode].invoiceUrl = item.invoiceUrl;
                    if (!groups[refCode].invoicePdfUrl) groups[refCode].invoicePdfUrl = item.invoicePdfUrl;
                    if (!groups[refCode].poPdfUrl) groups[refCode].poPdfUrl = po.poPdfUrl;
                    groups[refCode].boxCount = Math.max(groups[refCode].boxCount, po.boxes || 0);
                }
                groups[refCode].items.push(item);
                groups[refCode].qty += effectiveQty;
                groups[refCode].amount += effectiveLineAmount;
            });
        });

        let results = Object.values(groups);
        if (activeFilter !== 'All POs') {
             results = results.filter(so => {
                 const status = so.status.toLowerCase();
                 if (activeFilter === 'In-Transit') return status.includes('transit') || status.includes('shipped') || status.includes('manifest') || status.includes('batch') || status.includes('invoiced');
                 if (activeFilter === 'Closed') return status.includes('closed') || status.includes('delivered');
                 if (activeFilter === 'RTO') return status.includes('rto');
                 return true;
             });
        }

        // Apply header filters
        Object.keys(columnFilters).forEach(key => {
            const val = columnFilters[key].toLowerCase();
            if (!val) return;
            results = results.filter(so => String((so as any)[key] || '').toLowerCase().includes(val));
        });

        // Apply Descending Date Sort
        results.sort((a, b) => parseDate(b.orderDate) - parseDate(a.orderDate));
        return results;
    }, [purchaseOrders, activeFilter, columnFilters]);

    useEffect(() => {
        const handleClickOutside = (event: MouseEvent) => {
            if (filterMenuRef.current && !filterMenuRef.current.contains(event.target as Node)) {
                setActiveFilterColumn(null);
            }
        };
        document.addEventListener('mousedown', handleClickOutside);
        return () => document.removeEventListener('mousedown', handleClickOutside);
    }, []);

    const toggleRowExpansion = (soId: string) => setExpandedRowId(expandedRowId === soId ? null : soId);

    const handleCreateZohoInvoice = async (eeRef: string) => {
        setIsCreatingInvoice(eeRef);
        try {
            const res = await createZohoInvoice(eeRef);
            if (res.status === 'success') { addNotification(res.message || 'Invoice triggered.', 'success'); addLog('Invoice Creation', `EE Ref: ${eeRef}`); onSync(); }
            else { addNotification('Error: ' + res.message, 'error'); }
        } catch (e) { addNotification('Network error.', 'error'); }
        finally { setIsCreatingInvoice(null); }
    };

    const handlePushToNimbus = async (eeRef: string) => {
        setIsPushingNimbus(eeRef);
        try {
            const res = await pushToNimbusPost(eeRef);
            if (res.status === 'success') { addNotification(res.message || 'Pushed to Nimbus.', 'success'); addLog('Nimbus Shipping', `EE Ref: ${eeRef}`); onSync(); }
            else { addNotification('Shipping Error: ' + res.message, 'error'); }
        } catch (e) { addNotification('Network error.', 'error'); }
        finally { setIsPushingNimbus(null); }
    };

    const TimelineStep = ({ label, date, icon, isLast = false }: { label: string, date?: string, icon: React.ReactNode, isLast?: boolean }) => {
        const isActive = !!date;
        return (
            <div className="flex items-center flex-1 last:flex-none">
                <div className="flex flex-col items-center">
                    <div className={`flex items-center justify-center w-8 h-8 rounded-full border-2 transition-colors ${isActive ? 'bg-partners-green border-partners-green text-white shadow-sm' : 'bg-white border-gray-200 text-gray-300'}`}>{icon}</div>
                    <div className="mt-2 text-center"><p className={`text-[10px] font-bold uppercase tracking-wider ${isActive ? 'text-gray-800' : 'text-gray-400'}`}>{label}</p><p className="text-[11px] font-medium text-gray-500 whitespace-nowrap mt-0.5">{date || 'Pending'}</p></div>
                </div>
                {!isLast && <div className={`h-0.5 flex-1 mx-4 -mt-6 transition-colors ${isActive ? 'bg-partners-green' : 'bg-gray-200'}`}></div>}
            </div>
        );
    };

    const uniqueChannels = useMemo(() => Array.from(new Set(salesOrders.map(s => s.channel))), [salesOrders]);

    const getPrimaryAction = (so: GroupedSalesOrder) => {
        if (so.status === 'Confirmed' || so.status === 'Batch Created') return { label: 'Create Invoice', color: 'bg-purple-600 text-white hover:bg-purple-700', onClick: () => handleCreateZohoInvoice(so.id) };
        if (so.status === 'Invoiced' && !so.awb) return { label: 'Ship Nimbus', color: 'bg-blue-600 text-white hover:bg-blue-700', onClick: () => handlePushToNimbus(so.id) };
        if (so.awb) return { label: 'Track Order', color: 'bg-partners-green text-white hover:bg-green-700', onClick: () => toggleRowExpansion(so.id) };
        return { label: 'Details', color: 'bg-gray-50 text-gray-700 border border-gray-200 hover:bg-gray-100', onClick: () => toggleRowExpansion(so.id) };
    };

    return (
        <div className="bg-white p-6 rounded-xl shadow-sm">
            {blinkitModal.isOpen && blinkitModal.so && <BlinkitAppointmentModal so={blinkitModal.so} onClose={() => setBlinkitModal({ isOpen: false, so: null })} />}
            <div className="flex flex-col md:flex-row justify-between items-center gap-4 mb-6">
                <div className="flex flex-wrap items-center gap-2">
                    {tabs.map(tab => (
                        <button key={tab.name} onClick={() => setActiveFilter(tab.name)} className={`px-3 py-1.5 text-sm font-semibold rounded-full border transition-colors ${activeFilter === tab.name ? 'bg-partners-green text-white border-partners-green' : 'bg-white text-gray-600 border-partners-border hover:bg-gray-50'}`}>{tab.name}</button>
                    ))}
                </div>
                <button onClick={onSync} disabled={isSyncing} className="flex items-center gap-2 px-3 py-2 text-sm font-medium text-white bg-blue-600 rounded-lg"><CloudDownloadIcon className={`h-4 w-4 ${isSyncing ? 'animate-bounce' : ''}`} /> Sync Data</button>
            </div>

            <div className="mt-6 overflow-x-auto border border-gray-100 rounded-xl shadow-inner max-h-[70vh]">
                <table className="w-full text-sm text-left text-gray-600 border-collapse">
                    <thead className="text-xs text-gray-700 uppercase bg-gray-50 sticky top-0 z-20">
                        <tr>
                            <th className="p-4 w-4 sticky left-0 bg-gray-50 z-30 border-r border-gray-100"></th>
                            <th className="px-6 py-3 text-blue-600 sticky left-12 bg-gray-50 z-30 border-r border-gray-100 min-w-[150px]">
