const EmailAppointmentModal: FC<AppointmentModalProps> = ({ po, poc, onClose, onSuccess, addLog, addNotification }) => {
    const [boxes, setBoxes] = useState(po.boxes || 1);
    const [isLoading, setIsLoading] = useState(false);

    const handleSend = async () => {
        if (!poc?.pocEmail) {
            alert("No POC Email found for this store. Please check Store_POC_Mapping.");
            return;
        }
        setIsLoading(true);
        try {
            const res = await sendAppointmentEmail(po, boxes, poc.pocEmail);
            if (res.status === 'success') {
                addLog('Email Sent', `Appointment request sent to ${poc.pocEmail} for PO ${po.poNumber}`);
                addNotification(`Email sent to ${poc.pocName} (${poc.pocEmail})`, 'success');
                onSuccess();
                onClose();
            } else {
                alert("Failed to send email: " + res.message);
            }
        } catch (e) {
            alert("Network error sending email");
        } finally {
            setIsLoading(false);
        }
    };

    return (
        <div className="fixed inset-0 bg-black/50 backdrop-blur-sm flex items-center justify-center z-50 p-4">
            <div className="bg-white rounded-2xl shadow-2xl w-full max-w-2xl overflow-hidden border border-gray-100">
                <div className="p-6 border-b border-gray-100 flex justify-between items-center">
                    <div><h3 className="text-xl font-bold text-gray-800">Email Appointment Request</h3><p className="text-sm text-gray-500">To: <span className="font-bold text-partners-green">{poc?.pocName || 'Unknown'} ({poc?.pocEmail || 'Missing Email'})</span></p></div>
                    <button onClick={onClose} className="p-2 hover:bg-gray-100 rounded-full transition-colors"><XCircleIcon className="h-6 w-6 text-gray-400"/></button>
                </div>
                <div className="p-6 space-y-6">
                    <div className="grid grid-cols-2 gap-4 bg-gray-50 p-4 rounded-xl border border-gray-100 text-sm">
                        <div><p className="text-[10px] font-bold text-gray-400 uppercase">PO Number</p><p className="font-bold text-gray-800">{po.poNumber}</p></div>
                        <div><p className="text-[10px] font-bold text-gray-400 uppercase">Store Code</p><p className="font-bold text-gray-800">{po.storeCode}</p></div>
                        <div><p className="text-[10px] font-bold text-gray-400 uppercase">Total Qty</p><p className="font-bold text-gray-800">{po.qty} Units</p></div>
                        <div><p className="text-[10px] font-bold text-gray-400 uppercase">Dispatch Date</p><p className="font-bold text-gray-800">{po.dispatchDate || po.eeManifestDate || 'N/A'}</p></div>
                    </div>
                    <div><label className="block text-xs font-bold text-gray-500 uppercase tracking-wider mb-2">Number of Boxes / Cartons</label><input type="number" className={inputClassName} value={boxes} onChange={e => setBoxes(Number(e.target.value))} placeholder="Enter physical box count"/></div>
                </div>
                <div className="p-4 bg-gray-50 border-t border-gray-100 flex justify-end gap-3">
                    <button onClick={onClose} className="px-6 py-2.5 text-sm font-bold text-gray-500 bg-white border border-gray-300 rounded-xl hover:bg-gray-100 transition-colors">Cancel</button>
                    <button onClick={handleSend} disabled={isLoading} className="px-8 py-2.5 text-sm font-bold text-white bg-blue-600 rounded-xl hover:bg-blue-700 transition-all flex items-center gap-2 shadow-lg shadow-blue-100 disabled:opacity-50">{isLoading ? <RefreshIcon className="h-4 w-4 animate-spin"/> : <MailIcon className="h-4 w-4"/>}{isLoading ? 'Sending...' : 'Send Email Request'}</button>
                </div>
            </div>
        </div>
    );
};

const AppointmentManager: React.FC<{ purchaseOrders: PurchaseOrder[], setPurchaseOrders: any, addLog: any, addNotification: any }> = ({ purchaseOrders, setPurchaseOrders, addLog, addNotification }) => {
    const [pocMappings, setPocMappings] = useState<StorePocMapping[]>([]);
    const [isLoading, setIsLoading] = useState(false);
    const [emailModal, setEmailModal] = useState<{ isOpen: boolean, po?: PurchaseOrder, poc?: StorePocMapping }>({ isOpen: false });
    const [blinkitModal, setBlinkitModal] = useState<{ isOpen: boolean, po?: PurchaseOrder }>({ isOpen: false });

    useEffect(() => {
        const loadPocs = async () => {
            setIsLoading(true);
            const data = await fetchStorePocMappings();
            setPocMappings(data);
            setIsLoading(false);
        };
        loadPocs();
    }, []);

    const relevantOrders = useMemo(() => {
        return purchaseOrders.filter(po => {
            const hasEeRef = (po.items || []).some(i => !!i.eeReferenceCode);
            const channel = po.channel.toLowerCase();
            if (channel.includes('blinkit')) return !!po.awb && !po.appointmentDate;
            return (po.status === POStatus.InTransit || hasEeRef) && !po.appointmentDate;
        }).sort((a, b) => new Date(b.orderDate).getTime() - new Date(a.orderDate).getTime());
    }, [purchaseOrders]);

    const getPoc = (channel: string, storeCode: string) => {
        return pocMappings.find(m => m.channel === channel && m.storeCode === storeCode);
    };

    const handleConfirmAppointment = (po: PurchaseOrder) => {
        const date = prompt("Enter Appointment Date (e.g. 15 Oct 24):");
        const id = prompt("Enter Appointment ID / ASN:");
        if (date && id) {
            setPurchaseOrders((prev: PurchaseOrder[]) => prev.map(p => 
                p.id === po.id ? { ...p, appointmentDate: date, appointmentId: id, actionToBeTaken: 'Awaiting Delivery' } : p
            ));
            addLog('Appointment Confirmed', `Recorded appointment ${id} for PO ${po.poNumber}`);
            addNotification(`Appointment recorded for ${po.poNumber}`, 'success');
        }
    };

    return (
        <>
            {emailModal.isOpen && emailModal.po && (
                <EmailAppointmentModal 
                    po={emailModal.po} 
                    poc={emailModal.poc}
                    onClose={() => setEmailModal({ isOpen: false })}
                    onSuccess={() => {
                        setPurchaseOrders((prev: PurchaseOrder[]) => prev.map(p => 
                            p.id === emailModal.po!.id ? { ...p, appointmentRequestDate: new Date().toLocaleDateString('en-GB') } : p
                        ));
                    }}
                    addLog={addLog}
                    addNotification={addNotification}
                />
            )}

            {blinkitModal.isOpen && blinkitModal.po && (
                <BlinkitAppointmentModal 
                    po={blinkitModal.po}
                    onClose={() => setBlinkitModal({ isOpen: false })}
                />
            )}

            <div className="p-4 sm:p-6 lg:p-8 flex-1 space-y-6">
                <div className="bg-white rounded-2xl shadow-sm border border-gray-100 overflow-hidden">
                    <div className="p-6 border-b border-gray-50 flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
                        <div>
                            <h2 className="text-xl font-bold text-gray-800">Warehouse Appointment Queue</h2>
                            <p className="text-sm text-gray-500 mt-1">Manage delivery slots and scheduling for dispatched purchase orders.</p>
                        </div>
                        <div className="flex items-center gap-3">
                            <div className="flex items-center gap-2 bg-blue-50 px-3 py-2 rounded-xl border border-blue-100 text-[11px] font-bold text-blue-700">
                                <InfoIcon className="h-4 w-4" /> Blinkit portal automation ready
                            </div>
                            <button onClick={() => window.location.reload()} className="p-2 text-gray-400 hover:text-partners-green hover:bg-gray-50 rounded-lg transition-all"><RefreshIcon className="h-5 w-5" /></button>
                        </div>
                    </div>

                    <div className="overflow-x-auto">
                        <table className="w-full text-sm text-left text-gray-600 border-collapse">
                            <thead className="bg-gray-50/80 text-[11px] text-gray-500 uppercase tracking-wider font-bold">
                                <tr>
                                    <th className="px-6 py-4">PO Number & Date</th>
                                    <th className="px-6 py-4">Store & Channel</th>
                                    <th className="px-6 py-4">Units / Amount</th>
                                    <th className="px-6 py-4">Logistics Ref</th>
                                    <th className="px-6 py-4">Current Status</th>
                                    <th className="px-6 py-4 text-center">Action</th>
                                </tr>
                            </thead>
                            <tbody className="divide-y divide-gray-100">
                                {relevantOrders.length === 0 ? (
                                    <tr>
                                        <td colSpan={6} className="px-6 py-16 text-center">
                                            <div className="flex flex-col items-center">
                                                <div className="w-16 h-16 bg-gray-50 rounded-full flex items-center justify-center mb-4"><CalendarIcon className="h-8 w-8 text-gray-200" /></div>
                                                <h3 className="text-gray-800 font-bold">No Pending Appointments</h3>
                                                <p className="text-gray-400 text-xs mt-1">Orders will appear here once they are dispatched or pushed.</p>
                                            </div>
                                        </td>
                                    </tr>
                                ) : (
                                    relevantOrders.map(po => {
                                        const isBlinkit = po.channel.toLowerCase().includes('blinkit');
                                        const amountWithTax = (po.amount * 1.05).toLocaleString('en-IN', { maximumFractionDigits: 0 });

                                        return (
                                            <tr key={po.id} className="bg-white hover:bg-partners-light-green/20 transition-colors group">
                                                <td className="px-6 py-5">
                                                    <div className="flex flex-col">
                                                        <span className="font-bold text-gray-900 group-hover:text-partners-green transition-colors">{po.poNumber}</span>
                                                        <span className="text-[10px] text-gray-400 mt-1 flex items-center gap-1 font-medium"><CalendarIcon className="h-3 w-3" /> {po.orderDate}</span>
                                                    </div>
                                                </td>
                                                <td className="px-6 py-5">
                                                    <div className="flex flex-col">
                                                        <span className="font-semibold text-gray-800 text-xs">{po.channel}</span>
                                                        <div className="flex items-center gap-1.5 mt-1">
                                                            <div className="w-1.5 h-1.5 rounded-full bg-partners-green"></div>
                                                            <span className="text-[11px] font-bold text-gray-500 uppercase tracking-tighter">{po.storeCode}</span>
                                                        </div>
                                                    </div>
                                                </td>
                                                <td className="px-6 py-5">
                                                    <div className="flex flex-col">
                                                        <span className="text-gray-900 font-bold">{po.qty} <span className="text-[10px] font-medium text-gray-400">Units</span></span>
                                                        <span className="text-[11px] text-gray-500 font-bold mt-0.5">₹{amountWithTax}</span>
                                                    </div>
                                                </td>
                                                <td className="px-6 py-5">
                                                    <div className="text-[11px]">
                                                        <p className="font-bold text-gray-700 flex items-center gap-1"><TruckIcon className="h-3.5 w-3.5 text-blue-500" /> {po.carrier || 'Pending'}</p>
                                                        <p className="text-gray-400 font-mono mt-1 select-all">{po.awb || 'No AWB Assigned'}</p>
                                                    </div>
                                                </td>
                                                <td className="px-6 py-5">
                                                    <span className={`px-2.5 py-1 rounded-lg text-[10px] font-bold uppercase tracking-tight border ${
                                                        po.status === POStatus.InTransit 
                                                            ? 'bg-blue-50 text-blue-700 border-blue-100' 
                                                            : 'bg-orange-50 text-orange-700 border-orange-100'
                                                    }`}>
                                                        {po.status === POStatus.InTransit ? 'In-Transit' : 'Processing'}
                                                    </span>
                                                </td>
                                                <td className="px-6 py-5 text-center">
                                                    <div className="flex flex-col gap-2">
                                                        {isBlinkit ? (
                                                            <button 
                                                                onClick={() => setBlinkitModal({ isOpen: true, po })}
                                                                className="inline-flex items-center justify-center gap-2 px-4 py-2 bg-partners-green text-white text-[11px] font-bold rounded-xl shadow-md shadow-green-50 hover:bg-green-600 transition-all active:scale-95"
                                                            >
                                                                <ExternalLinkIcon className="h-3.5 w-3.5" /> Take Appointment
                                                            </button>
                                                        ) : (
                                                            <button 
                                                                onClick={() => setEmailModal({ isOpen: true, po, poc: getPoc(po.channel, po.storeCode) })}
                                                                className="inline-flex items-center justify-center gap-2 px-4 py-2 bg-blue-600 text-white text-[11px] font-bold rounded-xl shadow-md shadow-blue-50 hover:bg-blue-700 transition-all active:scale-95"
                                                            >
                                                                <MailIcon className="h-3.5 w-3.5" /> Send Booking Mail
                                                            </button>
                                                        )}
                                                        <button 
                                                            onClick={() => handleConfirmAppointment(po)}
                                                            className="text-[10px] font-bold text-gray-400 hover:text-partners-green transition-colors uppercase tracking-widest flex items-center justify-center gap-1"
                                                        >
                                                            <CheckCircleIcon className="h-3 w-3" /> Appointment Taken
                                                        </button>
                                                    </div>
                                                </td>
                                            </tr>
                                        );
                                    })
                                )}
                            </tbody>
                        </table>
                    </div>

                    <div className="px-6 py-4 bg-gray-50 border-t border-gray-100 text-[10px] text-gray-400 font-bold uppercase tracking-[0.2em] flex justify-between items-center">
                        <span>Queue Management System v2.1</span>
