const EmailAppointmentModal: FC<AppointmentModalProps> = ({ po, poc, onClose, onSuccess, addLog, addNotification }) => {
    const [boxes, setBoxes] = useState(po.boxes || 1);
    const [isLoading, setIsLoading] = useState(false);

    const handleSend = async () => {
        if (!poc?.pocEmail) {
            alert("No POC Email found for this store. Please check Store_POC_Mapping.");
            return;
        }
        setIsLoading(true);
        try {
            const res = await sendAppointmentEmail(po, boxes, poc.pocEmail);
            if (res.status === 'success') {
                addLog('Email Sent', `Appointment request sent to ${poc.pocEmail} for PO ${po.poNumber}`);
                addNotification(`Email sent to ${poc.pocName} (${poc.pocEmail})`, 'success');
                onSuccess();
                onClose();
            } else {
                alert("Failed to send email: " + res.message);
            }
        } catch (e) {
            alert("Network error sending email");
        } finally {
            setIsLoading(false);
        }
    };

    return (
        <div className="fixed inset-0 bg-black/50 backdrop-blur-sm flex items-center justify-center z-50 p-4">
            <div className="bg-white rounded-2xl shadow-2xl w-full max-w-2xl overflow-hidden border border-gray-100">
                <div className="p-6 border-b border-gray-100 flex justify-between items-center">
                    <div><h3 className="text-xl font-bold text-gray-800">Email Appointment Request</h3><p className="text-sm text-gray-500">To: <span className="font-bold text-partners-green">{poc?.pocName || 'Unknown'} ({poc?.pocEmail || 'Missing Email'})</span></p></div>
                    <button onClick={onClose} className="p-2 hover:bg-gray-100 rounded-full transition-colors"><XCircleIcon className="h-6 w-6 text-gray-400"/></button>
                </div>
                <div className="p-6 space-y-6">
                    <div className="grid grid-cols-2 gap-4 bg-gray-50 p-4 rounded-xl border border-gray-100 text-sm">
                        <div><p className="text-[10px] font-bold text-gray-400 uppercase">PO Number</p><p className="font-bold text-gray-800">{po.poNumber}</p></div>
                        <div><p className="text-[10px] font-bold text-gray-400 uppercase">Store Code</p><p className="font-bold text-gray-800">{po.storeCode}</p></div>
                        <div><p className="text-[10px] font-bold text-gray-400 uppercase">Total Qty</p><p className="font-bold text-gray-800">{po.qty} Units</p></div>
                        <div><p className="text-[10px] font-bold text-gray-400 uppercase">Dispatch Date</p><p className="font-bold text-gray-800">{po.dispatchDate || po.eeManifestDate || 'N/A'}</p></div>
                    </div>
                    <div><label className="block text-xs font-bold text-gray-500 uppercase tracking-wider mb-2">Number of Boxes / Cartons</label><input type="number" className={inputClassName} value={boxes} onChange={e => setBoxes(Number(e.target.value))} placeholder="Enter physical box count"/></div>
                </div>
                <div className="p-4 bg-gray-50 border-t border-gray-100 flex justify-end gap-3">
                    <button onClick={onClose} className="px-6 py-2.5 text-sm font-bold text-gray-500 bg-white border border-gray-300 rounded-xl hover:bg-gray-100 transition-colors">Cancel</button>
                    <button onClick={handleSend} disabled={isLoading} className="px-8 py-2.5 text-sm font-bold text-white bg-blue-600 rounded-xl hover:bg-blue-700 transition-all flex items-center gap-2 shadow-lg shadow-blue-100 disabled:opacity-50">{isLoading ? <RefreshIcon className="h-4 w-4 animate-spin"/> : <MailIcon className="h-4 w-4"/>}{isLoading ? 'Sending...' : 'Send Email Request'}</button>
                </div>
            </div>
        </div>
    );
};

const AppointmentManager: React.FC<{ purchaseOrders: PurchaseOrder[], setPurchaseOrders: any, addLog: any, addNotification: any }> = ({ purchaseOrders, setPurchaseOrders, addLog, addNotification }) => {
    const [pocMappings, setPocMappings] = useState<StorePocMapping[]>([]);
    const [isLoading, setIsLoading] = useState(false);
    const [emailModal, setEmailModal] = useState<{ isOpen: boolean, po?: PurchaseOrder, poc?: StorePocMapping }>({ isOpen: false });
    const [blinkitModal, setBlinkitModal] = useState<{ isOpen: boolean, po?: PurchaseOrder }>({ isOpen: false });
    const [activeTab, setActiveTab] = useState<'toBeScheduled' | 'open' | 'invoicePending' | 'serviced' | 'cancelled'>('toBeScheduled');

    useEffect(() => {
        const loadPocs = async () => {
            setIsLoading(true);
            const data = await fetchStorePocMappings();
            setPocMappings(data);
            setIsLoading(false);
        };
        loadPocs();
    }, []);

    // Core Logic: If logistics (AWB) or appointment exists, it's already taken.
    const getIsAppointmentTaken = (po: PurchaseOrder) => {
        return !!po.awb || !!po.carrier || !!po.appointmentDate;
    };

    const statistics = useMemo(() => {
        const toBeScheduled = purchaseOrders.filter(po => 
            !getIsAppointmentTaken(po) && 
            (po.status === POStatus.Pushed || po.status === POStatus.PartiallyProcessed || po.status === POStatus.InTransit)
        ).length;

        const openAppointments = purchaseOrders.filter(po => 
            getIsAppointmentTaken(po) && 
            po.status !== POStatus.Delivered && 
            po.status !== POStatus.Closed && 
            po.status !== POStatus.Cancelled
        ).length;

        const invoicePending = purchaseOrders.filter(po => 
            !po.poPdfUrl && 
            po.status !== POStatus.Cancelled
        ).length;

        const fulfilled = purchaseOrders.filter(po => 
            po.status === POStatus.Delivered || po.status === POStatus.Closed
        ).length;

        const cancelled = purchaseOrders.filter(po => 
            po.status === POStatus.Cancelled
        ).length;

        return { toBeScheduled, openAppointments, invoicePending, fulfilled, cancelled, totalServiced: fulfilled + 15 }; // 15 is mock no-show from image
    }, [purchaseOrders]);

    const tableOrders = useMemo(() => {
        let filtered = purchaseOrders;

        switch (activeTab) {
            case 'toBeScheduled':
                filtered = purchaseOrders.filter(po => !getIsAppointmentTaken(po) && (po.status === POStatus.Pushed || po.status === POStatus.PartiallyProcessed || po.status === POStatus.InTransit));
                break;
            case 'open':
                filtered = purchaseOrders.filter(po => getIsAppointmentTaken(po) && po.status !== POStatus.Delivered && po.status !== POStatus.Closed && po.status !== POStatus.Cancelled);
                break;
            case 'invoicePending':
                filtered = purchaseOrders.filter(po => !po.poPdfUrl && po.status !== POStatus.Cancelled);
                break;
            case 'serviced':
                filtered = purchaseOrders.filter(po => po.status === POStatus.Delivered || po.status === POStatus.Closed);
                break;
            case 'cancelled':
                filtered = purchaseOrders.filter(po => po.status === POStatus.Cancelled);
                break;
        }

        return filtered.sort((a, b) => new Date(b.orderDate).getTime() - new Date(a.orderDate).getTime());
    }, [purchaseOrders, activeTab]);

    const getPoc = (channel: string, storeCode: string) => {
        return pocMappings.find(m => m.channel === channel && m.storeCode === storeCode);
    };

    const handleSchedule = (po: PurchaseOrder) => {
        const isBlinkit = po.channel.toLowerCase().includes('blinkit');
        if (isBlinkit) {
            setBlinkitModal({ isOpen: true, po });
        } else {
            setEmailModal({ isOpen: true, po, poc: getPoc(po.channel, po.storeCode) });
        }
    };

    return (
        <>
            {emailModal.isOpen && emailModal.po && (
                <EmailAppointmentModal 
                    po={emailModal.po} 
                    poc={emailModal.poc}
                    onClose={() => setEmailModal({ isOpen: false })}
                    onSuccess={() => {
                        setPurchaseOrders((prev: PurchaseOrder[]) => prev.map(p => 
                            p.id === emailModal.po!.id ? { ...p, appointmentRequestDate: new Date().toLocaleDateString('en-GB') } : p
                        ));
                    }}
                    addLog={addLog}
                    addNotification={addNotification}
                />
            )}

            {blinkitModal.isOpen && blinkitModal.po && (
                <BlinkitAppointmentModal 
                    po={blinkitModal.po}
                    onClose={() => setBlinkitModal({ isOpen: false })}
                />
            )}

            <div className="p-4 sm:p-6 lg:p-8 flex-1 space-y-6 bg-[#F8F9FA]">
                <h1 className="text-2xl font-bold text-gray-800">PO Appointments</h1>

                {/* Top Summary Cards */}
                <div className="grid grid-cols-1 md:grid-cols-5 gap-0 rounded-xl overflow-hidden border border-gray-200 shadow-sm bg-white">
                    {/* Card 1: To be Scheduled */}
                    <div 
                        onClick={() => setActiveTab('toBeScheduled')}
                        className={`p-4 border-r border-gray-100 cursor-pointer transition-colors ${activeTab === 'toBeScheduled' ? 'bg-[#E9F7EF]' : 'hover:bg-gray-50'}`}
                    >
                        <div className="flex items-baseline gap-2">
                            <span className="text-2xl font-bold text-gray-900">{statistics.toBeScheduled}</span>
                            <span className="text-xs font-medium text-gray-600">POs to be Scheduled</span>
                        </div>
                        <div className="mt-6 flex justify-between">
                            <div><p className="text-[10px] text-gray-500">Expiring tomorrow</p><p className="text-lg font-bold text-gray-800">0</p></div>
                            <div><p className="text-[10px] text-gray-500">This week</p><p className="text-lg font-bold text-gray-800">0</p></div>
                        </div>
                    </div>
                    {/* Card 2: Open Appointments */}
                    <div 
                        onClick={() => setActiveTab('open')}
                        className={`p-4 border-r border-gray-100 cursor-pointer transition-colors ${activeTab === 'open' ? 'bg-[#EBF5FB]' : 'hover:bg-gray-50'}`}
                    >
                        <div className="flex items-baseline gap-2">
                            <span className="text-2xl font-bold text-gray-900">{statistics.openAppointments}</span>
                            <span className="text-xs font-medium text-gray-600">Open Appointments</span>
                        </div>
                        <div className="mt-6 flex justify-between">
                            <div><p className="text-[10px] text-gray-500">Due Tomorrow</p><p className="text-lg font-bold text-gray-800">0</p></div>
                            <div><p className="text-[10px] text-gray-500">Due this week</p><p className="text-lg font-bold text-gray-800">0</p></div>
                        </div>
                    </div>
                    {/* Card 3: Invoice Pending */}
                    <div 
                        onClick={() => setActiveTab('invoicePending')}
                        className={`p-4 border-r border-gray-100 cursor-pointer transition-colors ${activeTab === 'invoicePending' ? 'bg-yellow-50' : 'hover:bg-gray-50'}`}
                    >
                        <p className="text-[10px] text-gray-500 leading-tight">PO's with invoice upload pending</p>
                        <p className="text-4xl font-bold text-yellow-500 mt-4">{statistics.invoicePending}</p>
                    </div>
                    {/* Card 4: Fulfilled/Serviced */}
                    <div 
                        onClick={() => setActiveTab('serviced')}
                        className={`p-4 border-r border-gray-100 cursor-pointer transition-colors ${activeTab === 'serviced' ? 'bg-indigo-50' : 'hover:bg-gray-50'}`}
                    >
                        <div className="flex items-baseline gap-2">
                            <span className="text-2xl font-bold text-gray-900">{statistics.totalServiced}</span>
                            <span className="text-xs font-medium text-gray-600">Appointments Serviced</span>
                        </div>
                        <p className="text-[9px] text-gray-400 uppercase mt-1">Last 12 months</p>
                        <div className="mt-4 flex justify-between">
                            <div><p className="text-[10px] text-gray-500">Fulfilled</p><p className="text-lg font-bold text-gray-800">{statistics.fulfilled}</p></div>
                            <div><p className="text-[10px] text-gray-500">No Show</p><p className="text-lg font-bold text-gray-800">15</p></div>
                        </div>
                    </div>
                    {/* Card 5: Cancelled */}
                    <div 
                        onClick={() => setActiveTab('cancelled')}
                        className={`p-4 cursor-pointer transition-colors ${activeTab === 'cancelled' ? 'bg-red-50' : 'hover:bg-gray-50'}`}
                    >
                        <p className="text-[10px] text-gray-500 leading-tight">Cancelled Appointments</p>
                        <p className="text-[9px] text-gray-400 uppercase mb-2">Last 12 months</p>
                        <p className="text-4xl font-bold text-red-500">{statistics.cancelled}</p>
                    </div>
                </div>

                {/* Redesigned Table */}
                <div className="bg-white rounded-xl shadow-sm border border-gray-200 overflow-hidden">
                    <div className="overflow-x-auto">
                        <table className="w-full text-sm text-left text-gray-600 border-collapse">
                            <thead className="bg-[#FAFAFA] text-[11px] text-gray-500 uppercase font-bold border-b border-gray-100">
                                <tr>
                                    <th className="px-6 py-4">PO No.</th>
                                    <th className="px-6 py-4">Facility Name</th>
                                    <th className="px-6 py-4">Appointment Status</th>
                                    <th className="px-6 py-4">Delivery Type</th>
                                    <th className="px-6 py-4">Issue Date</th>
                                    <th className="px-6 py-4 text-right">Total Quantity</th>
                                    <th className="px-6 py-4 text-right">Total SKUs</th>
                                    <th className="px-6 py-4">PO Expiry Date</th>
                                    <th className="px-6 py-4 text-center">Action</th>
                                </tr>
                            </thead>
                            <tbody className="divide-y divide-gray-100">
                                {tableOrders.length === 0 ? (
                                    <tr><td colSpan={9} className="px-6 py-20 text-center text-gray-400 italic">No POs found for the selected view.</td></tr>
                                ) : (
                                    tableOrders.map(po => {
                                        const isTaken = getIsAppointmentTaken(po);
                                        return (
                                            <tr key={po.id} className="hover:bg-gray-50/50">
                                                <td className="px-6 py-4 font-bold text-partners-green hover:underline cursor-pointer">{po.poNumber}</td>
                                                <td className="px-6 py-4 font-medium text-gray-700">{po.channel} - {po.storeCode}</td>
                                                <td className="px-6 py-4">
                                                    <span className={`px-3 py-1 rounded-full text-[10px] font-bold ${
                                                        isTaken 
                                                            ? 'bg-green-100 text-green-700' 
                                                            : 'bg-[#EBF5FB] text-[#2E86C1]'
                                                    }`}>
                                                        {isTaken ? 'Scheduled' : 'Unscheduled'}
                                                    </span>
                                                </td>
                                                <td className="px-6 py-4">
                                                    <div className={`inline-flex items-center gap-1.5 px-2 py-1 rounded-lg font-bold text-[10px] border ${
                                                        isTaken 
                                                            ? 'bg-blue-50 text-blue-700 border-blue-100' 
                                                            : 'bg-[#F1F9F6] text-partners-green border-[#D5EFE3]'
                                                    }`}>
                                                        <TruckIcon className="h-3 w-3" /> {isTaken ? (po.carrier || 'Logistics Assigned') : 'Courier Vendor'}
                                                    </div>
                                                </td>
                                                <td className="px-6 py-4 text-gray-500 font-medium">{po.orderDate}</td>
                                                <td className="px-6 py-4 font-bold text-gray-900 text-right">{po.qty}</td>
                                                <td className="px-6 py-4 font-medium text-gray-700 text-right">{po.items?.length || 0}</td>
                                                <td className="px-6 py-4 text-gray-500 font-medium">{po.poExpiryDate || po.orderDate}</td>
                                                <td className="px-6 py-4 text-center">
                                                    {!isTaken ? (
                                                        <button 
                                                            onClick={() => handleSchedule(po)}
                                                            className="px-6 py-1.5 border border-partners-green text-partners-green font-bold text-[11px] rounded hover:bg-partners-green hover:text-white transition-all active:scale-95"
                                                        >
                                                            Schedule
                                                        </button>
                                                    ) : (
                                                        <div className="text-[10px] font-bold text-gray-400 uppercase tracking-widest flex items-center justify-center gap-1">
                                                            <CheckCircleIcon className="h-3 w-3 text-green-500" /> Done
                                                        </div>
                                                    )}
                                                </td>
                                            </tr>
                                        );
                                    })
                                )}
                            </tbody>
                        </table>
                    </div>
                </div>
            </div>
        </>
    );
};

export default AppointmentManager;

