import React, { useState, useEffect, useRef } from 'react';
import { User, UploadMetadata } from '../types';
import { 
    CloudDownloadIcon as FileIcon, 
    ExternalLinkIcon, 
    InfoIcon, 
    XCircleIcon, 
    CheckCircleIcon, 
    RefreshIcon, 
    PaperclipIcon,
    AlertIcon,
    TruckIcon
} from './icons/Icons';
import { logFileUpload, fetchUploadMetadata } from '../services/api';

// Reusing AlertIcon if available, or using XCircleIcon as a fallback for the dialog
const ErrorDialog: React.FC<{ title: string, message: string, onClose: () => void }> = ({ title, message, onClose }) => (
    <div className="fixed inset-0 bg-black/70 backdrop-blur-md flex items-center justify-center z-[200] p-4 animate-in fade-in duration-200">
        <div className="bg-white rounded-3xl shadow-2xl w-full max-w-md overflow-hidden border border-red-100 transform animate-in zoom-in-95 duration-200">
            <div className="p-6 bg-red-50 border-b border-red-100 flex flex-col items-center text-center">
                <div className="w-16 h-16 bg-red-100 rounded-full flex items-center justify-center mb-4">
                    <XCircleIcon className="h-10 w-10 text-red-600" />
                </div>
                <h3 className="text-xl font-bold text-red-900">{title}</h3>
            </div>
            <div className="p-8 text-center">
                <p className="text-gray-600 leading-relaxed mb-8">{message}</p>
                <button 
                    onClick={onClose}
                    className="w-full py-4 bg-red-600 text-white font-bold rounded-2xl shadow-lg shadow-red-100 hover:bg-red-700 transition-all active:scale-[0.98]"
                >
                    Acknowledge Error
                </button>
            </div>
        </div>
    </div>
);

interface FileUploaderProps {
    currentUser: User;
    addLog: (action: string, details: string) => void;
    addNotification: (message: string, type?: 'info' | 'success' | 'warning' | 'error') => void;
}

const FileUploader: React.FC<FileUploaderProps> = ({ currentUser, addLog, addNotification }) => {
    const [uploadHistory, setUploadHistory] = useState<UploadMetadata[]>([]);
    const [isModalOpen, setIsModalOpen] = useState(false);
    const [selectedFunction, setSelectedFunction] = useState<string | null>(null);
    const [isUploading, setIsUploading] = useState(false);
    const [isLoadingMetadata, setIsLoadingMetadata] = useState(false);
    const [isDragging, setIsDragging] = useState(false);
    const [errorDetails, setErrorDetails] = useState<{ title: string, message: string } | null>(null);
    const [pendingFile, setPendingFile] = useState<File | null>(null);

    const uploadFunctions = [
        {
            id: 'b2b-packing-list',
            name: 'B2B Packing List Data',
            link: 'https://app.easyecom.io/V2/reports/reports-HomePage',
            instructions: "Go to 'B2B Packing List Report' in Other Reports section and Download last 7 days file.",
            accept: '.csv, .xlsx',
            validExtensions: ['.csv', '.xlsx']
        },
        {
            id: 'flipkart-minutes-po',
            name: 'FlipkartMinutes PO Upload',
            link: 'https://seller.flipkart.com/',
            instructions: "Upload the PO file (.xls only) downloaded from the Flipkart Minutes portal. The system backend will process this data into the PO database.",
            accept: '.xls',
            validExtensions: ['.xls']
        }
    ];

    const loadMetadata = async () => {
        setIsLoadingMetadata(true);
        try {
            const data = await fetchUploadMetadata();
            setUploadHistory(data);
        } catch (e) {
            console.error(e);
        } finally {
            setIsLoadingMetadata(false);
        }
    };

    useEffect(() => {
        loadMetadata();
    }, []);

    const handleUploadClick = (funcId: string) => {
        setSelectedFunction(funcId);
        setPendingFile(null);
        setIsModalOpen(true);
    };

    const triggerError = (title: string, message: string) => {
        addNotification(message, 'error');
        setErrorDetails({ title, message });
    };

    const handleFileSelection = (file: File) => {
        if (!selectedFunction) return;

        const func = uploadFunctions.find(f => f.id === selectedFunction);
        if (!func) return;

        // Validation for specific file formats
        const fileName = file.name.toLowerCase();
        const isValid = func.validExtensions.some(ext => fileName.endsWith(ext));

        if (!isValid) {
            triggerError(
                'Invalid File Format', 
                `The ${func.name} section only accepts ${func.accept} files. You attempted to upload: ${file.name}`
            );
            return;
        }

        setPendingFile(file);
    };

    const confirmAndProcessUpload = async () => {
        if (!selectedFunction || !pendingFile) return;

        const file = pendingFile;
        setIsUploading(true);
        try {
            const reader = new FileReader();

            reader.onload = async (e) => {
                try {
                    const base64Data = e.target?.result?.toString().split(',')[1];
                    const res = await logFileUpload(selectedFunction, currentUser.name, base64Data, file.name);

                    if (res.status === 'success') {
                        addLog('File Upload', `Successfully uploaded ${file.name} for ${selectedFunction}`);
                        addNotification(`File "${file.name}" processed successfully by backend.`, 'success');
                        setPendingFile(null);
                        setIsModalOpen(false);
                        loadMetadata();
                    } else {
                        triggerError('Server Processing Error', res.message || 'The server encountered an error while processing the file data.');
                    }
                } catch (err) {
                    triggerError('Network Error', 'Failed to communicate with the processing server. Please check your connection.');
                } finally {
                    setIsUploading(false);
                }
            };

            reader.onerror = () => {
                triggerError('File Access Error', 'System could not read the local file. It might be in use by another application.');
                setIsUploading(false);
            };

            reader.readAsDataURL(file);
        } catch (e) {
            triggerError('Initialization Error', 'An unexpected error occurred while starting the upload process.');
            setIsUploading(false);
        }
    };

    const onDragOver = (e: React.DragEvent) => {
        e.preventDefault();
        e.stopPropagation();
        if (!isUploading) setIsDragging(true);
    };

    const onDragLeave = (e: React.DragEvent) => {
        e.preventDefault();
        e.stopPropagation();
        setIsDragging(false);
    };

    const onDrop = (e: React.DragEvent) => {
        e.preventDefault();
        e.stopPropagation();
        setIsDragging(false);

        if (isUploading) return;

        const files = e.dataTransfer.files;
        if (files && files.length > 0) {
            handleFileSelection(files[0]);
        }
    };

    const getMetadata = (funcId: string) => uploadHistory.find(h => h.id === funcId);

    const formatFileSize = (bytes: number) => {
        if (bytes === 0) return '0 Bytes';
        const k = 1024;
        const sizes = ['Bytes', 'KB', 'MB', 'GB'];
        const i = Math.floor(Math.log(bytes) / Math.log(k));
        return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + ' ' + sizes[i];
    };

    return (
        <div className="p-4 sm:p-6 lg:p-8 flex-1">
            {errorDetails && (
                <ErrorDialog 
                    title={errorDetails.title} 
                    message={errorDetails.message} 
                    onClose={() => setErrorDetails(null)} 
                />
            )}

            <header className="mb-8">
                <h1 className="text-2xl font-bold text-gray-800">System Data File Uploader</h1>
                <p className="text-gray-500 mt-1">Manual synchronization hub for reports and channel data.</p>
            </header>

            <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-6">
                {uploadFunctions.map(func => {
                    const meta = getMetadata(func.id);
                    return (
                        <div key={func.id} className="bg-white rounded-2xl shadow-sm border border-gray-100 flex flex-col hover:shadow-md transition-shadow overflow-hidden">
                            <div className="p-6 flex-1">
                                <div className="flex items-center gap-3 mb-4">
                                    <div className="p-2.5 bg-blue-50 text-blue-600 rounded-xl">
                                        <FileIcon className="h-6 w-6" />
                                    </div>
                                    <h3 className="font-bold text-gray-900">{func.name}</h3>
                                </div>

                                <div className="space-y-4">
                                    <div className="p-3 bg-gray-50 rounded-xl border border-gray-100">
                                        <p className="text-[10px] font-bold text-gray-400 uppercase tracking-widest mb-1">Last Sync Status</p>
                                        {meta ? (
                                            <div className="flex items-center justify-between">
                                                <div className="flex items-center gap-2">
                                                    <CheckCircleIcon className="h-4 w-4 text-green-500" />
                                                    <span className="text-xs font-bold text-gray-700">{meta.lastUploadedBy}</span>
                                                </div>
                                                <span className="text-[10px] text-gray-400 font-medium italic">{meta.lastUploadedAt}</span>
                                            </div>
                                        ) : (
                                            <p className="text-xs text-gray-400 italic">No previous uploads found.</p>
                                        )}
                                    </div>

                                    <div className="flex flex-col gap-2">
                                        <a href={func.link} target="_blank" rel="noopener noreferrer" className="flex items-center justify-between px-4 py-2 bg-blue-50 text-blue-700 rounded-lg text-xs font-bold hover:bg-blue-100 transition-colors">
                                            <span>Open Portal Source</span>
                                            <ExternalLinkIcon className="h-3.5 w-3.5" />
                                        </a>
                                        <div className="p-3 bg-amber-50 border border-amber-100 rounded-xl flex gap-2">
                                            <InfoIcon className="h-4 w-4 text-amber-600 flex-shrink-0 mt-0.5" />
                                            <p className="text-[11px] text-amber-800 leading-relaxed">
                                                <span className="font-bold uppercase text-[9px] block mb-0.5">Instructions</span>
                                                {func.instructions}
                                            </p>
                                        </div>
                                    </div>
                                </div>
                            </div>

                            <div className="p-4 bg-gray-50 border-t border-gray-100">
                                <button 
                                    onClick={() => handleUploadClick(func.id)}
                                    className="w-full flex items-center justify-center gap-2 py-2.5 bg-partners-green text-white font-bold rounded-xl shadow-lg shadow-green-100 hover:bg-green-700 transition-all active:scale-[0.98]"
                                >
                                    <FileIcon className="h-4 w-4" />
                                    Upload New Data
                                </button>
                            </div>
                        </div>
                    );
                })}
            </div>

            {isModalOpen && selectedFunction && (
                <div className="fixed inset-0 bg-black/60 backdrop-blur-sm flex items-center justify-center z-[100] p-4 animate-in fade-in duration-300">
                    <div className="bg-white rounded-3xl shadow-2xl w-full max-w-lg overflow-hidden border border-gray-100">
                        <div className="p-6 bg-gray-50 border-b border-gray-100 flex justify-between items-center">
                            <div>
                                <h3 className="text-xl font-bold text-gray-800">Upload Data File</h3>
                                <p className="text-xs text-gray-500 font-medium">Processing: {uploadFunctions.find(f => f.id === selectedFunction)?.name}</p>
                            </div>
                            <button onClick={() => setIsModalOpen(false)} className="p-2 hover:bg-white rounded-full transition-colors"><XCircleIcon className="h-6 w-6 text-gray-400"/></button>
                        </div>

                        <div className="p-8">
                            {!pendingFile ? (
                                <>
                                    <div className="mb-6 p-4 bg-blue-50 rounded-2xl border border-blue-100 flex items-start gap-3">
                                        <InfoIcon className="h-5 w-5 text-blue-500 mt-0.5" />
                                        <div>
                                            <p className="text-[10px] font-bold text-blue-700 uppercase tracking-widest mb-1">Required Steps</p>
                                            <p className="text-xs text-blue-800 leading-relaxed">
                                                {uploadFunctions.find(f => f.id === selectedFunction)?.instructions}
                                            </p>
                                        </div>
                                    </div>

                                    <label 
                                        onDragOver={onDragOver}
                                        onDragLeave={onDragLeave}
                                        onDrop={onDrop}
                                        className={`group relative flex flex-col items-center justify-center w-full h-56 border-2 border-dashed rounded-3xl cursor-pointer transition-all overflow-hidden ${
                                            isDragging 
                                                ? 'bg-partners-light-green border-partners-green scale-[1.02] shadow-xl' 
                                                : 'bg-gray-50 border-gray-300 hover:bg-gray-100 hover:border-partners-green'
                                        }`}
                                    >
                                        <div className={`flex flex-col items-center justify-center pt-5 pb-6 transition-transform ${isDragging ? 'scale-110' : ''}`}>
                                            <PaperclipIcon className={`h-14 w-14 mb-3 transition-all ${
                                                isDragging ? 'text-partners-green animate-bounce' : 'text-gray-400 group-hover:text-partners-green group-hover:scale-110'
                                            }`} />
                                            <p className="mb-2 text-sm font-bold text-gray-700">
                                                {isDragging ? 'Release to upload' : 'Click to select or drag and drop'}
                                            </p>
                                            <p className="text-xs text-gray-500 px-4 text-center">
                                                Accepts: <span className="font-bold text-partners-green">{uploadFunctions.find(f => f.id === selectedFunction)?.accept}</span> (Max. 10MB)
                                            </p>
                                        </div>
                                        <input 
                                            type="file" 
                                            className="hidden" 
                                            accept={uploadFunctions.find(f => f.id === selectedFunction)?.accept || '.csv, .xlsx, .xls'}
                                            onChange={(e) => {
                                                const file = e.target.files?.[0];
                                                if (file) handleFileSelection(file);
                                            }}
                                            disabled={isUploading}
                                        />
                                    </label>
                                </>
                            ) : (
                                <div className="space-y-6 animate-in slide-in-from-bottom-4 duration-300">
                                    <div className="bg-partners-light-green border border-partners-green/20 rounded-2xl p-6 flex items-center gap-4">
                                        <div className="p-3 bg-partners-green text-white rounded-xl shadow-lg shadow-green-100">
                                            <PaperclipIcon className="h-8 w-8" />
                                        </div>
                                        <div className="flex-1 overflow-hidden">
                                            <p className="text-sm font-bold text-gray-900 truncate" title={pendingFile.name}>{pendingFile.name}</p>
                                            <p className="text-xs text-gray-500 font-medium">{formatFileSize(pendingFile.size)} • Ready to process</p>
                                        </div>
                                        <button 
                                            onClick={() => setPendingFile(null)}
                                            className="p-2 text-gray-400 hover:text-red-500 hover:bg-red-50 rounded-lg transition-all"
                                            title="Change File"
                                        >
                                            <XCircleIcon className="h-5 w-5" />
                                        </button>
                                    </div>

                                    <div className="bg-amber-50 border border-amber-100 rounded-2xl p-4 flex gap-3">
                                        <InfoIcon className="h-5 w-5 text-amber-600 flex-shrink-0 mt-0.5" />
                                        <p className="text-xs text-amber-800 leading-relaxed font-medium">
                                            Please verify that you have selected the correct file. Once confirmed, the system will begin parsing and updating the central database.
                                        </p>
                                    </div>

                                    <div className="flex flex-col gap-3">
                                        <button 
                                            onClick={confirmAndProcessUpload}
                                            disabled={isUploading}
                                            className="w-full flex items-center justify-center gap-2 py-4 bg-partners-green text-white font-bold rounded-2xl shadow-xl shadow-green-100 hover:bg-green-700 transition-all active:scale-[0.98] disabled:opacity-50"
                                        >
                                            {isUploading ? (
                                                <>
                                                    <RefreshIcon className="h-5 w-5 animate-spin" />
                                                    <span>Processing File...</span>
                                                </>
                                            ) : (
                                                <>
                                                    <CheckCircleIcon className="h-5 w-5" />
                                                    <span>Confirm and Process Upload</span>
                                                </>
                                            )}
                                        </button>
                                        <button 
                                            onClick={() => setPendingFile(null)}
                                            disabled={isUploading}
                                            className="w-full py-3 text-sm font-bold text-gray-400 hover:text-gray-600 transition-colors disabled:opacity-50"
                                        >
                                            Cancel and select another file
                                        </button>
                                    </div>
                                </div>
                            )}

                            <div className="mt-8 flex items-center justify-center gap-2 pt-4 border-t border-gray-50">
                                <CheckCircleIcon className="h-4 w-4 text-partners-green" />
                                <span className="text-[10px] text-gray-400 font-bold uppercase tracking-widest">Validations strictly applied</span>
                            </div>
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
};

export default FileUploader;

import React, { useState, useMemo, useEffect, useCallback } from 'react';
import Sidebar from './components/Sidebar';
import Header from './components/Header';
import SummaryCard from './components/SummaryCard';
import PoTable from './components/PoTable';
import SalesOrderTable from './components/SalesOrderTable';
import AppointmentManager from './components/AppointmentManager';
import AdminPanel from './components/AdminPanel';
import FinanceManager from './components/FinanceManager';
import InventoryManager from './components/InventoryManager';
import ReportsManager from './components/ReportsManager';
import FileUploader from './components/FileUploader';
import ToastContainer from './components/ToastContainer';
import { XIcon, QuestionMarkCircleIcon, RefreshIcon } from './components/icons/Icons';
import { initialRolePermissions } from './data/mockData';
import { type PurchaseOrder, POStatus, ActivityLog, NotificationItem, ViewType, User, RolePermissions, InventoryItem, ChannelConfig } from './types';
import { fetchPurchaseOrders, fetchInventoryFromSheet, fetchChannelConfigs, fetchUsers } from './services/api';

// Default user to bypass login
const defaultUser: User = {
    id: 'admin-user-01',
    name: 'Cubelelo Admin',
    email: 'admin@cubelelo.com',
    contactNumber: '9999999999',
    role: 'Admin',
    avatarInitials: 'AD',
    isInitialized: true
};

const App: React.FC = () => {
  const [isSidebarOpen, setSidebarOpen] = useState(true);
  const [isLoading, setIsLoading] = useState(false);
  const [lastSynced, setLastSynced] = useState<number>(0);

  // Set default user immediately
  const [currentUser, setCurrentUser] = useState<User | null>(defaultUser);
  const [isAuthChecked, setIsAuthChecked] = useState(true);

  const [users, setUsers] = useState<User[]>([]);
  const [rolePermissions] = useState<RolePermissions>(initialRolePermissions);

  const [activeView, setActiveView] = useState<ViewType>('Dashboard');
  const [activeFilter, setActiveFilter] = useState('New POs');
  const [adminTab, setAdminTab] = useState<'users' | 'roles' | 'channels' | 'integrations' | 'logs'>('users');

  const [purchaseOrders, setPurchaseOrders] = useState<PurchaseOrder[]>([]);
  const [inventoryItems, setInventoryItems] = useState<InventoryItem[]>([]);
  const [channelConfigs, setChannelConfigs] = useState<ChannelConfig[]>([]);

  const [logs, setLogs] = useState<ActivityLog[]>([
    { id: '1', user: 'System', action: 'Init', details: 'System initialized.', timestamp: new Date().toLocaleString() }
  ]);
  const [notifications, setNotifications] = useState<NotificationItem[]>([]);
  const [toasts, setToasts] = useState<NotificationItem[]>([]);

  const handleLogout = () => {
    setActiveView('Dashboard');
  };

  const toggleSidebar = () => setSidebarOpen(!isSidebarOpen);

  const addLog = useCallback((action: string, details: string) => {
    const newLog: ActivityLog = {
        id: Date.now().toString(),
        user: currentUser?.name || 'System', 
        action,
        details,
        timestamp: new Date().toLocaleString()
    };
    setLogs(prev => [newLog, ...prev]);
  }, [currentUser]);

  const addNotification = useCallback((message: string, type: 'info' | 'success' | 'warning' | 'error' = 'info') => {
    const newNotification: NotificationItem = {
        id: Date.now().toString(),
        message,
        timestamp: new Date().toLocaleTimeString(),
        read: false,
        type
    };
    setNotifications(prev => [newNotification, ...prev]);
    setToasts(prev => [...prev, newNotification]);
  }, []);

  const removeToast = useCallback((id: string) => {
    setToasts(prev => prev.filter(t => t.id !== id));
  }, []);

  const refreshData = useCallback(async (force = false) => {
      if (!force && purchaseOrders.length > 0 && Date.now() - lastSynced < 1800000) return; 

      setIsLoading(true);
      try {
          const [poData, invData, channelData, userData] = await Promise.all([
              fetchPurchaseOrders(),
              fetchInventoryFromSheet(),
              fetchChannelConfigs(),
              fetchUsers()
          ]);

          if (poData.length > 0) setPurchaseOrders(poData);
          if (invData.length > 0) setInventoryItems(invData);
          if (channelData.length > 0) setChannelConfigs(channelData);
          if (userData.length > 0) setUsers(userData);

          setLastSynced(Date.now());
      } catch (e) {
          addNotification('Failed to sync data.', 'error');
      } finally {
          setIsLoading(false);
      }
  }, [lastSynced, purchaseOrders.length, addNotification]);

  useEffect(() => {
    if (currentUser) {
        refreshData();
        const intervalId = setInterval(() => refreshData(true), 30 * 60 * 1000);
        return () => clearInterval(intervalId);
    }
  }, [refreshData, currentUser]);

  // Handle section-specific default filters when activeView changes
  useEffect(() => {
    if (activeView === 'Purchase Orders') {
      setActiveFilter('New POs');
    } else if (activeView === 'Sales Orders') {
      setActiveFilter('All POs');
    }
  }, [activeView]);

  const getCalculatedStatus = (po: PurchaseOrder): POStatus => {
    const rawStatus = String(po.status || '').trim().toLowerCase();
    if (rawStatus === 'cancelled') return POStatus.Cancelled;
    if (rawStatus === 'below threshold') return POStatus.BelowThreshold;

    const items = po.items || [];
    const pushedCount = items.filter(i => !!i.eeOrderRefId).length;
    if (items.length > 0 && pushedCount === items.length) return POStatus.Pushed;
    if (pushedCount > 0) return POStatus.PartiallyProcessed;
    return POStatus.NewPO;
  };

  const summaryData = useMemo(() => {
    const totalActive = purchaseOrders.filter(p => p.status !== POStatus.Closed && p.status !== POStatus.Cancelled).length;
    const pushed = purchaseOrders.filter(p => getCalculatedStatus(p) === POStatus.Pushed).length;
    const partiallyPushed = purchaseOrders.filter(p => getCalculatedStatus(p) === POStatus.PartiallyProcessed).length;

    return [
      { title: 'Total Active POs', value: totalActive.toString(), change: 'Across all stages', color: 'blue', targetView: 'Purchase Orders', targetFilter: 'All POs' },
      { title: 'Fully Pushed', value: pushed.toString(), change: 'To EasyEcom', color: 'green', targetView: 'Purchase Orders', targetFilter: 'Pushed POs' },
      { title: 'Partially Pushed', value: partiallyPushed.toString(), change: 'Pending items', color: 'yellow', targetView: 'Purchase Orders', targetFilter: 'Partially Pushed POs' },
    ];
  }, [purchaseOrders]);

  const tabCounts = useMemo(() => {
    const counts = { 
        'All POs': purchaseOrders.length, 
        'New POs': 0, 
        'Below Threshold POs': 0, 
        'Pushed POs': 0, 
        'Partially Pushed POs': 0, 
        'Cancelled POs': 0 
    };
    purchaseOrders.forEach(po => {
        const status = getCalculatedStatus(po);
        if (status === POStatus.NewPO) counts['New POs']++;
        else if (status === POStatus.BelowThreshold) counts['Below Threshold POs']++;
        else if (status === POStatus.Pushed) counts['Pushed POs']++;
        else if (status === POStatus.PartiallyProcessed) counts['Partially Pushed POs']++;
        else if (status === POStatus.Cancelled) counts['Cancelled POs']++;
    });
    return counts;
  }, [purchaseOrders]);

  const handleCardClick = (view: ViewType, filter?: string) => {
      if (currentUser && rolePermissions[currentUser.role]?.includes(view)) {
          setActiveView(view);
          if (filter) setActiveFilter(filter);
      } else {
          addNotification(`Access Denied.`, 'error');
      }
  };

  const renderContent = () => {
    if (!currentUser) return null;
    if (isLoading && purchaseOrders.length === 0) {
        return <div className="flex-1 flex flex-col items-center justify-center p-8"><RefreshIcon className="h-12 w-12 text-partners-green animate-spin mb-4" /><p className="text-gray-600 font-bold text-lg">Syncing Dashboard...</p></div>;
    }

    switch (activeView) {
        case 'Dashboard':
            return (
                <div className="p-4 sm:p-6 lg:p-8 flex-1">
                    <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
                        {summaryData.map((card, index) => (
                            <SummaryCard key={index} {...card as any} onClick={() => handleCardClick(card.targetView as ViewType, card.targetFilter)} />
                        ))}
                    </div>
                </div>
            );
        case 'Purchase Orders':
            return (
                <div className="p-4 sm:p-6 lg:p-8 flex-1">
                    <PoTable activeFilter={activeFilter} setActiveFilter={setActiveFilter} purchaseOrders={purchaseOrders} setPurchaseOrders={setPurchaseOrders} tabCounts={tabCounts} addLog={addLog} addNotification={addNotification} onSync={() => refreshData(true)} isSyncing={isLoading} channelConfigs={channelConfigs} />
                </div>
            );
        case 'File Uploader':
            return <FileUploader currentUser={currentUser} addLog={addLog} addNotification={addNotification} />;
        case 'Inventory': return <InventoryManager addLog={addLog} inventoryItems={inventoryItems} setInventoryItems={setInventoryItems} onSync={() => refreshData(true)} isSyncing={isLoading} />;
        case 'Finance': return <FinanceManager purchaseOrders={purchaseOrders} setPurchaseOrders={setPurchaseOrders} addLog={addLog} />;
        case 'Reports': return <ReportsManager purchaseOrders={purchaseOrders} inventoryItems={inventoryItems} />;
        case 'Appointments':
            return <AppointmentManager purchaseOrders={purchaseOrders} setPurchaseOrders={setPurchaseOrders} addLog={addLog} addNotification={addNotification} />;
        case 'Sales Orders':
             return (
                <div className="p-4 sm:p-6 lg:p-8 flex-1">
                    <SalesOrderTable activeFilter={activeFilter} setActiveFilter={setActiveFilter} purchaseOrders={purchaseOrders} setPurchaseOrders={setPurchaseOrders} tabCounts={tabCounts} addLog={addLog} addNotification={addNotification} onSync={() => refreshData(true)} isSyncing={isLoading} />
                </div>
            );
        case 'Admin': return (
            <AdminPanel logs={logs} users={users} setUsers={setUsers} rolePermissions={rolePermissions} setRolePermissions={() => {}} addLog={addLog} currentUser={currentUser} channelConfigs={channelConfigs} onSync={() => refreshData(true)} activeTab={adminTab} setActiveTab={setAdminTab} />
        );
        default: return <div className="p-8 text-center text-gray-500">Section Under Construction</div>;
    }
  };

  if (!isAuthChecked || !currentUser) return null;

  return (
    <div className="flex h-screen bg-partners-gray-bg font-sans overflow-hidden">
      <ToastContainer toasts={toasts} onRemove={removeToast} />

      {/* Sidebar Container */}
      <div 
        className={`fixed lg:relative inset-y-0 left-0 z-30 transition-all duration-300 ease-in-out border-r border-partners-border bg-white ${
          isSidebarOpen ? 'w-64 translate-x-0' : 'w-0 -translate-x-full'
        }`}
      >
        <div className={`w-64 h-full ${!isSidebarOpen && 'invisible'}`}>
          <Sidebar activeView={activeView} setActiveView={setActiveView} currentUser={currentUser} permissions={rolePermissions} onLogout={handleLogout} />
        </div>
      </div>

      {/* Main Content Container */}
      <main className="flex-1 flex flex-col min-w-0 overflow-y-auto transition-all duration-300 ease-in-out">
        <Header 
          notifications={notifications} 
          onMarkRead={() => {}} 
          onClearAll={() => {}} 
          onViewLogs={() => { setActiveView('Admin'); setAdminTab('logs'); }} 
          activeView={activeView}
          onToggleSidebar={toggleSidebar}
        />
        {renderContent()}
      </main>

      <button className="fixed bottom-6 right-6 bg-green-600 text-white p-3 rounded-full shadow-lg hover:bg-green-700 transition-all hover:scale-110 flex items-center gap-2 z-40">
        <QuestionMarkCircleIcon className="h-6 w-6" />
        <span className="font-bold text-sm pr-1">Help</span>
      </button>
    </div>
  );
};

export default App;

import React, { useState, useRef, useEffect } from 'react';
import { DownloadIcon, BellIcon, CheckCircleIcon, InfoIcon, AdminIcon, MenuIcon } from './icons/Icons';
import { NotificationItem, ViewType } from '../types';

interface HeaderProps {
    notifications: NotificationItem[];
    onMarkRead: (id: string) => void;
    onClearAll: () => void;
    onViewLogs: () => void;
    activeView: ViewType;
    onToggleSidebar: () => void;
}

const Header: React.FC<HeaderProps> = ({ notifications, onMarkRead, onClearAll, onViewLogs, activeView, onToggleSidebar }) => {
  const [isNotificationsOpen, setIsNotificationsOpen] = useState(false);
  const dropdownRef = useRef<HTMLDivElement>(null);

  const unreadCount = notifications.filter(n => !n.read).length;

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
        setIsNotificationsOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const getSubtext = () => {
    switch(activeView) {
        case 'Dashboard': return 'Real-time tracking of all purchase orders and shipment stages';
        case 'Purchase Orders': return 'Manage and process incoming purchase orders';
        case 'POC Verification': return 'Verify Point-of-Contact mobile numbers';
        case 'Appointments': return 'Schedule and track warehouse delivery slots';
        case 'Sales Orders': return 'Track fulfillment and shipping status of processed orders';
        case 'GRN / POD': return 'Manage Goods Received Notes and Proof of Delivery';
        case 'Inventory': return 'Mapping and stock management synced from EasyEcom';
        case 'Finance': return 'Track PO values, payments received, and customer accounts';
        case 'Reports': return 'Visual analytics and performance reporting';
        case 'Admin': return 'System configuration, role permissions, and activity logs';
        default: return 'Cubelelo Purchase Order Management Portal';
    }
  };

  return (
    <header className="flex flex-col md:flex-row justify-between md:items-center bg-white border-b border-gray-200 px-4 sm:px-6 lg:px-8 py-4 sticky top-0 z-40">
      <div className="flex items-center gap-3">
        <button 
          onClick={onToggleSidebar}
          className="p-2 -ml-2 text-gray-400 hover:text-partners-green hover:bg-partners-light-green rounded-lg transition-colors"
          title="Toggle Navigation"
        >
          <MenuIcon className="h-6 w-6" />
        </button>
        <div>
          <h1 className="text-2xl font-bold text-gray-800">{activeView === 'Dashboard' ? 'PO Dashboard' : activeView}</h1>
          <p className="text-xs text-gray-500 mt-0.5">{getSubtext()}</p>
        </div>
      </div>

      <div className="mt-4 md:mt-0 flex items-center gap-4">
        <div className="relative" ref={dropdownRef}>
            <button 
                onClick={() => setIsNotificationsOpen(!isNotificationsOpen)}
                className="p-2 text-gray-500 hover:bg-gray-100 rounded-full relative focus:outline-none transition-colors border border-transparent hover:border-gray-200"
                aria-label="Toggle notifications"
            >
                <BellIcon className="h-6 w-6" />
                {unreadCount > 0 && (
                    <span className="absolute top-1 right-1 h-4 w-4 bg-red-500 text-white text-[10px] font-bold rounded-full flex items-center justify-center border-2 border-white shadow-sm">
                        {unreadCount}
                    </span>
                )}
            </button>

            {isNotificationsOpen && (
                <div className="absolute right-0 mt-2 w-80 bg-white rounded-xl shadow-2xl border border-gray-100 z-50 overflow-hidden ring-1 ring-black ring-opacity-5">
                    <div className="p-3 border-b border-gray-100 flex justify-between items-center bg-gray-50">
                        <h3 className="font-bold text-sm text-gray-700">Notifications History</h3>
                        {notifications.length > 0 && (
                            <button onClick={onClearAll} className="text-[10px] font-bold text-gray-400 hover:text-red-500 transition-colors uppercase tracking-wider">
                                Clear all
                            </button>
                        )}
                    </div>
                    <div className="max-h-80 overflow-y-auto">
                        {notifications.length === 0 ? (
                            <div className="p-8 text-center text-gray-500 text-sm flex flex-col items-center gap-2">
                                <BellIcon className="h-8 w-8 text-gray-200" />
                                <p>No notifications yet.</p>
                            </div>
                        ) : (
                            <ul className="divide-y divide-gray-50">
                                {notifications.map((notification) => (
                                    <li 
                                        key={notification.id} 
                                        className={`p-4 hover:bg-gray-50 transition-colors cursor-pointer group ${!notification.read ? 'bg-blue-50/50' : ''}`}
                                        onClick={() => onMarkRead(notification.id)}
                                    >
                                        <div className="flex items-start gap-3">
                                            <div className={`mt-1 p-2 rounded-full flex-shrink-0 ${
                                                notification.type === 'success' ? 'bg-green-100 text-green-600' : 
                                                notification.type === 'error' ? 'bg-red-100 text-red-600' :
                                                'bg-blue-100 text-blue-600'
                                            }`}>
                                                {notification.type === 'success' ? <CheckCircleIcon className="h-4 w-4"/> : <InfoIcon className="h-4 w-4"/>}
                                            </div>
                                            <div className="flex-1">
                                                <p className={`text-sm leading-tight ${!notification.read ? 'font-bold text-gray-900' : 'text-gray-600'}`}>{notification.message}</p>
                                                <p className="text-[10px] text-gray-400 mt-1.5 flex items-center gap-1">
                                                    <span className="h-1 w-1 rounded-full bg-gray-300"></span>
                                                    {notification.timestamp}
                                                </p>
                                            </div>
                                            {!notification.read && (
                                                <span className="h-2 w-2 bg-blue-500 rounded-full mt-2 ring-4 ring-blue-50"></span>
                                            )}
                                        </div>
                                    </li>
                                ))}
                            </ul>
                        )}
                    </div>
                    <div className="p-3 bg-gray-50 border-t border-gray-100 text-center">
                        <button 
                            onClick={() => { setIsNotificationsOpen(false); onViewLogs(); }} 
                            className="text-[10px] font-bold text-partners-green hover:text-green-700 flex items-center justify-center w-full py-1.5 gap-2 uppercase tracking-widest transition-colors"
                        >
                            <AdminIcon className="h-4 w-4" />
                            Admin Activity Logs
                        </button>
                    </div>
                </div>
            )}
        </div>

        {(activeView === 'Purchase Orders' || activeView === 'Dashboard' || activeView === 'Sales Orders') && (
            <button className="hidden sm:flex items-center gap-2 px-4 py-2 text-sm font-bold text-partners-green border border-partners-green rounded-lg hover:bg-partners-light-green transition-all active:scale-95 shadow-sm">
                <DownloadIcon className="h-4 w-4" />
                <span>Bulk Export</span>
            </button>
        )}
      </div>
    </header>
  );
};

