import React, { useState } from 'react';
import { ViewType, User, RolePermissions } from '../types';
import { 
    SummaryIcon, 
    ReportIcon,
    AdminIcon,
    UploadIcon,
    TruckIcon,
    ExternalLinkIcon,
    ChevronDownIcon,
    ChevronRightIcon,
