                            </thead>
                            <tbody className="divide-y divide-gray-100">
                                {poData.map((po, idx) => (
                                    <tr key={po.id}>
                                        <td className="px-4 py-3 font-bold text-partners-green">{po.poNumber}</td>
                                        <td className="px-4 py-3">{po.storeCode}</td>
