                                                    <td className="p-10 text-right text-6xl font-bold">
                                                        {item.itemQuantity || item.qty}
                                                    </td>
                                                </tr>
                                            ))}
                                        </tbody>
                                    </table>
                                </div>
                            </div>
                        )}
                    </div>
                </div>

                <div className="p-10 border-t border-gray-100 bg-white flex justify-end gap-4 shadow-[0_-10px_20px_rgba(0,0,0,0.03)] no-print">
                    <button onClick={onClose} className="px-10 py-4 text-lg font-bold text-gray-500 hover:bg-gray-100 rounded-2xl transition-all border border-transparent hover:border-gray-200">Cancel</button>

                    <button 
                        onClick={handlePrint} 
                        className="px-8 py-4 bg-partners-blue text-white text-lg font-black rounded-2xl shadow-xl shadow-blue-100 hover:bg-blue-700 transition-all flex items-center gap-3 active:scale-95"
                    >
                        <CloudDownloadIcon className="h-6 w-6" />
                        Download PDF
                    </button>

                    <button 
                        onClick={handlePrint} 
                        className="px-14 py-4 bg-partners-green text-white text-lg font-black rounded-2xl shadow-xl shadow-green-100 hover:bg-green-700 transition-all flex items-center gap-4 active:scale-95"
                    >
                        <PrinterIcon className="h-6 w-6" />
                        Print Labels
                    </button>
                </div>
            </div>
        </div>
    );
};

const CopyField = ({ label, value, icon }: { label: string, value: string, icon: React.ReactNode }) => {
    const [copied, setCopied] = useState(false);
    const handleCopy = (e: React.MouseEvent) => {
        if (!value || value === 'N/A') return;
        navigator.clipboard.writeText(value);
        setCopied(true);
        setTimeout(() => setCopied(false), 2000);
    };
    return (
        <div onClick={handleCopy} className="flex flex-col gap-1.5 p-3 bg-white border border-gray-200 rounded-xl hover:border-partners-green transition-colors group cursor-pointer active:bg-gray-50 select-none">
            <div className="flex justify-between items-center pointer-events-none">
                <span className="text-[10px] font-bold text-gray-400 uppercase tracking-widest flex items-center gap-1">{icon} {label}</span>
                <div className={`text-[10px] font-bold px-2 py-0.5 rounded transition-all ${copied ? 'bg-green-100 text-green-600' : 'bg-gray-100 text-gray-500 group-hover:bg-partners-green group-hover:text-white'}`}>{copied ? 'COPIED!' : 'COPY'}</div>
            </div>
            <p className="text-sm font-bold text-gray-800 break-all pointer-events-none">{value || 'N/A'}</p>
        </div>
    );
};

