    const [printMode, setPrintMode] = useState<'individual' | 'master'>('individual');

    const totalQty = so.qty;
    const skuCount = so.items.length;
    const innerBoxCount = so.boxCount || 0;

    const handlePrint = () => {
        window.print();
    };

    const getItemEan = (item: POItem) => {
        // Find EAN from Master SKU Mapping (inventoryItems) using articleCode
        const inv = inventoryItems?.find(i => i.articleCode === item.articleCode);
        return inv?.ean || 'N/A';
    };

    // Flatten logic: 1 label per box as defined in the packing list
    const flattenedLabels = useMemo(() => {
        const labels: { item: POItem; boxIndex: number; totalBoxes: number }[] = [];
        let currentGlobalBoxIndex = 1;
        const totalBoxesCount = so.boxCount;

        if (totalBoxesCount === 0) return [];

        so.items.forEach(item => {
            const boxesForItem = item.eeBoxCount || 0;
            for (let i = 0; i < boxesForItem; i++) {
                labels.push({ 
                    item, 
                    boxIndex: currentGlobalBoxIndex++, 
                    totalBoxes: totalBoxesCount 
                });
            }
        });
        return labels;
    }, [so.items, so.boxCount]);

    return (
        <div className="fixed inset-0 bg-black/80 backdrop-blur-md flex items-center justify-center z-[150] p-4 no-print-overlay">
            <style>
                {`
