const LabelPrintModal: FC<{ so: GroupedSalesOrder, inventoryItems?: InventoryItem[], onClose: () => void }> = ({ so, inventoryItems, onClose }) => {
    const [printMode, setPrintMode] = useState<'individual' | 'master'>('individual');

    const totalQty = so.qty;
    const skuCount = so.items.length;
    const innerBoxCount = so.boxCount || 0;

    const handlePrint = () => {
        window.print();
    };

    const getItemEan = (item: POItem) => {
        const inv = inventoryItems?.find(i => String(i.articleCode).trim() === String(item.articleCode).trim());
        return inv?.ean || 'N/A';
    };

    const flattenedLabels = useMemo(() => {
        const labels: { item: POItem; boxIndex: number; totalBoxes: number }[] = [];
        let currentGlobalBoxIndex = 1;
        const totalBoxes = so.boxCount;

        if (totalBoxes === 0) return [];

        so.items.forEach(item => {
            const boxesForItem = item.eeBoxCount || 0;
            // Generate exactly as many labels as specified for this item in the box count
            for (let i = 0; i < boxesForItem; i++) {
                labels.push({ 
                    item, 
                    boxIndex: currentGlobalBoxIndex++, 
                    totalBoxes 
                });
            }
        });
        return labels;
    }, [so.items, so.boxCount]);

    return (
        <div className="fixed inset-0 bg-black/90 backdrop-blur-md flex items-center justify-center z-[150] p-4 no-print-overlay">
            <style>
                {`
                @media print {
                    /* Fix for blank page: Use visibility instead of display:none on parents */
                    body {
                        visibility: hidden !important;
                        background: white !important;
                    }

                    /* Target the exact container and its children only */
                    .print-section-only, .print-section-only * {
                        visibility: visible !important;
                    }

                    .print-section-only {
                        position: absolute !important;
                        left: 0 !important;
                        top: 0 !important;
                        width: 100% !important;
                        display: block !important;
                    }

                    @page { 
                        size: ${printMode === 'individual' ? '4in 6in' : 'A3'};
                        margin: 0 !important;
                    }

                    .thermal-label-4x6 {
                        width: 4in !important;
                        height: 6in !important;
                        page-break-after: always !important;
                        display: flex !important;
                        flex-direction: column !important;
                        padding: 0.4in !important;
                        box-sizing: border-box !important;
                        background: white !important;
                        color: black !important;
                        font-family: Arial, sans-serif !important;
                        border: none !important;
                    }

                    .master-slip-a3 {
                        width: 297mm !important;
                        min-height: 420mm !important;
                        page-break-after: always !important;
                        padding: 1.5cm !important;
                        box-sizing: border-box !important;
                    }
                }
                `}
            </style>

            <div className="bg-white rounded-[2.5rem] shadow-2xl w-full max-w-6xl flex flex-col h-[92vh] overflow-hidden no-print">
                <div className="p-8 border-b border-gray-100 flex justify-between items-center bg-gray-50/50">
