                                                        <span className="text-[11px] font-bold text-gray-500 mb-1 uppercase tracking-wider">Box ID</span>
                                                        <span className="text-[20px] font-bold leading-none tracking-tight uppercase">{so.id}</span>
                                                    </div>
                                                    <div className="flex flex-col">
                                                        <span className="text-[11px] font-bold text-gray-500 mb-1 uppercase tracking-wider">Packed Date</span>
                                                        <span className="text-[20px] font-bold leading-none">{new Date().toLocaleDateString('en-GB')}</span>
                                                    </div>
                                                </div>
                                            </div>
                                        );
                                    })
                                )}
                            </div>
                        ) : (
